export interface VisitorActor {
  email?: string;
  name?: string;
  role?: string;
  isAdminSecret?: boolean;
}

export interface VisitorPolicyDecision {
  allowed: boolean;
  actor: VisitorActor;
function headerValue(req: IncomingMessage, key: string): string | undefined {
  const value = req.headers[key.toLowerCase()];
  return Array.isArray(value) ? value[0] : value;
}

export async function resolveVisitorActor(req: IncomingMessage): Promise<VisitorActor> {
  const session = await resolveAdminSession(req);
  if (session) {
    return {
      email: session.email,
      name: session.name,
      role: session.role,
      isAdminSecret: session.isSuperAdmin,
    };
  }

  return {
    email: undefined,
    name: headerValue(req, "x-actor-name") ?? headerValue(req, "x-invited-by"),
    role: undefined,
    isAdminSecret: false,
  };
}

export async function seedDefaultAccessControl(): Promise<{
  permissions: typeof PERMISSION_CATALOG;
  roles: typeof DEFAULT_OFFICE_OPS_ROLES;
  persisted: boolean;
}> {
  const db = getOptionalPostgresDb();
  if (!db) {
    return { permissions: PERMISSION_CATALOG, roles: DEFAULT_OFFICE_OPS_ROLES, persisted: false };
  }

  await db
    .insert(permissions)
    .values(PERMISSION_CATALOG.map((permission) => ({
      key: permission.key,
      module: permission.module,
      description: permission.description,
    })))
    .onConflictDoNothing();

  await db
    .insert(roles)
    .values(DEFAULT_OFFICE_OPS_ROLES.map((role) => ({
      key: role.key,
      name: role.name,
      description: role.description,
      isSystem: role.isSystem,
    })))
    .onConflictDoNothing();

  const rolePermissionValues = DEFAULT_OFFICE_OPS_ROLES.flatMap((role) =>
    role.permissions.map((permissionKey) => ({
      roleKey: role.key,
      permissionKey,
    })),
  );

  if (rolePermissionValues.length > 0) {
    await db.insert(rolePermissions).values(rolePermissionValues).onConflictDoNothing();
  }

  // ── One-time deprecation migrations ─────────────────────────────────
  // Idempotent: each statement is a no-op once data is clean.
  try {
    // Replaced by visitor.dashboard.view (functionally identical).
    const deprecatedPerm = await db.execute(sql`
      DELETE FROM role_permissions
      WHERE permission_key = 'dashboard.visitor.view'
        AND EXISTS (
          SELECT 1 FROM role_permissions rp2
          WHERE rp2.role_key = role_permissions.role_key
            AND rp2.permission_key = 'visitor.dashboard.view'
        )
    `);
    await db.execute(sql`
      UPDATE role_permissions
      SET permission_key = 'visitor.dashboard.view'
      WHERE permission_key = 'dashboard.visitor.view'
    `);
    await db.execute(sql`
      DELETE FROM permissions WHERE key = 'dashboard.visitor.view'
    `);

    // sos.triggered → visitor.sos_triggered (SOS now lives under visitor module).
    const sosUpdate = await db.execute(sql`
      UPDATE flow_rules
      SET module = 'visitor', trigger = 'visitor.sos_triggered'
      WHERE module = 'sos' AND trigger = 'sos.triggered'
    `);
    if ((sosUpdate as { rowCount?: number })?.rowCount) {
      logInfo(`[policies] Migrated ${(sosUpdate as { rowCount?: number }).rowCount} sos.triggered rule(s) to visitor.sos_triggered`, { scope: "policies" });
    }
    void deprecatedPerm;
  } catch (err) {
    logInfo(`[policies] deprecation migration skipped: ${err instanceof Error ? err.message : String(err)}`, { scope: "policies" });
  }

  // Auto-seed initial superadmin if configured. In Google SSO-only setups,
  // INITIAL_SUPERADMIN_EMAIL is enough; password is optional for legacy login.
  const initialEmail = process.env.INITIAL_SUPERADMIN_EMAIL?.trim().toLowerCase();
  const initialPassword = process.env.INITIAL_SUPERADMIN_PASSWORD?.trim();

  if (initialEmail) {
    const existingAdmins = await db
      .select({ id: users.id })
      .from(users)
      .where(eq(users.email, initialEmail))
      .limit(1);

    if (existingAdmins.length === 0) {
      const passwordHash = initialPassword ? await hashAdminPassword(initialPassword) : null;
      const [newUser] = await db
        .insert(users)
        .values({
          email: initialEmail,
          name: "Super Admin",
          ...(passwordHash ? { passwordHash } : {}),
          status: "active",
        })
        .returning({ id: users.id });

      if (newUser) {
        await db
          .insert(userRoles)
          .values({
            userId: newUser.id,
            email: initialEmail,
            roleKey: "super_admin",
            grantedBy: "system",
          })
          .onConflictDoNothing();
      }
    }
  }

  return { permissions: PERMISSION_CATALOG, roles: DEFAULT_OFFICE_OPS_ROLES, persisted: true };
}

export async function checkVisitorPermission(
  req: IncomingMessage,
  permission: VisitorPermission,
): Promise<VisitorPolicyDecision> {
  const session = await resolveAdminSession(req);
  const actor: VisitorActor = session
    ? {
      email: session.email,
      name: session.name,
      role: session.role,
      isAdminSecret: session.isSuperAdmin,
    }
    : {
      name: headerValue(req, "x-actor-name") ?? headerValue(req, "x-invited-by"),
      isAdminSecret: false,
    };

  if (session?.isSuperAdmin || actor.role === "super_admin") {
    return { allowed: SUPER_ADMIN_PERMISSIONS.has(permission), actor, reason: "super_admin" };
  }

  if (!session?.email) {
    return { allowed: false, actor, reason: "no_policy_store_or_actor" };
  }

  try {
    if (session.permissions.includes(permission)) {
      return {
        allowed: true,
        actor,
        reason: "role_permission",
      };
    }
  } catch {
    return { allowed: false, actor, reason: "policy_store_unavailable" };
  }

  return { allowed: false, actor, reason: "permission_missing" };
}

