  const db = getOptionalPostgresDb();
  if (!db) {
    return { permissions: PERMISSION_CATALOG, roles: DEFAULT_OFFICE_OPS_ROLES, persisted: false };
  }

  await db
    .insert(permissions)
    .values(PERMISSION_CATALOG.map((permission) => ({
      key: permission.key,
      module: permission.module,
      description: permission.description,
    })))
    .onConflictDoNothing();

  await db
    .insert(roles)
    .values(DEFAULT_OFFICE_OPS_ROLES.map((role) => ({
      key: role.key,
      name: role.name,
      description: role.description,
      isSystem: role.isSystem,
    })))
    .onConflictDoNothing();

  const rolePermissionValues = DEFAULT_OFFICE_OPS_ROLES.flatMap((role) =>
    role.permissions.map((permissionKey) => ({
      roleKey: role.key,
      permissionKey,
    })),
  );

  if (rolePermissionValues.length > 0) {
    await db.insert(rolePermissions).values(rolePermissionValues).onConflictDoNothing();
  }

  // ── One-time deprecation migrations ─────────────────────────────────
  // Idempotent: each statement is a no-op once data is clean.
  try {
