    `);
    await db.execute(sql`
      UPDATE role_permissions
      SET permission_key = 'visitor.dashboard.view'
      WHERE permission_key = 'dashboard.visitor.view'
    `);
    await db.execute(sql`
      DELETE FROM permissions WHERE key = 'dashboard.visitor.view'
    `);

    // sos.triggered → visitor.sos_triggered (SOS now lives under visitor module).
    const sosUpdate = await db.execute(sql`
      UPDATE flow_rules
