      WHERE module = 'sos' AND trigger = 'sos.triggered'
    `);
    if ((sosUpdate as { rowCount?: number })?.rowCount) {
      logInfo(`[policies] Migrated ${(sosUpdate as { rowCount?: number }).rowCount} sos.triggered rule(s) to visitor.sos_triggered`, { scope: "policies" });
    }
    void deprecatedPerm;
  } catch (err) {
    logInfo(`[policies] deprecation migration skipped: ${err instanceof Error ? err.message : String(err)}`, { scope: "policies" });
  }

  // Auto-seed initial superadmin if configured. In Google SSO-only setups,
  // INITIAL_SUPERADMIN_EMAIL is enough; password is optional for legacy login.
  const initialEmail = process.env.INITIAL_SUPERADMIN_EMAIL?.trim().toLowerCase();
  const initialPassword = process.env.INITIAL_SUPERADMIN_PASSWORD?.trim();

  if (initialEmail) {
    const existingAdmins = await db
      .select({ id: users.id })
      .from(users)
      .where(eq(users.email, initialEmail))
      .limit(1);

    if (existingAdmins.length === 0) {
      const passwordHash = initialPassword ? await hashAdminPassword(initialPassword) : null;
      const [newUser] = await db
        .insert(users)
        .values({
          email: initialEmail,
          name: "Super Admin",
          ...(passwordHash ? { passwordHash } : {}),
          status: "active",
        })
        .returning({ id: users.id });

      if (newUser) {
        await db
          .insert(userRoles)
          .values({
            userId: newUser.id,
            email: initialEmail,
            roleKey: "super_admin",
            grantedBy: "system",
          })
          .onConflictDoNothing();
      }
    }
  }

  return { permissions: PERMISSION_CATALOG, roles: DEFAULT_OFFICE_OPS_ROLES, persisted: true };
}

export async function checkVisitorPermission(
  req: IncomingMessage,
  permission: VisitorPermission,
): Promise<VisitorPolicyDecision> {
  const session = await resolveAdminSession(req);
  const actor: VisitorActor = session
    ? {
      email: session.email,
      name: session.name,
      role: session.role,
      isAdminSecret: session.isSuperAdmin,
    }
    : {
      name: headerValue(req, "x-actor-name") ?? headerValue(req, "x-invited-by"),
      isAdminSecret: false,
    };

  if (session?.isSuperAdmin || actor.role === "super_admin") {
    return { allowed: SUPER_ADMIN_PERMISSIONS.has(permission), actor, reason: "super_admin" };
  }

  if (!session?.email) {
    return { allowed: false, actor, reason: "no_policy_store_or_actor" };
  }

  try {
    if (session.permissions.includes(permission)) {
      return {
        allowed: true,
        actor,
        reason: "role_permission",
      };
    }
  } catch {
    return { allowed: false, actor, reason: "policy_store_unavailable" };
  }

  return { allowed: false, actor, reason: "permission_missing" };
}

