import { createHmac, randomBytes, randomInt, scrypt as nodeScrypt, timingSafeEqual } from "crypto";
import type { IncomingMessage } from "http";
import { promisify } from "util";
import { and, eq, gt, inArray } from "drizzle-orm";
import { passwordResetOtps, rolePermissions, userRoles, users } from "../../db/schema";
import { getOptionalPostgresDb } from "../../lib/postgres";

const scryptAsync = promisify(nodeScrypt);
const SESSION_TTL_MS = 12 * 60 * 60 * 1000;
const ephemeralSessionSecret = randomBytes(32).toString("hex");

export interface AdminResolvedSession {
  email?: string;
  name: string;
  role: string;
  roleKeys: string[];
  permissions: string[];
  isSuperAdmin: boolean;
  status?: string;
}

interface AdminTokenPayload {
  email?: string;
  name: string;
  roleKeys: string[];
  isSuperAdmin: boolean;
  exp: number;
}

function base64UrlEncode(value: string): string {
  return Buffer.from(value, "utf8").toString("base64url");
}

function base64UrlDecode(value: string): string {
  return Buffer.from(value, "base64url").toString("utf8");
}

function sessionSecret(): string {
  return process.env.VISITOR_ADMIN_SESSION_SECRET
    ?? process.env.VISITOR_ADMIN_SECRET
    ?? ephemeralSessionSecret;
}

function signPayload(payload: string): string {
  return createHmac("sha256", sessionSecret()).update(payload).digest("base64url");
}

function getHeader(req: IncomingMessage, key: string): string | undefined {
  const value = req.headers[key.toLowerCase()];
  return Array.isArray(value) ? value[0] : value;
}

function getBearerToken(req: IncomingMessage): string | undefined {
  const authorization = getHeader(req, "authorization");
  if (!authorization) return undefined;
  const match = authorization.match(/^Bearer\s+(.+)$/i);
  return match?.[1]?.trim();
}

function parseToken(token: string): AdminTokenPayload | null {
  const [encodedPayload, signature] = token.split(".");
  if (!encodedPayload || !signature) return null;

  const expected = signPayload(encodedPayload);
  const provided = Buffer.from(signature, "utf8");
  const actual = Buffer.from(expected, "utf8");
  if (provided.length !== actual.length || !timingSafeEqual(provided, actual)) {
    return null;
  }

  try {
    const payload = JSON.parse(base64UrlDecode(encodedPayload)) as AdminTokenPayload;
    if (!payload?.name || !Array.isArray(payload.roleKeys) || typeof payload.exp !== "number") {
      return null;
    }
    if (payload.exp <= Date.now()) {
      return null;
    }
    return payload;
  } catch {
    return null;
  }
}

export function createAdminSessionToken(input: {
  email?: string;
  name: string;
  roleKeys: string[];
  isSuperAdmin: boolean;
}): string {
  const payload: AdminTokenPayload = {
    email: input.email,
    name: input.name,
    roleKeys: input.roleKeys,
    isSuperAdmin: input.isSuperAdmin,
    exp: Date.now() + SESSION_TTL_MS,
  };
  const encodedPayload = base64UrlEncode(JSON.stringify(payload));
  return `${encodedPayload}.${signPayload(encodedPayload)}`;
}

export async function hashAdminPassword(password: string): Promise<string> {
  const salt = randomBytes(16);
  const derived = await scryptAsync(password, salt, 64) as Buffer;
  return `scrypt:${salt.toString("base64url")}:${derived.toString("base64url")}`;
}

export async function verifyAdminPassword(password: string, storedHash?: string | null): Promise<boolean> {
  if (!storedHash) return false;

  const [algorithm, saltValue, hashValue] = storedHash.split(":");
  if (algorithm !== "scrypt" || !saltValue || !hashValue) return false;

  const salt = Buffer.from(saltValue, "base64url");
  const expected = Buffer.from(hashValue, "base64url");
  const derived = await scryptAsync(password, salt, expected.length) as Buffer;
  return derived.length === expected.length && timingSafeEqual(derived, expected);
}

export async function getAdminAccessProfile(email: string): Promise<AdminResolvedSession | null> {
  const db = getOptionalPostgresDb();
  if (!db) return null;

  const normalizedEmail = email.trim().toLowerCase();
  if (!normalizedEmail) return null;

  const userRows = await db
    .select({
      email: users.email,
      name: users.name,
      status: users.status,
    })
    .from(users)
    .where(eq(users.email, normalizedEmail))
    .limit(1);

  const user = userRows[0];
  if (!user) return null;

  const assignedRoles = await db
    .select({ roleKey: userRoles.roleKey })
    .from(userRoles)
    .where(eq(userRoles.email, normalizedEmail));
  const roleKeys = assignedRoles.map((row) => row.roleKey);
  const isSuperAdmin = roleKeys.includes("super_admin");
  const permissionRows = roleKeys.length === 0
    ? []
    : await db
      .select({ permissionKey: rolePermissions.permissionKey })
      .from(rolePermissions)
      .where(inArray(rolePermissions.roleKey, roleKeys));

  return {
    email: user.email,
    name: user.name?.trim() || user.email,
    role: isSuperAdmin ? "super_admin" : (roleKeys[0] ?? "admin"),
    roleKeys,
    permissions: Array.from(new Set(permissionRows.map((row) => row.permissionKey))),
    isSuperAdmin,
    status: user.status,
  };
}

export async function authenticateAdminWithPassword(input: {
  email: string;
  password: string;
}): Promise<AdminResolvedSession | null> {
  const db = getOptionalPostgresDb();
  if (!db) return null;

  const email = input.email.trim().toLowerCase();
  const rows = await db
    .select({
      email: users.email,
      passwordHash: users.passwordHash,
      status: users.status,
    })
    .from(users)
    .where(eq(users.email, email))
    .limit(1);

  const user = rows[0];
  if (!user || user.status !== "active") return null;

  const valid = await verifyAdminPassword(input.password, user.passwordHash);
  if (!valid) return null;

  await db.update(users).set({ lastLoginAt: new Date(), updatedAt: new Date() }).where(eq(users.email, email));
  return getAdminAccessProfile(email);
}

export async function resolveAdminSession(req: IncomingMessage): Promise<AdminResolvedSession | null> {
  const token = getBearerToken(req);
  if (token) {
    const payload = parseToken(token);
    if (!payload) return null;

    if (payload.isSuperAdmin) {
      return {
        email: payload.email,
        name: payload.name,
        role: "super_admin",
        roleKeys: ["super_admin"],
        permissions: [],
        isSuperAdmin: true,
        status: "active",
      };
    }

    if (!payload.email) return null;
    const liveProfile = await getAdminAccessProfile(payload.email);
    if (!liveProfile || liveProfile.status !== "active") return null;
    return {
      ...liveProfile,
      name: payload.name || liveProfile.name,
    };
  }

  const configuredSecret = process.env.VISITOR_ADMIN_SECRET ?? "";
  const providedSecret = getHeader(req, "x-admin-secret");

  // SECURITY: never accept the x-admin-secret header when no secret is
  // configured — otherwise any non-empty header value grants super-admin.
  if (!configuredSecret) {
    if (providedSecret) warnMissingAdminSecretOnce();
    return null;
  }

  if (providedSecret !== configuredSecret) return null;

  return {
    name: getHeader(req, "x-actor-name") ?? "Admin",
    role: "super_admin",
    roleKeys: ["super_admin"],
    permissions: [],
    isSuperAdmin: true,
    status: "active",
  };
}

let warnedMissingAdminSecret = false;
function warnMissingAdminSecretOnce(): void {
  if (warnedMissingAdminSecret) return;
  warnedMissingAdminSecret = true;
  console.warn(
    "[admin-auth] x-admin-secret header received but VISITOR_ADMIN_SECRET " +
      "is not configured — rejecting. Set VISITOR_ADMIN_SECRET in the " +
      "environment to enable header-based admin auth.",
  );
}

