/**
 * Header only. The session token used to be accepted from `?token=` as well,
 * which put a live credential into access logs, referrers, and browser history.
 * No client ever sent it that way, so it is gone. SSE endpoints that genuinely
 * cannot set headers (EventSource) use their own scoped tokens instead.
 */
async function guardAuth(req: IncomingMessage): Promise<Awaited<ReturnType<typeof validateGuardSession>>> {
  const token = req.headers['x-guard-token'] as string | undefined;
  if (!token) return null;
  return validateGuardSession(token);
}

async function requireVisitorPermission(
  req: IncomingMessage,
  res: ServerResponse,
  permission: VisitorPermission,
): Promise<boolean> {
  const decision = await checkVisitorPermission(req, permission);
  await logPolicyDecision({
    actor: decision.actor,
    action: permission,
    resourceType: 'visitor_permission',
    decision: decision.allowed ? 'allow' : 'deny',
    metadata: { reason: decision.reason },
  });
  if (!decision.allowed) {
    json(res, 403, { error: `Forbidden: missing ${permission}` });
    return false;
  }
  return true;
}

async function requireAnyVisitorPermission(
  req: IncomingMessage,
  res: ServerResponse,
  permissions: VisitorPermission[],
): Promise<boolean> {
  const decisions = await Promise.all(permissions.map((permission) => checkVisitorPermission(req, permission)));
  const allowedDecision = decisions.find((decision) => decision.allowed);
  await logPolicyDecision({
    actor: allowedDecision?.actor ?? decisions[0]?.actor ?? { name: 'unknown', isAdminSecret: false },
    action: permissions.join('|'),
    resourceType: 'visitor_permission',
    decision: allowedDecision ? 'allow' : 'deny',
    metadata: {
      requestedAnyOf: permissions,
      reasons: decisions.map((decision) => ({ reason: decision.reason, role: decision.actor.role })),
      passConfig,
      activeBroadcast: invitation.token_used ? await getActiveBroadcastForInvitation(invitation.id) : null,
    });
    return true;
  }

  // ── Guard API ─────────────────────────────────────────────

  if (pathname === '/api/guard/login' && method === 'POST') {
    const body = await readBodyJson(req);
    const guardName = String(body.guardName ?? body.name ?? '').trim();
    const pin = String(body.pin ?? '').trim();

    // A guard PIN is short by design (they type it on a phone many times a day),
    // so the only thing standing between it and a dictionary run is this.
    if (!enforceRateLimit(req, res, 'login', guardName)) return true;

    if (!guardName || !pin) {
      json(res, 400, { error: 'guardName and pin are required' });
      return true;
    }

    const token = await authenticateGuard(guardName, pin, {
      deviceId: body.deviceId ? String(body.deviceId) : undefined,
      deviceName: body.deviceName ? String(body.deviceName) : undefined,
      userAgent: Array.isArray(req.headers['user-agent'])
        ? req.headers['user-agent'][0]
        : req.headers['user-agent'],
    });
    if (!token) {
      json(res, 401, { error: 'Invalid guard name or PIN' });
      return true;
    }

    const session = await validateGuardSession(token);
    json(res, 200, {
      token,
      // Server-assigned. The field-app may display it, but it no longer decides it.
      siteId: session?.siteId,
      language: session?.language ?? 'hindi',
      guardName: session?.guardName,
      guardId: session?.guardId,
    });
    return true;
  }

  if (pathname === '/api/guard/logout' && method === 'POST') {
    const { logoutGuard } = await import('./guard-auth');
    const token = req.headers['x-guard-token'] as string;
    if (token) await logoutGuard(token);
    json(res, 200, { success: true });
    return true;
  }

  if (pathname === '/api/guard/session' && method === 'GET') {
    const session = await guardAuth(req);
    if (!session) {
      json(res, 401, { error: 'Unauthorized' });
      return true;
    }

    json(res, 200, {
      guardName: session.guardName,
      guardId: session.guardId,
      language: session.language,
      expiresAt: session.expiresAt,
    });
    return true;
  }

  // ── Web Push (guard PWA) ─────────────────────────────────
  // VAPID public key is fetched by the SW before subscribing. No auth: the
  // public key is, by definition, public — and we don't want to gate the
  // very first call the SW makes on a session token.
  if (pathname === '/api/push/vapid-public-key' && method === 'GET') {
    const { features, push: pushCfg } = await import('../../lib/config');
    if (!features.isWebPushEnabled()) {
      json(res, 503, { error: 'Web push is not configured on this server.' });
      return true;
    }
    json(res, 200, { publicKey: pushCfg.vapidPublicKey() });
    return true;
  }

  if (pathname === '/api/guard/push/subscribe' && method === 'POST') {
    const session = await guardAuth(req);
  }

  // ── Guard Management ──────────────────────────────────────────

  if (pathname === '/api/admin/guards' && method === 'GET') {
    if (!(await requireVisitorPermission(req, res, 'visitor.dashboard.view'))) return true;
    const guards = await getAllGuards();
    json(res, 200, {
      guards: guards.map((g) => ({
        id: g.id,
        name: g.name,
        phone: g.phone ?? null,
        language: g.language,
        siteId: g.site_id ?? null,
        isActive: g.is_active === 1,
        createdAt: g.created_at,
      })),
    });
    return true;
  }

  if (pathname === '/api/admin/guards' && method === 'POST') {
    if (!(await requireVisitorPermission(req, res, 'visitor.dashboard.view'))) return true;
    const body = await readBodyJson(req);
    const name = normalizeBodyString(body.name);
    const pin = normalizeBodyString(body.pin);
    if (!name || !pin) {
      json(res, 400, { error: 'name and pin are required' });
      return true;
    }
    const { id } = await registerGuard({
      name,
      pin,
      phone: normalizeBodyString(body.phone) || undefined,
      language: body.language === 'english' ? 'english' : 'hindi',
      // Optional. Left unset, the guard resolves to the default site at login.
      siteId: normalizeBodyString(body.siteId) || undefined,
    });
    json(res, 201, { success: true, id });
    return true;
  }

  if (pathname.startsWith('/api/admin/guards/') && method === 'POST') {
    if (!(await requireVisitorPermission(req, res, 'visitor.dashboard.view'))) return true;
    const parts = pathname.split('/');
    const guardId = parts[4] ?? '';
    const action = parts[5] ?? '';

    if (action === 'deactivate') {
      await deactivateGuard(guardId);
      json(res, 200, { success: true });
      return true;
    }
    if (action === 'reactivate') {
      await reactivateGuard(guardId);
      json(res, 200, { success: true });
      return true;
    }
    if (action === 'reset-pin') {
      const body = await readBodyJson(req);
      const newPin = normalizeBodyString(body.pin);
      if (!newPin) { json(res, 400, { error: 'pin is required' }); return true; }
      const pinHash = await hashPin(newPin);
      await resetGuardPin(guardId, pinHash);
      json(res, 200, { success: true });
      return true;
    }
    if (action === 'language') {
      const body = await readBodyJson(req);
      const lang = body.language === 'english' ? 'english' : body.language === 'hindi' ? 'hindi' : null;
      if (!lang) { json(res, 400, { error: 'language must be "hindi" or "english"' }); return true; }
      await updateGuardLanguage(guardId, lang);
      json(res, 200, { success: true });
      return true;
    }
    json(res, 404, { error: 'Unknown guard action' });
    return true;
  }

  // ── Flow rules ──────────────────────────────────────────────────────
