      await invalidateAffectedCaches(touched);
    }

    if (pullReads && getSession()?.token) {
      await syncCanonicalProducts().catch(() => {});
      await syncOrders().catch(() => {});
    }
  } finally {
    running = false;
    await notify();
  }

  if (retryQueued) {
    retryQueued = false;
    return flushOnce();
  }

  return { sent, failed };
}

