              <Stack.Screen name="Login" component={LoginScreen} options={{ animation: 'fade' }} />
            ) : (
              screens.map((s) => (
                <Stack.Screen
                  key={s.name}
                  name={s.name}
                  component={s.component}
                  options={s.options as any}
                />
              ))
            )}
          </Stack.Navigator>
        </NavigationContainer>
      </View>
    </OrderSessionProvider>
  );
}
