export async function findGuardByName(name: string): Promise<Guard | null> {
  const db = getDb();
  const result = await db.execute({
    sql: `SELECT * FROM guards WHERE name = ? AND is_active = 1 LIMIT 1`,
    args: [name],
  });
  return (result.rows[0] as unknown as Guard) ?? null;
}

export async function getAllActiveGuards(): Promise<Guard[]> {
  const db = getDb();
  const result = await db.execute(`SELECT * FROM guards WHERE is_active = 1 ORDER BY name`);
  return result.rows as unknown as Guard[];
}

export async function createGuard(data: {
  name: string;
  pinHash: string;
  phone?: string;
  language?: "hindi" | "english";
  siteId?: string;
}): Promise<string> {
  const db = getDb();
  const id = randomUUID();
  await db.execute({
    sql:
      `INSERT INTO guards (id, name, pin_hash, phone, language, site_id) VALUES (?, ?, ?, ?, ?, ?)`,
    args: [
      id,
      data.name,
      data.pinHash,
      data.phone ?? null,
      data.language ?? "hindi",
      data.siteId ?? null,
    ],
  });
  return id;
}

export async function createGuardSessionRecord(input: {
  guardId: string;
  guardName: string;
  language: "hindi" | "english";
  tokenHash: string;
  expiresAt: string;
  siteId: string;
  deviceId?: string;
  deviceName?: string;
  userAgent?: string;
}): Promise<string> {
  const db = getDb();
  const id = randomUUID();
  await db.execute({
    sql: `INSERT INTO guard_sessions
      (id, guard_id, guard_name, language, token_hash, site_id, device_id, device_name, user_agent, expires_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    args: [
      id,
      input.guardId,
      input.guardName,
      input.language,
      input.tokenHash,
      input.siteId,
      input.deviceId ?? null,
      input.deviceName ?? null,
      input.userAgent ?? null,
      input.expiresAt,
    ],
  });
  return id;
}

export async function getGuardSessionByTokenHash(
  tokenHash: string,
): Promise<GuardSessionRecord | null> {
  const db = getDb();
  const result = await db.execute({
    sql: `SELECT * FROM guard_sessions
      WHERE token_hash = ? AND revoked_at IS NULL
      LIMIT 1`,
    args: [tokenHash],
  });
  return (result.rows[0] as unknown as GuardSessionRecord) ?? null;
}

export async function touchGuardSession(sessionId: string, expiresAt: string): Promise<void> {
  const db = getDb();
  await db.execute({
    sql: `UPDATE guard_sessions
      SET last_seen_at = ?, expires_at = ?
      WHERE id = ?`,
    args: [new Date().toISOString(), expiresAt, sessionId],
  });
}

export async function revokeGuardSessionByTokenHash(tokenHash: string): Promise<void> {
  const db = getDb();
  await db.execute({
    sql: `UPDATE guard_sessions SET revoked_at = ? WHERE token_hash = ? AND revoked_at IS NULL`,
    args: [new Date().toISOString(), tokenHash],
  });
}

// ─── Authentication ────────────────────────────────────────────

function hashSessionToken(token: string): string {
  return createHash("sha256").update(token).digest("hex");
}

function buildExpiryIso(now = Date.now()): string {
  return new Date(now + SESSION_TTL_MS).toISOString();
}

export async function authenticateGuard(
  guardName: string,
  pin: string,
  deviceMeta?: { deviceId?: string; deviceName?: string; userAgent?: string },
): Promise<string | null> {
  const guard = await findGuardByName(guardName);
  if (!guard) return null;

  const valid = await verifyPin(pin, guard.pin_hash);
  if (!valid) return null;

  const token = randomUUID();
  await createGuardSessionRecord({
    guardId: guard.id,
    guardName: guard.name,
    language: guard.language as "hindi" | "english",
    tokenHash: hashSessionToken(token),
    expiresAt: buildExpiryIso(),
    siteId: resolveSiteId(guard.site_id),
    deviceId: deviceMeta?.deviceId,
    deviceName: deviceMeta?.deviceName,
    userAgent: deviceMeta?.userAgent,
  });

  return token;
}

/**
 * Sliding expiry: every successful validation pushes the 24h window out and
 * writes back. That is one UPDATE on every authenticated request -- fine for a
 * long-lived process, worth noting here because Edge Functions add per-request
 * connection overhead on top of it.
 */
export async function validateGuardSession(token: string): Promise<GuardSession | null> {
  const tokenHash = hashSessionToken(token);
  const record = await getGuardSessionByTokenHash(tokenHash);
  if (!record) return null;

  const expiresAt = Date.parse(record.expires_at);
  if (!Number.isFinite(expiresAt) || Date.now() > expiresAt) {
    await revokeGuardSessionByTokenHash(tokenHash);
    return null;
  }

  const refreshedExpiry = buildExpiryIso();
  await touchGuardSession(record.id, refreshedExpiry);

  return {
    sessionId: record.id,
    guardId: record.guard_id,
    guardName: record.guard_name,
    language: record.language,
    expiresAt: Date.parse(refreshedExpiry),
    siteId: resolveSiteId(record.site_id),
  };
}

export async function logoutGuard(token: string): Promise<void> {
  await revokeGuardSessionByTokenHash(hashSessionToken(token));
}
