    const denied = await requireVisitorPermission(req, "visitor.dashboard.view");
    if (denied) return denied;
    const guards = await getAllGuards();
    return json(200, {
      guards: guards.map((g) => ({
        id: g.id,
        name: g.name,
        phone: g.phone ?? null,
        language: g.language,
        siteId: g.site_id ?? null,
        // `is_active` is INTEGER in the DB and boolean on the wire.
        isActive: g.is_active === 1,
        createdAt: g.created_at,
      })),
    });
  }

  if (pathname === "/api/admin/guards" && method === "POST") {
    const denied = await requireVisitorPermission(req, "visitor.dashboard.view");
    if (denied) return denied;
    const body = await readBodyJson(req);
    const name = normalizeBodyString(body.name);
    const pin = normalizeBodyString(body.pin);
    if (!name || !pin) return json(400, { error: "name and pin are required" });
    // Engine registerGuard(): hash the PIN, then createGuard.
    const id = await createGuard({
      name,
      pinHash: await hashPin(pin),
      phone: normalizeBodyString(body.phone) || undefined,
      language: body.language === "english" ? "english" : "hindi",
      // Optional. Left unset, the guard resolves to the default site at login.
      siteId: normalizeBodyString(body.siteId) || undefined,
    });
    return json(201, { success: true, id });
  }

  if (pathname.startsWith("/api/admin/guards/") && method === "POST") {
    const denied = await requireVisitorPermission(req, "visitor.dashboard.view");
    if (denied) return denied;
    const parts = pathname.split("/");
    const guardId = parts[4] ?? "";
    const action = parts[5] ?? "";

    if (action === "deactivate") {
      await deactivateGuard(guardId);
      return json(200, { success: true });
    }
    if (action === "reactivate") {
      await reactivateGuard(guardId);
      return json(200, { success: true });
    }
    if (action === "reset-pin") {
      const body = await readBodyJson(req);
      const newPin = normalizeBodyString(body.pin);
      if (!newPin) return json(400, { error: "pin is required" });
      await resetGuardPin(guardId, await hashPin(newPin));
      return json(200, { success: true });
    }
    if (action === "language") {
      const body = await readBodyJson(req);
      const lang = body.language === "english" ? "english" : body.language === "hindi" ? "hindi" : null;
      if (!lang) return json(400, { error: 'language must be "hindi" or "english"' });
      await updateGuardLanguage(guardId, lang);
      return json(200, { success: true });
    }
    return json(404, { error: "Unknown guard action" });
  }

