  req: Request,
  pathname: string,
  method: string,
): Promise<Response | null> {
  if (pathname === "/api/guard/login" && method === "POST") {
    const body = await readBodyJson(req);
    const guardName = String(body.guardName ?? body.name ?? "").trim();
    const pin = String(body.pin ?? "").trim();

    // A guard PIN is short by design (they type it on a phone many times a
    // day), so the only thing standing between it and a dictionary run is this.
    // Scoped by guard name as well as IP so one IP hammering many accounts is
    // caught by both keys.
    const limited = await enforceRateLimit(req, "login", guardName);
    if (limited) return limited;

    if (!guardName || !pin) {
      return json(400, { error: "guardName and pin are required" });
    }

    const token = await authenticateGuard(guardName, pin, {
      deviceId: body.deviceId ? String(body.deviceId) : undefined,
      deviceName: body.deviceName ? String(body.deviceName) : undefined,
      userAgent: req.headers.get("user-agent") ?? undefined,
    });
    if (!token) return json(401, { error: "Invalid guard name or PIN" });

    const session = await validateGuardSession(token);
    return json(200, {
      token,
      // Server-assigned. The field-app may display it, but it no longer
      // decides it.
      siteId: session?.siteId,
      language: session?.language ?? "hindi",
      guardName: session?.guardName,
      guardId: session?.guardId,
    });
  }

  if (pathname === "/api/guard/logout" && method === "POST") {
    const token = header(req, "x-guard-token");
    if (token) await logoutGuard(token);
    return json(200, { success: true });
  }

  if (pathname === "/api/guard/session" && method === "GET") {
    const session = await guardAuth(req);
    if (!session) return json(401, { error: "Unauthorized" });
    return json(200, {
      guardName: session.guardName,
      guardId: session.guardId,
      language: session.language,
      expiresAt: session.expiresAt,
    });
  }

  if (pathname === "/api/visitors/active" && method === "GET") {
    const session = await guardAuth(req);
    if (!session) return json(401, { error: "Unauthorized" });
    return json(200, { sessions: await getActiveSessions() });
  }

  if (pathname === "/api/visitor/locations" && method === "GET") {
    const limited = await enforceRateLimit(req, "publicRead");
    if (limited) return limited;
    return json(200, { locations: await getAllLocations() });
      return json(200, { success: true, attendance: record });
    } catch (error) {
      return json(400, { error: error instanceof Error ? error.message : String(error) });
    }
  }

  // ── Guard admin ─────────────────────────────────────────────────────
  if (pathname === "/api/admin/guards" && method === "GET") {
    const denied = await requireVisitorPermission(req, "visitor.dashboard.view");
    if (denied) return denied;
    const guards = await getAllGuards();
    return json(200, {
      guards: guards.map((g) => ({
        id: g.id,
        name: g.name,
        phone: g.phone ?? null,
        language: g.language,
        siteId: g.site_id ?? null,
        // `is_active` is INTEGER in the DB and boolean on the wire.
        isActive: g.is_active === 1,
        createdAt: g.created_at,
      })),
    });
  }

  if (pathname === "/api/admin/guards" && method === "POST") {
    const denied = await requireVisitorPermission(req, "visitor.dashboard.view");
    if (denied) return denied;
    const body = await readBodyJson(req);
    const name = normalizeBodyString(body.name);
    const pin = normalizeBodyString(body.pin);
    if (!name || !pin) return json(400, { error: "name and pin are required" });
    // Engine registerGuard(): hash the PIN, then createGuard.
    const id = await createGuard({
      name,
      pinHash: await hashPin(pin),
      phone: normalizeBodyString(body.phone) || undefined,
      language: body.language === "english" ? "english" : "hindi",
      // Optional. Left unset, the guard resolves to the default site at login.
      siteId: normalizeBodyString(body.siteId) || undefined,
    });
    return json(201, { success: true, id });
  }

  if (pathname.startsWith("/api/admin/guards/") && method === "POST") {
    const denied = await requireVisitorPermission(req, "visitor.dashboard.view");
    if (denied) return denied;
    const parts = pathname.split("/");
    const guardId = parts[4] ?? "";
    const action = parts[5] ?? "";

    if (action === "deactivate") {
      await deactivateGuard(guardId);
      return json(200, { success: true });
    }
    if (action === "reactivate") {
      await reactivateGuard(guardId);
      return json(200, { success: true });
    }
    if (action === "reset-pin") {
      const body = await readBodyJson(req);
      const newPin = normalizeBodyString(body.pin);
      if (!newPin) return json(400, { error: "pin is required" });
      await resetGuardPin(guardId, await hashPin(newPin));
      return json(200, { success: true });
    }
    if (action === "language") {
      const body = await readBodyJson(req);
      const lang = body.language === "english" ? "english" : body.language === "hindi" ? "hindi" : null;
      if (!lang) return json(400, { error: 'language must be "hindi" or "english"' });
      await updateGuardLanguage(guardId, lang);
      return json(200, { success: true });
    }
    return json(404, { error: "Unknown guard action" });
