  const [draft, setDraft] = useState({ name: "", pin: "", confirmPin: "", phone: "", language: "hindi" });
  const [draftError, setDraftError] = useState("");
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [resetTarget, setResetTarget] = useState<GuardEntry | null>(null);
  const [newPin, setNewPin] = useState("");
  const [newPinConfirm, setNewPinConfirm] = useState("");
  const [resetError, setResetError] = useState("");

  const createMutation = useMutation({
    mutationFn: () => createGuard({ name: draft.name, pin: draft.pin, phone: draft.phone || undefined, language: draft.language }),
    onSuccess: (res) => {
      if (!res.ok) {
        const msg = apiError(res, "Could not create guard.");
        setDraftError(msg);
        toastError(msg);
        return;
      }
      setDraft({ name: "", pin: "", confirmPin: "", phone: "", language: "hindi" });
      setDraftError("");
      setShowCreateForm(false);
      void queryClient.invalidateQueries({ queryKey: ["guards"] });
      toastSuccess("Support staff created");
    },
    onError: (err) => toastError(err, "Could not create guard."),
  });

  const deactivateMutation = useMutation({
    mutationFn: deactivateGuard,
    onSuccess: (res) => {
      void queryClient.invalidateQueries({ queryKey: ["guards"] });
      if (res.ok) toastSuccess("Support staff deactivated");
      else toastError(apiError(res, "Could not deactivate guard."));
    },
    onError: (err) => toastError(err, "Could not deactivate guard."),
  });

  const reactivateMutation = useMutation({
    mutationFn: reactivateGuard,
    onSuccess: (res) => {
      void queryClient.invalidateQueries({ queryKey: ["guards"] });
      if (res.ok) toastSuccess("Support staff reactivated");
      else toastError(apiError(res, "Could not reactivate guard."));
    },
    onError: (err) => toastError(err, "Could not reactivate guard."),
  });

  const updateLanguageMutation = useMutation({
    mutationFn: ({ id, language }: { id: string; language: "hindi" | "english" }) => updateGuardLanguage(id, language),
    onSuccess: (res) => {
      void queryClient.invalidateQueries({ queryKey: ["guards"] });
      if (res.ok) toastSuccess("Language updated");
      else toastError(apiError(res, "Could not update language."));
    },
    onError: (err) => toastError(err, "Could not update language."),
  });

  const resetPinMutation = useMutation({
    mutationFn: ({ id, pin }: { id: string; pin: string }) => resetGuardPin(id, pin),
    onSuccess: (res) => {
      if (!res.ok) {
        const msg = apiError(res, "Could not reset PIN.");
        setResetError(msg);
        toastError(msg);
        return;
      }
      setResetTarget(null);
      setNewPin("");
      setNewPinConfirm("");
      setResetError("");
      toastSuccess("PIN reset");
    },
    onError: (err) => toastError(err, "Could not reset PIN."),
  });

  function handleCreate(e: React.FormEvent) {
    e.preventDefault();
    setDraftError("");
    if (draft.pin !== draft.confirmPin) { setDraftError("PINs do not match."); return; }
    if (draft.pin.length < 4) { setDraftError("PIN must be at least 4 digits."); return; }
    createMutation.mutate();
  }

  function handleResetPin(e: React.FormEvent) {
    e.preventDefault();
    setResetError("");
    if (newPin !== newPinConfirm) { setResetError("PINs do not match."); return; }
    if (newPin.length < 4) { setResetError("PIN must be at least 4 digits."); return; }
    if (!resetTarget) return;
    resetPinMutation.mutate({ id: resetTarget.id, pin: newPin });
  }

  return (
    <div>
      <section className="panel">
        <PanelTitle
          eyebrow="Security"
          title="Support Staff"
          action={
            <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
              <RefreshButton onClick={() => void guardsQuery.refetch()} />
              <button
                type="button"
                className="primary-button"
                onClick={() => { setDraftError(""); setShowCreateForm(true); }}
              >
                <UserPlus size={15} />
                New support staff
              </button>
            </div>
          }
        />
        <p className="panel-copy">
          Support staff log in to the visitor PWA using their name and PIN. Create accounts here and share credentials directly.
        </p>
        <div className="record-stack">
          {guards.length === 0 ? <p className="muted" style={{ fontSize: 13 }}>No support staff yet — click <strong>New support staff</strong> to create one.</p> : null}
          {guards.map((guard) => (
            <article className="record-card" key={guard.id}>
              <div>
                <strong>{guard.name}</strong>
                <span>{guard.phone ? `${guard.phone} · ` : ""}created {formatDateTime(guard.createdAt)}</span>
              </div>
              <div className="record-actions">
                <StatusBadge status={guard.isActive ? "active" : "disabled"} />
                <select
                  className="guard-language-select"
                  value={guard.language === "english" ? "english" : "hindi"}
                  disabled={updateLanguageMutation.isPending}
                  onChange={(e) => updateLanguageMutation.mutate({ id: guard.id, language: e.target.value === "english" ? "english" : "hindi" })}
                  aria-label={`Language for ${guard.name}`}
                >
                  <option value="hindi">Hindi</option>
                  <option value="english">English</option>
                </select>
                <button
                  type="button"
                  className="inline-button"
                  onClick={() => { setResetTarget(guard); setNewPin(""); setNewPinConfirm(""); setResetError(""); }}
                >
                  Reset PIN
                </button>
                {guard.isActive ? (
                  <button type="button" className="inline-button reject" onClick={() => deactivateMutation.mutate(guard.id)}>
                    Deactivate
                  </button>
                ) : (
                  <button type="button" className="inline-button approve" onClick={() => reactivateMutation.mutate(guard.id)}>
                    Reactivate
                  </button>
                )}
              </div>
            </article>
          ))}
        </div>
      </section>

      {showCreateForm ? (
        <div className="drawer-backdrop modal-backdrop" onClick={() => setShowCreateForm(false)}>
          <aside className="drawer-panel modal-panel" style={{ maxWidth: 440 }} onClick={(e) => e.stopPropagation()}>
            <div className="panel-title" style={{ marginBottom: 14 }}>
              <div>
                <span className="eyebrow">Add</span>
                <h2>New support staff</h2>
              </div>
              <button type="button" className="icon-button" onClick={() => setShowCreateForm(false)} aria-label="Close"><X size={16} /></button>
            </div>
            <form className="form-grid" onSubmit={handleCreate}>
              <TextInput label="Full name" value={draft.name} onChange={(name) => setDraft({ ...draft, name })} required />
              <TextInput label="Phone (optional)" value={draft.phone} onChange={(phone) => setDraft({ ...draft, phone })} />
              <label className="field">
                <span>Language</span>
                <select className="field-select" value={draft.language} onChange={(e) => setDraft({ ...draft, language: e.target.value })}>
                  <option value="hindi">Hindi</option>
                  <option value="english">English</option>
                </select>
              </label>
              <TextInput label="PIN" type="password" value={draft.pin} onChange={(pin) => setDraft({ ...draft, pin })} required />
              <TextInput label="Confirm PIN" type="password" value={draft.confirmPin} onChange={(confirmPin) => setDraft({ ...draft, confirmPin })} required />
              {draftError ? <p className="form-error">{draftError}</p> : null}
              <Button
                type="submit"
                loading={createMutation.isPending}
                loadingLabel="Creating…"
                leftIcon={<UserPlus size={17} />}
              >
                Create support staff
              </Button>
            </form>
          </aside>
        </div>
      ) : null}

      {resetTarget ? (
        <div className="drawer-backdrop modal-backdrop" onClick={() => setResetTarget(null)}>
          <aside className="drawer-panel modal-panel" style={{ maxWidth: 400 }} onClick={(e) => e.stopPropagation()}>
            <div className="panel-title" style={{ marginBottom: 14 }}>
              <div>
                <span className="eyebrow">Reset PIN</span>
                <h2>{resetTarget.name}</h2>
              </div>
              <button type="button" className="icon-button" onClick={() => setResetTarget(null)} aria-label="Close"><X size={16} /></button>
            </div>
            <form className="form-grid" onSubmit={handleResetPin}>

