// Behavioural test for the inventory port (63 checks; LLM endpoints have their own scripts), run against a locally
// served api/index.ts pointed at the throwaway Supabase DB. All rows live under
// a dedicated site id (plus one throwaway guard) and are deleted at the end.
//
// Usage: start scripts/serve-local.ts, then with the same env:
//   deno run -A scripts/test-inventory.ts
import postgres from "npm:postgres@3.4.5";
import { createHmac } from "node:crypto";
import { Buffer } from "node:buffer";

const BASE = "http://localhost:8787/api/api/inventory";
const SITE = "port-test-inv";
const RUN = Date.now().toString(36);
const sql = postgres(Deno.env.get("DATABASE_URL")!, { prepare: false, max: 2, connection: { search_path: "appointy_ops, public" } });

const secret = Deno.env.get("VISITOR_ADMIN_SESSION_SECRET")!;
const payload = Buffer.from(JSON.stringify({ email: "port-test@example.com", name: "Port Test", roleKeys: ["super_admin"], isSuperAdmin: true, exp: Date.now() + 3600_000 })).toString("base64url");
const token = `${payload}.${createHmac("sha256", secret).update(payload).digest("base64url")}`;

let pass = 0, fail = 0;
function check(name: string, ok: boolean, detail?: unknown) {
  if (ok) { pass++; console.log(`  ok   ${name}`); }
  else { fail++; console.log(`  FAIL ${name}`, detail !== undefined ? JSON.stringify(detail) : ""); }
}
// Field-app writes go through a real guard session (guard_id has an FK to
// guards). They also send a DECOY x-site-id: guards must be scoped by their
// session's site, never by the header.
let guardToken = "";
const GUARD_WRITES = /^\/(receipts|issues|corrections|reorder-requests|mismatch-flags)$/;
async function call(method: string, path: string, body?: unknown) {
  const asGuard = method === "POST" && GUARD_WRITES.test(path);
  const auth: Record<string, string> = asGuard
    ? { "x-guard-token": guardToken, "x-site-id": "site-dev" }
    : { Authorization: `Bearer ${token}`, "x-site-id": SITE };
  const res = await fetch(BASE + path, {
    method,
    headers: { ...auth, "x-device-id": "dev-test", ...(body ? { "Content-Type": "application/json" } : {}) },
    body: body ? JSON.stringify(body) : undefined,
  });
  let data: any = null;
  try { data = await res.json(); } catch { /* empty */ }
  return { status: res.status, data };
}
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const onHand = async (b: string) => Number((await sql`select on_hand from inventory_stock where site_id=${SITE} and barcode=${b}`)[0]?.on_hand ?? -1);

const B1 = `ptb1_${RUN}`, B2 = `ptb2_${RUN}`;
const GUARD_NAME = `PortTestGuard_${RUN}`;
const GUARD_ID = `ptg_${RUN}`;
try {
  const bcrypt = (await import("npm:bcryptjs@2.4.3")).default;
  await sql`insert into guards (id, name, pin_hash, language, site_id) values (${GUARD_ID}, ${GUARD_NAME}, ${await bcrypt.hash("4321", 10)}, 'english', ${SITE})`;
  const login = await fetch(BASE.replace("/inventory", "/guard/login"), { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ guardName: GUARD_NAME, pin: "4321" }) });
  const lj = await login.json();
  guardToken = lj.token ?? lj.data?.token ?? "";
  console.log("guard login", login.status, guardToken ? "token ok" : JSON.stringify(lj));

  console.log("auth");
  { const r = await fetch(BASE + "/stock"); check("no credentials -> 401", r.status === 401); await r.body?.cancel(); }

