/**
 * Serve the `api` function locally with plain Deno -- no Docker, no
 * `supabase functions serve`. Point DATABASE_URL at the throwaway project's
 * pooler (PROBE_DB_SESSION in .env.probe).
 *
 *   set -a; source <(grep -E '^(PROBE_DB_SESSION|VISITOR_ADMIN_SESSION_SECRET|INTERNAL_JOB_SECRET)=' .env.probe); set +a
 *   DATABASE_URL="$PROBE_DB_SESSION" deno run -A scripts/serve-local.ts
 *
 * Port 8787, not Deno.serve's default 8000 (often taken on dev machines --
 * a test once silently hit an unrelated app there). Base URL shape matches
 * deployed: http://localhost:8787/api/api/...
 */
const orig = Deno.serve.bind(Deno);
// deno-lint-ignore no-explicit-any
(Deno as any).serve = (handler: any) => orig({ port: Number(Deno.env.get("PORT") ?? 8787) }, handler);
await import("../supabase/functions/api/index.ts");

