import { describe, expect, test } from "bun:test";
import { DEFAULT_OFFICE_OPS_ROLES, PERMISSION_CATALOG } from "./policies";
import { officeOpsSchemaSql } from "../../lib/postgres-schema";

const FIELD_ROLE_KEYS = ["field_operator", "field_supervisor"] as const;
const FIELD_PERMISSIONS = [
  "inventory.view", "inventory.receive", "inventory.issue",
  "inventory.register", "inventory.reorder", "inventory.adjust",
];

describe("field roles stay in lockstep with boot SQL", () => {
  const sql = officeOpsSchemaSql();
  for (const key of FIELD_ROLE_KEYS) {
    const role = DEFAULT_OFFICE_OPS_ROLES.find((r) => r.key === key);
    test(`${key} is a default role`, () => expect(role).toBeDefined());
    test(`${key} boot SQL grants exactly the TS permissions`, () => {
      const perms = role?.permissions ?? [];
      for (const p of perms) expect(sql).toContain(`('${key}', '${p}')`);
      const sqlCount = sql.split(`('${key}', 'inventory.`).length - 1;
      expect(sqlCount).toBe(perms.length);
    });
  }
  test("every field permission is in the catalog", () => {
    const keys = new Set<string>(PERMISSION_CATALOG.map((p) => p.key));
    for (const p of FIELD_PERMISSIONS) expect(keys.has(p)).toBe(true);
  });
  test("operator cannot adjust or register", () => {
    const op = DEFAULT_OFFICE_OPS_ROLES.find((r) => r.key === "field_operator")!;
    expect(op.permissions).not.toContain("inventory.adjust");
    expect(op.permissions).not.toContain("inventory.register");
  });
});

