// Behavioural test for field staff roles (guard_roles + inventory.* checks).
// Runs against either backend; both must give the same answers.
//
// Supabase (serve-local.ts running):  deno run -A scripts/test-field-rbac.ts
// Engine (local, throwaway DB):       RBAC_BASE=http://localhost:4112/api deno run -A scripts/test-field-rbac.ts
//
// Needs DATABASE_URL (throwaway only, never prod) and VISITOR_ADMIN_SESSION_SECRET
// in env. All rows live under a dedicated site id and are deleted at the end.
import postgres from "npm:postgres@3.4.5";
import { createHmac } from "node:crypto";
import { Buffer } from "node:buffer";

const BASE = Deno.env.get("RBAC_BASE") ?? "http://localhost:8787/api/api";
const SITE = "rbac-test";
const RUN = Date.now().toString(36);
const sql = postgres(Deno.env.get("DATABASE_URL")!, { prepare: false, max: 2, connection: { search_path: "appointy_ops, public" } });

const secret = Deno.env.get("VISITOR_ADMIN_SESSION_SECRET")!;
const payload = Buffer.from(JSON.stringify({ email: "rbac-test@example.com", name: "RBAC Test", roleKeys: ["super_admin"], isSuperAdmin: true, exp: Date.now() + 3600_000 })).toString("base64url");
const adminToken = `${payload}.${createHmac("sha256", secret).update(payload).digest("base64url")}`;

let pass = 0, fail = 0;
function check(name: string, ok: boolean, detail?: unknown) {
  if (ok) { pass++; console.log(`  ok   ${name}`); }
  else { fail++; console.log(`  FAIL ${name}`, detail !== undefined ? JSON.stringify(detail) : ""); }
}

async function send(url: string, method: string, headers: Record<string, string>, body?: unknown) {
  const res = await fetch(url, {
    method,
    headers: { ...headers, ...(body !== undefined ? { "Content-Type": "application/json" } : {}) },
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });
  let data: any = null;
  try { data = await res.json(); } catch { /* empty */ }
  return { status: res.status, data };
}
// Guard calls send a DECOY x-site-id: scope must come from the session.
const g = (token: string, method: string, path: string, body?: unknown) =>
  send(`${BASE}/inventory${path}`, method, { "x-guard-token": token, "x-site-id": "site-dev", "x-device-id": "rbac-test" }, body);
const gRaw = (token: string, method: string, path: string) =>
  send(`${BASE}${path}`, method, { "x-guard-token": token });
const a = (method: string, path: string, body?: unknown) =>
  send(`${BASE}${path}`, method, { Authorization: `Bearer ${adminToken}`, "x-site-id": SITE }, body);

const OP_ID = `rbac_op_${RUN}`, SUP_ID = `rbac_sup_${RUN}`, NONE_ID = `rbac_none_${RUN}`;
const guardIds = [OP_ID, SUP_ID, NONE_ID];
const tokens: Record<string, string> = {};

try {
  const bcrypt = (await import("npm:bcryptjs@2.4.3")).default;
  const pinHash = await bcrypt.hash("4321", 10);
  for (const [id, role] of [[OP_ID, "field_operator"], [SUP_ID, "field_supervisor"], [NONE_ID, null]] as const) {
    await sql`insert into guards (id, name, pin_hash, language, site_id) values (${id}, ${`RBAC ${id}`}, ${pinHash}, 'english', ${SITE})`;
    if (role) await sql`insert into guard_roles (guard_id, role_key, granted_by) values (${id}, ${role}, 'test')`;
  }
  const logins: Record<string, any> = {};
  for (const id of guardIds) {
    const r = await send(`${BASE}/guard/login`, "POST", {}, { guardName: `RBAC ${id}`, pin: "4321" });
    logins[id] = r.data;
    tokens[id] = r.data?.token ?? "";
    if (!tokens[id]) console.log("login failed", id, r.status, JSON.stringify(r.data));
  }

  console.log("login + session");
  const opPerms: string[] = logins[OP_ID]?.permissions ?? [];
  check("1 operator login carries inventory.issue, not inventory.adjust",
    opPerms.includes("inventory.issue") && !opPerms.includes("inventory.adjust"), opPerms);
  const sess = await gRaw(tokens[OP_ID], "GET", "/guard/session");
  check("2 session repeats permissions and has siteId",
    sess.status === 200 && JSON.stringify([...(sess.data?.permissions ?? [])].sort()) === JSON.stringify([...opPerms].sort()) && sess.data?.siteId === SITE,
    sess);

  console.log("inventory checks");
  const noneStock = await g(tokens[NONE_ID], "GET", "/stock");
  check("3 no roles -> 403 permission_denied", noneStock.status === 403 && noneStock.data?.code === "permission_denied", noneStock);
  const opStock = await g(tokens[OP_ID], "GET", "/stock");
  check("4 operator can read stock", opStock.status === 200, opStock.status);
  const opCorr = await g(tokens[OP_ID], "POST", "/corrections", { id: `rbac_c1_${RUN}`, barcode: `rbac_b_${RUN}`, old_qty: 0, new_qty: 1 });
  check("5 operator correction -> 403 inventory.adjust", opCorr.status === 403 && opCorr.data?.permission === "inventory.adjust", opCorr);
  const supCorr = await g(tokens[SUP_ID], "POST", "/corrections", { id: `rbac_c2_${RUN}`, barcode: `rbac_b_${RUN}`, old_qty: 0, new_qty: 1 });
  check("6 supervisor correction is not refused", supCorr.status !== 403, supCorr);
  const opProd = await g(tokens[OP_ID], "POST", "/products", { barcode: `rbac_p_${RUN}`, name: "RBAC Test", unit: "pcs", pack_size: 1 });
  check("7 operator new product -> 403 inventory.register", opProd.status === 403 && opProd.data?.permission === "inventory.register", opProd);
  const opBill = await g(tokens[OP_ID], "POST", "/bills/validate", { items: [] });
  check("8 guard on admin-only route -> 403 admin", opBill.status === 403 && opBill.data?.permission === "admin", opBill);

  console.log("admin role management");
  const superRole = await a("POST", `/admin/guards/${OP_ID}/roles`, { roleKeys: ["super_admin"] });
  check("9 super_admin cannot be given to staff", superRole.status === 400, superRole);
  const badRole = await a("POST", `/admin/guards/${OP_ID}/roles`, { roleKeys: ["no_such_role"] });
  check("10 unknown role -> 400", badRole.status === 400, badRole);
  const promote = await a("POST", `/admin/guards/${OP_ID}/roles`, { roleKeys: ["field_supervisor"] });
  const afterPromote = await g(tokens[OP_ID], "POST", "/corrections", { id: `rbac_c3_${RUN}`, barcode: `rbac_b_${RUN}`, old_qty: 1, new_qty: 2 });
  check("11 promotion takes effect at once", promote.status === 200 && afterPromote.status !== 403, { promote, afterPromote });
  const list = await a("GET", "/admin/guards");
  const opRow = (list.data?.guards ?? []).find((x: any) => x.id === OP_ID);
  check("12 admin list shows roleKeys", JSON.stringify(opRow?.roleKeys) === JSON.stringify(["field_supervisor"]), opRow);
  const deact = await a("POST", `/admin/guards/${NONE_ID}/deactivate`);
  const deadSess = await gRaw(tokens[NONE_ID], "GET", "/guard/session");
  check("13 deactivation kills the live session", deact.status === 200 && deadSess.status === 401, { deact: deact.status, deadSess: deadSess.status });
  const created = await a("POST", "/admin/guards", { name: `RBAC New ${RUN}`, pin: "5678" });
  if (created.data?.id) guardIds.push(created.data.id);
  check("14 new staff default to field_operator",
    created.status === 201 && JSON.stringify(created.data?.roleKeys) === JSON.stringify(["field_operator"]), created);
} finally {
  for (const t of ["inventory_stock_corrections", "inventory_stock_lots", "inventory_stock", "inventory_products"]) {
    await sql.unsafe(`delete from ${t} where site_id = $1`, [SITE]).catch(() => {});
  }
  for (const id of guardIds) {
    await sql`delete from guard_roles where guard_id=${id}`.catch(() => {});
    await sql`delete from guard_sessions where guard_id=${id}`.catch(() => {});
    await sql`delete from guards where id=${id}`.catch(() => {});
  }
  await sql.end();
  console.log(`\n${pass} passed, ${fail} failed`);
  Deno.exit(fail > 0 ? 1 : 0);
}

