 *
 * The engine's debounce exists to keep a burst of validations under Google's
 * **60 reads/min/user** quota -- its own comment calls that critical. Across
 * isolates the in-memory debounce never coalesces, so 30 validations would
 * become 30 Sheets writes and the quota breaks.
 *
 * Here the coalescing happens in the DB: N requests upsert one row, and a
 * pg_cron job drains it. `requested_at` is NOT bumped on conflict -- the row
 * keeps the FIRST request's timestamp, so a continuous stream of writes cannot
 * starve the drain by pushing the deadline forever.
 */
export async function markSheetTabDirty(siteId: string, tab: SheetTab): Promise<void> {
  try {
    const db = getDb();
    await db.execute({
      sql: `INSERT INTO sheet_sync_pending (site_id, tab) VALUES (?, ?)
            ON CONFLICT (site_id, tab) DO NOTHING`,
      args: [siteId, tab],
    });
  } catch (err) {
    console.error(
      `[isolate-state] failed to mark ${tab} dirty for ${siteId}`,
      err instanceof Error ? err.message : String(err),
    );
  }
}

/**
 * Claim every tab dirty for at least `minAgeSeconds`, returning what to sync.
 *
 * DELETE ... RETURNING makes the claim atomic, so two overlapping cron runs
 * cannot both sync the same tab.
 */
export async function claimDirtySheetTabs(
  minAgeSeconds = 15,
): Promise<Array<{ siteId: string; tab: SheetTab }>> {
  try {
    const db = getDb();
    const res = await db.execute({
      sql: `DELETE FROM sheet_sync_pending
            WHERE requested_at <= now() - make_interval(secs => ?)
            RETURNING site_id, tab`,
      args: [minAgeSeconds],
    });
    return (res.rows as Array<{ site_id: string; tab: SheetTab }>).map((r) => ({
      siteId: r.site_id,
      tab: r.tab,
    }));
  } catch (err) {
    console.error(
      "[isolate-state] failed to claim dirty sheet tabs",
      err instanceof Error ? err.message : String(err),
    );
    return [];
  }
}

