593	function ScannerScreen({
594	  t,
595	  showToast,
596	  pendingCount,
597	  syncInProgress,
598	  online,
599	  attemptQueueSync,
600	  refreshPendingCount,
601	}: {
602	  t: (key: string) => string;
603	  showToast: (message: string, tone?: ToastTone, icon?: IconName) => void;
604	  pendingCount: number;
605	  syncInProgress: boolean;
606	  online: boolean;
607	  attemptQueueSync: (options?: SyncOptions) => Promise<SyncSummary | null>;
608	  refreshPendingCount: () => Promise<number>;
609	}) {
610	  const [scannerActive, setScannerActive] = useState(true);
611	  const [restartKey, setRestartKey] = useState(0);
612	  const [loading, setLoading] = useState(false);
613	  const [currentCard, setCurrentCard] = useState<CurrentVisitorCard | null>(null);
614	
615	  const startScanner = useCallback(() => {
616	    setCurrentCard(null);
617	    setLoading(false);
618	    setScannerActive(true);
619	    setRestartKey((value) => value + 1);
620	  }, []);
621	
622	  async function handleScannedValue(value: string) {
623	    setScannerActive(false);
624	    const extracted = extractToken(value);
625	    if (!extracted.token) return;
626	    await handleQRResult(extracted);
627	  }
628	
629	  async function handleQRResult(extracted: ExtractedQrToken) {
630	    setLoading(true);
631	    const res = await verifyQr(extracted.token);
632	    setLoading(false);
633	
634	    if (res.offline) {
635	      const expectedMatch = findCachedExpectedGuestByToken(extracted.token);
636	      const visitorMeta = expectedMatch
637	        ? expectedGuestToMeta(expectedMatch)
638	        : extracted.visitorMeta;
639	      if (expectedMatch) showToast(t('expected_match_found'), 'info', 'search');
640	      setCurrentCard({ token: extracted.token, offlinePending: true, visitorMeta });
641	      return;
642	    }
643	    if (!res.data?.invitation) {
644	      setCurrentCard({ token: extracted.token, data: res.data });
645	      return;
646	    }
647	    const card = { token: extracted.token, data: res.data };
648	    setCurrentCard(card);
649	    if (
650	      res.ok &&
651	      res.data.valid &&
652	      res.data.invitation.approval_status === 'approved' &&
653	      !res.data.session
654	    ) {
655	      showToast(t('auto_checking_in'), 'info', 'check');
656	      await checkIn(card);
657	    }
658	  }
659	
660	  async function checkIn(card: CurrentVisitorCard) {
661	    const res = await checkInVisitor(card.token);
662	    if (res.ok) {
663	      showToast(t('checked_in'), 'success', 'check');
664	      setCurrentCard({ ...card, data: { ...card.data!, session: res.data.session } });
665	      return;
666	    }
667	    if (res.offline) {
668	      const invitation = card.data?.invitation;
669	      const event = createOfflineEvent({
670	        eventType: 'qr_checkin_capture',
671	        ...getGuardContext(),
672	        qrToken: card.token,
673	        scannedRawValue: card.token,
674	        visitorName: invitation?.visitor_name || undefined,
675	        hostName: invitation?.host_employee_name || undefined,
676	        purpose: invitation?.purpose || undefined,
677	      }) as OfflineEventRecord;
678	      const recordId = await enqueue(event) as number;
679	      await refreshPendingCount();
680	      void registerBackgroundSync();
681	      setCurrentCard({ ...card, offlinePending: true, offlineEventId: event.offlineEventId });
682	      showToast(t('checkin_saved_offline'), 'info', 'offline');
683	      return;
684	    }
685	    showToast(res.data?.errorMessage ?? t('error'), 'error', 'alert');
686	  }
687	
688	  async function saveOfflineQr(card: CurrentVisitorCard, form: OfflineQrFormValue) {
689	    const event = createOfflineEvent({
690	      eventType: 'qr_checkin_capture',
691	      ...getGuardContext(),
692	      qrToken: card.token,
693	      scannedRawValue: card.token,
694	      visitorName: form.visitorName || undefined,
695	      hostName: form.hostName || undefined,
696	      purpose: form.purpose || undefined,
697	      notes: form.notes || undefined,
698	    }) as OfflineEventRecord;
699	    const recordId = await enqueue(event) as number;
700	    await refreshPendingCount();
701	    void registerBackgroundSync();
702	    setCurrentCard({ ...card, offlinePending: true, offlineEventId: event.offlineEventId });
703	    showToast(t('checkin_saved_offline'), 'info', 'offline');
704	    return recordId;
705	  }
706	
707	  return (
708	    <div id="scanner-screen" className="screen active" aria-label={t('aria_scanner')}>
709	      <Topbar title={t('page_scan')} icon="camera">
710	        <button className="icon-btn" type="button" title={t('aria_restart_camera')} aria-label={t('aria_restart_camera')} onClick={startScanner}>
711	          <IconGlyph name="refresh" />
712	        </button>
713	      </Topbar>
714	      <div className="scanner-body">
715	        <QrScanner active={scannerActive} restartKey={restartKey} onResult={handleScannedValue} />
716	        <div className="scan-hint">{t('scan_hint')}</div>
717	        {(syncInProgress || pendingCount > 0) ? (
718	          <ScannerSyncPanel
719	            t={t}
720	            pendingCount={pendingCount}
721	            syncInProgress={syncInProgress}
722	            online={online}
723	            attemptQueueSync={attemptQueueSync}
724	          />
725	        ) : null}
726	        {loading ? <div style={{ textAlign: 'center', padding: 24 }}><div className="spinner" style={{ margin: '0 auto' }} /></div> : null}
727	        {currentCard ? (
728	          <div id="visitor-card-section">
729	            <VisitorResultCard
730	              card={currentCard}
731	              t={t}
732	              onRetry={() => handleQRResult({ token: currentCard.token, visitorMeta: currentCard.visitorMeta ?? null })}
733	              onRescan={startScanner}
734	              onSaveOffline={(form) => saveOfflineQr(currentCard, form)}
735	              showToast={showToast}
736	            />
737	          </div>
738	        ) : null}
739	      </div>
740	    </div>
741	  );
742	}
743	
744	interface OfflineQrFormValue {
745	  visitorName: string;
746	  hostName: string;
747	  purpose: string;
748	  notes: string;
749	}
750	
751	function VisitorResultCard({
752	  card,
753	  t,
754	  onRetry,
755	  onRescan,
756	  onSaveOffline,
757	  showToast,
758	}: {
759	  card: CurrentVisitorCard;
760	  t: (key: string) => string;
761	  onRetry: () => void;
762	  onRescan: () => void;
763	  onSaveOffline: (form: OfflineQrFormValue) => Promise<number | undefined>;
764	  showToast: (message: string, tone?: ToastTone, icon?: IconName) => void;
765	}) {
766	  const [offlineForm, setOfflineForm] = useState({
767	    visitorName: card.visitorMeta?.visitorName ?? '',
768	    hostName: card.visitorMeta?.hostName ?? '',
769	    purpose: card.visitorMeta?.purpose ?? '',
770	    notes: '',
771	  });
772	  const data = card.data;
773	
774	  if (card.offlinePending && !card.offlineEventId) {
775	    return (
776	      <div className="visitor-card">
777	        <div className="vc-header">
778	          <div className="vc-name">{offlineForm.visitorName || t('qr_captured')}</div>
779	          <div className="vc-status-badge badge-pending">{t('offline_verify_later')}</div>
780	        </div>
781	        <div className="vc-details">
782	          {offlineForm.visitorName ? <DetailRow label={t('visitor_label')} value={offlineForm.visitorName} /> : null}
783	          {offlineForm.purpose ? <DetailRow label={t('purpose')} value={offlineForm.purpose} /> : null}
784	          {offlineForm.hostName ? <DetailRow label={t('host')} value={offlineForm.hostName} /> : null}
785	          {card.visitorMeta?.phone ? <DetailRow label={t('phone')} value={card.visitorMeta.phone} /> : null}
786	          <DetailRow label={t('qr_token')} value={card.token} small />
787	        </div>
788	        <div style={{ padding: '0 20px 12px', color: 'var(--text-secondary)', fontSize: 13 }}>{t('offline_server_hint')}</div>
789	        <div style={{ padding: '0 20px 16px', display: 'flex', flexDirection: 'column', gap: 12 }}>
790	          <input className="input-field" placeholder={t('visitor_name')} value={offlineForm.visitorName} onChange={(event) => setOfflineForm({ ...offlineForm, visitorName: event.target.value })} />
791	          <input className="input-field" placeholder={t('host')} value={offlineForm.hostName} onChange={(event) => setOfflineForm({ ...offlineForm, hostName: event.target.value })} />
792	          <input className="input-field" placeholder={t('purpose')} value={offlineForm.purpose} onChange={(event) => setOfflineForm({ ...offlineForm, purpose: event.target.value })} />
793	          <textarea className="input-field" placeholder={t('notes_optional')} style={{ minHeight: 80, paddingTop: 12 }} value={offlineForm.notes} onChange={(event) => setOfflineForm({ ...offlineForm, notes: event.target.value })} />
794	        </div>
795	        <div className="vc-actions">
796	          <button className="btn-checkin" type="button" onClick={() => void onSaveOffline(offlineForm)}>{t('save_offline')}</button>
797	          <button className="btn-secondary" type="button" onClick={onRetry}>{t('retry')}</button>
798	          <button className="btn-secondary" type="button" onClick={onRescan}>{t('scan_qr')}</button>
799	        </div>
800	      </div>
801	    );
802	  }
803	
804	  if (card.offlinePending && card.offlineEventId) {
805	    const event = {
806	      offlineEventId: card.offlineEventId,
807	      eventType: 'qr_checkin_capture',
808	      qrToken: card.token,
809	      visitorName: card.data?.invitation?.visitor_name || card.visitorMeta?.visitorName || undefined,
810	      hostName: card.data?.invitation?.host_employee_name || card.visitorMeta?.hostName || undefined,
811	      purpose: card.data?.invitation?.purpose || card.visitorMeta?.purpose || undefined,
812	    } as OfflineEventRecord;
813	    return (
814	      <div className="visitor-card">
815	        <div className="vc-header">
816	          <div className="vc-name">{event.visitorName || event.qrToken || t('offline_event_saved')}</div>
817	          <div className="vc-status-badge badge-pending">{t('sync_pending')}</div>
818	        </div>
819	        <div className="vc-details">
820	          <DetailRow label={t('offline_id')} value={event.offlineEventId} small />
821	          {event.hostName ? <DetailRow label={t('host')} value={event.hostName} /> : null}
822	          {event.purpose ? <DetailRow label={t('purpose')} value={event.purpose} /> : null}
823	        </div>
824	        <div style={{ padding: '0 20px 12px', color: 'var(--text-secondary)', fontSize: 13 }}>{t('offline_sync_hint')}</div>
825	        <div className="vc-actions">
826	          <button className="btn-secondary" type="button" onClick={onRescan}>{t('scan_qr')}</button>
827	        </div>
828	      </div>
829	    );
830	  }
831	
832	  if (!data?.invitation) {
833	    const errorCode = data?.errorCode ?? 'not_found';
834	    return (
835	      <div className="visitor-card visitor-card-rejected" style={{ textAlign: 'center', padding: '32px 20px' }}>
836	        <div style={{ fontSize: 48, marginBottom: 12, color: 'var(--red)' }}><IconGlyph name={errorIcon(errorCode)} /></div>
837	        <div className="vc-status-badge badge-rejected" style={{ display: 'inline-block', marginBottom: 12 }}>{errorLabel(errorCode, t)}</div>
838	        <div style={{ color: 'var(--text-secondary)', fontSize: 14 }}>{data?.errorMessage ?? ''}</div>
839	        <button className="btn-secondary" style={{ marginTop: 20, width: '100%' }} type="button" onClick={onRescan}>{t('scan_qr')}</button>
840	      </div>
841	    );
842	  }
843	
844	  const inv = data.invitation as unknown as Record<string, string | number | null | undefined>;
845	  const verificationError = data.valid === false ? data.errorCode : null;
846	  const approvalStatus = String(inv.approval_status ?? 'expired');
847	  const badgeKey = verificationError === 'not_yet_valid'
848	    ? 'pending'
849	    : verificationError === 'already_used'
850	      ? 'expired'
851	      : approvalStatus === 'approved'
852	        ? 'approved'
853	        : approvalStatus === 'pending'
854	          ? 'pending'
