function ScannerScreen({
  t,
  showToast,
  pendingCount,
  syncInProgress,
  online,
  attemptQueueSync,
  refreshPendingCount,
}: {
  t: (key: string) => string;
  showToast: (message: string, tone?: ToastTone, icon?: IconName) => void;
  pendingCount: number;
  syncInProgress: boolean;
  online: boolean;
  attemptQueueSync: (options?: SyncOptions) => Promise<SyncSummary | null>;
  refreshPendingCount: () => Promise<number>;
}) {
  const [scannerActive, setScannerActive] = useState(true);
  const [restartKey, setRestartKey] = useState(0);
  const [loading, setLoading] = useState(false);
  const [currentCard, setCurrentCard] = useState<CurrentVisitorCard | null>(null);

  const startScanner = useCallback(() => {
    setCurrentCard(null);
    setLoading(false);
    setScannerActive(true);
    setRestartKey((value) => value + 1);
  }, []);

  async function handleScannedValue(value: string) {
    setScannerActive(false);
    const extracted = extractToken(value);
    if (!extracted.token) return;
    await handleQRResult(extracted);
  }

  async function handleQRResult(extracted: ExtractedQrToken) {
    setLoading(true);
    const res = await verifyQr(extracted.token);
    setLoading(false);

    if (res.offline) {
      const expectedMatch = findCachedExpectedGuestByToken(extracted.token);
      const visitorMeta = expectedMatch
        ? expectedGuestToMeta(expectedMatch)
        : extracted.visitorMeta;
      if (expectedMatch) showToast(t('expected_match_found'), 'info', 'search');
      setCurrentCard({ token: extracted.token, offlinePending: true, visitorMeta });
      return;
    }
    if (!res.data?.invitation) {
      setCurrentCard({ token: extracted.token, data: res.data });
      return;
    }
    const card = { token: extracted.token, data: res.data };
    setCurrentCard(card);
    if (
      res.ok &&
      res.data.valid &&
      res.data.invitation.approval_status === 'approved' &&
      !res.data.session
    ) {
      showToast(t('auto_checking_in'), 'info', 'check');
      await checkIn(card);
    }
  }

  async function checkIn(card: CurrentVisitorCard) {
    const res = await checkInVisitor(card.token);
    if (res.ok) {
      showToast(t('checked_in'), 'success', 'check');
      setCurrentCard({ ...card, data: { ...card.data!, session: res.data.session } });
      return;
    }
    if (res.offline) {
      const invitation = card.data?.invitation;
      const event = createOfflineEvent({
        eventType: 'qr_checkin_capture',
        ...getGuardContext(),
        qrToken: card.token,
        scannedRawValue: card.token,
        visitorName: invitation?.visitor_name || undefined,
        hostName: invitation?.host_employee_name || undefined,
        purpose: invitation?.purpose || undefined,
      }) as OfflineEventRecord;
      const recordId = await enqueue(event) as number;
      await refreshPendingCount();
      void registerBackgroundSync();
      setCurrentCard({ ...card, offlinePending: true, offlineEventId: event.offlineEventId });
      showToast(t('checkin_saved_offline'), 'info', 'offline');
      return;
    }
    showToast(res.data?.errorMessage ?? t('error'), 'error', 'alert');
  }

  async function saveOfflineQr(card: CurrentVisitorCard, form: OfflineQrFormValue) {
    const event = createOfflineEvent({
      eventType: 'qr_checkin_capture',
      ...getGuardContext(),
      qrToken: card.token,
      scannedRawValue: card.token,
      visitorName: form.visitorName || undefined,
      hostName: form.hostName || undefined,
      purpose: form.purpose || undefined,
      notes: form.notes || undefined,
    }) as OfflineEventRecord;
    const recordId = await enqueue(event) as number;
    await refreshPendingCount();
    void registerBackgroundSync();
    setCurrentCard({ ...card, offlinePending: true, offlineEventId: event.offlineEventId });
    showToast(t('checkin_saved_offline'), 'info', 'offline');
    return recordId;
  }

  return (
    <div id="scanner-screen" className="screen active" aria-label={t('aria_scanner')}>
      <Topbar title={t('page_scan')} icon="camera">
        <button className="icon-btn" type="button" title={t('aria_restart_camera')} aria-label={t('aria_restart_camera')} onClick={startScanner}>
          <IconGlyph name="refresh" />
        </button>
      </Topbar>
      <div className="scanner-body">
        <QrScanner active={scannerActive} restartKey={restartKey} onResult={handleScannedValue} />
        <div className="scan-hint">{t('scan_hint')}</div>
        {(syncInProgress || pendingCount > 0) ? (
          <ScannerSyncPanel
            t={t}
            pendingCount={pendingCount}
            syncInProgress={syncInProgress}
            online={online}
            attemptQueueSync={attemptQueueSync}
          />
        ) : null}
        {loading ? <div style={{ textAlign: 'center', padding: 24 }}><div className="spinner" style={{ margin: '0 auto' }} /></div> : null}
        {currentCard ? (
          <div id="visitor-card-section">
            <VisitorResultCard
              card={currentCard}
              t={t}
              onRetry={() => handleQRResult({ token: currentCard.token, visitorMeta: currentCard.visitorMeta ?? null })}
              onRescan={startScanner}
              onSaveOffline={(form) => saveOfflineQr(currentCard, form)}
              showToast={showToast}
            />
          </div>
        ) : null}
      </div>
    </div>
  );
}

interface OfflineQrFormValue {
  visitorName: string;
  hostName: string;
  purpose: string;
  notes: string;
}

function VisitorResultCard({
  card,
  t,
  onRetry,
  onRescan,
  onSaveOffline,
  showToast,
}: {
  card: CurrentVisitorCard;
  t: (key: string) => string;
  onRetry: () => void;
  onRescan: () => void;
  onSaveOffline: (form: OfflineQrFormValue) => Promise<number | undefined>;
  showToast: (message: string, tone?: ToastTone, icon?: IconName) => void;
}) {
  const [offlineForm, setOfflineForm] = useState({
    visitorName: card.visitorMeta?.visitorName ?? '',
    hostName: card.visitorMeta?.hostName ?? '',
    purpose: card.visitorMeta?.purpose ?? '',
    notes: '',
  });
  const data = card.data;

  if (card.offlinePending && !card.offlineEventId) {
    return (
      <div className="visitor-card">
        <div className="vc-header">
          <div className="vc-name">{offlineForm.visitorName || t('qr_captured')}</div>
          <div className="vc-status-badge badge-pending">{t('offline_verify_later')}</div>
        </div>
        <div className="vc-details">
          {offlineForm.visitorName ? <DetailRow label={t('visitor_label')} value={offlineForm.visitorName} /> : null}
          {offlineForm.purpose ? <DetailRow label={t('purpose')} value={offlineForm.purpose} /> : null}
          {offlineForm.hostName ? <DetailRow label={t('host')} value={offlineForm.hostName} /> : null}
          {card.visitorMeta?.phone ? <DetailRow label={t('phone')} value={card.visitorMeta.phone} /> : null}
          <DetailRow label={t('qr_token')} value={card.token} small />
        </div>
        <div style={{ padding: '0 20px 12px', color: 'var(--text-secondary)', fontSize: 13 }}>{t('offline_server_hint')}</div>
        <div style={{ padding: '0 20px 16px', display: 'flex', flexDirection: 'column', gap: 12 }}>
          <input className="input-field" placeholder={t('visitor_name')} value={offlineForm.visitorName} onChange={(event) => setOfflineForm({ ...offlineForm, visitorName: event.target.value })} />
          <input className="input-field" placeholder={t('host')} value={offlineForm.hostName} onChange={(event) => setOfflineForm({ ...offlineForm, hostName: event.target.value })} />
          <input className="input-field" placeholder={t('purpose')} value={offlineForm.purpose} onChange={(event) => setOfflineForm({ ...offlineForm, purpose: event.target.value })} />
          <textarea className="input-field" placeholder={t('notes_optional')} style={{ minHeight: 80, paddingTop: 12 }} value={offlineForm.notes} onChange={(event) => setOfflineForm({ ...offlineForm, notes: event.target.value })} />
        </div>
        <div className="vc-actions">
          <button className="btn-checkin" type="button" onClick={() => void onSaveOffline(offlineForm)}>{t('save_offline')}</button>
          <button className="btn-secondary" type="button" onClick={onRetry}>{t('retry')}</button>
          <button className="btn-secondary" type="button" onClick={onRescan}>{t('scan_qr')}</button>
        </div>
      </div>
    );
  }

  if (card.offlinePending && card.offlineEventId) {
    const event = {
      offlineEventId: card.offlineEventId,
      eventType: 'qr_checkin_capture',
      qrToken: card.token,
      visitorName: card.data?.invitation?.visitor_name || card.visitorMeta?.visitorName || undefined,
      hostName: card.data?.invitation?.host_employee_name || card.visitorMeta?.hostName || undefined,
      purpose: card.data?.invitation?.purpose || card.visitorMeta?.purpose || undefined,
    } as OfflineEventRecord;
    return (
      <div className="visitor-card">
        <div className="vc-header">
          <div className="vc-name">{event.visitorName || event.qrToken || t('offline_event_saved')}</div>
          <div className="vc-status-badge badge-pending">{t('sync_pending')}</div>
        </div>
        <div className="vc-details">
          <DetailRow label={t('offline_id')} value={event.offlineEventId} small />
          {event.hostName ? <DetailRow label={t('host')} value={event.hostName} /> : null}
          {event.purpose ? <DetailRow label={t('purpose')} value={event.purpose} /> : null}
        </div>
        <div style={{ padding: '0 20px 12px', color: 'var(--text-secondary)', fontSize: 13 }}>{t('offline_sync_hint')}</div>
        <div className="vc-actions">
          <button className="btn-secondary" type="button" onClick={onRescan}>{t('scan_qr')}</button>
        </div>
      </div>
    );
  }

  if (!data?.invitation) {
    const errorCode = data?.errorCode ?? 'not_found';
    return (
      <div className="visitor-card visitor-card-rejected" style={{ textAlign: 'center', padding: '32px 20px' }}>
        <div style={{ fontSize: 48, marginBottom: 12, color: 'var(--red)' }}><IconGlyph name={errorIcon(errorCode)} /></div>
        <div className="vc-status-badge badge-rejected" style={{ display: 'inline-block', marginBottom: 12 }}>{errorLabel(errorCode, t)}</div>
        <div style={{ color: 'var(--text-secondary)', fontSize: 14 }}>{data?.errorMessage ?? ''}</div>
        <button className="btn-secondary" style={{ marginTop: 20, width: '100%' }} type="button" onClick={onRescan}>{t('scan_qr')}</button>
      </div>
    );
  }

  const inv = data.invitation as unknown as Record<string, string | number | null | undefined>;
  const verificationError = data.valid === false ? data.errorCode : null;
  const approvalStatus = String(inv.approval_status ?? 'expired');
  const badgeKey = verificationError === 'not_yet_valid'
    ? 'pending'
    : verificationError === 'already_used'
      ? 'expired'
      : approvalStatus === 'approved'
        ? 'approved'
        : approvalStatus === 'pending'
          ? 'pending'
          : approvalStatus === 'rejected'
            ? 'rejected'
            : 'expired';
  const badgeClass = badgeKey === 'approved' ? 'badge-approved' : badgeKey === 'pending' ? 'badge-pending' : badgeKey === 'rejected' ? 'badge-rejected' : 'badge-expired';
  const statusLabel = verificationError ? errorLabel(verificationError, t) : t(approvalStatus === 'approved' ? 'approved' : approvalStatus === 'pending' ? 'pending' : approvalStatus === 'rejected' ? 'rejected' : 'expired');
  const noteText = data.session ? t('already_checked_in') : data.errorMessage;

  return (
    <div className={`visitor-card visitor-card-${badgeKey}`}>
      <div className="vc-header">
        <div className="vc-name">{inv.visitor_name}</div>
        <div className={`vc-status-badge ${badgeClass}`}>{statusLabel}</div>
      </div>
      <div className="vc-details">
        {inv.purpose ? <DetailRow label={t('purpose')} value={String(inv.purpose)} /> : null}
        {inv.host_employee_name ? <DetailRow label={t('host')} value={String(inv.host_employee_name)} /> : null}
        {inv.valid_from ? <DetailRow label={t('valid_from')} value={formatPassDateTime(String(inv.valid_from), langFromStorage())} /> : null}
        {(inv.valid_until || inv.expires_at) ? <DetailRow label={t('valid_until')} value={formatPassDateTime(String(inv.valid_until || inv.expires_at), langFromStorage())} /> : null}
      </div>
      {noteText ? <div className="inline-note warning"><IconGlyph name="alert" /><span>{noteText}</span></div> : null}
      <div className="vc-actions">
        <button className="btn-secondary" type="button" onClick={onRescan}>{t('scan_qr')}</button>
      </div>
    </div>
  );
}

function VisitorsScreen({ t, showToast, online, refreshPendingCount }: { t: (key: string) => string; showToast: (message: string, tone?: ToastTone, icon?: IconName) => void; online: boolean; refreshPendingCount: () => Promise<number> }) {
  const [sessions, setSessions] = useState<VisitorSession[]>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [exitTarget, setExitTarget] = useState<VisitorSession | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    const res = await getActiveVisitors();
    setLoading(false);
    if (!res.ok) {
      if (res.status === 401) showToast(t('visitors_error_auth'), 'error', 'alert');
      else if (res.offline) showToast(t('visitors_error_offline'), 'error', 'wifi-off');
      else showToast(t('visitors_error_generic'), 'error', 'alert');
      return;
    }
    setSessions(res.data.sessions ?? []);
  }, [showToast, t]);

  useEffect(() => {
    void load();
  }, [load, online]);

  const filtered = useMemo(() => {
    const needle = search.trim().toLowerCase();
    if (!needle) return sessions;
    return sessions.filter((session) => [session.visitor_name, session.host_employee_name, session.purpose].filter(Boolean).join(' ').toLowerCase().includes(needle));
  }, [search, sessions]);

  async function confirmExit() {
    if (!exitTarget) return;
    const res = await checkOutVisitor(exitTarget.id);
    const target = exitTarget;
    setExitTarget(null);
    if (res.ok) {
      showToast(`${t('checked_out')} — ${res.data.durationMinutes ?? 0} ${t('minutes')}`, 'success', 'door');
      void load();
      return;
    }
    if (res.offline) {
      const event = createOfflineEvent({
        eventType: 'checkout',
        ...getGuardContext(),
        sessionId: target.id,
        visitorName: target.visitor_name,
        checkoutTime: new Date().toISOString(),
      }) as OfflineEventRecord;
      await enqueue(event);
      await refreshPendingCount();
      void registerBackgroundSync();
      showToast(t('exit_saved_offline'), 'info', 'offline');
      return;
    }
    showToast(res.data?.errorMessage ?? t('error'), 'error', 'alert');
  }

  return (
    <div id="visitors-screen" className="screen active" aria-label={t('aria_active_visitors')}>
      <Topbar title={t('page_visitors')} icon="people">
        <button className="icon-btn" type="button" title={t('refresh')} onClick={() => void load()}><IconGlyph name="refresh" /></button>
      </Topbar>
      <div className="visitors-body">
        <div className="search-bar">
          <IconGlyph name="search" />
          <input type="search" placeholder={t('visitor_search_placeholder')} value={search} onChange={(event) => setSearch(event.target.value)} />
        </div>
        <div id="active-visitors-list">
          {loading ? <div style={{ textAlign: 'center', padding: 32 }}><div className="spinner" style={{ margin: '0 auto' }} /></div> : null}
          {!loading && sessions.length === 0 ? <EmptyState icon="people" message={t('no_active_visitors')} /> : null}
          {!loading && sessions.length > 0 && filtered.length === 0 ? <EmptyState icon="search" message={t('no_matching_visitors')} /> : null}
          {!loading && filtered.map((session) => (
            <div className="active-visitor-card" key={session.id}>
              <div className="avc-avatar"><IconGlyph name="person" /></div>
              <div className="avc-info">
                <div className="avc-name">{session.visitor_name}</div>
                <div className="avc-meta">{session.host_employee_name ? `${t('host')}: ${session.host_employee_name} · ` : ''}{formatDuration(session.checkin_time, t)}</div>
              </div>
              <button className="btn-exit" type="button" onClick={() => setExitTarget(session)}>{t('mark_exit')}</button>
            </div>
          ))}
        </div>
