1125	function readStaffCacheFromStorage(): { staff: StaffMember[]; loadedAt: number } | null {
1126	  try {
1127	    const raw = localStorage.getItem(STAFF_CACHE_KEY);
1128	    if (!raw) return null;
1129	    const parsed = JSON.parse(raw) as { staff: StaffMember[]; loadedAt: number };
1130	    if (!Array.isArray(parsed.staff) || typeof parsed.loadedAt !== 'number') return null;
1131	    return parsed;
1132	  } catch {
