1140	  }
1141	  if (staffIndexPromise) return staffIndexPromise;
1142	
1143	  staffIndexPromise = (async () => {
1144	    // Serve stale cache from localStorage immediately so the first
1145	    // keystroke after a refresh is still instant; refresh in background.
1146	    const stored = readStaffCacheFromStorage();
1147	    if (stored && !staffIndexCache) {
1148	      staffIndexCache = { index: buildNameIndex(stored.staff, (s) => s.name), loadedAt: stored.loadedAt };
