  const selectedPurpose = manualPurposeOptions.find((option) => option.value === form.purposeType) ?? manualPurposeOptions[0];
  const requiresHost = form.purposeType === 'meeting' || form.purposeType === 'interview';
  const requiresCustomPurpose = form.purposeType === 'other';

  async function submit(event: FormEvent) {
    event.preventDefault();
    const name = form.visitor_name.trim();
    if (!name) return;
    const purpose = requiresCustomPurpose ? form.customPurpose.trim() : selectedPurpose.backendLabel;
    const host = form.host.trim();
    if (requiresCustomPurpose && !purpose) {
      setError(t('error_enter_purpose'));
      return;
    }
    if (requiresHost && !host) {
      setError(t('error_select_host'));
      return;
    }
    setSubmitting(true);
    setError('');

    const entryData = {
      visitor_name: name,
      phone: form.phone.trim() || undefined,
      email: form.email.trim() || undefined,
      purpose,
      host: host || undefined,
    };

    if (!online) {
      await queueManualEntry(entryData);
      setSubmitting(false);
      return;
    }

    const res = await manualEntry(entryData);
    setSubmitting(false);
    if (res.ok) {
      showToast(`${name} ${t('checked_in')}`, 'success', 'check');
      setForm({ visitor_name: '', phone: '', email: '', purposeType: 'meeting', customPurpose: '', host: '' });
    } else if (res.offline) {
      await queueManualEntry(entryData);
    } else {
      setError(res.data?.error ?? t('error'));
    }
  }

  async function queueManualEntry(entryData: { visitor_name: string; phone?: string; email?: string; purpose?: string; host?: string }) {
    const event = createOfflineEvent({
      eventType: 'manual_checkin',
      ...getGuardContext(),
      visitorName: entryData.visitor_name,
      phone: entryData.phone,
      email: entryData.email,
      purpose: entryData.purpose,
      hostName: entryData.host,
    }) as OfflineEventRecord;
    const recordId = await enqueue(event) as number;
    await refreshPendingCount();
    void registerBackgroundSync();
    void recordId;
    showToast(t('saved_offline'), 'info', 'offline');
    setForm({ visitor_name: '', phone: '', email: '', purposeType: 'meeting', customPurpose: '', host: '' });
  }

  return (
    <div id="manual-screen" className="screen active" aria-label={t('aria_manual_entry')}>
      <Topbar title={t('page_entry')} icon="pencil" />
      <div className="manual-body" id="manual-body">
        <form className="manual-form-card" noValidate onSubmit={submit}>
          <label className="input-group">
            <span className="input-label">{t('visitor_name')} <span style={{ color: 'var(--red)' }}>*</span></span>
            <input className="input-field" value={form.visitor_name} onChange={(event) => setForm({ ...form, visitor_name: event.target.value })} placeholder={t('placeholder_full_name')} required />
          </label>
          <label className="input-group">
            <span className="input-label">{t('phone')}</span>
            <input className="input-field" value={form.phone} onChange={(event) => setForm({ ...form, phone: event.target.value })} type="tel" placeholder="+91 98765 43210" />
          </label>
          <label className="input-group">
            <span className="input-label">Email</span>
            <input className="input-field" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} type="email" placeholder="visitor@example.com" />
          </label>
          <label className="input-group">
            <span className="input-label">{t('purpose')}</span>
            <select
              className="input-field"
              value={form.purposeType}
              onChange={(event) => setForm({
                ...form,
                purposeType: event.target.value as ManualPurpose,
                customPurpose: event.target.value === 'other' ? form.customPurpose : '',
                host: event.target.value === 'delivery' || event.target.value === 'other' ? '' : form.host,
              })}
            >
              {manualPurposeOptions.map((option) => <option key={option.value} value={option.value}>{t(option.labelKey)}</option>)}
            </select>
          </label>
          {requiresCustomPurpose ? (
            <label className="input-group">
              <span className="input-label">{t('purpose_details')} <span style={{ color: 'var(--red)' }}>*</span></span>
              <input className="input-field" value={form.customPurpose} onChange={(event) => setForm({ ...form, customPurpose: event.target.value })} placeholder={t('placeholder_custom_purpose')} required />
            </label>
          ) : null}
          {requiresHost ? (
            <HostSuggestInput
              t={t}
              value={form.host}
              onChange={(host) => setForm({ ...form, host })}
              required
            />
          ) : null}
          <div style={{ color: 'var(--red)', fontSize: 13, minHeight: 20 }}>{error}</div>
          <button className="btn-primary" type="submit" disabled={submitting}>{submitting ? <span className="spinner" style={{ margin: '0 auto', width: 20, height: 20 }} /> : t('manual_entry_submit')}</button>
        </form>
      </div>
    </div>
  );
}

// In-memory + localStorage cache of the full staff directory, indexed for
// the client-side fuzzy matcher. Fetched once per session (or whenever the
// cache is older than STAFF_CACHE_TTL_MS). Keeps host autocomplete instant
// and offline-friendly — no per-keystroke network call.
const STAFF_CACHE_KEY = 'guard_staff_directory_v1';
const STAFF_CACHE_TTL_MS = 6 * 60 * 60 * 1000; // 6h
let staffIndexCache: { index: NameIndexEntry<StaffMember>[]; loadedAt: number } | null = null;
let staffIndexPromise: Promise<NameIndexEntry<StaffMember>[]> | null = null;

function readStaffCacheFromStorage(): { staff: StaffMember[]; loadedAt: number } | null {
  try {
    const raw = localStorage.getItem(STAFF_CACHE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as { staff: StaffMember[]; loadedAt: number };
    if (!Array.isArray(parsed.staff) || typeof parsed.loadedAt !== 'number') return null;
    return parsed;
  } catch {
    return null;
  }
}

async function loadStaffIndex(): Promise<NameIndexEntry<StaffMember>[]> {
  if (staffIndexCache && Date.now() - staffIndexCache.loadedAt < STAFF_CACHE_TTL_MS) {
    return staffIndexCache.index;
  }
  if (staffIndexPromise) return staffIndexPromise;

  staffIndexPromise = (async () => {
    // Serve stale cache from localStorage immediately so the first
    // keystroke after a refresh is still instant; refresh in background.
    const stored = readStaffCacheFromStorage();
    if (stored && !staffIndexCache) {
      staffIndexCache = { index: buildNameIndex(stored.staff, (s) => s.name), loadedAt: stored.loadedAt };
    }

    const res = await searchStaff('');
    if (res.ok) {
      const staff = res.data.results ?? [];
      staffIndexCache = { index: buildNameIndex(staff, (s) => s.name), loadedAt: Date.now() };
      try {
        localStorage.setItem(STAFF_CACHE_KEY, JSON.stringify({ staff, loadedAt: staffIndexCache.loadedAt }));
      } catch {
        // storage quota or private mode — ignore
      }
    }
    staffIndexPromise = null;
    return staffIndexCache?.index ?? [];
  })();

  return staffIndexPromise;
}

function HostSuggestInput({
  t,
  value,
  onChange,
  required,
}: {
  t: (key: string) => string;
  value: string;
  onChange: (value: string) => void;
  required?: boolean;
}) {
  const [index, setIndex] = useState<NameIndexEntry<StaffMember>[]>(() => staffIndexCache?.index ?? []);
  const [loading, setLoading] = useState(() => !staffIndexCache);
  const [focused, setFocused] = useState(false);

  useEffect(() => {
    let cancelled = false;
    void loadStaffIndex().then((next) => {
      if (cancelled) return;
      setIndex(next);
      setLoading(false);
    });
    return () => {
      cancelled = true;
    };
  }, []);

  // Defer the ranking off the keystroke so typing never blocks on the fuzzy
  // matcher, even on a large directory / low-end tablet. React keeps the
  // input responsive and recomputes suggestions when it gets a free moment.
  const deferredValue = useDeferredValue(value);
  const suggestions = useMemo(() => {
    const query = deferredValue.trim();
    if (query.length < 2 || index.length === 0) return [];
    return rankByName(index, query, 5).map((m) => m.item);
  }, [index, deferredValue]);

  // "Stale" while the deferred ranking is catching up to the latest keystroke.
  const ranking = value !== deferredValue && value.trim().length >= 2;
  const showSuggestions = focused && (loading || ranking || suggestions.length > 0);

  return (
    <label className="input-group host-suggest-group">
      <span className="input-label">{t('host')} {required ? <span style={{ color: 'var(--red)' }}>*</span> : null}</span>
      <input
        className="input-field"
        value={value}
        onBlur={() => window.setTimeout(() => setFocused(false), 120)}
        onChange={(event) => {
          setFocused(true);
          onChange(event.target.value);
        }}
        onFocus={() => setFocused(true)}
        placeholder="Search employee name"
        required={required}
      />
      {showSuggestions ? (
        <div className="host-suggestions">
          {loading ? <div className="host-suggestion muted">{t('loading')}</div> : null}
          {!loading && ranking && suggestions.length === 0 ? (
            <div className="host-suggestion muted">{t('loading')}</div>
          ) : null}
          {!loading && suggestions.map((person) => (
            <button
              className="host-suggestion"
              key={person.id}
              type="button"
              onMouseDown={(event) => event.preventDefault()}
              onClick={() => {
                onChange(person.name);
                setFocused(false);
              }}
            >
              <span>{person.name}</span>
              <small>{[person.role, person.department].filter(Boolean).join(' · ') || person.employeeCode}</small>
            </button>
          ))}
        </div>
      ) : null}
    </label>
  );
}

function ExpectedGuestsScreen({ t, showToast, online }: { t: (key: string) => string; showToast: (message: string, tone?: ToastTone, icon?: IconName) => void; online: boolean }) {
  const [query, setQuery] = useState('');
  const [guests, setGuests] = useState<ExpectedGuest[]>(() => loadCachedExpectedGuests().guests);
  const [generatedAt, setGeneratedAt] = useState(() => loadCachedExpectedGuests().generatedAt);
  const [loading, setLoading] = useState(false);
  const [expandedGuestId, setExpandedGuestId] = useState<string | null>(null);

  const load = useCallback(async () => {
    if (!online) {
      const cached = loadCachedExpectedGuests();
      setGuests(cached.guests);
      setGeneratedAt(cached.generatedAt);
      showToast(t('expected_offline_using_cache'), 'info', 'offline');
      return;
    }

    setLoading(true);
    const res = await getExpectedGuests();
    setLoading(false);
    if (!res.ok) {
      const cached = loadCachedExpectedGuests();
      setGuests(cached.guests);
      setGeneratedAt(cached.generatedAt);
      showToast(res.offline ? t('expected_offline_using_cache') : (res.data?.error || t('error')), res.offline ? 'info' : 'error', res.offline ? 'offline' : 'alert');
      return;
    }
    const next = res.data.guests ?? [];
    saveCachedExpectedGuests(next, res.data.generatedAt);
    setGuests(next);
    setGeneratedAt(res.data.generatedAt);
    showToast(t('expected_cached'), 'success', 'check');
  }, [online, showToast, t]);

  useEffect(() => {
    void load();
  }, [load]);

  const filtered = useMemo(() => {
    const needle = query.trim().toLowerCase();
    if (!needle) return guests;
    return guests.filter((guest) => [
      guest.visitorName,
      guest.visitorPhone,
      guest.visitorEmail,
      guest.hostName,
      guest.purpose,
      guest.qrToken,
    ].filter(Boolean).join(' ').toLowerCase().includes(needle));
  }, [guests, query]);

  return (
    <div id="expected-screen" className="screen active" aria-label={t('aria_expected_guests')}>
      <Topbar title={t('expected_guests')} icon="search">
        <button className="icon-btn" type="button" title={t('refresh')} onClick={() => void load()}><IconGlyph name="refresh" /></button>
      </Topbar>
      <div className="staff-body">
        <div className="inline-note" style={{ marginBottom: 12 }}>
          <IconGlyph name={online ? 'wifi' : 'wifi-off'} />
          <span>{online ? t('expected_refresh_hint') : t('expected_offline_using_cache')}</span>
        </div>
        <div className="search-bar">
          <IconGlyph name="search" />
          <input type="search" placeholder={t('expected_search_placeholder')} value={query} onChange={(event) => setQuery(event.target.value)} />
        </div>
        <div style={{ color: 'var(--text-secondary)', fontSize: 12, padding: '4px 4px 12px' }}>
          {generatedAt ? `${t('expected_cached')} · ${formatTimeOnly(generatedAt)}` : t('expected_refresh_hint')}
        </div>
        <div id="expected-results">
          {loading ? <div className="empty-state" style={{ padding: 24 }}>{t('loading')}</div> : null}
          {!loading && guests.length === 0 ? <EmptyState icon="search" message={t('expected_none')} /> : null}
          {!loading && guests.length > 0 && filtered.length === 0 ? <EmptyState icon="search" message={t('no_results')} /> : null}
          {!loading && filtered.map((guest) => {
            const expanded = expandedGuestId === guest.id;
            const startLabel = guest.validFrom
              ? formatPassDateTime(guest.validFrom, langFromStorage())
              : [guest.expectedDate, guest.expectedTime].filter(Boolean).join(' ');
            const endLabel = guest.validUntil ? formatPassDateTime(guest.validUntil, langFromStorage()) : '';
            return (
              <button
                aria-expanded={expanded}
                className="staff-card expected-guest-card"
                key={guest.id}
                type="button"
                onClick={() => setExpandedGuestId(expanded ? null : guest.id)}
              >
                <div className="staff-card-main">
                  <div className="staff-avatar"><span className="staff-initials">{getInitials(guest.visitorName)}</span></div>
                  <div className="staff-info">
                    <div className="staff-name">{guest.visitorName}</div>
                    <div className="staff-role">{guest.hostName ? `${t('host')}: ${guest.hostName}` : guest.purpose || 'Visitor'}</div>
                    <div className="staff-attendance-meta">
                      <span className={`status-dot status-dot-${guest.tokenUsed ? 'in' : 'out'}`} />
                      {guest.expectedTime || guest.approvalStatus}
                    </div>
                  </div>
                  <div className={`vc-status-badge ${guest.approvalStatus === 'approved' ? 'badge-approved' : guest.approvalStatus === 'pending' ? 'badge-pending' : 'badge-expired'}`}>
                    {guest.tokenUsed ? t('already_used') : guest.approvalStatus === 'pending' ? t('awaiting_approval') : t(guest.approvalStatus)}
                  </div>
                </div>
                {expanded ? (
                  <div className="expected-guest-details">
                    {guest.hostName ? <DetailRow label={t('host')} value={guest.hostName} /> : null}
                    {startLabel ? <DetailRow label={t('valid_from')} value={startLabel} /> : null}
                    {endLabel ? <DetailRow label={t('valid_until')} value={endLabel} /> : null}
                    {guest.visitorPhone ? <DetailRow label={t('phone')} value={guest.visitorPhone} /> : null}
                    {guest.purpose ? <DetailRow label={t('purpose')} value={guest.purpose} /> : null}
                  </div>
                ) : null}
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}

function StaffScreen({ t, showToast }: { t: (key: string) => string; showToast: (message: string, tone?: ToastTone, icon?: IconName) => void }) {
  const [query, setQuery] = useState('');
  const [staff, setStaff] = useState<StaffMember[]>([]);
  const [loading, setLoading] = useState(false);

  const load = useCallback(async (value: string) => {
    setLoading(true);
    const res = await searchStaff(value);
    setLoading(false);
    if (!res.ok) {
      showToast(res.data?.error || t('error'), 'error', 'alert');
      setStaff([]);
      return;
    }
    setStaff(res.data.results ?? []);
  }, [showToast, t]);

  useEffect(() => {
    const timer = window.setTimeout(() => void load(query.trim()), 220);
    return () => window.clearTimeout(timer);
  }, [load, query]);

  async function updateAttendance(person: StaffMember) {
    const action = person.attendanceStatus === 'in' ? 'out' : 'in';
    const response = action === 'in' ? await markStaffIn(person.id) : await markStaffOut(person.id);
    if (!response.ok) {
      showToast(response.data?.error || t('error'), 'error', 'alert');
      return;
    }
    showToast(action === 'in' ? `${t('staff_marked_in')} ${person.name}` : `${t('staff_marked_out')} ${person.name}`, 'success', action === 'in' ? 'check' : 'door');
    await load(query.trim());
  }

  return (
    <div id="staff-screen" className="screen active" aria-label={t('aria_staff_search')}>
      <Topbar title={t('page_search')} icon="person" />
      <div className="staff-body">
        <div className="search-bar">
          <IconGlyph name="search" />
          <input type="search" placeholder={t('staff_search_placeholder')} value={query} onChange={(event) => setQuery(event.target.value)} />
        </div>
        <div id="staff-results">
          {loading ? <div className="empty-state" style={{ padding: 24 }}>{t('loading')}</div> : null}
          {!loading && staff.length === 0 ? <div className="empty-state" style={{ padding: 24 }}>{t('no_results')}</div> : null}
          {!loading && staff.map((person) => {
            const actionType = person.attendanceStatus === 'in' ? 'out' : 'in';
            const timeString = person.attendanceStatus === 'in' ? formatTimeOnly(person.markedInAt) : formatTimeOnly(person.markedOutAt);
            const timestampLabel = person.attendanceStatus === 'in' ? `IN ${timeString}`.trim() : `OUT ${timeString}`.trim();
            return (
              <div className="staff-card" key={person.id}>
                <div className="staff-card-main">
                  <StaffAvatar person={person} />
                  <div className="staff-info">
                    <div className="staff-name">{person.name}</div>
                    <div className="staff-role">{person.employeeCode || ''}</div>
                    <div className="staff-attendance-meta">
                      <span className={`status-dot status-dot-${actionType === 'in' ? 'out' : 'in'}`} />
                      {timestampLabel}
                    </div>
                  </div>
                  <button className={`btn-staff-action-inline ${actionType === 'in' ? 'btn-staff-in' : 'btn-staff-out'}`} type="button" onClick={() => void updateAttendance(person)}>
                    <IconGlyph name={actionType === 'in' ? 'check' : 'door'} /> {actionType === 'in' ? t('staff_mark_in') : t('staff_mark_out')}
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

