export async function handleCheckinRoutes(
  req: Request,
  pathname: string,
  method: string,
): Promise<Response | null> {
  const isVerify = pathname.startsWith("/api/visitor/verify/") && method === "GET";
  const isCheckin = pathname.startsWith("/api/visitor/checkin/") && method === "POST";
  const isCheckout = pathname.startsWith("/api/visitor/checkout/") && method === "POST";
  if (!isVerify && !isCheckin && !isCheckout) return null;

  const session = await guardFromRequest(req);
  if (!session) return json(401, { error: "Unauthorized" });

  if (isVerify) {
    const token = pathname.replace("/api/visitor/verify/", "");
    const result = await verifyQRToken(token);

    // Audited even when invalid -- a rejected scan is exactly the event
    // someone will later want to look up.
    await logAction({
      action: "qr_scanned",
      actorType: "guard",
      actor: session.guardName,
      channel: "pwa",
      invitationId: result.invitation?.id,
      metadata: { token, valid: result.valid, errorCode: result.errorCode },
    });

    // 400-with-body on invalid: see the header.
    return json(result.valid ? 200 : 400, result);
  }

  if (pathname === "/api/offline-events/sync" && method === "POST") {
    const session = await guardAuth(req);
    if (!session) return json(401, { error: "Unauthorized" });
    try {
      const body = await readBodyJson(req);
      const rawEvent = (body.event ?? body) as Record<string, unknown>;
      const event = normalizeOfflineSyncEvent({
        ...rawEvent,
        guardId: rawEvent.guardId ?? session.guardId,
        guardName: rawEvent.guardName ?? session.guardName,
      });
      const result = await processOfflineSyncEvent({ event, source: "pwa" });
      return json(result.status === "sync_failed" ? 500 : 200, result);
    } catch (error) {
      return json(400, { error: error instanceof Error ? error.message : String(error) });
    }
  }

  return null;
}

