function errorIcon(errorCode: string): IconName {
  if (errorCode === 'not_found') return 'search';
  if (errorCode === 'expired' || errorCode === 'not_yet_valid') return 'info';
  if (errorCode === 'already_used') return 'check';
  return 'x';
}

function errorLabel(errorCode: string, t: (key: string) => string) {
  const labels: Record<string, string> = {
    not_found: t('not_found'),
    expired: t('expired'),
    already_used: t('already_used'),
    rejected: t('rejected'),
    cancelled: t('cancelled'),
    not_yet_valid: t('not_yet_valid'),
  };
  return labels[errorCode] ?? 'ERROR';
}

function getInitials(name: string) {
  const parts = String(name ?? '').trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return 'NA';
  return parts.slice(0, 2).map((part) => part[0]?.toUpperCase() ?? '').join('');
}
