import { HeroAction } from '../../../components/HeroAction';
import { StatTile } from '../../../components/StatTile';
import { pendingCountOfKind } from '../../../db/outbox';
import { IconButton, spacing, Text } from '../../../design';
import { useT } from '../../../i18n';
import type { RootStackParamList } from '../../../navigation/types';
import { useTheme } from '../../../theme';
import { visitorApi } from '../api';
import { readExpected, saveExpected } from '../cache';

type Props = NativeStackScreenProps<RootStackParamList, 'GateHome'>;

/**
 * Visitor gate home. One obvious action (scan a pass) and four tiles, each
 * shown only if the person's role allows it.
 */
export function GateHomeScreen({ navigation }: Props) {
  const t = useT();
  const { palette } = useTheme();
  const can = useCan();
  const [insideCount, setInsideCount] = useState<number | undefined>();
  const [expectedCount, setExpectedCount] = useState<number | undefined>();
  const [pending, setPending] = useState(0);
  const [refreshing, setRefreshing] = useState(false);

  const load = useCallback(async () => {
    setPending(await pendingCountOfKind('visitor_event'));
    if (can('visitor.dashboard.view')) {
      const res = await visitorApi.active();
      if (res.ok && res.data) setInsideCount(res.data.sessions.length);
    }
    if (can('visitor.expected.view')) {
      const res = await visitorApi.expected();
      if (res.ok && res.data) {
        setExpectedCount(res.data.guests.length);
        // Refresh the offline copy every time we are online anyway.
        void saveExpected({ generatedAt: res.data.generatedAt, guests: res.data.guests });
      } else {
        const cached = await readExpected();
        if (cached) setExpectedCount(cached.guests.length);
      }
    }
  }, [can]);

  useFocusEffect(
    useCallback(() => {
      void load();
    }, [load]),
  );

  const onRefresh = useCallback(async () => {
    setRefreshing(true);
    try {
      await load();
    } finally {
      setRefreshing(false);
    }
  }, [load]);

  const tiles = [
    can('visitor.dashboard.view') && (
      <StatTile key="inside" label={t('onSite')} sub={t('onSiteSub')} Icon={Users}
        value={insideCount} loading={insideCount === undefined} onPress={() => navigation.navigate('OnSite')} />
    ),
    can('visitor.expected.view') && (
      <StatTile key="expected" label={t('gateExpected')} sub={t('gateExpectedSub')} Icon={CalendarCheck}
        value={expectedCount} loading={expectedCount === undefined} onPress={() => navigation.navigate('Expected')} />
    ),
    can('visitor.manual.create') && (
      <StatTile key="walkin" label={t('walkIn')} sub={t('walkInSub')} Icon={UserPlus}
        onPress={() => navigation.navigate('WalkIn')} />
    ),
    can('visitor.staff.mark') && (
      <StatTile key="staff" label={t('staffInOut')} sub={t('staffInOutSub')} Icon={UserRoundCheck}
        onPress={() => navigation.navigate('StaffInOut')} />
    ),
  ].filter(Boolean) as React.ReactElement[];

  // Two per row; an odd last tile keeps its half width.
  const rows: React.ReactElement[][] = [];
  for (let i = 0; i < tiles.length; i += 2) rows.push(tiles.slice(i, i + 2));

  return (
    <SafeAreaView edges={['top']} style={[styles.safe, { backgroundColor: palette.background }]}>
      <ScrollView
        contentContainerStyle={styles.scroll}
        refreshControl={<RefreshControl refreshing={refreshing} onRefresh={onRefresh} tintColor={palette.primary} />}
      >
        <View style={styles.header}>
          {navigation.canGoBack() ? <IconButton Icon={ArrowLeft} onPress={() => navigation.goBack()} /> : null}
          <Text variant="headlineMedium" style={{ flex: 1 }}>
            {t('moduleVisitor')}
          </Text>
          <IconButton Icon={SettingsIcon} onPress={() => navigation.navigate('Settings')} />
        </View>

        {can('visitor.checkin.create') ? (
          <HeroAction Icon={QrCode} title={t('scanPass')} sub={t('scanPassSub')} onPress={() => navigation.navigate('GateScan')} />
        ) : null}

        {pending > 0 ? (
          <View style={[styles.pending, { backgroundColor: palette.warnContainer }]}>
            <CloudOff size={18} color={palette.onWarnContainer} />
            <Text variant="bodyMedium" color={palette.onWarnContainer} style={{ flex: 1 }}>
              {t('gatePendingSync', { n: pending })}
            </Text>
          </View>
        ) : null}

        {rows.map((row, i) => (
          <View key={i} style={styles.tilesRow}>
            {row}
            {row.length === 1 ? <View style={{ flex: 1 }} /> : null}
          </View>
        ))}
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1 },
  scroll: { paddingBottom: spacing.xxxl },
  header: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: spacing.sm,
    paddingHorizontal: spacing.lg,
    paddingTop: spacing.lg,
    paddingBottom: spacing.md,
  },
  pending: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: spacing.sm,
    marginHorizontal: spacing.xl,
    marginBottom: spacing.md,
    padding: spacing.md,
    borderRadius: 12,
  },
  tilesRow: { flexDirection: 'row', gap: spacing.md, paddingHorizontal: spacing.xl, marginBottom: spacing.md },
});
