import { ChevronRight, type LucideIcon } from 'lucide-react-native';
import React from 'react';
import { Pressable, StyleSheet, View } from 'react-native';
import { spacing, Text, toneColors, type Tone } from '../design';
import { useTheme } from '../theme';

export type QuickAction = {
  key: string;
  label: string;
  Icon: LucideIcon;
  /** 'filled' = the one obvious action; the rest are tinted. */
  tone: Tone | 'filled';
  badge?: number;
  onPress: () => void;
};

/**
 * Two-column grid of big action tiles. The first action is usually the
 * filled purple one, so there is always a single obvious thing to do.
 */
export function QuickActions({ actions }: { actions: QuickAction[] }) {
  const rows: QuickAction[][] = [];
  for (let i = 0; i < actions.length; i += 2) rows.push(actions.slice(i, i + 2));
  return (
    <View style={{ paddingHorizontal: spacing.xl, gap: spacing.md }}>
      {rows.map((row, i) => (
        <View key={i} style={{ flexDirection: 'row', gap: spacing.md }}>
          {row.map((a) => (
            <ActionTile key={a.key} action={a} />
          ))}
          {row.length === 1 ? <View style={{ flex: 1 }} /> : null}
        </View>
      ))}
    </View>
  );
}

function ActionTile({ action }: { action: QuickAction }) {
  const { palette } = useTheme();
  const filled = action.tone === 'filled';
  const c = filled ? { bg: palette.primary, fg: palette.onPrimary } : toneColors(palette, action.tone as Tone);
  return (
    <Pressable
      onPress={action.onPress}
      accessibilityRole="button"
      style={({ pressed }) => [
        styles.tile,
        { backgroundColor: c.bg, opacity: pressed ? 0.85 : 1 },
        filled && { shadowColor: palette.primary, shadowOpacity: 0.3, shadowRadius: 14, shadowOffset: { width: 0, height: 6 }, elevation: 6 },
      ]}
    >
      <action.Icon size={26} color={c.fg} strokeWidth={2.2} />
      <Text variant="titleMedium" color={c.fg} style={{ flex: 1 }} numberOfLines={2}>
        {action.label}
      </Text>
      {action.badge ? (
        <View style={[styles.badge, { backgroundColor: palette.error }]}>
          <Text variant="labelMedium" color={palette.onError}>
            {action.badge}
          </Text>
        </View>
      ) : (
        <ChevronRight size={20} color={c.fg} />
      )}
    </Pressable>
  );
}

const styles = StyleSheet.create({
  tile: {
    flex: 1,
    flexDirection: 'row',
    alignItems: 'center',
    gap: spacing.md,
    minHeight: 76,
    borderRadius: 20,
    paddingHorizontal: spacing.lg,
  },
  badge: { minWidth: 24, height: 24, borderRadius: 12, alignItems: 'center', justifyContent: 'center', paddingHorizontal: 6 },
});
