import { useFocusEffect } from '@react-navigation/native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import {
  AlertTriangle,
  CalendarCheck,
  CheckCircle2,
  CloudOff,
  HandCoins,
  Package,
  QrCode,
  ScanLine,
  Truck,
  User,
  UserPlus,
  Users,
} from 'lucide-react-native';
import React, { useCallback, useState } from 'react';
import { View } from 'react-native';
import { useCan } from '../auth';
import { getSession } from '../auth/session';
import { Panel } from '../components/Panel';
import { QuickActions, type QuickAction } from '../components/QuickActions';
import { HubLayout } from '../components/shell/HubLayout';
import { SyncStatusChip } from '../components/shell/SyncStatusChip';
import { StatStrip, type Stat } from '../components/StatStrip';
import { listOpenOrders } from '../db/orders';
import { rejectedCount, stuckCount } from '../db/outbox';
import { listLowOrOut, type StockRow } from '../db/stock';
import { IconBadge, ListRow, SectionHeader, spacing, StatusChip } from '../design';
import { useT } from '../i18n';
import { visitorApi, type ExpectedGuest } from '../modules/visitor/api';
import { readExpected, saveExpected } from '../modules/visitor/cache';
import { timeOnly } from '../modules/visitor/format';
import { pullStockIntoCache } from '../sync/stockPull';
import { flushOnce } from '../sync/syncService';
import { refetchThrottled } from '../sync/refetch';
import { useTheme } from '../theme';
import type { RootStackParamList } from './types';

type Props = NativeStackScreenProps<RootStackParamList, 'Today'>;

export function greetingKey(): 'goodMorning' | 'goodAfternoon' | 'goodEvening' {
  const h = new Date().getHours();
  return h < 12 ? 'goodMorning' : h < 17 ? 'goodAfternoon' : 'goodEvening';
}

/**
 * The super-app home. Everything on it comes from what this person may do:
 * a gate guard sees visitors, a pantry operator sees stock, someone with
 * both sees both. It answers "what needs me today?" before anything else.
 */
export function TodayScreen({ navigation }: Props) {
  const t = useT();
  const { palette } = useTheme();
  const can = useCan();
  const gate = can('visitor.checkin.create');
  const stock = can('inventory.view');

  const [expected, setExpected] = useState<ExpectedGuest[] | undefined>();
  const [inside, setInside] = useState<number | undefined>();
  const [low, setLow] = useState<StockRow[] | undefined>();
  const [deliveries, setDeliveries] = useState<number | undefined>();
  const [problems, setProblems] = useState(0);
  const [refreshing, setRefreshing] = useState(false);

  const load = useCallback(async () => {
    const jobs: Promise<unknown>[] = [
      Promise.all([rejectedCount(), stuckCount()]).then(([r, s]) => setProblems(r + s)),
    ];
    if (can('visitor.expected.view')) {
      jobs.push(
        visitorApi.expected().then(async (res) => {
          if (res.ok && res.data) {
            setExpected(res.data.guests);
            void saveExpected({ generatedAt: res.data.generatedAt, guests: res.data.guests });
          } else {
            setExpected((await readExpected())?.guests ?? []);
          }
        }),
      );
    }
    if (can('visitor.dashboard.view')) {
      jobs.push(visitorApi.active().then((res) => res.ok && res.data && setInside(res.data.sessions.length)));
    }
    if (stock) {
      // Local first (instant), then a throttled pull and a re-read.
      const readLocal = async () => {
        const [lowRows, orders] = await Promise.all([listLowOrOut(), listOpenOrders()]);
        setLow(lowRows);
        setDeliveries(orders.length);
      };
      jobs.push(
        readLocal()
          .then(() => refetchThrottled('stock', async () => {
            await flushOnce().catch(() => {});
            await pullStockIntoCache();
          }))
          .then(readLocal),
      );
    }
    await Promise.allSettled(jobs);
  }, [can, stock]);

  useFocusEffect(
    useCallback(() => {
      void load();
    }, [load]),
  );

  const onRefresh = useCallback(async () => {
    setRefreshing(true);
    try {
      await load();
    } finally {
      setRefreshing(false);
    }
  }, [load]);

  const upcoming = (expected ?? []).filter((g) => !g.tokenUsed).slice(0, 3);

  const stats: Stat[] = [];
  if (can('visitor.expected.view')) {
    stats.push({ key: 'exp', Icon: CalendarCheck, tone: 'info', value: expected?.length, label: t('statExpected'), onPress: () => navigation.navigate('Expected') });
  }
  if (can('visitor.dashboard.view')) {
    stats.push({ key: 'in', Icon: Users, tone: 'primary', value: inside, label: t('statInside'), onPress: () => navigation.navigate('OnSite') });
  }
  if (stock) {
    stats.push({ key: 'low', Icon: AlertTriangle, tone: 'warn', value: low?.length, label: t('statLow'), onPress: () => navigation.navigate('Alerts') });
    stats.push({ key: 'del', Icon: Truck, tone: 'success', value: deliveries, label: t('deliveriesSub'), onPress: () => navigation.navigate('Orders') });
  }

  const actions: QuickAction[] = [];
  if (gate) actions.push({ key: 'pass', label: t('scanPass'), Icon: QrCode, tone: 'filled', onPress: () => navigation.navigate('GateScan') });
  if (can('visitor.manual.create')) actions.push({ key: 'walkin', label: t('walkIn'), Icon: UserPlus, tone: 'info', onPress: () => navigation.navigate('WalkIn') });
  if (can('inventory.receive')) actions.push({ key: 'item', label: t('scanItemAction'), Icon: ScanLine, tone: actions.length === 0 ? 'filled' : 'primary', onPress: () => navigation.navigate('Scanner') });
  if (can('inventory.issue')) actions.push({ key: 'take', label: t('takeOutAction'), Icon: HandCoins, tone: 'success', onPress: () => navigation.navigate('Dispense') });

  const attention = [
    ...(low ?? []).slice(0, 3).map((row) => (
      <ListRow
        key={row.barcode}
        Icon={Package}
        tone={row.on_hand <= 0 ? 'danger' : 'warn'}
        title={row.name}
        subtitle={t('qtyLeft', { qty: row.on_hand, unit: row.unit ?? '' })}
        trailing={<StatusChip label={row.on_hand <= 0 ? t('outOfStock') : t('lowChip')} tone={row.on_hand <= 0 ? 'danger' : 'warn'} />}
        onPress={() => navigation.navigate('Stock', { expandBarcode: row.barcode })}
      />
    )),
    problems > 0 ? (
      <ListRow key="sync" Icon={CloudOff} tone="danger" title={t('writesNotSent', { n: problems })} onPress={() => navigation.navigate('Outbox')} />
    ) : null,
  ].filter(Boolean);

  return (
    <HubLayout
      title={`${t(greetingKey())}, ${getSession()?.guardName ?? ''}`}
      band={<SyncStatusChip />}
      refreshing={refreshing}
      onRefresh={onRefresh}
    >
      <SectionHeader title={t('todayAtGlance')} />
      <StatStrip stats={stats} />

      {actions.length > 0 ? (
        <>
          <SectionHeader title={t('quickActions')} />
          <QuickActions actions={actions.slice(0, 4)} />
        </>
      ) : null}

      {can('visitor.expected.view') && upcoming.length > 0 ? (
        <>
          <SectionHeader title={t('comingToday')} actionLabel={t('viewAll')} onAction={() => navigation.navigate('Expected')} />
          <Panel>
            {upcoming.map((g, i) => (
              <ListRow
                key={g.id}
                leading={<TimelineMark last={i === upcoming.length - 1} />}
                title={g.visitorName}
                subtitle={g.hostName ?? g.purpose ?? null}
                trailing={g.approvalStatus === 'pending' ? <StatusChip label={t('passPending')} tone="warn" Icon={null} /> : g.expectedTime || timeOnly(g.validFrom)}
                onPress={() => navigation.navigate('Expected')}
              />
            ))}
          </Panel>
        </>
      ) : null}

      <SectionHeader title={t('needsAttention')} />
      <Panel>
        {attention.length > 0 ? attention : (
          <ListRow key="clear" Icon={CheckCircle2} tone="success" title={t('allClear')} />
        )}
      </Panel>
      <View style={{ height: spacing.xl }} />
    </HubLayout>
  );
}

/** Dot-and-line marker for a vertical timeline of today's visitors. */
function TimelineMark({ last }: { last: boolean }) {
  const { palette } = useTheme();
  return (
    <View style={{ flexDirection: 'row', alignItems: 'center', gap: spacing.md }}>
      <View style={{ width: 12, alignItems: 'center', alignSelf: 'stretch', justifyContent: 'center' }}>
        <View style={{ width: 12, height: 12, borderRadius: 6, backgroundColor: palette.primary }} />
        {!last ? (
          <View style={{ position: 'absolute', top: '60%', bottom: -40, width: 2, backgroundColor: palette.primaryContainer }} />
        ) : null}
      </View>
      <IconBadge Icon={User} tone="primary" size={40} />
    </View>
  );
}
