                Icon={Package}
                tone={row.on_hand <= 0 ? 'danger' : 'warn'}
                title={row.name}
                subtitle={t('qtyLeft', { qty: row.on_hand, unit: row.unit ?? '' })}
                trailing={<StatusChip label={row.on_hand <= 0 ? t('outOfStock') : t('lowChip')} tone={row.on_hand <= 0 ? 'danger' : 'warn'} />}
                onPress={() => navigation.navigate('Stock', { expandBarcode: row.barcode })}
              />
            ))}
          </Panel>
        </>
      ) : null}

