            trailing={stats && stats.orders > 0 ? String(stats.orders) : undefined}
            onPress={() => navigation.navigate('Orders')} />
        ) : null}
        <ListRow Icon={AlertTriangle} tone="warn" title={t('alerts')} subtitle={t('alertsSub')}
          trailing={stats && stats.alerts > 0 ? <StatusChip label={String(stats.alerts)} tone="warn" Icon={null} /> : undefined}
          onPress={() => navigation.navigate('Alerts')} />
      </Panel>
      <View style={{ height: spacing.xl }} />
    </HubLayout>
  );
}

/**
 * Stock health at a glance (design 02): three counts with icons and one
 * segmented bar. Tapping the counts opens the matching list.
 */
function StockHealth({
  loading,
  inStock,
  low,
  out,
  onAll,
  onLow,
}: {
  loading: boolean;
  inStock: number;
  low: number;
  out: number;
  onAll: () => void;
  onLow: () => void;
}) {
  const t = useT();
  const { palette } = useTheme();
  const total = inStock + low + out;
  const seg = (n: number) => (total > 0 ? Math.max(n / total, n > 0 ? 0.04 : 0) : 0);
  const cells = [
    { key: 'in', Icon: CheckCircle2, tone: 'success' as const, value: inStock, label: t('statInStock'), onPress: onAll },
    { key: 'low', Icon: AlertTriangle, tone: 'warn' as const, value: low, label: t('statLow'), onPress: onLow },
    { key: 'out', Icon: XCircle, tone: 'danger' as const, value: out, label: t('statOut'), onPress: onLow },
  ];
  return (
    <View style={[styles.health, { backgroundColor: palette.surfaceContainerLowest, borderColor: palette.outlineVariant }]}>
      <View style={{ flexDirection: 'row' }}>
        {cells.map((c, i) => (
          <Pressable key={c.key} onPress={c.onPress} style={[styles.healthCell, i > 0 && { borderLeftWidth: StyleSheet.hairlineWidth, borderLeftColor: palette.outlineVariant }]}>
            <IconBadge Icon={c.Icon} tone={c.tone} size={36} />
            {loading ? (
              <Skeleton width={40} height={30} style={{ marginTop: spacing.sm }} />
            ) : (
              <Text variant="headlineMedium" style={{ marginTop: spacing.sm, fontWeight: '800' }}>
                {c.value}
              </Text>
            )}
            <Text variant="labelMedium" color={palette.onSurfaceVariant}>
              {c.label}
            </Text>
          </Pressable>
        ))}
      </View>
      <View style={[styles.bar, { backgroundColor: palette.surfaceContainerHigh }]}>
        {total > 0 ? (
          <>
            <View style={{ flex: seg(inStock), backgroundColor: palette.success }} />
            <View style={{ flex: seg(low), backgroundColor: '#F5B53F' }} />
            <View style={{ flex: seg(out), backgroundColor: palette.error }} />
          </>
        ) : null}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  health: {
    marginHorizontal: spacing.xl,
    borderRadius: 20,
    borderWidth: StyleSheet.hairlineWidth,
    padding: spacing.md,
    elevation: 2,
    shadowColor: '#000',
    shadowOpacity: 0.06,
    shadowRadius: 10,
    shadowOffset: { width: 0, height: 4 },
  },
  healthCell: { flex: 1, paddingHorizontal: spacing.sm },
  bar: { flexDirection: 'row', height: 10, borderRadius: 5, overflow: 'hidden', marginTop: spacing.md, gap: 2 },
});
'''
