cat > modules/visitor/screens/GateHomeScreen.tsx <<'EOF'
import { useFocusEffect } from '@react-navigation/native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { CalendarCheck, CloudOff, QrCode, UserPlus, UserRoundCheck, Users } from 'lucide-react-native';
import React, { useCallback, useState } from 'react';
import { View } from 'react-native';
import { useCan } from '../../../auth';
import { Panel } from '../../../components/Panel';
import { QuickActions, type QuickAction } from '../../../components/QuickActions';
import { HubLayout } from '../../../components/shell/HubLayout';
import { SyncStatusChip } from '../../../components/shell/SyncStatusChip';
import { StatStrip, type Stat } from '../../../components/StatStrip';
import { TimelineMark } from '../../../components/TimelineMark';
import { pendingCountOfKind } from '../../../db/outbox';
import { ListRow, SectionHeader, spacing, StatusChip, Text } from '../../../design';
import { useT } from '../../../i18n';
import type { RootStackParamList } from '../../../navigation/types';
import { useTheme } from '../../../theme';
import { visitorApi, type ExpectedGuest } from '../api';
import { readExpected, saveExpected } from '../cache';
import { timeOnly } from '../format';

type Props = NativeStackScreenProps<RootStackParamList, 'GateHome'>;

/**
 * Visitors hub (design 03): today's numbers, the scan button, who is coming
 * next as a timeline, and the two lists a guard returns to all day.
 */
export function GateHomeScreen({ navigation }: Props) {
  const t = useT();
  const { palette } = useTheme();
  const can = useCan();
  const [expected, setExpected] = useState<ExpectedGuest[] | undefined>();
  const [inside, setInside] = useState<number | undefined>();
  const [pending, setPending] = useState(0);
  const [refreshing, setRefreshing] = useState(false);

  const load = useCallback(async () => {
    setPending(await pendingCountOfKind('visitor_event'));
    const jobs: Promise<unknown>[] = [];
    if (can('visitor.dashboard.view')) {
      jobs.push(visitorApi.active().then((res) => res.ok && res.data && setInside(res.data.sessions.length)));
    }
    if (can('visitor.expected.view')) {
      jobs.push(
        visitorApi.expected().then(async (res) => {
          if (res.ok && res.data) {
            setExpected(res.data.guests);
            // Refresh the offline copy every time we are online anyway.
            void saveExpected({ generatedAt: res.data.generatedAt, guests: res.data.guests });
          } else {
            setExpected((await readExpected())?.guests ?? []);
          }
        }),
      );
    }
    await Promise.allSettled(jobs);
  }, [can]);

  useFocusEffect(
    useCallback(() => {
      void load();
    }, [load]),
  );

  const onRefresh = useCallback(async () => {
    setRefreshing(true);
    try {
      await load();
    } finally {
      setRefreshing(false);
    }
  }, [load]);

  const upcoming = (expected ?? []).filter((g) => !g.tokenUsed).slice(0, 5);

  const stats: Stat[] = [];
  if (can('visitor.expected.view')) {
    stats.push({ key: 'exp', Icon: CalendarCheck, tone: 'info', value: expected?.length, label: t('statExpected'), onPress: () => navigation.navigate('Expected') });
  }
  if (can('visitor.dashboard.view')) {
    stats.push({ key: 'in', Icon: Users, tone: 'primary', value: inside, label: t('statInside'), onPress: () => navigation.navigate('OnSite') });
  }

  const actions: QuickAction[] = [];
  if (can('visitor.checkin.create')) actions.push({ key: 'scan', label: t('scanPass'), Icon: QrCode, tone: 'filled', onPress: () => navigation.navigate('GateScan') });
  if (can('visitor.manual.create')) actions.push({ key: 'walkin', label: t('walkIn'), Icon: UserPlus, tone: 'info', onPress: () => navigation.navigate('WalkIn') });

  return (
    <HubLayout
      title={t('tabVisitors')}
      band={<SyncStatusChip />}
      refreshing={refreshing}
      onRefresh={onRefresh}
    >
      {stats.length > 0 ? <StatStrip stats={stats} /> : null}

      {pending > 0 ? (
        <View style={{ flexDirection: 'row', alignItems: 'center', gap: spacing.sm, marginHorizontal: spacing.xl, marginTop: spacing.md, padding: spacing.md, borderRadius: 16, backgroundColor: palette.warnContainer }}>
          <CloudOff size={18} color={palette.onWarnContainer} />
          <Text variant="bodyMedium" color={palette.onWarnContainer} style={{ flex: 1 }}>
            {t('gatePendingSync', { n: pending })}
          </Text>
        </View>
      ) : null}

      {actions.length > 0 ? (
        <View style={{ marginTop: spacing.xl }}>
          <QuickActions actions={actions} />
        </View>
      ) : null}

      {can('visitor.expected.view') ? (
        <>
          <SectionHeader title={t('comingToday')} actionLabel={t('viewAll')} onAction={() => navigation.navigate('Expected')} />
          <Panel>
            {upcoming.length > 0 ? (
              upcoming.map((g, i) => (
                <ListRow
                  key={g.id}
                  leading={<TimelineMark last={i === upcoming.length - 1} />}
                  title={g.visitorName}
