import { useFocusEffect } from '@react-navigation/native';
import React, { useCallback, useEffect, useState } from 'react';
import { View } from 'react-native';
import { rejectedCount, stuckCount } from '../../db/outbox';
import { spacing, Text } from '../../design';
import { useT } from '../../i18n';
import { isOnline, subscribeNetworkState } from '../../sync/networkState';
import { onPendingChange } from '../../sync/syncService';
import { useTheme } from '../../theme';

/**
 * One quiet line under a screen title: a dot and a few words about whether
 * this phone's work has reached the server. Green all sent, amber waiting,
 * red needs a person, grey offline.
 */
export function StatusLine() {
  const t = useT();
  const { palette } = useTheme();
  const [online, setOnline] = useState(isOnline());
  const [pending, setPending] = useState(0);
  const [problems, setProblems] = useState(0);

  useEffect(() => subscribeNetworkState(setOnline), []);
  useEffect(() => onPendingChange((n) => setPending(n)), []);
  useFocusEffect(
    useCallback(() => {
      void Promise.all([rejectedCount(), stuckCount()]).then(([r, s]) => setProblems(r + s));
    }, []),
  );

  let dot: string = palette.success;
  let label = t('syncAllGood');
  if (!online) {
    dot = palette.outline;
    label = t('syncOfflineChip');
  } else if (problems > 0) {
    dot = palette.error;
    label = t('syncProblemChip', { n: problems });
  } else if (pending > 0) {
    dot = palette.amber;
    label = t('syncWaiting', { n: pending });
  }

  return (
    <View style={{ flexDirection: 'row', alignItems: 'center', gap: spacing.sm }}>
      <View style={{ width: 10, height: 10, borderRadius: 5, backgroundColor: dot }} />
      <Text variant="bodyLarge" color={palette.onSurfaceVariant}>
        {label}
      </Text>
    </View>
  );
}
