import { StackActions, useNavigation, useRoute } from '@react-navigation/native';
import type { NativeStackNavigationProp } from '@react-navigation/native-stack';
import { ScanLine } from 'lucide-react-native';
import React from 'react';
import { Pressable, StyleSheet, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { spacing, Text } from '../../design';
import { useT } from '../../i18n';
import type { RootStackParamList } from '../../navigation/types';
import { useTheme } from '../../theme';
import { haptic } from '../../utils/haptics';
import { type Hub, type HubRoute, useHubs } from './hubs';

type Nav = NativeStackNavigationProp<RootStackParamList>;

/**
 * Flat bottom bar (designs 04 to 06). Scan sits in the middle as a normal
 * tab. Tabs behave like tabs on a plain stack: the stack never holds more
 * than the first hub plus one other, so Android back goes to the first
 * tab and then out of the app.
 */
export function BottomBar() {
  const t = useT();
  const { palette } = useTheme();
  const insets = useSafeAreaInsets();
  const navigation = useNavigation<Nav>();
  const route = useRoute();
  const { hubs, scanRoute } = useHubs();

  const go = (target: HubRoute) => {
    if (target === route.name) return;
    haptic.tap();
    const first = navigation.getState().routes[0]?.name;
    if (target === first || route.name === first) navigation.navigate(target as never);
    else navigation.dispatch(StackActions.replace(target));
  };

  const item = (key: string, label: string, Icon: Hub['Icon'], active: boolean, onPress: () => void) => {
    const color = active ? palette.primary : palette.onSurfaceVariant;
    return (
      <Pressable key={key} onPress={onPress} style={styles.tab} accessibilityRole="tab" accessibilityState={{ selected: active }}>
        <Icon size={26} color={color} strokeWidth={active ? 2.4 : 1.8} fill={active ? palette.primaryContainer : 'transparent'} />
        <Text variant="labelMedium" color={color} style={{ fontWeight: active ? '700' : '500' }}>
          {label}
        </Text>
      </Pressable>
    );
  };

  const mid = Math.ceil(hubs.length / 2);
  return (
    <View
      style={[
        styles.bar,
        { backgroundColor: palette.background, borderTopColor: palette.outlineVariant, paddingBottom: Math.max(insets.bottom, spacing.sm) },
      ]}
    >
      {hubs.slice(0, mid).map((h) => item(h.route, t(h.labelKey), h.Icon, h.route === route.name, () => go(h.route)))}
      {scanRoute
        ? item('scan', t('tabScan'), ScanLine, false, () => {
          haptic.tap();
          navigation.navigate(scanRoute as never);
        })
        : null}
      {hubs.slice(mid).map((h) => item(h.route, t(h.labelKey), h.Icon, h.route === route.name, () => go(h.route)))}
    </View>
  );
}

const styles = StyleSheet.create({
  bar: { flexDirection: 'row', borderTopWidth: StyleSheet.hairlineWidth, paddingTop: spacing.sm + 2 },
  tab: { flex: 1, alignItems: 'center', gap: 4, minHeight: 52 },
});
