import { useFocusEffect } from '@react-navigation/native';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { HandCoins, Package, ScanLine, UserRound } from 'lucide-react-native';
import React, { useCallback, useState } from 'react';
import { View } from 'react-native';
import { useCan } from '../auth';
import { AttentionBanner } from '../components/AttentionBanner';
import { NavRow } from '../components/NavRow';
import { PrimaryAction } from '../components/PrimaryAction';
import { HubLayout } from '../components/shell/HubLayout';
import { useHubs } from '../components/shell/hubs';
import { StatusLine } from '../components/shell/StatusLine';
import { rejectedCount, stuckCount } from '../db/outbox';
import { listLowOrOut } from '../db/stock';
import { spacing } from '../design';
import { useT } from '../i18n';
import { pullStockIntoCache } from '../sync/stockPull';
import { refetchThrottled } from '../sync/refetch';
import { flushOnce } from '../sync/syncService';
import type { RootStackParamList } from './types';

type Props = NativeStackScreenProps<RootStackParamList, 'Today'>;

/**
 * Home for people with more than one module (design 04): one big scan
 * button, at most three tasks, and one amber line only when something
 * needs them. Everything else lives one tap away in its module.
 */
export function TodayScreen({ navigation }: Props) {
  const t = useT();
  const can = useCan();
  const { scanRoute } = useHubs();
  const [lowCount, setLowCount] = useState(0);
  const [problems, setProblems] = useState(0);
  const [refreshing, setRefreshing] = useState(false);

  const load = useCallback(async () => {
    const [r, s] = await Promise.all([rejectedCount(), stuckCount()]);
    setProblems(r + s);
    if (can('inventory.view')) {
      setLowCount((await listLowOrOut()).length);
      await refetchThrottled('stock', async () => {
        await flushOnce().catch(() => {});
        await pullStockIntoCache();
      });
      setLowCount((await listLowOrOut()).length);
    }
  }, [can]);

  useFocusEffect(
    useCallback(() => {
      void load();
    }, [load]),
  );

  const onRefresh = useCallback(async () => {
    setRefreshing(true);
    try {
      await load();
    } finally {
      setRefreshing(false);
    }
  }, [load]);

  const scanLabel = scanRoute === 'GateScan' ? t('scanPass') : scanRoute === 'Scanner' ? t('scanItemAction') : t('scanAction');
  const attention = lowCount + problems;

  return (
    <HubLayout title={t('tabToday')} subtitle={<StatusLine />} refreshing={refreshing} onRefresh={onRefresh}>
      <View style={{ gap: spacing.lg }}>
        {scanRoute ? <PrimaryAction Icon={ScanLine} label={scanLabel} onPress={() => navigation.navigate(scanRoute)} /> : null}
        {can('inventory.receive') ? (
          <NavRow Icon={Package} label={t('receiveAction')} onPress={() => navigation.navigate('Orders')} />
        ) : null}
        {can('visitor.checkin.create') ? (
          <NavRow Icon={UserRound} label={t('checkInVisitor')} onPress={() => navigation.navigate('GateHome')} />
        ) : null}
        {can('inventory.issue') ? (
          <NavRow Icon={HandCoins} label={t('takeOutAction')} onPress={() => navigation.navigate('Dispense')} />
        ) : null}
        {attention > 0 ? (
          <View style={{ marginTop: spacing.sm }}>
            <AttentionBanner
              text={t('itemsNeedAttention', { n: attention })}
              onPress={() => navigation.navigate(lowCount > 0 ? 'Alerts' : 'Outbox')}
            />
          </View>
        ) : null}
      </View>
    </HubLayout>
  );
}
