def rep(f,old,new):
    s=open(f).read(); assert s.count(old)==1,(f,old[:60],s.count(old)); open(f,'w').write(s.replace(old,new))
rep('modules/types.ts',"""  /** Override default screen options for this route. */
  options?: Record<string, unknown>;
};""","""  /** Override default screen options for this route. */
  options?: Record<string, unknown>;
  /**
   * Who may open this screen: any one of these permissions. Omitted = anyone
   * who can see the module. Screens a person may not use are not registered
   * at all, so nothing (a stale button, a deep link) can open them.
   */
  requires?: Permission[];
};""")
rep('modules/types.ts',"""  /** Permissions a user must hold to see this module on the home screen. */
  requiredPermissions: Permission[];""","""  /** Holding any one of these shows the module (its tab, its home). */
  requiredPermissions: Permission[];""")
rep('modules/registry.ts',"""export function getVisibleModules(can: (permission: Permission) => boolean): Module[] {
  return MODULES.filter((m) => m.requiredPermissions.every((p) => can(p)));
}""","""export function getVisibleModules(can: (permission: Permission) => boolean): Module[] {
  return MODULES.filter((m) => m.requiredPermissions.some((p) => can(p)));
}

/** The screens of a module this person may open (see ModuleScreen.requires). */
export function getAllowedScreens(m: Module, can: (permission: Permission) => boolean): Module['screens'] {
  return m.screens.filter((s) => !s.requires || s.requires.some((p) => can(p)));
}""")
rep('modules/index.ts',"export { MODULES, getVisibleModules } from './registry';","export { MODULES, getAllowedScreens, getVisibleModules } from './registry';")

f='modules/inventory/index.ts'; s=open(f).read()
reqs={
 'Scanner':"['inventory.receive']",'Receiving':"['inventory.receive']",'RegisterProduct':"['inventory.receive']",
 'CatalogPicker':"['inventory.receive']",'OrderSession':"['inventory.receive']",'DeliverySummary':"['inventory.receive']",
 'Orders':"['inventory.receive']",'EditStock':"['inventory.adjust']",'Dispense':"['inventory.issue']",
}
import re
def add(m):
    name=m.group(1); rest=m.group(2)
    if name in reqs:
        return "{ name: '%s'%s, requires: %s }" % (name, rest, reqs[name])
    return m.group(0)
s=re.sub(r"\{ name: '([A-Za-z]+)'(, component: [A-Za-z]+(?:, options: \{[^}]*\})?) \}", add, s)
open(f,'w').write(s)

f='modules/visitor/index.ts'; s=open(f).read()
vreqs={'GateScan':"['visitor.checkin.create']",'PassResult':"['visitor.checkin.create']",'OnSite':"['visitor.dashboard.view']",
 'WalkIn':"['visitor.manual.create']",'Expected':"['visitor.expected.view']",'StaffInOut':"['visitor.staff.mark']"}
def addv(m):
    name=m.group(1); rest=m.group(2)
    if name in vreqs: return "{ name: '%s'%s, requires: %s }" % (name, rest, vreqs[name])
    return m.group(0)
s=re.sub(r"\{ name: '([A-Za-z]+)'(, component: [A-Za-z]+(?:, options: \{[^}]*\})?) \}", addv, s)
s=s.replace("""  requiredPermissions: ['visitor.checkin.create'],""","""  // Any gate job opens the module: a staff-attendance desk with only
  // visitor.staff.mark still gets the Visitors tab, showing just that row.
  requiredPermissions: [
    'visitor.checkin.create',
    'visitor.expected.view',
    'visitor.manual.create',
    'visitor.staff.mark',
    'visitor.dashboard.view',
  ],""")
s=s.replace(" * Visible to anyone who can check visitors in (the security_guard role).\n"," * Each screen is registered only for people whose role allows it.\n")
open(f,'w').write(s)

f='navigation/RootNavigator.tsx'; s=open(f).read()
s=s.replace("import { getVisibleModules, type ModuleScreen } from '../modules';","import { getAllowedScreens, getVisibleModules, type ModuleScreen } from '../modules';")
s=s.replace("    ...modules.flatMap((m) => m.screens),","    ...modules.flatMap((m) => getAllowedScreens(m, can)),")
open(f,'w').write(s)
EOF
