    }, [themeName]),
  );

  const ready = guardName.trim().length > 0 && pin.length >= PIN_MIN;

  const submit = async () => {
    if (busy) return;
    if (!ready) {
      setError({ text: t('fillDetailsError') });
      haptic.warn();
      return;
    }
    setBusy(true);
    setError(null);
    try {
      await login({ guardName: guardName.trim(), pin });
      haptic.success();
      // AuthProvider flips state → RootNavigator swaps to the main stack.
    } catch (e) {
      haptic.warn();
      setPin('');
      const msg = e instanceof Error ? e.message : String(e);
      if (e instanceof ApiError && e.status === 401) {
        setError({ text: t('wrongNameOrPin') });
