30	import { NoPermission } from '../../../components/NoPermission';
31	import { useTheme } from '../../../theme';
32	import { RootStackParamList } from '../../../navigation/types';
33	import { flushOnce } from '../../../sync/syncService';
34	import { haptic } from '../../../utils/haptics';
