36	import { useKeyboardHeight } from '../../../hooks/useKeyboardHeight';
37	import { BatchEditor, Batch } from '../components/BatchEditor';
38	
39	type Props = NativeStackScreenProps<RootStackParamList, 'Receiving'>;
40	
41	/** Convert Date object to ISO date string */
42	function toISO(d: Date): string {
43	  return d.toISOString().split('T')[0];
44	}
45	
46	const QUICK_MONTHS = [
47	  { label: '3 mo', months: 3 },
48	  { label: '6 mo', months: 6 },
49	  { label: '1 yr', months: 12 },
50	  { label: '2 yr', months: 24 },
51	];
52	
53	export function ReceivingScreen({ route, navigation }: Props) {
54	  const t = useT();
55	  const can = useCan();
56	  const { palette } = useTheme();
57	  const kbHeight = useKeyboardHeight();
58	  const { barcode, productId, productName: paramProductName, unit: paramUnit, packSize: paramPackSize } = route.params;
59	  const orderSession = useOrderSession();
60	  const [product, setProduct] = useState<Product | null>(null);
61	  // Fallback identity for barcodes we were handed WITHOUT route params —
62	  // e.g. the Stock screen's "Received" action, which only knows the
63	  // barcode. Resolved from the canonical catalog, then the local stock
64	  // row. Without this the screen printed the barcode next to the word
65	  // "Unknown" for products the guard had already linked.
66	  const [fallback, setFallback] = useState<{
67	    name: string;
68	    unit: string | null;
69	    packSize: number | null;
70	    category: string | null;
71	  } | null>(null);
72	  const [item, setItem] = useState<OrderItem | null>(null);
73	  const [saving, setSaving] = useState(false);
74	
75	  // One row per distinct expiry. Default to a single batch carrying
76	  // qty=1 — matches the 90% case of "one pack, one expiry". Guard taps
77	  // "+ Add another expiry batch" to break into groups.
78	  // ReceivingScreen always asks in packs (integer) even for divisible
79	  // products: physical intake is always whole packs. The translation to
80	  // base units (e.g. 3 packs × 5 kg → 15 kg lot qty) happens at submit.
81	  // Initial batch is "unset" (undefined) — forces the guard to actively
82	  // pick "Pick expiry" or "No expiry" rather than silently defaulting.
83	  const [batches, setBatches] = useState<Batch[]>([{ qty: 1, expiry: undefined }]);
84	  const qty = useMemo(() => batches.reduce((s, b) => s + (b.qty || 0), 0), [batches]);
85	
86	  // Identity resolution, most-specific first: route params (the scanner
87	  // already resolved it) → legacy local products row → canonical catalog
88	  // / stock cache. Only a barcode nothing on the device recognises falls
89	  // through to "Unknown".
90	  const resolvedName = paramProductName ?? product?.name ?? fallback?.name ?? 'Unknown';
91	  const resolvedUnit = paramUnit ?? product?.unit ?? fallback?.unit ?? null;
92	  const resolvedPackSize = paramPackSize ?? product?.pack_size ?? fallback?.packSize ?? null;
93	  const resolvedCategory = product?.category ?? fallback?.category ?? null;
94	  const packDisplay =
95	    resolvedPackSize != null && resolvedUnit
96	      ? `${resolvedPackSize} ${resolvedUnit}`
97	      : resolvedUnit ?? null;
98	
99	  useEffect(() => {
100	    let cancelled = false;
101	    (async () => {
102	      const local = await findProduct(barcode);
103	      if (cancelled) return;
104	      setProduct(local);
105	
106	      // Catalog first (canonical name + authoritative pack size), stock
107	      // cache second (whatever the last sync knew this barcode as).
108	      const canonical = await findCanonicalProductByBarcode(barcode).catch(() => null);
109	      const stockRow = await findStock(barcode);
110	      if (cancelled) return;
111	      if (canonical) {
112	        setFallback({
113	          name: canonical.canonical_name,
114	          unit: canonical.unit ?? null,
115	          packSize: canonical.pack_size ?? null,
116	          category: canonical.category ?? null,
117	        });
118	      } else if (stockRow) {
119	        setFallback({
120	          name: stockRow.name,
121	          unit: stockRow.unit ?? null,
122	          packSize: stockRow.pack_size ?? null,
123	          category: stockRow.category ?? null,
124	        });
125	      } else {
126	        setFallback(null);
127	      }
128	
129	      // If we have a productId from catalog, look up order item by product_id
130	      const openItem = productId
131	        ? ((await findOpenItemByProductId(productId)) as OrderItem | null)
132	        : await findOpenItemByBarcode(barcode);
133	      if (cancelled) return;
134	      setItem(openItem);
135	    })();
136	    return () => { cancelled = true; };
137	  }, [barcode, productId]);
138	
139	  /** Convert a "packs received" integer into the units stored in lots:
140	   *  Under the new unit-aware system, all stock is stored in packs. */
141	  const toLotQty = (packsQty: number): number => {
142	    return packsQty;
143	  };
144	
145	  // Auto-fill expiry on the (single) initial batch from the last scanned
146	  // item in this order session — matches "same expiry as the last pack
147	  // off the truck" behaviour.
148	  useEffect(() => {
149	    if (orderSession.lastExpiry && batches.length === 1 && batches[0].expiry === undefined) {
150	      setBatches([{ qty: batches[0].qty, expiry: orderSession.lastExpiry }]);
151	    }
152	    // eslint-disable-next-line react-hooks/exhaustive-deps
153	  }, [orderSession.lastExpiry]);
154	
155	  /** Standalone receipt path — when no order session is active */
156	  const persistStandalone = async (flagged: boolean) => {
157	    const session = getSession();
158	    // One receipt per distinct expiry batch. Each batch carries its
159	    // total qty (no exploding into N qty=1 rows).
160	    // Coerce the editor's tri-state (undefined = unset) into the binary
161	    // string|null the persistence layer expects. Unset at submit time
162	    // = same as "no expiry" — submit shouldn't block on an indecision.
163	    const cleanBatches = batches
164	      .filter((b) => b.qty > 0)
165	      .map((b) => ({ ...b, expiry: b.expiry ?? null }));
166	    // For divisible products, the lot is stored in base units (pack count
167	    // × pack_size). Pack-mode lots keep the raw count.
168	    const receipts: Array<{ id: string; qty: number; expiry: string | null }> =
169	      cleanBatches.map((b) => ({
170	        id: `rcp_${nanoid(12)}`,
171	        qty: toLotQty(b.qty),
172	        expiry: b.expiry,
173	      }));
174	
175	    // The first receipt's id is what we use to link mismatch flags etc.
176	    const id = receipts[0]?.id ?? `rcp_${nanoid(12)}`;
177	
178	    for (const r of receipts) {
179	      await enqueue('receipt', {
180	        id: r.id,
181	        order_id: item?.order_id ?? null,
182	        order_item_id: item?.id ?? null,
183	        product_id: productId ?? null,
184	        barcode,
185	        product_name: resolvedName,
186	        qty: r.qty,
187	        expiry_date: r.expiry,
188	        flagged,
189	        scanned_at: Date.now(),
190	        performed_by: session?.guardId ?? null,
191	        performed_by_name: session?.guardName ?? null,
192	      });
193	      // Mirror the lot locally so EditStock / Dispense see the new
194	      // batch before the next sync round-trip.
195	      await addLotLocal(barcode, r.expiry, r.qty);
196	    }
197	
198	    // Barcode learning: if this receipt was resolved via canonical catalog,
199	    // permanently map this barcode to the product_id for auto-resolution.
200	    if (productId && !barcode.startsWith('catalog_')) {
201	      await learnBarcode(barcode, productId, 'scan');
202	      // Also tell the backend to learn it
203	      await enqueue('learn_barcode', {
204	        barcode,
205	        product_id: productId,
206	      }).catch(() => {});
207	    }
208	    if (flagged) {
209	      await enqueue('mismatch_flag', {
210	        id: `flg_${nanoid(12)}`,
211	        receipt_id: id,
212	        order_item_id: item?.id ?? null,
213	        barcode,
214	        expected: item?.expected_qty ?? null,
215	        received_total: (item?.received_qty ?? 0) + qty,
216	        flagged_at: Date.now(),
217	      });
218	    }
219	    // Order item received_qty and stock on_hand track the same lot units —
220	    // packs for pack-mode, base units for divisible. Mirror toLotQty.
221	    const totalLotQty = toLotQty(qty);
222	    if (item) await addReceivedQty(item.id, totalLotQty);
223	
224	    const existing = await findStock(barcode);
225	    if (existing) {
226	      await adjustOnHand(barcode, totalLotQty);
227	    } else {
228	      await upsertStock({
229	        barcode,
230	        name: resolvedName,
231	        category: resolvedCategory,
232	        unit: resolvedUnit,
233	        pack_size: resolvedPackSize,
234	        dispense_mode: 'pack',
235	        on_hand: totalLotQty,
236	        threshold: 0,
237	      });
238	    }
239	
240	    // Goods just arrived — this is the new "full" for the stock list's
241	    // "left of stocked" bar. Server does the same in addLot; doing it
242	    // locally too stops the bar flashing a stale baseline until sync.
243	    await snapshotOpeningLocal(barcode);
244	
245	    flushOnce().catch(() => {});
246	
247	    // Track expiry for future alerts — one entry per batch (qty in lot units).
248	    for (const b of cleanBatches) {
249	      if (!b.expiry) continue;
250	      await trackExpiry({
251	        barcode,
252	        productName: resolvedName,
253	        expiryDate: b.expiry,
254	        qty: toLotQty(b.qty),
255	        receiptId: id,
256	        performedBy: session?.guardId ?? null,
257	        performedByName: session?.guardName ?? null,
258	      });
259	    }
260	  };
261	
262	  /** Add to order session */
263	  const addToSession = () => {
264	    const cleanBatches = batches.filter((b) => b.qty > 0);
265	    const totalQty = cleanBatches.reduce((s, b) => s + b.qty, 0);
266	
267	    orderSession.addItem({
268	      barcode,
269	      productId: productId ?? null,
270	      name: resolvedName,
271	      category: resolvedCategory,
272	      unit: resolvedUnit,
273	      packSize: resolvedPackSize,
274	      qty: totalQty,
275	      // Coerce tri-state expiry into the binary string|null the session
276	      // expects — submit shouldn't carry an indecision past this point.
277	      batches: cleanBatches.map((b) => ({ qty: b.qty, expiry: b.expiry ?? null })),
278	    });
279	    haptic.success();
280	    navigation.navigate('OrderSession');
281	  };
282	
283	  /** Standalone confirm (no active order session) */
284	  const confirmStandalone = async () => {
285	    setSaving(true);
286	    try {
287	      await persistStandalone(false);
288	      haptic.success();
289	      navigation.replace('DeliverySummary', {
290	        items: [{ name: resolvedName, category: resolvedCategory, qty }],
291	        totalItems: 1,
292	        totalQty: qty,
293	        productName: resolvedName,
294	        qty,
295	        expected: item?.expected_qty ?? null,
296	        flagged: false,
297	      });
298	    } finally {
299	      setSaving(false);
300	    }
301	  };
302	
303	  const flagAndContinueStandalone = async () => {
304	    setSaving(true);
305	    try {
306	      await persistStandalone(true);
307	      haptic.warn();
308	      navigation.replace('DeliverySummary', {
309	        items: [{ name: resolvedName, category: resolvedCategory, qty }],
310	        totalItems: 1,
311	        totalQty: qty,
312	        productName: resolvedName,
313	        qty,
314	        expected: item?.expected_qty ?? null,
315	        flagged: true,
316	      });
317	    } finally {
318	      setSaving(false);
319	    }
320	  };
321	
322	  const expected = item?.expected_qty ?? null;
323	  const alreadyIn = item?.received_qty ?? 0;
324	  const projected = alreadyIn + qty;
325	  const mismatch = expected !== null && projected > expected;
326	
327	  // Reached without the right role (old deep link, role changed meanwhile).
328	  // After every hook on purpose: hooks must run in the same order each render.
329	  if (!can('inventory.receive')) {
330	    return <NoPermission title={t('receiveItem')} onBack={() => navigation.goBack()} />;
331	  }
332	
333	  return (
334	    <KeyboardAvoidingView
335	      behavior={Platform.OS === 'ios' ? 'height' : undefined}
336	      style={{ flex: 1 }}
337	    >
338	      <View style={[styles.safe, { backgroundColor: palette.background }]}>
339	        <AppBar
340	          title={t('receiveItem')}
341	          onBack={() => navigation.goBack()}
342	          trailing={
343	            <View style={{ flexDirection: 'row', alignItems: 'center', gap: spacing.xs }}>
344	              {expected !== null ? (
345	                <StatusPill
346	                  label={`${projected} / ${expected}`}
347	                  tone={mismatch ? 'danger' : projected === expected ? 'success' : 'neutral'}
348	                />
349	              ) : null}
350	              <IconButton Icon={ScanLine} onPress={() => navigation.replace('Scanner')} />
351	            </View>
352	          }
353	        />
354	
355	        <ScrollView
356	          contentContainerStyle={[styles.content, { paddingBottom: spacing.xxxl + kbHeight }]}
357	          keyboardShouldPersistTaps="handled"
358	        >
359	        <Card tone="elevated" padding="xl">
360	          <Text variant="labelLarge" color={palette.onSurfaceVariant}>
361	            {t('product').toUpperCase()}
362	          </Text>
363	          <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'flex-end', marginTop: spacing.xs, gap: spacing.md }}>
364	            <Text variant="headlineSmall" style={{ flex: 1 }}>
365	              {resolvedName}
366	            </Text>
367	            {packDisplay ? (
368	              <Text variant="titleMedium" color={palette.onSurfaceVariant}>
369	                {packDisplay}
370	              </Text>
371	            ) : null}
372	          </View>
373	          {/* Barcode chip. For real (scanned or already-learned) barcodes
374	              we surface the code so guards can confirm at a glance. For
375	              an unmapped catalog pick we don't dump the synthetic
376	              `catalog_<product_id>` id — it's meaningless to the user.
