1	import { NativeStackScreenProps } from '@react-navigation/native-stack';
2	import { Check, ScanLine, Trash2, X } from 'lucide-react-native';
3	import React, { useCallback, useState } from 'react';
4	import { Alert, FlatList, Pressable, StyleSheet, View } from 'react-native';
5	import { formatExpiry } from '../../../utils/expiry';
6	import {
7	  AppBar,
8	  Button,
9	  Card,
10	  radius,
11	  spacing,
12	  Text,
13	} from '../../../design';
14	import { useT } from '../../../i18n';
15	import { StringKey, TParams } from '../../../i18n/strings';
16	import { RootStackParamList } from '../../../navigation/types';
17	import { haptic } from '../../../utils/haptics';
18	import { useOrderSession, OrderSessionItem, OrderBatch } from '../components/OrderSessionContext';
19	import { useTheme } from '../../../theme';
20	
21	type Props = NativeStackScreenProps<RootStackParamList, 'OrderSession'>;
22	
23	export function OrderSessionScreen({ navigation }: Props) {
24	  const t = useT();
25	  const { palette } = useTheme();
26	  const { items, removeItem, submitAll, clear, isActive } = useOrderSession();
27	  const [submitting, setSubmitting] = useState(false);
28	
29	  const handleSubmit = useCallback(async () => {
30	    if (items.length === 0) return;
31	    setSubmitting(true);
32	    try {
33	      await submitAll();
34	      haptic.success();
35	      navigation.replace('DeliverySummary', {
36	        items: items.map((i) => ({
37	          name: i.name,
38	          category: i.category,
39	          qty: i.qty,
40	        })),
41	        totalItems: items.length,
42	        totalQty: items.reduce((sum, i) => sum + i.qty, 0),
43	      });
44	    } finally {
45	      setSubmitting(false);
46	    }
47	  }, [items, submitAll, navigation]);
48	
49	  const handleCancel = useCallback(() => {
50	    Alert.alert(
51	      t('cancelOrder'),
52	      t('discardScannedItems', { count: items.length }),
53	      [
54	        { text: t('keepScanning'), style: 'cancel' },
55	        {
56	          text: t('discardAll'),
57	          style: 'destructive',
58	          onPress: () => {
59	            clear();
60	            haptic.warn();
61	            navigation.navigate('Home');
62	          },
63	        },
64	      ],
65	    );
66	  }, [items.length, clear, navigation, t]);
67	
68	  const handleRemoveItem = useCallback(
69	    (barcode: string, name: string) => {
70	      Alert.alert(t('removeItem'), t('removeItemBody', { name }), [
71	        { text: t('cancel'), style: 'cancel' },
72	        {
73	          text: t('remove'),
74	          style: 'destructive',
75	          onPress: () => {
76	            removeItem(barcode);
77	            haptic.tap();
78	          },
79	        },
80	      ]);
81	    },
82	    [removeItem, t],
83	  );
84	
85	  const renderItem = useCallback(
86	    ({ item }: { item: OrderSessionItem }) => (
87	      <Card tone="filled" padding="lg">
88	        <View style={styles.row}>
89	          <View style={{ flex: 1 }}>
90	            <Text variant="titleMedium">{item.name}</Text>
91	            <Text
92	              variant="bodyMedium"
93	              color={palette.onSurfaceVariant}
94	              style={{ marginTop: 2 }}
95	            >
