import { NativeStackScreenProps } from '@react-navigation/native-stack';
import { Check, ScanLine, Trash2, X } from 'lucide-react-native';
import React, { useCallback, useState } from 'react';
import { Alert, FlatList, Pressable, StyleSheet, View } from 'react-native';
import { formatExpiry } from '../../../utils/expiry';
import {
  AppBar,
  Button,
  Card,
  radius,
  spacing,
  Text,
} from '../../../design';
import { useT } from '../../../i18n';
import { StringKey, TParams } from '../../../i18n/strings';
import { RootStackParamList } from '../../../navigation/types';
import { haptic } from '../../../utils/haptics';
import { useOrderSession, OrderSessionItem, OrderBatch } from '../components/OrderSessionContext';
import { useTheme } from '../../../theme';

type Props = NativeStackScreenProps<RootStackParamList, 'OrderSession'>;

export function OrderSessionScreen({ navigation }: Props) {
  const t = useT();
  const { palette } = useTheme();
  const { items, removeItem, submitAll, clear, isActive } = useOrderSession();
  const [submitting, setSubmitting] = useState(false);

  const handleSubmit = useCallback(async () => {
    if (items.length === 0) return;
    setSubmitting(true);
    try {
      await submitAll();
      haptic.success();
      navigation.replace('DeliverySummary', {
        items: items.map((i) => ({
          name: i.name,
          category: i.category,
          qty: i.qty,
        })),
        totalItems: items.length,
        totalQty: items.reduce((sum, i) => sum + i.qty, 0),
      });
    } finally {
      setSubmitting(false);
    }
  }, [items, submitAll, navigation]);

  const handleCancel = useCallback(() => {
    Alert.alert(
      t('cancelOrder'),
      t('discardScannedItems', { count: items.length }),
      [
        { text: t('keepScanning'), style: 'cancel' },
        {
          text: t('discardAll'),
          style: 'destructive',
          onPress: () => {
            clear();
            haptic.warn();
            navigation.navigate('Home');
          },
        },
      ],
    );
  }, [items.length, clear, navigation, t]);

  const handleRemoveItem = useCallback(
    (barcode: string, name: string) => {
      Alert.alert(t('removeItem'), t('removeItemBody', { name }), [
        { text: t('cancel'), style: 'cancel' },
        {
          text: t('remove'),
          style: 'destructive',
          onPress: () => {
            removeItem(barcode);
            haptic.tap();
          },
        },
      ]);
    },
    [removeItem, t],
  );

  const renderItem = useCallback(
    ({ item }: { item: OrderSessionItem }) => (
      <Card tone="filled" padding="lg">
        <View style={styles.row}>
          <View style={{ flex: 1 }}>
            <Text variant="titleMedium">{item.name}</Text>
            <Text
              variant="bodyMedium"
              color={palette.onSurfaceVariant}
              style={{ marginTop: 2 }}
            >
              {item.category ?? '—'}
              {formatPack(item)}
              {formatBatches(item.batches, t)}
            </Text>
          </View>
          <View style={[styles.qtyBadge, { backgroundColor: palette.primaryContainer }]}>
            <Text variant="titleLarge" color={palette.primary}>
              {item.qty}
            </Text>
          </View>
          <Pressable
            onPress={() => handleRemoveItem(item.barcode, item.name)}
            hitSlop={12}
            style={styles.deleteBtn}
          >
            <Trash2 size={20} color={palette.error} strokeWidth={2.2} />
          </Pressable>
        </View>
      </Card>
    ),
    [handleRemoveItem, t],
  );

  return (
    <View style={[styles.safe, { backgroundColor: palette.background }]}>
      <AppBar
        title={`Order — ${items.length} item${items.length === 1 ? '' : 's'}`}
        subtitle={`Total: ${items.reduce((s, i) => s + i.qty, 0)} units`}
        onBack={() => navigation.goBack()}
      />

      <FlatList
        data={items}
        keyExtractor={(item) => item.barcode}
        contentContainerStyle={styles.list}
        ItemSeparatorComponent={() => <View style={{ height: spacing.sm }} />}
        renderItem={renderItem}
        ListEmptyComponent={
          <View style={styles.empty}>
            <Text
              variant="headlineSmall"
              style={{ textAlign: 'center' }}
            >
              {t('noItemsScanned')}
            </Text>
            <Text
              variant="bodyLarge"
              color={palette.onSurfaceVariant}
              style={{ textAlign: 'center', marginTop: spacing.sm }}
            >
              {t('scanNextItem')} — {t('addToOrder').toLowerCase()}.
            </Text>
          </View>
        }
      />

      <View style={[styles.footer, { backgroundColor: palette.surface, borderTopColor: palette.outlineVariant }]}>
        <Button
          label={t('scanNextItem')}
          leadingIcon={<ScanLine size={22} color={palette.onPrimary} strokeWidth={2.4} />}
          size="lg"
          fullWidth
          onPress={() => navigation.navigate('Scanner')}
        />
        {items.length > 0 && (
          <>
            <Button
              label={`${t('submitOrder')} (${items.length})`}
              variant="tonal"
              leadingIcon={<Check size={22} color={palette.onSecondaryContainer} strokeWidth={2.4} />}
              size="lg"
              fullWidth
              onPress={handleSubmit}
              loading={submitting}
              style={{ marginTop: spacing.sm }}
            />
            <Button
              label={t('cancelOrder')}
              variant="text"
              onPress={handleCancel}
              style={{ marginTop: spacing.xs }}
            />
          </>
        )}
      </View>
    </View>
  );
}

function formatPack(item: OrderSessionItem): string {
  const hasPack = item.packSize != null && item.packSize !== 1;
  if (!hasPack && !item.unit) return '';
  const parts: string[] = [];
  parts.push(String(item.qty));
  if (hasPack) parts.push(`× ${item.packSize}`);
  if (item.unit) parts.push(item.unit);
  return ` · ${parts.join(' ')}`;
}

function formatBatches(
  batches: OrderBatch[],
  t: (key: StringKey, params?: TParams) => string,
): string {
  const dated = batches.filter((b) => b.expiry);
  if (dated.length === 0) return '';
  const unique = Array.from(new Set(dated.map((b) => b.expiry as string))).sort();
  if (unique.length === 1) return ` · ${t('expShort', { date: formatExpiry(unique[0]) })}`;
  return ` · ${t('expiriesEarliest', { count: unique.length, date: formatExpiry(unique[0]) })}`;
}

const styles = StyleSheet.create({
  safe: { flex: 1 },
  list: { padding: spacing.xl, paddingBottom: spacing.xxxl },
  row: { flexDirection: 'row', alignItems: 'center', gap: spacing.md },
  qtyBadge: {
    minWidth: 48,
    alignItems: 'center',
    justifyContent: 'center',
    paddingVertical: spacing.xs,
    paddingHorizontal: spacing.md,
    borderRadius: radius.md,
  },
  empty: { padding: spacing.xxl },
  deleteBtn: {
    width: 40,
    height: 40,
    borderRadius: 20,
    alignItems: 'center',
    justifyContent: 'center',
  },
  footer: {
    padding: spacing.xl,
    borderTopWidth: 1,
  },
});

