import { CalendarOff, CalendarPlus } from 'lucide-react-native';
import React from 'react';
import { StyleSheet, View } from 'react-native';
import { Text } from '../design';
import { useTheme } from '../theme';
import { expiryUrgency } from '../utils/expiry';

const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];

/**
 * A date drawn as a calendar page: the month on a coloured strip, the day
 * big, the year small. Reads without reading: green = plenty of time,
 * amber = expiring within a month, red = expired. A crossed calendar means
 * "no expiry date"; a dashed page with + means "date not picked yet".
 */
export function DateTile({ iso, size = 64 }: { iso: string | null | undefined; size?: number }) {
  const { palette } = useTheme();
  const w = size;
  const h = Math.round(size * 1.08);

  if (iso === undefined) {
    return (
      <View style={[styles.tile, styles.center, { width: w, height: h, borderStyle: 'dashed', borderWidth: 2, borderColor: palette.primary, backgroundColor: palette.primaryContainer }]}>
        <CalendarPlus size={Math.round(size * 0.42)} color={palette.onPrimaryContainer} strokeWidth={2} />
      </View>
    );
  }
  if (iso === null) {
    return (
      <View style={[styles.tile, styles.center, { width: w, height: h, borderWidth: 1, borderColor: palette.outlineVariant, backgroundColor: palette.surfaceContainer }]}>
        <CalendarOff size={Math.round(size * 0.42)} color={palette.onSurfaceVariant} strokeWidth={2} />
      </View>
    );
  }

  const [y, m, d] = iso.split('-').map(Number);
  const urgency = expiryUrgency(iso);
  const strip = urgency === 'expired' ? palette.error : urgency === 'soon' ? palette.amber : palette.success;
  return (
    <View style={[styles.tile, { width: w, height: h, borderWidth: 1, borderColor: strip, backgroundColor: palette.surfaceContainerLowest }]}>
      <View style={[styles.strip, { backgroundColor: strip, height: Math.round(h * 0.28) }]}>
        <Text style={{ color: '#FFFFFF', fontSize: Math.round(size * 0.17), fontWeight: '800', letterSpacing: 0.5 }}>
          {MONTHS[(m ?? 1) - 1]}
        </Text>
      </View>
      <View style={styles.center}>
        <Text style={{ color: palette.onSurface, fontSize: Math.round(size * 0.38), lineHeight: Math.round(size * 0.44), fontWeight: '800' }}>
          {d}
        </Text>
        <Text style={{ color: palette.onSurfaceVariant, fontSize: Math.round(size * 0.15), fontWeight: '600' }}>
          {y}
        </Text>
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  tile: { borderRadius: 14, overflow: 'hidden' },
  strip: { alignItems: 'center', justifyContent: 'center' },
  center: { flex: 1, alignItems: 'center', justifyContent: 'center' },
});
EOF
