import { CalendarDays, CalendarOff, CalendarPlus, Trash2 } from 'lucide-react-native';
import React, { useMemo, useState } from 'react';
import { Pressable, StyleSheet, View } from 'react-native';
import { AmountStepper } from '../../../components/AmountStepper';
import { DateTile } from '../../../components/DateTile';
import { PackIcons } from '../../../components/PackIcons';
import { BottomSheet, spacing, Text } from '../../../design';
import { useT } from '../../../i18n';
import { useTheme } from '../../../theme';
import { compareExpiryAsc, relativeExpiry } from '../../../utils/expiry';
import { haptic } from '../../../utils/haptics';
import type { Batch } from './BatchEditor';
import { DatePickerModal } from './DatePickerModal';

function toISO(d: Date): string {
  return d.toISOString().split('T')[0];
}

/**
 * Packs that arrived with different expiry dates, drawn so it reads
 * without reading: each row is [calendar page]  − 3 +  [bin], meaning
 * "3 packs expire on this date". Rows sort earliest first (the order
 * they should be used). The total at the top is boxes plus a number.
 */
export function ExpiryGroups({ batches, onChange }: { batches: Batch[]; onChange: (next: Batch[]) => void }) {
  const t = useT();
  const { palette } = useTheme();
  // Which row's date is being chosen, and whether the calendar is open.
  const [choosingFor, setChoosingFor] = useState<number | null>(null);
  const [calendarFor, setCalendarFor] = useState<number | null>(null);

  const total = batches.reduce((s, b) => s + (b.qty || 0), 0);
  const rows = useMemo(
    () => batches.map((b, i) => ({ b, i })).sort((a, z) => compareExpiryAsc(a.b.expiry ?? null, z.b.expiry ?? null)),
    [batches],
  );

  const update = (i: number, next: Partial<Batch>) => onChange(batches.map((b, idx) => (idx === i ? { ...b, ...next } : b)));
  const remove = (i: number) => {
    haptic.tap();
    onChange(batches.filter((_, idx) => idx !== i));
  };
  const addRow = () => {
    haptic.tap();
    onChange([...batches, { qty: 1, expiry: undefined }]);
    // Straight to "which date?" for the new row.
    setChoosingFor(batches.length);
  };

  return (
    <View style={{ gap: spacing.md }}>
      {/* Total, as boxes and a number. */}
      <View style={[styles.total, { backgroundColor: palette.surfaceContainerLow }]}>
        <PackIcons count={total} size={20} />
        <Text style={{ fontSize: 36, lineHeight: 42, fontWeight: '800', color: palette.onSurface }}>{total}</Text>
        <Text variant="bodyMedium" color={palette.onSurfaceVariant}>
          {t('packsWord')}
        </Text>
      </View>

      {rows.map(({ b, i }) => {
        const rel = b.expiry ? relativeExpiry(b.expiry, t) : null;
        return (
          <View key={i} style={[styles.row, { borderColor: palette.outlineVariant, backgroundColor: palette.surfaceContainerLowest }]}>
            <Pressable onPress={() => setChoosingFor(i)} style={{ alignItems: 'center', width: 76 }} accessibilityRole="button" accessibilityLabel={t('expiryDateTitle')}>
              <DateTile iso={b.expiry} size={60} />
              <Text variant="labelMedium" color={palette.onSurfaceVariant} numberOfLines={1} style={{ marginTop: 4 }}>
                {b.expiry === undefined ? t('pickDateShort') : b.expiry === null ? t('noDateShort') : rel ?? ''}
              </Text>
            </Pressable>
            <View style={{ flex: 1 }}>
              <AmountStepper compact value={b.qty} onChange={(n) => update(i, { qty: n })} min={1} />
            </View>
            {batches.length > 1 ? (
              <Pressable onPress={() => remove(i)} hitSlop={10} style={styles.bin} accessibilityLabel={t('remove')}>
                <Trash2 size={22} color={palette.onSurfaceVariant} />
              </Pressable>
            ) : (
              <View style={styles.bin} />
            )}
          </View>
        );
      })}

      <Pressable
        onPress={addRow}
        accessibilityRole="button"
        style={({ pressed }) => [styles.add, { borderColor: palette.primary, backgroundColor: pressed ? palette.primaryContainer : 'transparent' }]}
      >
        <CalendarPlus size={24} color={palette.primary} />
        <Text variant="titleMedium" color={palette.primary} style={{ fontWeight: '700' }}>
          {t('addAnotherDate')}
        </Text>
      </Pressable>

      {/* Two big choices for a row's date. */}
      <BottomSheet visible={choosingFor !== null} onClose={() => setChoosingFor(null)}>
        <View style={{ gap: spacing.md, paddingBottom: spacing.sm }}>
          <Text variant="titleLarge" style={{ fontWeight: '700' }}>
            {t('expiryDateTitle')}
          </Text>
          <BigChoice
            Icon={CalendarDays}
            label={t('pickExpiry')}
            primary
            onPress={() => {
              setCalendarFor(choosingFor);
              setChoosingFor(null);
            }}
          />
          <BigChoice
            Icon={CalendarOff}
            label={t('noExpiry')}
            onPress={() => {
              if (choosingFor !== null) update(choosingFor, { expiry: null });
              setChoosingFor(null);
            }}
          />
        </View>
      </BottomSheet>

      <DatePickerModal
        visible={calendarFor !== null}
        value={calendarFor !== null && batches[calendarFor]?.expiry ? new Date(batches[calendarFor].expiry as string) : null}
        minimumDate={new Date()}
        onSelect={(d) => {
          if (calendarFor !== null) update(calendarFor, { expiry: toISO(d) });
          setCalendarFor(null);
        }}
        onDismiss={() => setCalendarFor(null)}
      />
    </View>
  );
}

function BigChoice({ Icon, label, onPress, primary }: { Icon: typeof CalendarDays; label: string; onPress: () => void; primary?: boolean }) {
  const { palette } = useTheme();
  return (
    <Pressable
      onPress={() => {
        haptic.tap();
        onPress();
      }}
      style={[
        styles.choice,
        { backgroundColor: primary ? palette.primary : palette.surfaceContainerLow, borderColor: primary ? palette.primary : palette.outlineVariant },
      ]}
    >
      <Icon size={26} color={primary ? palette.onPrimary : palette.onSurface} />
      <Text variant="titleMedium" color={primary ? palette.onPrimary : palette.onSurface} style={{ fontWeight: '700' }}>
        {label}
      </Text>
    </Pressable>
  );
}

const styles = StyleSheet.create({
  total: { alignItems: 'center', gap: spacing.xs, paddingVertical: spacing.lg, borderRadius: 18 },
  row: { flexDirection: 'row', alignItems: 'center', gap: spacing.md, borderWidth: 1, borderRadius: 18, padding: spacing.md },
  bin: { width: 40, height: 40, alignItems: 'center', justifyContent: 'center' },
  add: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    gap: spacing.sm,
    height: 60,
    borderRadius: 18,
    borderWidth: 2,
    borderStyle: 'dashed',
  },
  choice: { flexDirection: 'row', alignItems: 'center', gap: spacing.md, height: 60, borderRadius: 16, borderWidth: 1, paddingHorizontal: spacing.xl },
});
