def rep(f,old,new):
    s=open(f).read(); assert s.count(old)==1,(f,old[:70],s.count(old)); open(f,'w').write(s.replace(old,new))
# ── BottomBar: one scan button, meaning follows the page ──
f='components/shell/BottomBar.tsx'
rep(f,"import { useT } from '../../i18n';","import { useCan } from '../../auth';\nimport { useT } from '../../i18n';\nimport type { StringKey } from '../../i18n/strings';")
rep(f,"""  const { hubs, scanRoute } = useHubs();""","""  const { hubs, scanRoute } = useHubs();
  const can = useCan();

  // The only scan button in the app. It stays in one place and takes its
  // meaning from the page: items on Inventory, passes on Visitors, either
  // on Today/More. Hidden where the person's job has nothing to scan.
  const scan: { route: 'Scan' | 'GateScan' | 'Scanner'; labelKey: StringKey } | null =
    route.name === 'Home'
