1	import { NativeStackScreenProps } from '@react-navigation/native-stack';
2	import { Check } from 'lucide-react-native';
3	import { nanoid } from 'nanoid/non-secure';
4	import React, { useEffect, useMemo, useRef, useState } from 'react';
5	import {
6	  ActivityIndicator,
7	  KeyboardAvoidingView,
8	  Platform,
9	  ScrollView,
10	  StyleSheet,
11	  View,
12	} from 'react-native';
13	import {
14	  AppBar,
15	  Button,
16	  Card,
17	  spacing,
18	  Text,
19	} from '../../../design';
20	import { getSession } from '../../../auth/session';
21	import { correctStockLocal, findStock, getNearestExpiry, StockRow } from '../../../db/stock';
22	import { listLots, replaceLotsLocal } from '../../../db/lots';
23	import { enqueue } from '../../../db/outbox';
24	import { useT } from '../../../i18n';
25	import { useCan } from '../../../auth';
26	import { NoPermission } from '../../../components/NoPermission';
27	import { useTheme } from '../../../theme';
28	import { RootStackParamList } from '../../../navigation/types';
29	import { api, ApiError } from '../../../sync/api';
30	import { flushOnce } from '../../../sync/syncService';
31	import { haptic } from '../../../utils/haptics';
32	import { useKeyboardHeight } from '../../../hooks/useKeyboardHeight';
33	import { BatchEditor, Batch } from '../components/BatchEditor';
34	import { formatOnHand, resolveUnit } from '../../../units';
35	
36	type Props = NativeStackScreenProps<RootStackParamList, 'EditStock'>;
37	
38	/** Earliest non-null ISO date out of a list of batches. */
39	function earliestExpiry(batches: Batch[]): string | null {
40	  const sorted = batches
41	    .map((b) => b.expiry)
42	    .filter((e): e is string => !!e)
43	    .sort();
44	  return sorted[0] ?? null;
45	}
46	
47	/**
48	 * This screen records a STOCKTAKE: "I counted the shelf and there is
49	 * this much." A count is a fact about the physical world, so it always
50	 * applies — there is no state in which we ask the user to choose between
51	 * their count and a number the system remembers. If an admin's change
52	 * and this count both land, they apply in server-arrival order and the
53	 * later one wins, which is what a queue does.
54	 *
55	 * loading — first read still in flight; save disabled because there is
56	 *           nothing to save yet.
57	 * ready   — we have something on screen and the count can be recorded,
58	 *           online or off. The outbox reconciles it either way.
59	 *
60	 * Deliberately absent: a `conflict` state. See
61	 * Planning-docs/inventory_conflict_free_sync_design.md — a merge prompt
62	 * asks a non-power user a question they cannot answer, and it only
63	 * exists because someone wrote an absolute number. We keep the absolute
64	 * write (a count IS absolute) but stop treating a stale local number as
65	 * a competing opinion worth arbitrating.
66	 */
67	type VerifyStatus = 'loading' | 'ready';
68	
69	export function EditStockScreen({ route, navigation }: Props) {
70	  const t = useT();
71	  const can = useCan();
72	  const { palette } = useTheme();
73	  const kbHeight = useKeyboardHeight();
74	  const { barcode } = route.params;
75	
76	  const [row, setRow] = useState<StockRow | null>(null);
77	  const [originalQty, setOriginalQty] = useState<number>(0);
78	  const [originalExpiry, setOriginalExpiry] = useState<string | null>(null);
79	  const [originalBatches, setOriginalBatches] = useState<Batch[]>([]);
80	  const [batches, setBatches] = useState<Batch[]>([]);
81	
82	  const [saving, setSaving] = useState(false);
83	
84	  // Freshness fetch. Not a gate — we pull the server's lot breakdown so
85	  // the guard starts from the best numbers we have, then get out of the
86	  // way. A failure here never blocks recording a count: the shelf does
87	  // not stop being countable because the network is down.
88	  const [verifyStatus, setVerifyStatus] = useState<VerifyStatus>('loading');
89	  const [serverQty, setServerQty] = useState<number | null>(null);
90	
91	  /**
92	   * Where the batch rows on screen came from. The local read and the JIT
93	   * fetch race each other, so both consult this instead of assuming an
94	   * order. 'remote' wins and is never downgraded — the server's lot
95	   * breakdown is the real one.
96	   */
97	  const seedSource = useRef<'none' | 'local' | 'remote'>('none');
98	  /** Set once the guard edits anything, so a late-arriving JIT response
99	   *  can't wipe what they just typed. */
100	  const userTouched = useRef(false);
101	
102	  const applySeed = (
103	    seed: Batch[],
104	    source: 'local' | 'remote',
105	    qtyRef: number,
106	    expiryRef: string | null,
107	  ) => {
108	    seedSource.current = source;
109	    setOriginalBatches(seed);
110	    setBatches(seed);
111	    setOriginalQty(qtyRef);
112	    setOriginalExpiry(expiryRef);
113	  };
114	
115	  useEffect(() => {
116	    let cancelled = false;
117	    (async () => {
118	      const r = await findStock(barcode);
119	      const exp = await getNearestExpiry(barcode);
120	      const lots = await listLots(barcode);
121	      if (cancelled) return;
122	      if (!r) return;
123	      setRow(r);
124	      setVerifyStatus((s) => (s === 'loading' ? 'ready' : s));
125	      if (seedSource.current === 'remote') return;
126	      // Seed batches from local lots. If lots are empty (legacy row from
127	      // before the lots migration, or a cache that hasn't pulled batches
128	      // yet), synthesise one batch carrying the entire on_hand at the
129	      // cached nearest_expiry. That synthetic row is a placeholder to
130	      // look at, NOT something to save — the JIT fetch below replaces it
131	      // with the server's real breakdown, and Save stays disabled until
132	      // the fetch settles.
133	      const seed: Batch[] = lots.length > 0
134	        ? lots.map((l) => ({ expiry: l.expiry_date, qty: Number(l.qty) }))
135	        : [{ expiry: exp, qty: r.on_hand || 1 }];
136	      // Conflict reference = the earliest expiry actually present in what
137	      // we opened with. Deriving it from the seed rather than reading the
138	      // denormalised nearest_expiry column keeps the two in step even if
139	      // the column lags the lots it summarises — a mismatch here shows up
140	      // as a permanent, unresolvable "Stock has changed" banner.
141	      applySeed(seed, 'local', r.on_hand, earliestExpiry(seed));
142	    })();
143	    return () => { cancelled = true; };
144	  }, [barcode]);
145	
146	  // Fire the JIT fetch independently of the local read so neither
147	  // blocks the other. The 3 s timeout matches CatalogPickerScreen.
148	  useEffect(() => {
149	    let cancelled = false;
150	    const controller = new AbortController();
151	    const t = setTimeout(() => controller.abort(), 3000);
152	    (async () => {
153	      try {
154	        const remote = await api.fetch.stockOne(barcode);
155	        if (cancelled) return;
156	        const remoteQty = Number(remote.on_hand);
157	        const remoteExpiry = remote.nearest_expiry ?? null;
158	        setServerQty(remoteQty);
159	
160	        // Take the server's lot breakdown over anything we guessed
161	        // locally. Correcting stock REPLACES the lots, so seeding from a
162	        // cache that had no batches meant saving "one lot, no expiry"
163	        // over the real dated ones — the correction silently wiped the
164	        // expiry for everyone. Only skip this if the guard already
165	        // started editing; their input outranks a late response.
166	        const remoteLots = (remote.lots ?? []).map((l) => ({
167	          expiry: l.expiry_date,
168	          qty: Number(l.qty),
169	        }));
170	        if (remoteLots.length > 0 && !userTouched.current) {
171	          applySeed(remoteLots, 'remote', remoteQty, remoteExpiry);
172	        }
173	      } catch (err) {
174	        if (cancelled) return;
175	        // 401 is handled centrally; clear navigates to Login.
176	        if (err instanceof ApiError && err.status === 401) return;
177	        // Everything else — 404, offline, timeout, 5xx — is survivable.
178	        // We fall back to the local view and still let the count through.
179	        // Blocking here would punish the guard for our connectivity.
180	      } finally {
181	        clearTimeout(t);
182	        if (!cancelled) setVerifyStatus('ready');
183	      }
184	    })();
185	    return () => { cancelled = true; clearTimeout(t); controller.abort(); };
186	  }, [barcode]);
187	
188	  /** Total qty across all batches — replaces the old single qty stepper. */
189	  const qty = useMemo(() => batches.reduce((s, b) => s + (b.qty || 0), 0), [batches]);
190	
191	  /** Whatever ends up as the locally-tracked "nearest" expiry. */
192	  const localNearestExpiry = useMemo(() => earliestExpiry(batches), [batches]);
193	
194	  /** True iff batches differ from what was loaded — qty or per-batch
195	   *  expiry. Counts re-orderings as no change. */
196	  const changed = useMemo(() => {
197	    if (!row) return false;
198	    const a = [...batches]
199	      .map((b) => `${b.expiry ?? ''}@${b.qty}`)
200	      .sort()
201	      .join('|');
202	    const b = [...originalBatches]
203	      .map((b) => `${b.expiry ?? ''}@${b.qty}`)
204	      .sort()
205	      .join('|');
206	    return a !== b;
207	  }, [row, batches, originalBatches]);
208	  /**
209	   * The system's number differs from what the guard is about to record.
210	   * This is a note, not a question — it exists so the guard can catch
211	   * their own typo, and it never blocks the save. If they counted 12 and
212	   * we thought 20, they are standing at the shelf and we are not.
213	   */
214	  const systemDiffers =
215	    serverQty !== null && Math.abs(serverQty - qty) > 1e-6 && userTouched.current;
216	
217	  const submit = async () => {
218	    if (!row || !changed) return;
219	    const session = getSession();
220	    setSaving(true);
221	    try {
222	      // Coerce tri-state expiry (undefined = unset) → null for persistence.
223	      const cleanBatches = batches
224	        .filter((b) => b.qty > 0)
225	        .map((b) => ({ ...b, expiry: b.expiry ?? null }));
226	      // Optimistic local writes: stock cache + lots mirror.
227	      await correctStockLocal(barcode, qty, localNearestExpiry);
228	      await replaceLotsLocal(
229	        barcode,
230	        cleanBatches.map((b) => ({ expiry_date: b.expiry, qty: b.qty })),
231	      );
232	      await enqueue('stock_correction', {
233	        id: `crn_${nanoid(12)}`,
234	        barcode,
235	        product_name: row.name,
236	        old_qty: originalQty,
237	        new_qty: qty,
238	        old_expiry: originalExpiry,
239	        // New canonical shape: per-batch breakdown. Server's correction
240	        // route prefers `lots` over the legacy `new_expiry` /
241	        // `new_expiries` fields.
242	        lots: cleanBatches.map((b) => ({ expiry_date: b.expiry, qty: b.qty })),
243	        // Legacy fields kept for backward compatibility with older
244	        // server builds and dashboard audit views.
245	        new_expiry: cleanBatches.length === 1 ? cleanBatches[0].expiry : localNearestExpiry,
246	        new_expiries: null,
247	        performed_by: session?.guardId ?? null,
248	        performed_by_name: session?.guardName ?? null,
249	        corrected_at: Date.now(),
250	        // When the shelf was actually counted. Today this equals
251	        // corrected_at, but stamping it makes the count a dated
252	        // observation rather than an edit — which is what lets the
253	        // server later decide that an older in-flight movement was
254	        // already included in this count.
255	        counted_at: Date.now(),
256	      });
257	      // Await the flush so the StockScreen's focus refresh sees the
258	      // server-acknowledged value, not stale read-back data. Without
259	      // this, the GET races the POST and replaceStockFromRemote
260	      // overwrites the local optimistic write.
261	      await flushOnce().catch(() => {});
262	      haptic.success();
263	      navigation.goBack();
264	    } finally {
265	      setSaving(false);
266	    }
267	  };
268	
269	  // Reached without the right role (old deep link, role changed meanwhile).
270	  // After every hook on purpose: hooks must run in the same order each render.
271	  if (!can('inventory.adjust')) {
272	    return <NoPermission title={t('editStock')} onBack={() => navigation.goBack()} />;
273	  }
274	
275	  if (!row) {
276	    return (
277	      <View style={[styles.safe, { backgroundColor: palette.background }]}>
278	        <AppBar title={t('editStock')} onBack={() => navigation.goBack()} />
279	      </View>
280	    );
281	  }
282	
283	  return (
284	    <KeyboardAvoidingView
285	      behavior={Platform.OS === 'ios' ? 'height' : undefined}
286	      style={{ flex: 1 }}
287	    >
288	      <View style={[styles.safe, { backgroundColor: palette.background }]}>
289	        <AppBar title={t('editStock')} subtitle={t('editStockSub')} onBack={() => navigation.goBack()} />
290	
291	        <ScrollView
292	          contentContainerStyle={[styles.content, { paddingBottom: spacing.xxxl + kbHeight }]}
293	          keyboardShouldPersistTaps="handled"
294	        >
295	          {/* Two states only. While the freshest numbers are still
296	              loading we say so; once loaded we may note that the system
297	              expected a different total. There is deliberately no
298	              banner that asks the guard to choose a number. */}
299	          {verifyStatus === 'loading' && (
300	            <View style={[styles.statusBanner, { borderColor: palette.outlineVariant }]}>
301	              <ActivityIndicator color={palette.primary} size="small" />
302	              <Text variant="bodyMedium" color={palette.onSurfaceVariant} style={{ marginLeft: spacing.sm }}>
303	                {t('verifying')}
304	              </Text>
305	            </View>
306	          )}
307	          {systemDiffers && serverQty !== null && (
308	            <View
309	              style={[
310	                styles.statusBanner,
311	                {
312	                  borderColor: palette.outlineVariant,
313	                  backgroundColor: palette.surfaceContainerLow,
314	                },
315	              ]}
316	            >
317	              <Text variant="bodyMedium" color={palette.onSurfaceVariant} style={{ flex: 1 }}>
318	                {t('systemShows', {
319	                  amount: formatOnHand(serverQty, row?.pack_size, row?.unit),
320	                })}
321	              </Text>
322	            </View>
323	          )}
324	
325	          <Card tone="elevated" padding="xl">
326	            <Text variant="labelLarge" color={palette.onSurfaceVariant}>
327	              {t('product').toUpperCase()}
328	            </Text>
329	            <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'flex-end', marginTop: spacing.xs, gap: spacing.md }}>
330	              <Text variant="headlineSmall" style={{ flex: 1 }}>{row.name}</Text>
331	            </View>
332	            <Text variant="bodyMedium" color={palette.onSurfaceVariant} style={{ marginTop: spacing.md }}>
333	              {t('currentCount')}: {formatOnHand(originalQty, row.pack_size, row.unit)}
334	            </Text>
335	          </Card>
336	
337	          <BatchEditor
338	            batches={batches}
339	            onChange={(next) => {
340	              userTouched.current = true;
341	              setBatches(next);
342	            }}
343	            unit={row.unit ?? null}
344	            packSize={row.pack_size ?? null}
345	            decimal={resolveUnit(row.unit).nature === 'continuous'}
346	            // Corrections are counted in base units — the guard weighs
347	            // "347 g left", they don't estimate "0.694 of a 500 g tub".
348	            editInBaseUnits
349	          />
350	        </ScrollView>
351	
352	        <View style={[styles.footer, { backgroundColor: palette.surface, borderTopColor: palette.outlineVariant }]}>
353	          {/* The only reasons a count cannot be recorded are that we
354	              have not loaded the item yet, or nothing was changed. Being
355	              offline is NOT one of them — the count goes to the outbox
356	              and reconciles when the network returns. */}
357	          <Button
358	            label={changed ? t('recordCount') : t('noChanges')}
359	            onPress={submit}
360	            loading={saving}
361	            disabled={!changed || verifyStatus === 'loading'}
362	            size="lg"
363	            fullWidth
364	            Icon={Check}
365	          />
366	          <Button
367	            label={t('cancel')}
368	            variant="text"
369	            onPress={() => navigation.goBack()}
370	            style={{ marginTop: spacing.sm }}
371	          />
372	        </View>
373	      </View>
374	    </KeyboardAvoidingView>
375	  );
376	}
377	
378	const styles = StyleSheet.create({
379	  safe: { flex: 1 },
380	  content: { padding: spacing.xl, gap: spacing.xl },
381	  footer: {
382	    padding: spacing.xl,
383	    borderTopWidth: 1,
384	  },
385	  statusBanner: {
386	    flexDirection: 'row',
387	    alignItems: 'center',
388	    padding: spacing.md,
389	    borderRadius: 8,
390	    borderWidth: 1,
391	  },
392	});
