  const [looseSmall, setLooseSmall] = useState<number | null>(null);""")
old="""              <View>
                <Question Icon={Package} text={t('howManyPacks')} />
                <AmountStepper value={single.qty} onChange={(n) => setSingle({ qty: n })} min={1} unitLabel={t('packsWord')} />
