108	 * Returns the mode and the starting amount in packs.
109	 */
110	function startingTake(row: StockRow, available: number): { mode: 'whole' | 'some'; packs: number; small: number } {
111	  const shape = productShape(row.pack_size, row.unit);
112	  if (shape === 'single' || available >= 1) {
113	    return { mode: 'whole', packs: Math.min(1, Math.floor(available)), small: smallStep(row.pack_size, row.unit) };
