115	  const maxSmall = Math.floor(available * smallPerPack(row.pack_size, row.unit));
116	  const small = Math.max(0, Math.min(smallStep(row.pack_size, row.unit), maxSmall));
117	  return { mode: 'some', packs: smallToPacks(small, row.pack_size, row.unit), small };
