567	              <Text variant="bodyMedium" color={palette.onSurfaceVariant}>
568	                {t('inStoreAmount', { amount: formatOnHandShort(inStore, selected.pack_size, selected.unit) })}
569	              </Text>
570	            </View>
571	          </View>
572	
573	          {/* Live count check. Offline still allows taking out against the
574	              saved count (it queues); only "absent" blocks. */}
575	          {verifyStatus === 'verifying' ? (
576	            <View style={styles.note}>
577	              <ActivityIndicator color={palette.primary} size="small" />
578	              <Text variant="bodyMedium" color={palette.onSurfaceVariant}>
579	                {t('checkingCount')}
580	              </Text>
581	            </View>
582	          ) : null}
583	          {verifyStatus === 'offline' || verifyStatus === 'error' ? (
584	            <View style={[styles.note, styles.noteBox, { backgroundColor: palette.surfaceContainerLow }]}>
585	              <CloudOff size={20} color={palette.onSurfaceVariant} />
586	              <Text variant="bodyMedium" color={palette.onSurfaceVariant} style={{ flex: 1 }}>
587	                {t('dispenseOfflineNote')}
588	              </Text>
589	            </View>
590	          ) : null}
591	          {verifyStatus === 'absent' ? (
592	            <View style={[styles.note, styles.noteBox, { backgroundColor: palette.errorContainer }]}>
593	              <XCircle size={20} color={palette.onErrorContainer} />
594	              <Text variant="bodyMedium" color={palette.onErrorContainer} style={{ flex: 1 }}>
595	                {t('itemNotOnServer')}
596	              </Text>
597	            </View>
598	          ) : null}
599	
600	          {verifyStatus === 'verifying' ? (
601	            <View style={{ gap: spacing.md }}>
602	              <Skeleton width="60%" height={18} />
603	              <Skeleton width="100%" height={64} rounded="md" />
604	            </View>
605	          ) : (
606	            <>
607	              <View>
608	                <Question Icon={HandCoins} text={t('howManyTaking')} />
609	                {shape !== 'single' ? (
610	                  <View style={styles.modeRow}>
611	                    <ModeTile
612	                      Icon={Package}
613	                      label={t('wholePackChoice')}
614	                      on={takeMode === 'whole'}
615	                      disabled={maxWhole < 1}
616	                      onPress={() => {
617	                        setTakeMode('whole');
618	                        setQty(Math.min(Math.max(1, Math.round(qty)), maxWhole));
619	                      }}
620	                    />
621	                    <ModeTile
622	                      Icon={PackageOpen}
623	                      label={shape === 'countPack' ? t('somePieces') : t('someOfIt')}
624	                      on={takeMode === 'some'}
625	                      disabled={maxSome < 1}
626	                      onPress={() => {
627	                        const small = Math.max(1, Math.min(someSmall || step, maxSome));
628	                        setTakeMode('some');
629	                        setSomeSmall(small);
630	                        setQty(smallToPacks(small, selected.pack_size, selected.unit));
631	                      }}
632	                    />
633	                  </View>
634	                ) : null}
635	
636	                {takeMode === 'whole' || shape === 'single' ? (
637	                  <AmountStepper
638	                    value={Math.round(qty)}
639	                    onChange={(n) => setQty(n)}
640	                    min={1}
641	                    max={maxWhole}
642	                    unitLabel={shape === 'single' ? formatOnHandShort(Math.round(qty), selected.pack_size, selected.unit).replace(/^\S+\s*/, '') : t('packsWord')}
643	                  />
644	                ) : (
645	                  <View style={{ gap: spacing.lg }}>
646	                    {/* One-tap amounts, made from the pack size. */}
647	                    <View style={styles.quickRow}>
648	                      {quick.filter((v) => v <= maxSome).map((v) => (
649	                        <Chip key={v} label={formatSmall(v, selected.unit)} selected={someSmall === v} onPress={() => setSome(v)} />
650	                      ))}
651	                    </View>
652	                    <AmountStepper
653	                      value={someSmall}
654	                      onChange={setSome}
655	                      min={1}
656	                      max={maxSome}
657	                      step={step}
658	                      unitLabel={someSmall >= smallUnit(selected.unit).perBase && smallUnit(selected.unit).perBase > 1
659	                        ? formatSmall(someSmall, selected.unit)
660	                        : smallUnit(selected.unit).symbol}
661	                    />
662	                    {shape === 'countPack' && smallPerPack(selected.pack_size, selected.unit) <= 24 ? (
663	                      <OpenBox
664	                        perPack={smallPerPack(selected.pack_size, selected.unit)}
665	                        available={inStore}
666	                        taking={someSmall}
667	                      />
668	                    ) : null}
669	                  </View>
670	                )}
671	
672	                {/* Before and after, as one bar: what stays, what goes. */}
673	                <View style={[styles.track, { backgroundColor: palette.surfaceContainerHigh }]}>
674	                  <View style={{ flex: after, backgroundColor: afterColor }} />
675	                  <View style={{ flex: Math.min(totalTaken, inStore), backgroundColor: palette.primaryContainer }} />
676	                </View>
677	                <View style={styles.afterRow}>
678	                  {afterStatus !== 'ok' ? <AlertTriangle size={18} color={afterColor} /> : null}
679	                  <Text variant="bodyLarge" color={afterStatus === 'ok' ? palette.onSurfaceVariant : afterColor} style={{ fontWeight: afterStatus === 'ok' ? '400' : '700' }}>
680	                    {t('leftAfterThis', { amount: formatOnHandShort(after, selected.pack_size, selected.unit) })}
681	                  </Text>
682	                </View>
683	              </View>
684	
685	              {availability.length > 1 && takeMode === 'some' ? (
686	                <View style={styles.note}>
687	                  <CalendarDays size={20} color={palette.onSurfaceVariant} />
688	                  <Text variant="bodyMedium" color={palette.onSurfaceVariant}>
689	                    {t('takenFromOldest')}
690	                  </Text>
691	                </View>
692	              ) : null}
693	              {availability.length > 1 && takeMode === 'whole' ? (
694	                <View>
