706	                      mode={dispenseMode}
707	                    />
708	                  )}
709	                </View>
710	              ) : null}
711	            </>
712	          )}
713	
714	          <View>
715	            <Question Icon={Tag} text={t('whatIsItFor')} />
716	            <View style={styles.reasonGrid}>
717	              {REASONS.map((r) => {
718	                const on = r.value === reason;
719	                return (
720	                  <Pressable
721	                    key={r.value}
722	                    onPress={() => {
723	                      haptic.tap();
724	                      setReason(r.value);
725	                    }}
726	                    accessibilityRole="radio"
727	                    accessibilityState={{ selected: on }}
728	                    style={[
729	                      styles.reason,
730	                      {
731	                        borderColor: on ? palette.primary : palette.outlineVariant,
732	                        borderWidth: on ? 2 : 1,
733	                        backgroundColor: on ? palette.primaryContainer : palette.surfaceContainerLowest,
734	                      },
735	                    ]}
736	                  >
737	                    <r.Icon size={26} color={on ? palette.onPrimaryContainer : palette.onSurfaceVariant} />
738	                    <Text variant="labelLarge" color={on ? palette.onPrimaryContainer : palette.onSurface} numberOfLines={1} style={{ fontWeight: on ? '700' : '500' }}>
739	                      {t(r.labelKey)}
740	                    </Text>
741	                  </Pressable>
742	                );
743	              })}
744	            </View>
745	          </View>
746	
747	          {/* Always the signed-in person: no field to fill, just shown. */}
748	          <View style={styles.note}>
749	            <UserRound size={20} color={palette.onSurfaceVariant} />
750	            <Text variant="bodyMedium" color={palette.onSurfaceVariant}>
751	              {t('takenByName', { name: getSession()?.guardName ?? '' })}
752	            </Text>
753	          </View>
754	        </ScrollView>
755	
756	        <View style={[styles.footer, { backgroundColor: palette.background, borderTopColor: palette.outlineVariant }]}>
757	          {/* Blocked only while the live check runs or when the server has
758	              no record of the item ('absent'). Offline falls back to the
759	              saved count (offline-first): the write queues and reconciles. */}
760	          <Button
761	            label={totalTaken > 0 ? t('takeOutAmount', { amount: amountTaken }) : t('takeOutAction')}
762	            onPress={submit}
763	            loading={saving}
764	            disabled={verifyStatus === 'verifying' || verifyStatus === 'absent' || totalTaken <= 0}
765	            size="lg"
766	            fullWidth
767	            Icon={HandCoins}
768	          />
769	        </View>
770	      </KeyboardAvoidingView>
771	    </View>
772	  );
773	}
774	
775	/** Whole pack or part of one: a big picture choice. */
776	function ModeTile({ Icon, label, on, disabled, onPress }: { Icon: LucideIcon; label: string; on: boolean; disabled?: boolean; onPress: () => void }) {
777	  const { palette } = useTheme();
778	  return (
779	    <Pressable
780	      onPress={() => {
781	        if (disabled) return;
782	        haptic.tap();
783	        onPress();
784	      }}
785	      accessibilityRole="radio"
786	      accessibilityState={{ selected: on, disabled }}
787	      style={[
788	        styles.modeTile,
789	        {
790	          borderColor: on ? palette.primary : palette.outlineVariant,
791	          borderWidth: on ? 2 : 1,
792	          backgroundColor: on ? palette.primaryContainer : palette.surfaceContainerLowest,
793	          opacity: disabled ? 0.4 : 1,
794	        },
795	      ]}
