798	      <Text variant="titleMedium" color={on ? palette.onPrimaryContainer : palette.onSurface} style={{ fontWeight: '700' }}>
799	        {label}
800	      </Text>
801	    </Pressable>
802	  );
803	}
804	
805	/**
806	 * The open box drawn as slots: pieces being taken, pieces left in it, and
807	 * empty slots already used. With no open box, a full box is opened.
808	 */
809	function OpenBox({ perPack, available, taking }: { perPack: number; available: number; taking: number }) {
810	  const t = useT();
811	  const { palette } = useTheme();
812	  const loose = Math.round((available - Math.floor(available + 1e-9)) * perPack);
813	  const inBox = loose > 0 ? loose : available >= 1 ? perPack : 0;
814	  const take = Math.min(taking, inBox);
815	  const slot = (i: number) =>
816	    i < take ? 'take' : i < inBox ? 'have' : 'empty';
817	  return (
818	    <View style={{ gap: spacing.sm }}>
819	      <View style={[styles.box, { backgroundColor: palette.surfaceContainerLow, borderColor: palette.outlineVariant }]}>
820	        {Array.from({ length: perPack }).map((_, i) => {
821	          const k = slot(i);
822	          return (
823	            <View
824	              key={i}
825	              style={[
826	                styles.slot,
827	                k === 'take'
828	                  ? { backgroundColor: palette.primaryContainer, borderColor: palette.primary, borderWidth: 2 }
829	                  : k === 'have'
830	                    ? { backgroundColor: palette.surfaceContainerLowest, borderColor: palette.outlineVariant, borderWidth: 1 }
831	                    : { borderColor: palette.outlineVariant, borderWidth: 1.5, borderStyle: 'dashed' },
832	              ]}
833	            />
834	          );
835	        })}
836	      </View>
837	      <View style={styles.legend}>
838	        <Legend color={palette.primaryContainer} border={palette.primary} label={t('takingLegend')} />
839	        <Legend color={palette.surfaceContainerLowest} border={palette.outlineVariant} label={t('leftInBoxLegend')} />
840	      </View>
841	    </View>
842	  );
843	}
844	
845	function Legend({ color, border, label }: { color: string; border: string; label: string }) {
846	  const { palette } = useTheme();
847	  return (
848	    <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6 }}>
849	      <View style={{ width: 14, height: 14, borderRadius: 4, backgroundColor: color, borderWidth: 1.5, borderColor: border }} />
850	      <Text variant="labelMedium" color={palette.onSurfaceVariant}>
851	        {label}
852	      </Text>
853	    </View>
854	  );
855	}
856	
857	/** A question with its picture, so the icon carries it before the words do. */
858	function Question({ Icon, text }: { Icon: LucideIcon; text: string }) {
859	  const { palette } = useTheme();
860	  return (
861	    <View style={styles.questionRow}>
862	      <View style={[styles.questionIcon, { backgroundColor: palette.primaryContainer }]}>
863	        <Icon size={22} color={palette.onPrimaryContainer} />
864	      </View>
865	      <Text variant="titleMedium" style={{ fontWeight: '700', flex: 1 }}>
866	        {text}
867	      </Text>
868	    </View>
869	  );
870	}
871	
872	const styles = StyleSheet.create({
873	  safe: { flex: 1 },
874	  search: {
875	    flexDirection: 'row',
876	    alignItems: 'center',
877	    gap: spacing.md,
878	    height: 52,
879	    marginHorizontal: spacing.xl,
880	    paddingHorizontal: spacing.lg,
881	    borderRadius: 16,
882	    borderWidth: 1,
883	  },
884	  searchInput: { flex: 1, fontSize: 16, paddingVertical: 0 },
885	  chips: { gap: spacing.sm, paddingHorizontal: spacing.xl, paddingVertical: spacing.md },
886	  pickRow: { flexDirection: 'row', alignItems: 'center', gap: spacing.lg, minHeight: 72, paddingHorizontal: spacing.xl, paddingVertical: spacing.md },
887	  skeletonRow: { flexDirection: 'row', alignItems: 'center', gap: spacing.lg, paddingHorizontal: spacing.xl, paddingVertical: spacing.md },
888	  empty: { padding: spacing.xxl },
889	  body: { flexGrow: 1, padding: spacing.xl, gap: spacing.xxl },
890	  product: { flexDirection: 'row', alignItems: 'center', gap: spacing.lg },
891	  note: { flexDirection: 'row', alignItems: 'center', gap: spacing.sm },
892	  noteBox: { padding: spacing.md, borderRadius: 14 },
