894	  questionIcon: { width: 40, height: 40, borderRadius: 12, alignItems: 'center', justifyContent: 'center' },
895	  track: { flexDirection: 'row', height: 12, borderRadius: 6, overflow: 'hidden', marginTop: spacing.xl, gap: 2 },
896	  afterRow: { flexDirection: 'row', alignItems: 'center', gap: spacing.sm, marginTop: spacing.sm },
897	  reasonGrid: { flexDirection: 'row', flexWrap: 'wrap', gap: spacing.sm },
898	  modeRow: { flexDirection: 'row', gap: spacing.md, marginBottom: spacing.lg },
899	  modeTile: { flex: 1, alignItems: 'center', justifyContent: 'center', gap: spacing.xs, paddingVertical: spacing.md, borderRadius: 18 },
900	  quickRow: { flexDirection: 'row', flexWrap: 'wrap', gap: spacing.sm },
