 * NOTE: This module-level export remains the source of truth for components
 * that haven't migrated to `useTheme()` yet. Once the theme system is wired
 * through everywhere, this can become a re-export of the active theme's
 * palette. For now both code paths resolve to the same colors.
 */
export const palette = {
  primary: '#92288E',
  onPrimary: '#FFFFFF',
  primaryContainer: '#F8D9F5',
  onPrimaryContainer: '#310031',

  secondary: '#6E5868',
  onSecondary: '#FFFFFF',
  secondaryContainer: '#F8DAEF',
  onSecondaryContainer: '#271624',

  tertiary: '#7C5635',
  onTertiary: '#FFFFFF',
  tertiaryContainer: '#FFDCBE',
  onTertiaryContainer: '#2C1600',

  error: '#BA1A1A',
  onError: '#FFFFFF',
  errorContainer: '#FFDAD6',
  onErrorContainer: '#410002',

  warn: '#7A5900',
  onWarn: '#FFFFFF',
  warnContainer: '#FFDF9E',
  onWarnContainer: '#261A00',

  // Extended Material 3 colour role for "healthy / in stock". Green is
  // load-bearing in inventory — it is the difference between "fine" and
  // "go buy more" — so it belongs in the token set rather than as a
  // hardcoded #43A047 scattered across screens, which is what it was.
  // Tonal values follow the same M3 recipe as error/warn above.
  success: '#276A2B',
  onSuccess: '#FFFFFF',
  successContainer: '#ACF3A5',
  onSuccessContainer: '#002204',

  // Neutrals are true greys, not purple-tinted: white space and one brand
  // colour read as calm and premium; tinted greys read as muddy.
  background: '#FFFFFF',
  onBackground: '#111114',

  surface: '#FFFFFF',
  onSurface: '#111114',
  surfaceDim: '#DCDCE0',
  surfaceBright: '#FFFFFF',

  surfaceContainerLowest: '#FFFFFF',
  surfaceContainerLow: '#F7F7F9',
  surfaceContainer: '#F2F2F5',
  surfaceContainerHigh: '#ECECF0',
  surfaceContainerHighest: '#E5E5EA',

  onSurfaceVariant: '#62646B',
  outline: '#8B8D94',
  outlineVariant: '#E4E5E9',

  scrim: 'rgba(0,0,0,0.45)',

  // Attention amber for status icons and words (the warn container pair is
  // too brown for a small icon).
  amber: '#D97706',
  amberSoft: '#FFF8EB',
  amberLine: '#F6D9A6',

  // Header band on hub screens: a deep plum from the brand seed, so white
  // text reads at AAA contrast and the white sheet below can overlap it.
  band: '#3D0E3B',
  onBand: '#FFFFFF',
  onBandMuted: 'rgba(255,255,255,0.74)',
} as const;

