1	import { NativeStackScreenProps } from '@react-navigation/native-stack';
2	import { Check, Package, PackageOpen, type LucideIcon } from 'lucide-react-native';
3	import { nanoid } from 'nanoid/non-secure';
4	import React, { useEffect, useMemo, useRef, useState } from 'react';
5	import { ActivityIndicator, KeyboardAvoidingView, Platform, Pressable, ScrollView, StyleSheet, View } from 'react-native';
6	import Svg, { ClipPath, Defs, Path, Rect } from 'react-native-svg';
7	import { AmountStepper } from '../../../components/AmountStepper';
8	import { AppBar, Button, IconBadge, spacing, Text } from '../../../design';
9	import { getSession } from '../../../auth/session';
10	import { correctStockLocal, findStock, getNearestExpiry, StockRow } from '../../../db/stock';
11	import { listLots, replaceLotsLocal } from '../../../db/lots';
12	import { enqueue } from '../../../db/outbox';
13	import { useT } from '../../../i18n';
14	import { useCan } from '../../../auth';
15	import { NoPermission } from '../../../components/NoPermission';
16	import { useTheme } from '../../../theme';
17	import { RootStackParamList } from '../../../navigation/types';
18	import { api, ApiError } from '../../../sync/api';
19	import { flushOnce } from '../../../sync/syncService';
20	import { haptic } from '../../../utils/haptics';
21	import { useKeyboardHeight } from '../../../hooks/useKeyboardHeight';
22	import { formatAmount, formatSmall, productShape, smallPerPack, smallStep, smallUnit } from '../../../units';
23	import type { Batch } from '../components/BatchEditor';
24	import { ExpiryGroups } from '../components/ExpiryGroups';
25	import { categoryIcon } from '../categoryIcon';
26	import { joinLots, lotsKey, splitLots, type Lot } from '../countMath';
27	
28	type Props = NativeStackScreenProps<RootStackParamList, 'EditStock'>;
29	
30	
31	/**
32	 * Correct count: a STOCKTAKE ("I counted the shelf and there is this
33	 * much"). A count is a fact about the physical world, so it always applies;
34	 * there is deliberately no conflict state (see
35	 * Planning-docs/inventory_conflict_free_sync_design.md).
36	 *
37	 * People count what they can see: full packs (per expiry date), then the
38	 * one open pack in exact kg + grams or pieces. Bag pictures only pre-fill
39	 * the open-pack amount; the saved number is always exact. On save the
40	 * open pack is added back to the dated batch it came from, so expiry
41	 * dates are never lost.
42	 */
43	type VerifyStatus = 'loading' | 'ready';
44	
45	const EPS = 1e-9;
46	
47	export function EditStockScreen({ route, navigation }: Props) {
48	  const t = useT();
49	  const can = useCan();
50	  const { palette } = useTheme();
51	  const kbHeight = useKeyboardHeight();
52	  const { barcode } = route.params;
53	
54	  const [row, setRow] = useState<StockRow | null>(null);
55	  const [originalQty, setOriginalQty] = useState<number>(0);
56	  const [originalExpiry, setOriginalExpiry] = useState<string | null>(null);
57	  const [originalLots, setOriginalLots] = useState<Lot[]>([]);
58	  const [full, setFull] = useState<Batch[]>([]);
59	  const [openSmall, setOpenSmall] = useState(0);
60	  const [openExpiry, setOpenExpiry] = useState<string | null | undefined>(undefined);
61	  const [saving, setSaving] = useState(false);
62	  const [verifyStatus, setVerifyStatus] = useState<VerifyStatus>('loading');
63	
64	  /** 'remote' wins over 'local' and is never downgraded (the server's lot breakdown is the real one). */
65	  const seedSource = useRef<'none' | 'local' | 'remote'>('none');
66	  /** Set once the person edits anything, so a late server reply can't wipe what they typed. */
67	  const userTouched = useRef(false);
68	
69	  const shape = row ? productShape(row.pack_size, row.unit) : 'single';
70	  const perPack = row ? smallPerPack(row.pack_size, row.unit) : 1;
71	  const countsOpen = shape !== 'single';
72	
73	  const applySeed = (lots: Lot[], r: StockRow, source: 'local' | 'remote', qtyRef: number) => {
74	    seedSource.current = source;
75	    const pp = smallPerPack(r.pack_size, r.unit);
76	    const split = splitLots(lots, pp, productShape(r.pack_size, r.unit) !== 'single');
77	    setOriginalLots(lots);
78	    setFull(split.full);
79	    setOpenSmall(split.openSmall);
80	    setOpenExpiry(split.openExpiry);
81	    setOriginalQty(qtyRef);
82	    setOriginalExpiry(lots.map((l) => l.expiry).filter((e): e is string => !!e).sort()[0] ?? null);
83	  };
84	
85	  useEffect(() => {
86	    let cancelled = false;
87	    (async () => {
88	      const r = await findStock(barcode);
89	      const exp = await getNearestExpiry(barcode);
90	      const lots = await listLots(barcode);
91	      if (cancelled || !r) return;
92	      setRow(r);
93	      setVerifyStatus((s) => (s === 'loading' ? 'ready' : s));
94	      if (seedSource.current === 'remote') return;
95	      // No lots yet (legacy row): one placeholder lot with the cached total.
96	      const seed: Lot[] = lots.length > 0
97	        ? lots.map((l) => ({ expiry: l.expiry_date, qty: Number(l.qty) }))
98	        : [{ expiry: exp, qty: r.on_hand || 0 }];
99	      applySeed(seed, r, 'local', r.on_hand);
100	    })();
101	    return () => { cancelled = true; };
102	    // eslint-disable-next-line react-hooks/exhaustive-deps
103	  }, [barcode]);
104	
105	  // Fresh lot breakdown from the server, independent of the local read. A
106	  // failure never blocks the count: the shelf stays countable offline.
107	  useEffect(() => {
108	    let cancelled = false;
109	    const controller = new AbortController();
110	    const timer = setTimeout(() => controller.abort(), 3000);
111	    (async () => {
112	      try {
113	        const remote = await api.fetch.stockOne(barcode);
114	        const r = await findStock(barcode);
115	        if (cancelled || !r) return;
116	        // Correcting REPLACES the lots, so seed from the server's real dated
117	        // batches rather than a cache that might have none.
118	        const remoteLots = (remote.lots ?? []).map((l) => ({ expiry: l.expiry_date, qty: Number(l.qty) }));
119	        if (remoteLots.length > 0 && !userTouched.current) applySeed(remoteLots, r, 'remote', Number(remote.on_hand));
120	      } catch (err) {
121	        if (cancelled) return;
122	        if (err instanceof ApiError && err.status === 401) return;
123	      } finally {
124	        clearTimeout(timer);
125	        if (!cancelled) setVerifyStatus('ready');
126	      }
127	    })();
128	    return () => { cancelled = true; clearTimeout(timer); controller.abort(); };
129	    // eslint-disable-next-line react-hooks/exhaustive-deps
130	  }, [barcode]);
131	
132	  const nextLots = useMemo(() => joinLots(full, countsOpen ? openSmall : 0, openExpiry, perPack), [full, openSmall, openExpiry, perPack, countsOpen]);
133	  const total = useMemo(() => nextLots.reduce((s, l) => s + l.qty, 0), [nextLots]);
134	  const changed = !!row && lotsKey(nextLots) !== lotsKey(originalLots);
135	  const diff = total - originalQty;
136	
137	  const touch = () => { userTouched.current = true; };
138	
139	  const submit = async () => {
140	    if (!row || !changed) return;
141	    const session = getSession();
142	    setSaving(true);
143	    try {
144	      const nearest = nextLots.map((l) => l.expiry).filter((e): e is string => !!e).sort()[0] ?? null;
145	      await correctStockLocal(barcode, total, nearest);
146	      await replaceLotsLocal(barcode, nextLots.map((l) => ({ expiry_date: l.expiry, qty: l.qty })));
147	      await enqueue('stock_correction', {
148	        id: `crn_${nanoid(12)}`,
149	        barcode,
150	        product_name: row.name,
151	        old_qty: originalQty,
152	        new_qty: total,
153	        old_expiry: originalExpiry,
154	        // Canonical shape: per-batch breakdown (the server prefers `lots`).
155	        lots: nextLots.map((l) => ({ expiry_date: l.expiry, qty: l.qty })),
156	        // Legacy fields for older servers and audit views.
157	        new_expiry: nextLots.length === 1 ? nextLots[0].expiry : nearest,
158	        new_expiries: null,
159	        performed_by: session?.guardId ?? null,
160	        performed_by_name: session?.guardName ?? null,
161	        corrected_at: Date.now(),
162	        // A count is a dated observation, which lets the server tell that
163	        // an older in-flight movement was already included in it.
164	        counted_at: Date.now(),
165	      });
166	      // Await so the stock list's refresh sees the server-acknowledged value.
167	      await flushOnce().catch(() => {});
168	      haptic.success();
