272	}
273	
274	/**
275	 * How much is in the open pack, exactly: kg + grams (or l + ml) side by
276	 * side, or one number of pieces/grams. The pictures above only pre-fill
277	 * it (tap "½" → 2 kg 500 g), then the person adjusts to the real amount.
278	 */
279	function OpenPackInput({
280	  perPack,
281	  value,
282	  unit,
283	  packSize,
284	  pieces,
285	  onChange,
286	}: {
287	  perPack: number;
288	  value: number;
289	  unit: string | null;
290	  packSize: number | null;
291	  pieces: boolean;
292	  onChange: (small: number) => void;
293	}) {
294	  const t = useT();
295	  const { palette } = useTheme();
296	  const { symbol: smallSymbol, perBase } = smallUnit(unit);
297	  const max = perPack - (pieces ? 1 : 0);
298	  const fractions: Array<{ f: number; label: string }> = [
299	    { f: 0, label: t('fillNone') },
300	    { f: 0.1, label: t('fillLittle') },
301	    { f: 0.25, label: '¼' },
302	    { f: 0.5, label: '½' },
303	    { f: 0.75, label: '¾' },
304	  ];
305	  const fromFraction = (f: number) => Math.min(max, Math.round(perPack * f));
306	  const split = perBase > 1 && perPack >= perBase;
307	  const big = Math.floor(value / perBase);
308	  const small = value - big * perBase;
309	
310	  return (
311	    <View style={{ gap: spacing.lg }}>
312	      {/* Pictures: a quick guess for people without a scale. */}
313	      <View style={styles.fills}>
314	        {fractions.map(({ f, label }) => {
315	          const on = value === fromFraction(f);
316	          return (
317	            <Pressable
318	              key={label}
319	              onPress={() => {
320	                haptic.tap();
321	                onChange(fromFraction(f));
322	              }}
323	              accessibilityRole="button"
324	              accessibilityLabel={label}
325	              style={[styles.fill, { borderColor: on ? palette.primary : palette.outlineVariant, borderWidth: on ? 2 : 1, backgroundColor: on ? palette.primaryContainer : palette.surfaceContainerLowest }]}
326	            >
327	              <BagPicture fraction={f} active={on} />
328	              <Text variant="labelMedium" color={on ? palette.onPrimaryContainer : palette.onSurface} style={{ fontWeight: '600' }}>
329	                {label}
330	              </Text>
331	            </Pressable>
332	          );
333	        })}
334	      </View>
335	
336	      {/* The exact amount. */}
337	      {split ? (
338	        <View style={styles.two}>
339	          <View style={[styles.unitBox, { borderColor: palette.outlineVariant }]}>
340	            <AmountStepper compact value={big} min={0} max={Math.floor(max / perBase)} onChange={(n) => onChange(Math.min(max, n * perBase + small))} />
341	            <Text variant="labelLarge" color={palette.onSurfaceVariant}>
342	              {resolveBig(unit)}
343	            </Text>
344	          </View>
345	          <View style={[styles.unitBox, { borderColor: palette.outlineVariant }]}>
346	            <AmountStepper compact value={small} min={0} max={perBase - 1} step={smallStep(packSize, unit)} onChange={(n) => onChange(Math.min(max, big * perBase + n))} />
347	            <Text variant="labelLarge" color={palette.onSurfaceVariant}>
348	              {smallSymbol}
349	            </Text>
350	          </View>
351	        </View>
352	      ) : (
353	        <View style={[styles.unitBox, { borderColor: palette.outlineVariant }]}>
354	          <AmountStepper value={value} min={0} max={max} step={smallStep(packSize, unit)} onChange={onChange} />
355	          <Text variant="labelLarge" color={palette.onSurfaceVariant}>
356	            {pieces ? formatAmount(2 / perPack, packSize, unit).replace(/^\S+\s*/, '') : smallSymbol}
357	          </Text>
358	        </View>
359	      )}
360	      {split && value > 0 ? (
361	        <Text variant="bodyMedium" color={palette.onSurfaceVariant} style={{ textAlign: 'center' }}>
362	          {formatSmall(value, unit)}
363	        </Text>
364	      ) : null}
365	    </View>
366	  );
367	}
368	
369	/** The big unit's symbol (kg for g, l for ml). */
370	function resolveBig(unit: string | null): string {
371	  return formatSmall(smallUnit(unit).perBase, unit).replace(/^\S+\s*/, '');
372	}
373	
374	/** A sack drawn with its fill level, so ¼ and ¾ read without reading. */
375	function BagPicture({ fraction, active }: { fraction: number; active: boolean }) {
376	  const { palette } = useTheme();
377	  const stroke = active ? palette.primary : palette.onSurfaceVariant;
378	  const level = 72 - Math.round(fraction * 62);
379	  const d = 'M18 6 h24 l-3 8 c10 4 15 14 15 28 c0 16 -9 26 -24 26 s-24 -10 -24 -26 c0 -14 5 -24 15 -28 z';
380	  return (
381	    <Svg width={22} height={27} viewBox="0 0 60 72">
382	      <Defs>
383	        <ClipPath id={`fill-${fraction}`}>
384	          <Rect x={0} y={level} width={60} height={72 - level} />
385	        </ClipPath>
386	      </Defs>
387	      <Path d={d} fill={palette.surfaceContainerLowest} stroke={stroke} strokeWidth={4} />
388	      {fraction > 0 ? <Path d={d} fill={palette.primary} clipPath={`url(#fill-${fraction})`} /> : null}
389	    </Svg>
390	  );
391	}
392	
393	function Question({ Icon, text }: { Icon: LucideIcon; text: string }) {
394	  const { palette } = useTheme();
395	  return (
396	    <View style={styles.questionRow}>
397	      <View style={[styles.questionIcon, { backgroundColor: palette.primaryContainer }]}>
398	        <Icon size={22} color={palette.onPrimaryContainer} />
399	      </View>
400	      <Text variant="titleMedium" style={{ fontWeight: '700', flex: 1 }}>
401	        {text}
402	      </Text>
403	    </View>
404	  );
405	}
406	
407	const styles = StyleSheet.create({
408	  safe: { flex: 1 },
409	  content: { padding: spacing.xl, gap: spacing.xxl },
410	  product: { flexDirection: 'row', alignItems: 'center', gap: spacing.lg },
411	  questionRow: { flexDirection: 'row', alignItems: 'center', gap: spacing.md, marginBottom: spacing.lg },
412	  questionIcon: { width: 40, height: 40, borderRadius: 12, alignItems: 'center', justifyContent: 'center' },
413	  fills: { flexDirection: 'row', gap: spacing.xs },
414	  fill: { flex: 1, alignItems: 'center', gap: 2, paddingVertical: spacing.sm, borderRadius: 14 },
415	  two: { flexDirection: 'row', gap: spacing.md },
416	  unitBox: { flex: 1, alignItems: 'center', gap: spacing.xs, borderWidth: 1, borderRadius: 16, paddingVertical: spacing.md, paddingHorizontal: spacing.sm },
417	  total: { flexDirection: 'row', alignItems: 'center', gap: spacing.md, padding: spacing.lg, borderRadius: 16 },
418	  footer: { paddingHorizontal: spacing.xl, paddingTop: spacing.md, paddingBottom: spacing.lg, borderTopWidth: StyleSheet.hairlineWidth },
419	});
