p='src/modules/inventory/components/Shelf.tsx'
s=open(p).read()
start=s.index("function Fig(")
s=s[:start]+'''/**
 * One picture on the shelf with up to two caption lines. Every figure has
 * the same tile box and caption box, so all tiles stand on the same line
 * whether they have one caption line or two, and figures share the row
 * width (flex) so four always fit, even on a small phone.
 */
function Fig({ tile, line1, line2, go, onPress }: { tile: React.ReactNode; line1?: string; line2?: string; go?: boolean; onPress?: () => void }) {
  const { palette } = useTheme();
  const color = go ? palette.primary : palette.onSurfaceVariant;
  const body = (
    <>
      <View style={styles.tileBox}>{tile}</View>
      <View style={styles.capBox}>
        {line1 ? <Caption text={line1} color={color} /> : null}
        {line2 ? <Caption text={line2} color={color} strong /> : null}
      </View>
    </>
  );
  if (!onPress) return <View style={styles.fig}>{body}</View>;
  return (
    <Pressable
      onPress={() => {
        haptic.tap();
        onPress();
      }}
      accessibilityRole="button"
      accessibilityLabel={line1}
      style={styles.fig}
    >
      {body}
    </Pressable>
  );
}

/** Shrinks a long caption to fit rather than cutting it off with "…". */
function Caption({ text, color, strong }: { text: string; color: string; strong?: boolean }) {
  return (
    <Text
      variant="labelMedium"
      color={color}
      numberOfLines={1}
      adjustsFontSizeToFit
      minimumFontScale={0.7}
      style={[styles.cap, strong && { fontWeight: '800' }]}
    >
      {text}
    </Text>
  );
}

function More({ n, go }: { n: number; go?: boolean }) {
  const t = useT();
  const { palette } = useTheme();
  const color = go ? palette.primary : palette.onSurfaceVariant;
  return (
    <View style={styles.fig}>
      <View style={styles.tileBox}>
        <View style={[styles.more, { backgroundColor: go ? palette.primaryContainer : palette.surfaceContainerHigh }]}>
          <Text variant="titleMedium" color={color} numberOfLines={1} adjustsFontSizeToFit style={{ fontWeight: '800', letterSpacing: 0 }}>
            +{n}
          </Text>
        </View>
      </View>
      <View style={styles.capBox}>
        <Caption text={go ? t('tileTaking') : t('tileMore')} color={color} />
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  shelf: { borderRadius: 18, paddingTop: spacing.md, paddingBottom: spacing.sm, paddingHorizontal: spacing.sm, gap: spacing.xs },
  row: { flexDirection: 'row', justifyContent: 'center', alignItems: 'flex-end', gap: spacing.xs },
  fig: { flex: 1, maxWidth: 80, alignItems: 'center' },
  // Tallest tile (64) plus the 6 a taken tile lifts, so nothing pokes out.
  tileBox: { height: 72, alignSelf: 'stretch', alignItems: 'center', justifyContent: 'flex-end' },
  capBox: { height: 36, alignSelf: 'stretch', paddingTop: 4, alignItems: 'center' },
  cap: { textAlign: 'center', letterSpacing: 0, alignSelf: 'stretch' },
