/**
 * The shelf drawn the way it really is: the open pack first (that is where
 * loose amounts come from), any pack that has to be opened, then the closed
 * ones. Whatever goes in your hand is purple. Tapping a closed pack takes it
 * whole; tapping a purple one puts it back.
 */
export function PackShelf({
  Icon,
  perPack,
  totalSmall,
  unit,
  closedTaken = 0,
  looseTaken = 0,
  onTakeClosed,
  onReturnClosed,
  legend,
}: {
  Icon: LucideIcon;
  /** Small units in one pack (12 pieces, 5000 g). */
  perPack: number;
  /** Everything on the shelf, in small units. */
  totalSmall: number;
  unit: string | null | undefined;
  closedTaken?: number;
  looseTaken?: number;
  onTakeClosed?: () => void;
  onReturnClosed?: () => void;
  legend?: boolean;
}) {
  const t = useT();
  const p = takePlan(totalSmall, perPack, closedTaken, looseTaken);
  const amount = (n: number) => formatSmall(n, unit);
  const figs: React.ReactNode[] = [];

  if (p.open > 0) {
    figs.push(
      <Fig
        key="open"
        tile={<PackTile kind="open" Icon={Icon} fill={(p.open - p.fromOpen) / perPack} out={p.fromOpen / perPack} />}
        line1={t('tileOpen')}
        line2={p.fromOpen > 0 ? t('tileTake', { amount: amount(p.fromOpen) }) : t('tileLeft', { amount: amount(p.open) })}
        go={p.fromOpen > 0}
      />,
    );
  }
  p.opened.forEach((take, i) => {
    figs.push(
      <Fig
        key={`opened-${i}`}
        tile={<PackTile kind="open" Icon={Icon} fill={(perPack - take) / perPack} out={take / perPack} />}
        line1={t('tileOpenThis')}
        line2={t('tileTake', { amount: amount(take) })}
        go
      />,
    );
  });
  const takenShown = Math.min(closedTaken, 2);
  for (let i = 0; i < takenShown; i++) {
    figs.push(
      <Fig key={`taken-${i}`} tile={<PackTile kind="closed" Icon={Icon} taken />} line1={t('tileTakeWhole')} go onPress={onReturnClosed} />,
    );
  }
  if (closedTaken > takenShown) figs.push(<More key="taken-more" n={closedTaken - takenShown} go />);
  const room = Math.max(1, ROOM - figs.length);
  const leftShown = Math.min(p.sealedLeft, room);
  for (let i = 0; i < leftShown; i++) {
    figs.push(<Fig key={`closed-${i}`} tile={<PackTile kind="closed" Icon={Icon} />} line1={t('tileClosed')} onPress={onTakeClosed} />);
  }
  if (p.sealedLeft > leftShown) figs.push(<More key="closed-more" n={p.sealedLeft - leftShown} />);

  return <ShelfFrame legend={legend} empty={figs.length === 0}>{figs}</ShelfFrame>;
}

/** Things that never come in packs: one tile each, the taken ones purple. */
export function SingleShelf({ Icon, count, taking = 0, legend }: { Icon: LucideIcon; count: number; taking?: number; legend?: boolean }) {
  const t = useT();
  const total = Math.max(0, Math.floor(count));
  const take = Math.min(total, Math.max(0, Math.floor(taking)));
  const figs: React.ReactNode[] = [];
  const takenShown = Math.min(take, 2);
  for (let i = 0; i < takenShown; i++) figs.push(<Fig key={`t-${i}`} tile={<PackTile kind="single" Icon={Icon} taken />} />);
  if (take > takenShown) figs.push(<More key="t-more" n={take - takenShown} go />);
  const left = total - take;
  const room = Math.max(1, ROOM + 1 - figs.length);
  const leftShown = Math.min(left, room);
  for (let i = 0; i < leftShown; i++) figs.push(<Fig key={`l-${i}`} tile={<PackTile kind="single" Icon={Icon} />} />);
  if (left > leftShown) figs.push(<More key="l-more" n={left - leftShown} />);
  return <ShelfFrame legend={legend} empty={figs.length === 0}>{figs}</ShelfFrame>;
}

