/**
 * WhatsApp Sender — Meta Graph API
 *
 * Every outbound message type (text, media, template) funnels through the one
 * `postToGraph` chokepoint, which holds credentials, parses the returned
 * `wamid`, and logs the send to the delivery log for status reconciliation.
 *
 * Required env vars:
 *   WHATSAPP_ACCESS_TOKEN    — Meta Graph API access token
 *   WHATSAPP_PHONE_NUMBER_ID — Your WhatsApp Business phone number ID
 */

import { logError, logInfo, logWarn } from "../../lib/logger";
import { recordOutboundMessage } from "./delivery-log";
import {
  WA_TEMPLATES,
  type TemplateComponent,
  type WaTemplateKey,
  type WaTemplateVars,
} from "./templates";

const GRAPH_API_VERSION = "v25.0";
const LOG_SCOPE = "whatsapp";

/**
 * Normalize a phone number into the digits-only international form the
 * WhatsApp Graph API expects. Bare 10-digit Indian mobiles get the `91`
 * country code; already-prefixed numbers keep theirs. Returns "" if nothing
 * usable remains (the caller should skip the send).
 */
export function normalizeWhatsAppNumber(raw: string): string {
  const digits = (raw ?? "").replace(/\D+/g, "");
  if (!digits) return "";
  return digits.length === 10 ? `91${digits}` : digits;
}

interface WhatsAppSendOptions {
  parseMode?: "markdown" | "html" | "plain";
  replyToMessageId?: string;
}

