  } catch (err) {
    log(`bot: mark-seen failed for ${chatId}: ${err.message}`);
  }
}

async function sendReply(sessionId, chatId, text) {
  const res = await api(`/sessions/${sessionId}/messages/send-text`, {
    method: 'POST',
    body: JSON.stringify({ chatId, text }),
  });
  // Keep our own copy so the archive shows both sides of the conversation.
  storeMessage(sessionId, {
    id: res?.waMessageId || res?.id || `bot_${Date.now()}`,
    from: 'me',
    to: chatId,
    chatId,
    body: text,
    type: 'chat',
    timestamp: Math.floor(Date.now() / 1000),
    fromMe: true,
    isGroup: chatId.endsWith('@g.us'),
  });
}

