    to: msg.to,
    fromMe: Boolean(msg.fromMe),
    isGroup: Boolean(msg.isGroup),
    type: msg.type,
    body: msg.body || '',
    timestamp: Number(msg.timestamp) || Math.floor(Date.now() / 1000),
    quotedMessage: msg.quotedMessage,
    receivedAt: new Date().toISOString(),
  };
  rec.ref = refOf(rec);
  rec.tags = tagsOf(rec.body);

  if (msg.media?.data) {
    const mediaDir = path.join(dir, 'media');
    fs.mkdirSync(mediaDir, { recursive: true });
    const file = `${rec.timestamp}_${safeName(msg.id).slice(-40)}.${extFor(msg.media.mimetype, msg.media.filename)}`;
    const buf = Buffer.from(msg.media.data, 'base64');
    fs.writeFileSync(path.join(mediaDir, file), buf);
    rec.media = { file, mimetype: msg.media.mimetype, filename: msg.media.filename, size: buf.length };
    drive.enqueue(driveItem(rec, path.join(mediaDir, file)));
  } else if (msg.media) {
    rec.media = { mimetype: msg.media.mimetype, filename: msg.media.filename, missing: true };
  }

  fs.appendFileSync(path.join(dir, 'messages.jsonl'), JSON.stringify(rec) + '\n');
  indexMessage(rec);
  const wanted = mimetype => !mediaTypes.length || mediaTypes.some(p => String(mimetype || '').startsWith(p));

  /** item: { sessionId, chatId, file, localPath, mimetype, filename, timestamp } */
  function enqueue(item) {
    if (!account || !wanted(item.mimetype)) return;
    const key = keyOf(item);
    if (uploaded.has(key) || queued.has(key)) return;
    queued.add(key);
    queue.push(item);
    kick();
  }

  function kick() {
    if (running || needsReconnect || retryTimer || !account || !queue.length) return;
    void run();
  }

  async function uploadOne(item) {
    const data = fs.readFileSync(item.localPath);
    const mimetype = String(item.mimetype).split(';')[0].trim();
    const parent = await chatFolder(item.chatId);

    // Resumable upload works for any size, including large videos.
    const start = await gfetch(`${UPLOAD_URL}?uploadType=resumable&fields=id`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json; charset=UTF-8',
        'X-Upload-Content-Type': mimetype,
        'X-Upload-Content-Length': String(data.length),
      },
      body: JSON.stringify({ ...driveMetadata(item), parents: [parent], createdTime: new Date(item.timestamp * 1000).toISOString() }),
    });
    const location = start.headers.get('location');
    if (!location) throw new Error('Drive did not return an upload URL');
    const res = await gfetch(location, { method: 'PUT', headers: { 'Content-Type': mimetype }, body: data }, 10 * 60_000);
    return (await res.json()).id;
  }

    if (!account || needsReconnect) return;
    lastError = null;
    clearTimeout(retryTimer);
    retryTimer = null;
    backoffMs = 5_000;
    kick();
  }

  /** Drive file id once uploaded to the connected account, else null. */
  const fileId = item => (account && uploaded.get(keyOf(item))) || null;

  /** Stream a file back from Drive (for the archive UI once the local copy is gone). */
  async function download(item) {
    const id = account && uploaded.get(keyOf(item));
    if (!id || needsReconnect) return null;
    return gfetch(`${FILES_URL}/${id}?alt=media`, {}, 10 * 60_000);
  }

  function status() {
    return {
      configured: configured(),
      connected: Boolean(account),
      email: account?.email || null,
      needsReconnect,
      pending: queue.length,
      uploaded: uploaded.size,
      lastError,
      folderUrl: account?.rootFolderId ? `https://drive.google.com/drive/folders/${account.rootFolderId}` : null,
    };
  }

  return { authUrl, handleCallback, disconnect, enqueue, retry, download, fileId, status };
}

