/**
 * Core Notifications — Platform-Agnostic Admin Notification Dispatcher
 *
 * Sends admin notifications across all registered channels.
 * Replaces the hardcoded bot.sendMessage(adminId, ...) calls
 * that were scattered throughout the codebase.
 */

import { getAllChannels } from "../channels/index";
import { logWarn } from "../lib/logger";
import type { SendMessageOptions } from "./types";

/**
 * Send a notification to admin users across ALL registered channels.
 * Each channel adapter handles its own admin ID lookup and delivery.
 */
export async function notifyAdmins(
  text: string,
  options?: SendMessageOptions,
): Promise<void> {
  const channels = getAllChannels();

  for (const channel of channels) {
    try {
      await channel.notifyAdmins(text, options);
    } catch (error) {
      logWarn(
        `Failed to notify admins via ${channel.name}: ${error instanceof Error ? error.message : String(error)}`,
      );
    }
  }
}
