if (pathname === "/api/inventory/issues" && method === "POST") {
  const auth = await authenticate(req, res, "inventory.issue");
  if (!auth) return true;
  const body = await readBodyJson(req);
  const id = asString(body.id);
  const barcode = asString(body.barcode);
  const qty = asNumber(body.qty);
  if (!id || !barcode || qty === null) {
    const missing: string[] = [];
    if (!id) missing.push("id");
    if (!barcode) missing.push("barcode");
    if (qty === null) missing.push("qty (numeric)");
    badRequest(res, `Cannot record issue — missing or invalid: ${missing.join(", ")}`);
    return true;
  }

  const productName = asString(body.product_name) ?? "Unknown";
  const result = await insertIssue({
    id,
    siteId: auth.siteId,
    barcode,
    productName,
    qty,
    dispenseUnit: asString(body.dispense_unit),
    dispenseQty: asNumber(body.dispense_qty),
    reason: asString(body.reason),
    takenBy: asString(body.taken_by),
    deviceId: auth.deviceId,
    guardId: auth.guardId,
    issuedAt: isoOrNow(body.issued_at),
  });

  // Optional explicit lot picks — when the guard told us "I took 1
  // from batch A, 2 from batch B". Absent / empty array → FEFO.
  const rawPicks = Array.isArray(body.lot_picks) ? body.lot_picks : null;
  const picks: LotSummary[] | null = rawPicks
    ? rawPicks
        .map((p) => {
          const expiry = asString((p as Record<string, unknown>).expiry_date);
          const pickQty = asNumber((p as Record<string, unknown>).qty);
          if (pickQty === null || pickQty <= 0) return null;
          return { expiry_date: expiry, qty: pickQty } as LotSummary;
        })
        .filter((p): p is LotSummary => p !== null)
    : null;

  let applied: LotSummary[] = [];
  if (result.inserted) {
    await ensureStockRow({
      siteId: auth.siteId,
      barcode,
      fallbackName: productName,
    });
    applied = await decrementLots({
      siteId: auth.siteId,
      barcode,
      qty,
      picks: picks && picks.length > 0 ? picks : null,
    });
    // Stock changed (on_hand -qty). Debounced.
    void syncStockTabToSheet(auth.siteId).catch(() => {});

    // Fire-and-forget anomaly checks — non-blocking.
    void (async () => {
      const spike = await checkIssueSpike(auth.siteId, barcode, qty);
      if (spike) await fireAnomalyAlert(auth.siteId, barcode, productName, spike);
      const drain = await checkDrainRate(auth.siteId, barcode);
      if (drain) await fireAnomalyAlert(auth.siteId, barcode, productName, drain);
    })().catch(() => {});
  }

  json(res, 200, { id, inserted: result.inserted, lot_picks: applied });
  return true;
}

