/**
 * Ops outbox — curated operational messages for people (a WhatsApp group
 * today), channel-agnostic.
 *
 * Domains queue a typed event (`inventory.delivery_received`, ...) with
 * a dedupe key, so every producer is safe to call twice (outbox retries,
 * duplicate webhooks). Nothing here knows about WhatsApp: a relay pulls
 * work with `claimOpsNotifications`, posts it wherever it posts, and
 * reports back with `ackOpsNotification`.
 *
 * The words are written at claim time by the domain's composer, so a
 * message always reflects the latest data (e.g. every receipt of a
 * delivery that synced while the photo was on its way).
 */

import { randomUUID } from "crypto";
import { getDb } from "../lib/database";
import { logError } from "../lib/logger";

export type OpsNotificationStatus = "waiting" | "pending" | "sending" | "sent" | "failed" | "skipped";

export type OpsNotificationRow = {
  id: string;
  site_id: string;
  kind: string;
  dedupe_key: string;
  subject_id: string | null;
  payload: Record<string, unknown>;
  status: OpsNotificationStatus;
  attempts: number;
  created_at: string;
};

/** What a relay posts. `photoRef` is fetched separately with loadOpsPhoto. */
export type ComposedOpsMessage = {
  text: string;
  /** Searchable tags without "#", e.g. ["delivery", "sugar"]. */
  tags: string[];
  photoRef?: string | null;
};

export type OpsDelivery = {
  /** The channel's id for the posted message. */
  messageId?: string | null;
  /** The relay's archive reference for it (e.g. WA-261009-7K3FQ2). */
  proofRef?: string | null;
};

type Composer = (row: OpsNotificationRow) => Promise<ComposedOpsMessage | null>;
type SentHook = (row: OpsNotificationRow, delivery: OpsDelivery) => Promise<void>;
type PhotoLoader = (ref: string) => Promise<{ bytes: Buffer; mime: string } | null>;
type Ticker = () => Promise<void>;

const composers = new Map<string, Composer>();
const sentHooks = new Map<string, SentHook>();
const photoLoaders = new Map<string, PhotoLoader>();
const tickers: Ticker[] = [];

/** How long a message may wait for its data before it goes out with what exists. */
const WAIT_MAX_MINUTES = 30;
/** A claimed message the relay never acked is handed out again after this. */
const CLAIM_TIMEOUT_MINUTES = 5;
/** Attempts before a message is parked as failed. */
const MAX_ATTEMPTS = 5;

/** Writes the words for one kind. Return null to skip the message. */
export function registerOpsComposer(kind: string, composer: Composer): void {
  composers.set(kind, composer);
}

/** Runs once a message of this kind is confirmed posted. */
export function registerOpsSentHook(kind: string, hook: SentHook): void {
  sentHooks.set(kind, hook);
}

/** Serves photos whose ref starts with `prefix:`. */
export function registerOpsPhotoLoader(prefix: string, loader: PhotoLoader): void {
  photoLoaders.set(prefix, loader);
}

/**
 * Runs before every claim: the place for time-based messages (a daily
 * summary) without a scheduler. Cheap, idempotent work only.
 */
export function registerOpsTicker(ticker: Ticker): void {
  tickers.push(ticker);
}

/** Queue one message. A second call with the same dedupeKey does nothing. */
export async function queueOpsNotification(input: {
  siteId: string;
  kind: string;
  dedupeKey: string;
  subjectId?: string | null;
  payload?: Record<string, unknown>;
  status?: "waiting" | "pending" | "skipped";
}): Promise<{ queued: boolean }> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      INSERT INTO ops_notifications (id, site_id, kind, dedupe_key, subject_id, payload, status)
      VALUES (?, ?, ?, ?, ?, ?::jsonb, ?)
      ON CONFLICT (dedupe_key) DO NOTHING
    `,
    args: [
      `opn_${randomUUID()}`,
      input.siteId,
      input.kind,
      input.dedupeKey,
      input.subjectId ?? null,
      JSON.stringify(input.payload ?? {}),
      input.status ?? "pending",
    ],
  });
  return { queued: (result.rowsAffected ?? 0) > 0 };
}

/** A waiting message has what it needs: let the relay take it. */
export async function markOpsNotificationReady(dedupeKey: string): Promise<void> {
  const db = await getDb();
  await db.execute({
    sql: `UPDATE ops_notifications SET status = 'pending', updated_at = now()
          WHERE dedupe_key = ? AND status = 'waiting'`,
    args: [dedupeKey],
  });
}

function normalizeRow(r: Record<string, unknown>): OpsNotificationRow {
  const payload = typeof r.payload === "string" ? JSON.parse(r.payload) : (r.payload ?? {});
  return {
    id: String(r.id),
    site_id: String(r.site_id),
    kind: String(r.kind),
    dedupe_key: String(r.dedupe_key),
    subject_id: (r.subject_id as string | null) ?? null,
    payload: payload as Record<string, unknown>,
    status: r.status as OpsNotificationStatus,
    attempts: Number(r.attempts ?? 0),
    created_at: r.created_at instanceof Date ? r.created_at.toISOString() : String(r.created_at),
  };
}

export type ClaimedOpsMessage = ComposedOpsMessage & {
  id: string;
  kind: string;
  siteId: string;
  createdAt: string;
};

/**
 * Hand up to `limit` messages to a relay, oldest first. Claimed messages
 * are "sending" until acked; an un-acked claim is handed out again after
 * a few minutes, so a relay crash never loses a message.
 */
export async function claimOpsNotifications(limit = 10): Promise<ClaimedOpsMessage[]> {
  for (const tick of tickers) {
    await tick().catch((err) => logError("[OpsOutbox] ticker failed", err, { scope: "ops-outbox" }));
  }
  const db = await getDb();
  // Waited long enough for its data: send with what exists.
  await db.execute({
    sql: `UPDATE ops_notifications SET status = 'pending', updated_at = now()
          WHERE status = 'waiting' AND created_at < now() - (? || ' minutes')::interval`,
    args: [String(WAIT_MAX_MINUTES)],
  });
  const claimed = await db.execute({
    sql: `
      UPDATE ops_notifications
         SET status = 'sending', claimed_at = now(), attempts = attempts + 1, updated_at = now()
       WHERE id IN (
         SELECT id FROM ops_notifications
          WHERE status = 'pending'
             OR (status = 'sending' AND claimed_at < now() - (? || ' minutes')::interval)
          ORDER BY created_at
          LIMIT ?
          FOR UPDATE SKIP LOCKED
       )
      RETURNING *
    `,
    args: [String(CLAIM_TIMEOUT_MINUTES), Math.max(1, Math.min(50, Math.floor(limit)))],
  });

  const rows = claimed.rows.map(normalizeRow).sort((a, b) => a.created_at.localeCompare(b.created_at));
  const out: ClaimedOpsMessage[] = [];
  for (const row of rows) {
    const composer = composers.get(row.kind);
    let message: ComposedOpsMessage | null = null;
    try {
      message = composer ? await composer(row) : null;
    } catch (err) {
      logError("[OpsOutbox] composer failed", err, { scope: "ops-outbox", kind: row.kind, id: row.id });
      await settle(row.id, { ok: false, error: `compose failed: ${err instanceof Error ? err.message : String(err)}` });
      continue;
    }
    if (!message) {
      await db.execute({
        sql: `UPDATE ops_notifications SET status = 'skipped', updated_at = now() WHERE id = ?`,
        args: [row.id],
      });
      continue;
    }
    out.push({ ...message, id: row.id, kind: row.kind, siteId: row.site_id, createdAt: row.created_at });
  }
  return out;
}

async function settle(id: string, result: { ok: true; delivery: OpsDelivery } | { ok: false; error: string }) {
  const db = await getDb();
  if (result.ok) {
    await db.execute({
      sql: `UPDATE ops_notifications
               SET status = 'sent', sent_at = now(), delivery = ?::jsonb, last_error = NULL, updated_at = now()
             WHERE id = ?`,
      args: [JSON.stringify(result.delivery), id],
    });
    return;
  }
  await db.execute({
    sql: `UPDATE ops_notifications
             SET status = CASE WHEN attempts >= ? THEN 'failed' ELSE 'pending' END,
                 last_error = ?, updated_at = now()
           WHERE id = ?`,
    args: [MAX_ATTEMPTS, result.error.slice(0, 1000), id],
  });
}

/**
 * The relay's answer for one claimed message. Only a message that is
 * still "sending" is settled, so a late duplicate ack changes nothing.
 */
export async function ackOpsNotification(
  id: string,
  result: { ok: true; delivery: OpsDelivery } | { ok: false; error: string },
): Promise<{ found: boolean }> {
  const db = await getDb();
  const found = await db.execute({
    sql: `SELECT * FROM ops_notifications WHERE id = ? AND status = 'sending'`,
    args: [id],
  });
  const raw = found.rows[0];
  if (!raw) return { found: false };
  const row = normalizeRow(raw);
  await settle(id, result);
  if (result.ok) {
    const hook = sentHooks.get(row.kind);
    if (hook) {
      await hook(row, result.delivery).catch((err) =>
        logError("[OpsOutbox] sent hook failed", err, { scope: "ops-outbox", kind: row.kind, id }),
      );
    }
  }
  return { found: true };
}

/** Bytes for a photo a claimed message points at, or null when gone. */
export async function loadOpsPhoto(ref: string): Promise<{ bytes: Buffer; mime: string } | null> {
  const prefix = ref.split(":")[0];
  const loader = photoLoaders.get(prefix);
  return loader ? loader(ref) : null;
}

