  for (const row of rows) {
    const composer = composers.get(row.kind);
    let message: ComposedOpsMessage | null = null;
    try {
      message = composer ? await composer(row) : null;
    } catch (err) {
      logError("[OpsOutbox] composer failed", err, { scope: "ops-outbox", kind: row.kind, id: row.id });
      await settle(row.id, { ok: false, error: `compose failed: ${err instanceof Error ? err.message : String(err)}` });
      continue;
    }
    if (!message) {
      await db.execute({
        sql: `UPDATE ops_notifications SET status = 'skipped', updated_at = now() WHERE id = ?`,
        args: [row.id],
      });
      continue;
    }
    out.push({ ...message, id: row.id, kind: row.kind, siteId: row.site_id, createdAt: row.created_at });
  }
  return out;
}

async function settle(id: string, result: { ok: true; delivery: OpsDelivery } | { ok: false; error: string }) {
  const db = await getDb();
  if (result.ok) {
    await db.execute({
      sql: `UPDATE ops_notifications
               SET status = 'sent', sent_at = now(), delivery = ?::jsonb, last_error = NULL, updated_at = now()
             WHERE id = ?`,
      args: [JSON.stringify(result.delivery), id],
    });
    return;
  }
  await db.execute({
    sql: `UPDATE ops_notifications
             SET status = CASE WHEN attempts >= ? THEN 'failed' ELSE 'pending' END,
                 last_error = ?, updated_at = now()
           WHERE id = ?`,
    args: [MAX_ATTEMPTS, result.error.slice(0, 1000), id],
  });
}

/**
 * The relay's answer for one claimed message. Only a message that is
 * still "sending" is settled, so a late duplicate ack changes nothing.
 */
export async function ackOpsNotification(
  id: string,
  result: { ok: true; delivery: OpsDelivery } | { ok: false; error: string },
): Promise<{ found: boolean }> {
  const db = await getDb();
  const found = await db.execute({
    sql: `SELECT * FROM ops_notifications WHERE id = ? AND status = 'sending'`,
    args: [id],
  });
  const raw = found.rows[0];
  if (!raw) return { found: false };
  const row = normalizeRow(raw);
  await settle(id, result);
  if (result.ok) {
    const hook = sentHooks.get(row.kind);
    if (hook) {
      await hook(row, result.delivery).catch((err) =>
        logError("[OpsOutbox] sent hook failed", err, { scope: "ops-outbox", kind: row.kind, id }),
      );
    }
  }
  return { found: true };
}

/** Bytes for a photo a claimed message points at, or null when gone. */
export async function loadOpsPhoto(ref: string): Promise<{ bytes: Buffer; mime: string } | null> {
  const prefix = ref.split(":")[0];
  const loader = photoLoaders.get(prefix);
  return loader ? loader(ref) : null;
}

