  const expected = process.env.OPS_RELAY_SECRET ?? "";
  const raw = req.headers["x-relay-secret"];
  const given = Array.isArray(raw) ? raw[0] : raw;
  if (!expected || !given) return false;
  const a = Buffer.from(given);
  const b = Buffer.from(expected);
  return a.length === b.length && timingSafeEqual(a, b);
}

function readJson(req: IncomingMessage): Promise<Record<string, unknown>> {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks: Buffer[] = [];
    req.on("data", (c: Buffer) => {
      size += c.length;
      if (size > MAX_BODY_BYTES) {
        reject(new Error("body too large"));
        req.destroy();
        return;
      }
      chunks.push(c);
    });
    req.on("end", () => {
      try {
        const text = Buffer.concat(chunks).toString("utf8");
        resolve(text ? (JSON.parse(text) as Record<string, unknown>) : {});
      } catch {
        resolve({});
      }
    });
    req.on("error", reject);
  });
}

export async function handleOpsRelayRequest(req: IncomingMessage, res: ServerResponse): Promise<boolean> {
  const url = new URL(req.url ?? "/", "http://relay.local");
  if (!url.pathname.startsWith(PREFIX)) return false;
  const method = (req.method ?? "GET").toUpperCase();

  if (!process.env.OPS_RELAY_SECRET) {
    send(res, 503, { error: "The ops relay is not set up on this server (OPS_RELAY_SECRET is missing)." });
    return true;
  }
  if (!authorized(req)) {
    send(res, 401, { error: "Wrong or missing relay secret." });
    return true;
  }

  if (url.pathname === `${PREFIX}claim` && method === "POST") {
    const body = await readJson(req);
    const limit = typeof body.limit === "number" ? body.limit : 10;
    const messages = await claimOpsNotifications(limit);
    send(res, 200, {
      messages: messages.map((m) => ({
        id: m.id,
        kind: m.kind,
        site_id: m.siteId,
        created_at: m.createdAt,
        text: m.text,
        tags: m.tags,
        photo_ref: m.photoRef ?? null,
      })),
    });
    return true;
  }

  if (url.pathname === `${PREFIX}photo` && method === "GET") {
    const ref = url.searchParams.get("ref") ?? "";
    const photo = ref ? await loadOpsPhoto(ref) : null;
    if (!photo) {
      send(res, 404, { error: "No photo for that reference (already posted, or never uploaded)." });
      return true;
    }
    res.writeHead(200, { "Content-Type": photo.mime, "Content-Length": String(photo.bytes.length) });
    res.end(photo.bytes);
    return true;
  }

  if (url.pathname === `${PREFIX}ack` && method === "POST") {
    const body = await readJson(req);
    const id = typeof body.id === "string" ? body.id : "";
    if (!id) {
      send(res, 400, { error: "Missing id." });
      return true;
    }
    const result =
      body.ok === true
        ? {
            ok: true as const,
            delivery: {
              messageId: typeof body.message_id === "string" ? body.message_id : null,
              proofRef: typeof body.proof_ref === "string" ? body.proof_ref : null,
            },
          }
        : { ok: false as const, error: typeof body.error === "string" && body.error ? body.error : "relay reported a failure" };
    const { found } = await ackOpsNotification(id, result);
    send(res, found ? 200 : 409, found ? { ok: true } : { error: "Not a message waiting for an answer (unknown, or already settled)." });
    return true;
  }

  send(res, 404, { error: "Unknown relay endpoint." });
  return true;
}

