/**
 * Inventory → ops outbox: what the store posts to the ops group, and the
 * words it uses.
 *
 * Producers (called from routes after a FRESH insert, so outbox retries
 * never post twice):
 *   inventory.delivery_received  one per delivery, with its proof photo;
 *                                waits until every receipt has synced
 *   inventory.count_corrected    a shelf count that changed the number
 *   inventory.low_stock          at or under the reorder level, once a day
 *   inventory.out_of_stock       nothing left, once a day
 *   inventory.daily_takeouts     one summary per day after 6 pm (ticker)
 *
 * Amounts are written the way people say them, matching the field-app
 * (field-app/src/units/amount.ts): "9 kg 800 g", "2 packs + 5 pcs".
 * Stored quantities are packs, possibly fractional.
 */

import { getDb } from "../../lib/database";
import {
  markOpsNotificationReady,
  queueOpsNotification,
  registerOpsComposer,
  registerOpsPhotoLoader,
  registerOpsSentHook,
  registerOpsTicker,
  type ComposedOpsMessage,
  type OpsNotificationRow,
} from "../../core/ops-outbox";

const TZ = "Asia/Kolkata";
/** Daily take-out summary goes out after this hour (local time). */
const DIGEST_HOUR = 18;
/** Largest delivery photo accepted. The app sends about 250 KB. */
export const MAX_DELIVERY_PHOTO_BYTES = 4 * 1024 * 1024;

// ─── Amounts ──────────────────────────────────────────────────────

const SUB_UNITS: Record<string, { symbol: string; factor: number }> = {
  kg: { symbol: "g", factor: 1000 },
  l: { symbol: "ml", factor: 1000 },
  m: { symbol: "cm", factor: 100 },
};
const CONTINUOUS = new Set(["kg", "g", "l", "ml", "m", "cm"]);
const PLURALS: Record<string, string> = {
  bottle: "bottles", box: "boxes", roll: "rolls", pair: "pairs", can: "cans",
  bag: "bags", tube: "tubes", set: "sets", pack: "packs",
};
const word = (symbol: string, n: number) => (n === 1 ? symbol : (PLURALS[symbol] ?? symbol));

function smallAmount(small: number, unit: string): string {
  const sub = SUB_UNITS[unit];
  const n = Math.max(0, Math.round(small));
  if (!sub) return `${n} ${unit}`;
  const big = Math.floor(n / sub.factor);
  const rest = n - big * sub.factor;
  if (big === 0) return `${rest} ${sub.symbol}`;
  if (rest === 0) return `${big} ${unit}`;
  return `${big} ${unit} ${rest} ${sub.symbol}`;
}

/** Packs (possibly fractional) the way people say them. */
export function formatPacks(packs: number, unitRaw: string | null | undefined, packSizeRaw: number | null | undefined): string {
  const unit = (unitRaw ?? "pcs").trim().toLowerCase() || "pcs";
  const ps = packSizeRaw && packSizeRaw > 0 ? Number(packSizeRaw) : 1;
  if (CONTINUOUS.has(unit)) {
    const perPack = ps * (SUB_UNITS[unit]?.factor ?? 1);
    return smallAmount(packs * perPack, unit);
  }
  if (ps <= 1) {
    const n = Math.round(packs * 100) / 100;
    return `${n} ${word(unit, n)}`;
  }
  const pieces = Math.max(0, Math.round(packs * ps));
  const whole = Math.floor(pieces / ps);
  const rest = pieces - whole * ps;
  if (whole === 0) return `${rest} ${word(unit, rest)}`;
  const packsText = `${whole} ${word("pack", whole)}`;
  return rest === 0 ? packsText : `${packsText} + ${rest} ${word(unit, rest)}`;
}

/** "Sugar 5 kg" → "sugar5kg": a tag that Drive and the archive can search. */
export function tagOf(name: string): string {
  return name.toLowerCase().normalize("NFKD").replace(/[^\p{L}\p{N}]+/gu, "").slice(0, 30);
}

const clock = (d: Date) =>
  new Intl.DateTimeFormat("en-IN", { timeZone: TZ, hour: "numeric", minute: "2-digit", hour12: true }).format(d).toLowerCase();
const dayMonth = (d: Date) => new Intl.DateTimeFormat("en-IN", { timeZone: TZ, day: "numeric", month: "short" }).format(d);
const fullDate = (iso: string) =>
  new Intl.DateTimeFormat("en-IN", { timeZone: "UTC", day: "numeric", month: "short", year: "numeric" }).format(new Date(`${iso}T00:00:00Z`));

/** Today's date (YYYY-MM-DD) and hour in the office's time zone. */
export function localNow(now = new Date()): { date: string; hour: number } {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: TZ, year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", hourCycle: "h23",
  }).formatToParts(now);
  const get = (t: string) => parts.find((p) => p.type === t)?.value ?? "";
  return { date: `${get("year")}-${get("month")}-${get("day")}`, hour: Number(get("hour")) };
}

const toDate = (v: unknown) => (v instanceof Date ? v : new Date(String(v)));

/** Unit and pack size for a barcode, the same way the stock list finds them. */
const PRODUCT_JOINS = `
  LEFT JOIN product_barcodes pb ON pb.site_id = x.site_id AND pb.barcode = x.barcode
  LEFT JOIN canonical_products cp ON cp.product_id = pb.product_id
  LEFT JOIN inventory_products ip ON ip.site_id = x.site_id AND ip.barcode = x.barcode
  LEFT JOIN inventory_stock s ON s.site_id = x.site_id AND s.barcode = x.barcode
`;
const PRODUCT_COLS = `
  COALESCE(s.unit, cp.unit, ip.unit) AS unit,
  COALESCE(cp.pack_size, ip.pack_size) AS pack_size
`;

// ─── Delivery received (with photo) ───────────────────────────────

const deliveryKey = (deliveryId: string) => `inventory.delivery_received:${deliveryId}`;

/**
 * Store the proof photo for a delivery and queue its message. Idempotent:
 * a retried upload keeps the first photo. The message waits until every
 * receipt named in `receiptIds` has synced (they travel separately).
 */
export async function saveDeliveryPhoto(input: {
  siteId: string;
  deliveryId: string;
  receiptIds: string[];
  mime: string;
  bytes: Buffer;
  guardId: string | null;
  guardName: string | null;
  takenAt: string;
}): Promise<{ stored: boolean; sameSite: boolean }> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      INSERT INTO inventory_delivery_photos
        (delivery_id, site_id, receipt_ids, mime, bytes, size_bytes, guard_id, guard_name, taken_at)
      VALUES (?, ?, string_to_array(?, ','), ?, ?, ?, ?, ?, ?)
      ON CONFLICT (delivery_id) DO NOTHING
    `,
    args: [
      input.deliveryId,
      input.siteId,
      input.receiptIds.join(","),
      input.mime,
      input.bytes,
      input.bytes.length,
      input.guardId,
      input.guardName,
      input.takenAt,
    ],
  });
  const stored = (result.rowsAffected ?? 0) > 0;
  if (!stored) {
    const existing = await db.execute({
      sql: `SELECT site_id FROM inventory_delivery_photos WHERE delivery_id = ?`,
      args: [input.deliveryId],
    });
    return { stored: false, sameSite: existing.rows[0]?.site_id === input.siteId };
  }
  await queueOpsNotification({
    siteId: input.siteId,
    kind: "inventory.delivery_received",
    dedupeKey: deliveryKey(input.deliveryId),
    subjectId: input.deliveryId,
    status: "waiting",
  });
  await promoteDeliveryIfComplete(input.deliveryId);
  return { stored: true, sameSite: true };
}

/** Called after each fresh receipt of a delivery, and after its photo. */
export async function promoteDeliveryIfComplete(deliveryId: string): Promise<void> {
  const db = await getDb();
  const found = await db.execute({
    sql: `
      SELECT COALESCE(array_length(p.receipt_ids, 1), 0) AS expected,
             (SELECT COUNT(*) FROM inventory_receipts r WHERE r.delivery_id = p.delivery_id) AS synced
        FROM inventory_delivery_photos p
       WHERE p.delivery_id = ?
    `,
    args: [deliveryId],
  });
  const row = found.rows[0];
  if (!row) return; // photo not here yet; its upload will call this again
  if (Number(row.synced) >= Number(row.expected) && Number(row.synced) > 0) {
    await markOpsNotificationReady(deliveryKey(deliveryId));
  }
}

async function composeDelivery(row: OpsNotificationRow): Promise<ComposedOpsMessage | null> {
  const deliveryId = row.subject_id;
  if (!deliveryId) return null;
  const db = await getDb();
  const photo = (
    await db.execute({
      sql: `SELECT guard_name, taken_at, (bytes IS NOT NULL) AS has_bytes FROM inventory_delivery_photos WHERE delivery_id = ?`,
      args: [deliveryId],
    })
  ).rows[0];
  const receipts = (
    await db.execute({
      sql: `
        SELECT x.barcode, x.product_name, x.qty, to_char(x.expiry_date, 'YYYY-MM-DD') AS expiry,
               x.flagged, x.scanned_at, ${PRODUCT_COLS}
          FROM inventory_receipts x
          ${PRODUCT_JOINS}
         WHERE x.delivery_id = ?
         ORDER BY x.scanned_at, x.product_name
      `,
      args: [deliveryId],
    })
  ).rows;
  if (receipts.length === 0) return null;

  // One line per product; batches with different dates are listed on it.
  const byProduct = new Map<string, { name: string; unit: string | null; packSize: number | null; total: number; batches: { qty: number; expiry: string | null }[] }>();
  for (const r of receipts) {
    const key = String(r.barcode);
    const entry = byProduct.get(key) ?? {
      name: String(r.product_name),
      unit: (r.unit as string | null) ?? null,
      packSize: r.pack_size == null ? null : Number(r.pack_size),
      total: 0,
      batches: [],
    };
    entry.total += Number(r.qty);
    entry.batches.push({ qty: Number(r.qty), expiry: (r.expiry as string | null) ?? null });
    byProduct.set(key, entry);
  }

  const lines: string[] = [];
  for (const p of byProduct.values()) {
    const amount = formatPacks(p.total, p.unit, p.packSize);
    const dated = p.batches.filter((b) => b.expiry);
    let dates = "";
    if (dated.length === 1 && p.batches.length === 1) dates = ` · exp ${fullDate(dated[0].expiry!)}`;
    else if (dated.length > 0) {
      dates = ` · ${p.batches
        .map((b) => `${formatPacks(b.qty, p.unit, p.packSize)} ${b.expiry ? `exp ${fullDate(b.expiry)}` : "no expiry"}`)
        .join(", ")}`;
    }
    lines.push(`• *${p.name}*: ${amount}${dates}`);
  }

  const flagged = receipts.some((r) => r.flagged === true || r.flagged === "t");
  const when = toDate(photo?.taken_at ?? receipts[receipts.length - 1].scanned_at);
  const who = (photo?.guard_name as string | null) ?? null;
  const tags = ["delivery", ...Array.from(byProduct.values()).map((p) => tagOf(p.name))].filter(Boolean).slice(0, 10);
  const text = [
    `📦 *Delivery received* (${byProduct.size} ${byProduct.size === 1 ? "item" : "items"})`,
    ...lines,
    flagged ? "⚠️ Count did not match the order. Please check." : null,
    `${who ? `👤 ${who} · ` : ""}🕓 ${clock(when)}, ${dayMonth(when)}`,
    tags.map((t) => `#${t}`).join(" "),
  ]
    .filter(Boolean)
    .join("\n");
  return { text, tags, photoRef: photo?.has_bytes ? `delivery:${deliveryId}` : null };
}

// ─── Count corrected ──────────────────────────────────────────────

export async function queueCorrectionNotice(input: {
  siteId: string;
  correctionId: string;
  barcode: string;
  productName: string;
  appHad: number;
  counted: number;
  guardName: string | null;
  correctedAt: string;
}): Promise<void> {
  if (Math.abs(input.counted - input.appHad) < 1e-6) return;
  await queueOpsNotification({
    siteId: input.siteId,
    kind: "inventory.count_corrected",
    dedupeKey: `inventory.count_corrected:${input.correctionId}`,
    subjectId: input.barcode,
    payload: {
      product_name: input.productName,
      app_had: input.appHad,
      counted: input.counted,
      guard_name: input.guardName,
      at: input.correctedAt,
    },
  });
}

async function productUnit(siteId: string, barcode: string): Promise<{ unit: string | null; packSize: number | null }> {
  const db = await getDb();
  const r = (
    await db.execute({
      sql: `SELECT ${PRODUCT_COLS} FROM (SELECT ?::text AS site_id, ?::text AS barcode) x ${PRODUCT_JOINS} LIMIT 1`,
      args: [siteId, barcode],
    })
  ).rows[0];
  return { unit: (r?.unit as string | null) ?? null, packSize: r?.pack_size == null ? null : Number(r.pack_size) };
}

async function composeCorrection(row: OpsNotificationRow): Promise<ComposedOpsMessage | null> {
  const p = row.payload as { product_name?: string; app_had?: number; counted?: number; guard_name?: string | null; at?: string };
  if (!row.subject_id || p.counted == null || p.app_had == null) return null;
  const { unit, packSize } = await productUnit(row.site_id, row.subject_id);
  const diff = Number(p.counted) - Number(p.app_had);
  const when = toDate(p.at ?? row.created_at);
  const name = p.product_name ?? "Item";
  const tags = ["countcorrected", tagOf(name)];
  const text = [
    `✏️ *Count corrected*: *${name}*`,
    `App had ${formatPacks(Number(p.app_had), unit, packSize)}, shelf has ${formatPacks(Number(p.counted), unit, packSize)}`,
    `${diff < 0 ? "🔻" : "🔺"} ${formatPacks(Math.abs(diff), unit, packSize)} ${diff < 0 ? "less" : "more"} than the app`,
    `${p.guard_name ? `👤 ${p.guard_name} · ` : ""}🕓 ${clock(when)}, ${dayMonth(when)}`,
    tags.map((t) => `#${t}`).join(" "),
  ].join("\n");
  return { text, tags };
}

// ─── Low / out of stock ───────────────────────────────────────────

/** After stock went down: queue a low or out message, at most once a day each. */
export async function checkStockLevel(siteId: string, barcode: string): Promise<void> {
  const db = await getDb();
  const s = (
    await db.execute({
      sql: `SELECT on_hand, threshold FROM inventory_stock WHERE site_id = ? AND barcode = ?`,
      args: [siteId, barcode],
    })
  ).rows[0];
  if (!s) return;
  const onHand = Number(s.on_hand);
  const threshold = Number(s.threshold);
  const { date } = localNow();
  if (onHand <= 1e-9) {
    await queueOpsNotification({
      siteId, kind: "inventory.out_of_stock", subjectId: barcode,
      dedupeKey: `inventory.out_of_stock:${siteId}:${barcode}:${date}`,
    });
  } else if (threshold > 0 && onHand <= threshold) {
    await queueOpsNotification({
      siteId, kind: "inventory.low_stock", subjectId: barcode,
      dedupeKey: `inventory.low_stock:${siteId}:${barcode}:${date}`,
    });
  }
}

/** Written from the stock as it is now: refilled meanwhile means no message. */
function composeStockLevel(out: boolean) {
  return async (row: OpsNotificationRow): Promise<ComposedOpsMessage | null> => {
    if (!row.subject_id) return null;
    const db = await getDb();
    const s = (
      await db.execute({
        sql: `SELECT x.name, x.on_hand, x.threshold, ${PRODUCT_COLS}
                FROM inventory_stock x ${PRODUCT_JOINS}
               WHERE x.site_id = ? AND x.barcode = ? LIMIT 1`,
        args: [row.site_id, row.subject_id],
      })
    ).rows[0];
    if (!s) return null;
    const onHand = Number(s.on_hand);
    const threshold = Number(s.threshold);
    const unit = (s.unit as string | null) ?? null;
    const packSize = s.pack_size == null ? null : Number(s.pack_size);
    const name = String(s.name);
    if (out && onHand > 1e-9) return null;
    if (!out && !(threshold > 0 && onHand <= threshold && onHand > 1e-9)) return null;
    const tags = [out ? "outofstock" : "lowstock", tagOf(name)];
    const text = out
      ? [`🚫 *Out of stock*: *${name}*`, "Nothing left on the shelf. Please reorder.", tags.map((t) => `#${t}`).join(" ")].join("\n")
      : [
          `⚠️ *Running low*: *${name}*`,
          `${formatPacks(onHand, unit, packSize)} left (reorder at ${formatPacks(threshold, unit, packSize)})`,
          tags.map((t) => `#${t}`).join(" "),
        ].join("\n");
    return { text, tags };
  };
}

// ─── Daily take-out summary ───────────────────────────────────────

/** After 6 pm: one summary per site that took anything out today. */
async function queueDailyTakeouts(): Promise<void> {
  const { date, hour } = localNow();
  if (hour < DIGEST_HOUR) return;
  const db = await getDb();
  const sites = (
    await db.execute({
      sql: `
        SELECT DISTINCT site_id FROM inventory_issues
         WHERE issued_at >= (?::date)::timestamp AT TIME ZONE '${TZ}'
           AND issued_at <  ((?::date) + 1)::timestamp AT TIME ZONE '${TZ}'
           AND NOT EXISTS (
             SELECT 1 FROM ops_notifications n
              WHERE n.dedupe_key = 'inventory.daily_takeouts:' || inventory_issues.site_id || ':' || ?
           )
      `,
      args: [date, date, date],
    })
  ).rows;
  for (const s of sites) {
    const siteId = String(s.site_id);
    await queueOpsNotification({
      siteId,
      kind: "inventory.daily_takeouts",
      dedupeKey: `inventory.daily_takeouts:${siteId}:${date}`,
      subjectId: date,
    });
  }
}

async function composeDailyTakeouts(row: OpsNotificationRow): Promise<ComposedOpsMessage | null> {
  const date = row.subject_id;
  if (!date) return null;
  const db = await getDb();
  const rows = (
    await db.execute({
      sql: `
        SELECT x.barcode, MAX(x.product_name) AS name, SUM(x.qty) AS qty, COUNT(*) AS times,
               MAX(COALESCE(s.unit, cp.unit, ip.unit)) AS unit,
               MAX(COALESCE(cp.pack_size, ip.pack_size)) AS pack_size
          FROM inventory_issues x
          ${PRODUCT_JOINS}
         WHERE x.site_id = ?
           AND x.issued_at >= (?::date)::timestamp AT TIME ZONE '${TZ}'
           AND x.issued_at <  ((?::date) + 1)::timestamp AT TIME ZONE '${TZ}'
         GROUP BY x.barcode
         ORDER BY MAX(x.product_name)
      `,
      args: [row.site_id, date, date],
    })
  ).rows;
  if (rows.length === 0) return null;
  const people = (
    await db.execute({
      sql: `
        SELECT COALESCE(NULLIF(taken_by, ''), 'Someone') AS who, COUNT(*) AS n
          FROM inventory_issues
         WHERE site_id = ?
           AND issued_at >= (?::date)::timestamp AT TIME ZONE '${TZ}'
           AND issued_at <  ((?::date) + 1)::timestamp AT TIME ZONE '${TZ}'
         GROUP BY 1 ORDER BY 2 DESC, 1
      `,
      args: [row.site_id, date, date],
    })
  ).rows;
  const lines = rows.map((r) => {
    const times = Number(r.times);
    const amount = formatPacks(Number(r.qty), (r.unit as string | null) ?? null, r.pack_size == null ? null : Number(r.pack_size));
    return `• *${r.name}*: ${amount}${times > 1 ? ` (${times} times)` : ""}`;
  });
  const total = rows.reduce((n, r) => n + Number(r.times), 0);
  const tags = ["takeouts"];
  const text = [
    `📋 *Taken out today* (${fullDate(date)})`,
    ...lines,
    `👥 ${people.map((p) => `${p.who} (${p.n})`).join(", ")}`,
    `${total} take ${total === 1 ? "out" : "outs"} in all`,
    "#takeouts",
  ].join("\n");
  return { text, tags };
}

// ─── Wiring ───────────────────────────────────────────────────────

let registered = false;

export function registerInventoryNotifications(): void {
  if (registered) return;
  registered = true;
  registerOpsComposer("inventory.delivery_received", composeDelivery);
  registerOpsComposer("inventory.count_corrected", composeCorrection);
  registerOpsComposer("inventory.low_stock", composeStockLevel(false));
  registerOpsComposer("inventory.out_of_stock", composeStockLevel(true));
  registerOpsComposer("inventory.daily_takeouts", composeDailyTakeouts);
  registerOpsTicker(queueDailyTakeouts);

  registerOpsPhotoLoader("delivery", async (ref) => {
    const deliveryId = ref.slice("delivery:".length);
    const db = await getDb();
    const r = (
      await db.execute({
        sql: `SELECT bytes, mime FROM inventory_delivery_photos WHERE delivery_id = ? AND bytes IS NOT NULL`,
        args: [deliveryId],
      })
    ).rows[0];
    if (!r?.bytes) return null;
    const bytes = Buffer.isBuffer(r.bytes) ? r.bytes : Buffer.from(r.bytes as Uint8Array);
    return { bytes, mime: String(r.mime) };
  });

  // Posted and archived on the VPS: keep only the reference, drop the bytes.
  registerOpsSentHook("inventory.delivery_received", async (row, delivery) => {
    if (!row.subject_id) return;
    const db = await getDb();
    await db.execute({
      sql: `UPDATE inventory_delivery_photos
               SET proof_ref = ?, posted_at = now(), bytes = NULL
             WHERE delivery_id = ?`,
      args: [delivery.proofRef ?? null, row.subject_id],
    });
  });
}

