    if (!contentType.toLowerCase().startsWith("multipart/form-data")) {
      badRequest(res, "Send the photo as multipart/form-data.");
      return true;
    }
    let raw: Buffer;
    try {
      raw = await readBodyBuffer(req, MAX_DELIVERY_PHOTO_BYTES + 64 * 1024);
    } catch {
      json(res, 413, { error: "The photo is too big. Take it again; the app sends a smaller one." });
      return true;
    }
    let form: FormData;
    try {
      form = await new Response(raw, { headers: { "content-type": contentType } }).formData();
    } catch {
      badRequest(res, "Could not read the photo upload.");
      return true;
    }
    const deliveryId = asString(form.get("delivery_id"));
    const file = form.get("photo");
    if (!deliveryId || !/^dlv_[A-Za-z0-9_-]{6,64}$/.test(deliveryId)) {
      badRequest(res, "Missing or invalid delivery_id.");
      return true;
    }
    if (!file || typeof file === "string") {
      badRequest(res, "Missing photo.");
      return true;
    }
    const bytes = Buffer.from(await (file as Blob).arrayBuffer());
    const mime = sniffImageMime(bytes);
    if (!mime) {
      badRequest(res, "The photo must be a JPEG, PNG or WebP image.");
      return true;
    }
    if (bytes.length > MAX_DELIVERY_PHOTO_BYTES) {
      json(res, 413, { error: "The photo is too big. Take it again; the app sends a smaller one." });
      return true;
    }
    const receiptIds = String(form.get("receipt_ids") ?? "")
      .split(",")
      .map((x) => x.trim())
      .filter((x) => /^[A-Za-z0-9_-]{1,80}$/.test(x))
      .slice(0, 200);
    const takenAtRaw = Number(form.get("taken_at"));
    const takenAt = Number.isFinite(takenAtRaw) && takenAtRaw > 0 ? new Date(takenAtRaw).toISOString() : new Date().toISOString();

