      deliveryId,
      receiptIds,
      mime,
      bytes,
      guardId: auth.guardId,
      guardName: auth.guardName,
      takenAt,
    });
    if (!result.stored && !result.sameSite) {
      json(res, 409, { error: "This delivery belongs to another site." });
      return true;
    }
    json(res, 200, { delivery_id: deliveryId, stored: result.stored });
    return true;
  }

