/**
 * Ops relay: posts curated messages from the Office Ops engine into a
 * WhatsApp group (delivery photos, count corrections, low stock, the daily
 * take-out summary).
 *
 * It pulls, the engine never calls in: OpenWA stays on 127.0.0.1 and its
 * admin key never leaves this machine. Every OPS_RELAY_INTERVAL_MS it asks
 * the engine for new messages with one shared secret, sends them through
 * the local OpenWA session, files each one in the archive like a received
 * message (so photos go to Drive and get a WA-… reference), then tells the
 * engine what happened. If WhatsApp or this machine is down, messages wait
 * in the engine; a claimed message that is never answered is handed out
 * again after a few minutes, so nothing is lost.
 */

const GROUP_REFRESH_MS = 10 * 60_000;
/** Pause between two posts, so a backlog does not arrive as a burst. */
const GAP_MS = [1500, 3500];

const sleep = ms => new Promise(r => setTimeout(r, ms));
const between = ([a, b]) => a + Math.floor(Math.random() * (b - a));

/**
 * deps:
 *   api(path, init)          OpenWA API (same helper the agent uses)
 *   readySessionId()         id of the logged-in session, or null
 *   archive(sessionId, msg)  files a sent message; returns its record (with .ref)
 *   log(...args)
 */
export function createOpsRelay({ engineUrl, secret, group, intervalMs = 30_000, api, readySessionId, archive, log }) {
  const base = String(engineUrl || '').replace(/\/$/, '');
  const enabled = Boolean(base && secret && group);
  const state = {
    enabled,
    group: group || null,
    groupId: null,
    lastPollAt: null,
    lastSentAt: null,
    sent: 0,
    failed: 0,
    lastError: null,
    waiting: null, // why it is not posting right now, in plain words
  };
  let groupsFetchedAt = 0;
  let busy = false;
  let timer = null;
  let lastLogged = null;

  /** Log a problem once, not every 30 seconds. */
  function note(problem) {
    state.waiting = problem;
    if (problem && problem !== lastLogged) log(`ops relay: ${problem}`);
    lastLogged = problem;
  }

  async function engine(path, init = {}) {
    const res = await fetch(`${base}/api/ops-relay/${path}`, {
      ...init,
      headers: { 'Content-Type': 'application/json', 'X-Relay-Secret': secret, ...init.headers },
      signal: AbortSignal.timeout(init.timeoutMs ?? 20_000),
    });
    if (!res.ok) throw new Error(`engine ${path} -> ${res.status} ${(await res.text()).slice(0, 200)}`);
    return res;
  }

  /** OPS_GROUP may be a group id (…@g.us) or its name as shown in WhatsApp. */
  async function resolveGroup(sessionId) {
    if (/@g\.us$/.test(group)) return group;
    if (state.groupId && Date.now() - groupsFetchedAt < GROUP_REFRESH_MS) return state.groupId;
    const groups = await api(`/sessions/${sessionId}/groups`);
    groupsFetchedAt = Date.now();
    const want = group.trim().toLowerCase();
    const hit = groups.find(g => String(g.name || '').trim().toLowerCase() === want);
    state.groupId = hit?.id || null;
    if (!hit) {
      const names = groups.map(g => g.name).filter(Boolean).slice(0, 15).join(', ');
      note(`no WhatsApp group named "${group}". This number is in: ${names || 'no groups'}. Set OPS_GROUP to one of these, or to its …@g.us id.`);
    }
    return state.groupId;
  }

  async function postOne(sessionId, chatId, msg) {
    let photo = null;
    if (msg.photo_ref) {
      const res = await engine(`photo?ref=${encodeURIComponent(msg.photo_ref)}`, { timeoutMs: 60_000 });
      const buf = Buffer.from(await res.arrayBuffer());
      photo = { data: buf.toString('base64'), mimetype: res.headers.get('content-type') || 'image/jpeg' };
    }
    const sent = photo
      ? await api(`/sessions/${sessionId}/messages/send-image`, {
          method: 'POST',
          timeoutMs: 120_000,
          body: JSON.stringify({ chatId, base64: photo.data, mimetype: photo.mimetype, caption: msg.text }),
        })
      : await api(`/sessions/${sessionId}/messages/send-text`, {
          method: 'POST',
          body: JSON.stringify({ chatId, text: msg.text }),
        });
    const messageId = sent?.messageId || sent?.id || `ops_${msg.id}`;
    // File it like a received message: searchable, tagged, photo to Drive.
    const rec = archive(sessionId, {
      id: messageId,
      chatId,
      from: 'me',
      to: chatId,
      fromMe: true,
      isGroup: true,
      type: photo ? 'image' : 'chat',
      body: msg.text,
      timestamp: Math.floor(Date.now() / 1000),
      media: photo ? { data: photo.data, mimetype: photo.mimetype, filename: `${msg.kind}.jpg` } : undefined,
    });
    return { messageId, proofRef: rec?.ref || null };
  }

  async function tick() {
    if (busy) return;
    busy = true;
    try {
      state.lastPollAt = new Date().toISOString();
      const sessionId = await readySessionId();
      if (!sessionId) return note('WhatsApp is not linked yet; messages wait in the engine.');
      const chatId = await resolveGroup(sessionId);
      if (!chatId) return;

      const res = await engine('claim', { method: 'POST', body: JSON.stringify({ limit: 5 }) });
      const { messages = [] } = await res.json();
      note(null);
      for (const msg of messages) {
        try {
          const { messageId, proofRef } = await postOne(sessionId, chatId, msg);
          await engine('ack', { method: 'POST', body: JSON.stringify({ id: msg.id, ok: true, message_id: messageId, proof_ref: proofRef }) });
          state.sent++;
          state.lastSentAt = new Date().toISOString();
          state.lastError = null;
          log(`ops relay: posted ${msg.kind}${proofRef ? ` (${proofRef})` : ''}`);
        } catch (err) {
          state.failed++;
          state.lastError = err.message;
          log(`ops relay: could not post ${msg.kind}: ${err.message}`);
          await engine('ack', { method: 'POST', body: JSON.stringify({ id: msg.id, ok: false, error: err.message }) }).catch(() => {
            /* the engine hands it out again after its claim times out */
          });
        }
        await sleep(between(GAP_MS));
      }
    } catch (err) {
      state.lastError = err.message;
      note(`cannot reach the engine: ${err.message}`);
    } finally {
      busy = false;
    }
  }

  function start() {
    if (!enabled) {
      log('ops relay: off (set OPS_RELAY_URL, OPS_RELAY_SECRET and OPS_GROUP to post Office Ops messages)');
      return;
    }
    log(`ops relay: posting Office Ops messages to "${group}" from ${base}`);
    void tick();
    timer = setInterval(() => void tick(), Math.max(10_000, intervalMs));
  }

  function stop() {
    clearInterval(timer);
  }

  return { start, stop, tick, status: () => ({ ...state }) };
}

