            /* the engine hands it out again after its claim times out */
          });
        }
        await sleep(between(GAP_MS));
      }
    } catch (err) {
      state.lastError = err.message;
      note(`cannot reach the engine: ${err.message}`);
    } finally {
      busy = false;
    }
  }

  function start() {
    if (!enabled) {
      log('ops relay: off (set OPS_RELAY_URL, OPS_RELAY_SECRET and OPS_GROUP to post Office Ops messages)');
      return;
    }
    log(`ops relay: posting Office Ops messages to "${group}" from ${base}`);
    void tick();
    timer = setInterval(() => void tick(), Math.max(10_000, intervalMs));
  }

  function stop() {
    clearInterval(timer);
  }

  return { start, stop, tick, status: () => ({ ...state }) };
}

