import { Directory, File, Paths } from 'expo-file-system';
import { nanoid } from 'nanoid/non-secure';
import { enqueue } from '../../db/outbox';

/**
 * Delivery proof photos.
 *
 * Every delivery (one standalone receive, or one order session) carries one
 * photo. Its receipts get the same `delivery_id`; the photo travels in the
 * outbox after them, and the server posts one message for the delivery once
 * the photo and all its receipts have arrived.
 *
 * The camera writes to the cache folder, which Android may clear, so a kept
 * photo is moved into the app's own documents folder until it is uploaded.
 */

const FOLDER = 'delivery-photos';

export function newDeliveryId(): string {
  return `dlv_${nanoid(16)}`;
}

function folder(): Directory {
  const dir = new Directory(Paths.document, FOLDER);
  if (!dir.exists) dir.create({ intermediates: true, idempotent: true });
  return dir;
}

/** Move a just-taken photo somewhere it survives until upload. Returns its uri. */
export function keepPhoto(cameraPath: string): string {
  const src = new File(cameraPath.startsWith('file://') ? cameraPath : `file://${cameraPath}`);
  const dest = new File(folder(), `${nanoid(12)}.jpg`);
  src.move(dest);
  return dest.uri;
}

/** Throw away a kept photo that will not be used (retake, cancel). */
export function discardPhoto(uri: string | null | undefined): void {
  if (!uri) return;
  try {
    const f = new File(uri);
    if (f.exists) f.delete();
  } catch {
    /* already gone */
  }
}

export type DeliveryPhotoPayload = {
  delivery_id: string;
  receipt_ids: string[];
  file_uri: string;
  taken_at: number;
};

/** Queue the photo after the delivery's receipts. */
export async function queueDeliveryPhoto(input: { deliveryId: string; receiptIds: string[]; photoUri: string; takenAt?: number }): Promise<void> {
  const payload: DeliveryPhotoPayload = {
    delivery_id: input.deliveryId,
    receipt_ids: input.receiptIds,
    file_uri: input.photoUri,
    taken_at: input.takenAt ?? Date.now(),
  };
  await enqueue('delivery_photo', payload);
}

export function photoFileExists(uri: string): boolean {
  try {
    return new File(uri).exists;
  } catch {
    return false;
  }
}

