  // Walk-in registration -- the gating handler. Checked before the generic
  // visitor router because that one still 501s anything it does not know.
  if (
    (pathname === "/api/visitor/register" || pathname === "/visitor/register") &&
    method === "POST"
  ) {
    return await handleWalkinRegister(req, query);
  }

  // Admin sign-in / session / password. First among the admin routes: every
  // other admin surface needs the token this mints.
  const adminAuth = await handleAdminAuthRoutes(req, pathname, method);
  if (adminAuth) return adminAuth;

  const googleSso = await handleGoogleSsoRoutes(req, pathname, method, query);
  if (googleSso) return googleSso;

  // Visitor pass page, expected list, guard push.
  const pass = await handlePassRoutes(req, pathname, method, query);
  if (pass) return pass;

  // Visitor settings: rules + templates (admin).
  const vset = await handleVisitorSettingsRoutes(req, pathname, method);
  if (vset) return vset;

  // RBAC settings (admin).
  const rbac = await handleRbacRoutes(req, pathname, method);
  if (rbac) return rbac;

  // Automation editor (admin).
  const flowAdmin = await handleFlowAdminRoutes(req, pathname, method, query);
  if (flowAdmin) return flowAdmin;

  // Guard check-in / check-out / verify.
  const checkin = await handleCheckinRoutes(req, pathname, method);
  if (checkin) return checkin;

  const cafeteria = await handleCafeteriaRequest(req, pathname, method, query);
  if (cafeteria) return cafeteria;

  const inventory = await handleInventoryRequest(req, pathname, method, query);
