/**
 * Ops relay endpoints (port of office-ops-engine
 * src/mastra/channels/ops-relay/routes.ts) — how the WhatsApp agent on the
 * office VPS pulls curated messages from the ops outbox.
 *
 * Pull, not push: the VPS gateway listens on localhost only and its admin
 * key can unlink WhatsApp, so it is never exposed. The relay calls in with
 * one shared secret (OPS_RELAY_SECRET) that can only read queued messages
 * and their photos, and report what it posted.
 *
 *   POST /api/ops-relay/claim   { limit? }                 → { messages: [...] }
 *   GET  /api/ops-relay/photo?ref=delivery:dlv_…           → image bytes
 *   POST /api/ops-relay/ack     { id, ok, error?, message_id?, proof_ref? }
 */

import { CORS_HEADERS, json, readBodyJson } from "../http.ts";
import { ackOpsNotification, claimOpsNotifications, loadOpsPhoto } from "../ops-outbox.ts";

const PREFIX = "/api/ops-relay/";

/** Constant-time string compare (Deno has no timingSafeEqual on strings). */
function sameSecret(a: string, b: string): boolean {
  const x = new TextEncoder().encode(a);
  const y = new TextEncoder().encode(b);
  if (x.length !== y.length) return false;
  let diff = 0;
  for (let i = 0; i < x.length; i++) diff |= x[i] ^ y[i];
  return diff === 0;
}

export async function handleOpsRelayRequest(req: Request, pathname: string, method: string): Promise<Response | null> {
  if (!pathname.startsWith(PREFIX)) return null;

  const expected = Deno.env.get("OPS_RELAY_SECRET") ?? "";
  if (!expected) {
    return json(503, { error: "The ops relay is not set up on this server (OPS_RELAY_SECRET is missing)." });
  }
  const given = req.headers.get("x-relay-secret") ?? "";
  if (!given || !sameSecret(given, expected)) return json(401, { error: "Wrong or missing relay secret." });

  if (pathname === `${PREFIX}claim` && method === "POST") {
