start=s.index("// ─── Delivery received (with photo)")
end=s.index("// ─── Count corrected")
new='''// ─── Item received (with its photo) ───────────────────────────────

const itemKey = (photoId: string) => `inventory.item_received:${photoId}`;

/**
 * Store the proof photo for one received item (all its packs together)
 * and queue its message. Idempotent on photoId: a retried upload keeps the
 * first photo. The message waits until every receipt the photo covers has
 * synced (they travel separately, usually just before it).
 */
export async function saveReceiptPhoto(input: {
  siteId: string;
  photoId: string;
  deliveryId: string | null;
  receiptIds: string[];
  mime: string;
  bytes: Buffer;
  guardId: string | null;
  guardName: string | null;
  takenAt: string;
}): Promise<{ stored: boolean; sameSite: boolean }> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      INSERT INTO inventory_receipt_photos
        (photo_id, site_id, delivery_id, receipt_ids, mime, bytes, size_bytes, guard_id, guard_name, taken_at)
      VALUES (?, ?, ?, string_to_array(?, ','), ?, ?, ?, ?, ?, ?)
      ON CONFLICT (photo_id) DO NOTHING
    `,
    args: [
      input.photoId,
      input.siteId,
      input.deliveryId,
      input.receiptIds.join(","),
      input.mime,
      input.bytes,
      input.bytes.length,
      input.guardId,
      input.guardName,
      input.takenAt,
    ],
  });
  const stored = (result.rowsAffected ?? 0) > 0;
  if (!stored) {
    const existing = await db.execute({
      sql: `SELECT site_id FROM inventory_receipt_photos WHERE photo_id = ?`,
      args: [input.photoId],
    });
    return { stored: false, sameSite: existing.rows[0]?.site_id === input.siteId };
  }
  await queueOpsNotification({
    siteId: input.siteId,
    kind: "inventory.item_received",
    dedupeKey: itemKey(input.photoId),
    subjectId: input.photoId,
    status: "waiting",
  });
  await promotePhotoIfComplete(input.photoId);
  return { stored: true, sameSite: true };
}

/** The photo and every receipt it covers are here: the message can go. */
