    `${who ? `👤 ${who} · ` : ""}🕓 ${clock(when)}, ${dayMonth(when)}`,
    tags.map((t) => `#${t}`).join(" "),
  ]
    .filter(Boolean)
    .join("\\n");
  return { text, tags, photoRef: photo.has_bytes ? `receipt:${photoId}` : null };
}

