  receiptIds: string[];
  mime: string;
  bytes: Buffer;
  guardId: string | null;
  guardName: string | null;
  takenAt: string;
}): Promise<{ stored: boolean; sameSite: boolean }> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
