 * and queue its message. Idempotent on photoId: a retried upload keeps the
 * first photo. The message waits until every receipt the photo covers has
 * synced (they travel separately, usually just before it).
 */
export async function saveReceiptPhoto(input: {
  siteId: string;
  photoId: string;
  deliveryId: string | null;
  receiptIds: string[];
  mime: string;
  bytes: Buffer;
  guardId: string | null;
  guardName: string | null;
  takenAt: string;
}): Promise<{ stored: boolean; sameSite: boolean }> {
  const db = await getDb();
  const result = await db.execute({
    sql: `
      INSERT INTO inventory_receipt_photos
        (photo_id, site_id, delivery_id, receipt_ids, mime, bytes, size_bytes, guard_id, guard_name, taken_at)
      VALUES (?, ?, ?, string_to_array(?, ','), ?, ?, ?, ?, ?, ?)
      ON CONFLICT (photo_id) DO NOTHING
    `,
    args: [
      input.photoId,
      input.siteId,
      input.deliveryId,
      input.receiptIds.join(","),
      input.mime,
      input.bytes,
      input.bytes.length,
      input.guardId,
      input.guardName,
      input.takenAt,
    ],
  });
  const stored = (result.rowsAffected ?? 0) > 0;
  if (!stored) {
    const existing = await db.execute({
      sql: `SELECT site_id FROM inventory_receipt_photos WHERE photo_id = ?`,
      args: [input.photoId],
    });
    return { stored: false, sameSite: existing.rows[0]?.site_id === input.siteId };
  }
  await queueOpsNotification({
    siteId: input.siteId,
    kind: "inventory.item_received",
    dedupeKey: itemKey(input.photoId),
    subjectId: input.photoId,
    status: "waiting",
  });
  await promotePhotoIfComplete(input.photoId);
  return { stored: true, sameSite: true };
}

/** The photo and every receipt it covers are here: the message can go. */
async function promotePhotoIfComplete(photoId: string): Promise<void> {
  const db = await getDb();
  const row = (
    await db.execute({
      sql: `
        SELECT COALESCE(array_length(p.receipt_ids, 1), 0) AS expected,
               (SELECT COUNT(*) FROM inventory_receipts r WHERE r.id = ANY(p.receipt_ids)) AS synced
          FROM inventory_receipt_photos p
         WHERE p.photo_id = ?
      `,
      args: [photoId],
    })
  ).rows[0];
  if (!row) return;
  if (Number(row.expected) > 0 && Number(row.synced) >= Number(row.expected)) {
    await markOpsNotificationReady(itemKey(photoId));
  }
}

/** Called after each fresh receipt: a photo that arrived first may now be complete. */
export async function promotePhotosForReceipt(receiptId: string): Promise<void> {
  const db = await getDb();
  const photos = (
    await db.execute({
      sql: `SELECT photo_id FROM inventory_receipt_photos WHERE ? = ANY(receipt_ids)`,
      args: [receiptId],
    })
  ).rows;
  for (const p of photos) await promotePhotoIfComplete(String(p.photo_id));
}

type ProductLine = { name: string; unit: string | null; packSize: number | null; total: number; batches: { qty: number; expiry: string | null }[] };

/** "50 pcs · exp 1 Nov 2026", or each batch with its date when there are several. */
function describeLine(p: ProductLine): string {
  const amount = formatPacks(p.total, p.unit, p.packSize);
  const dated = p.batches.filter((b) => b.expiry);
  const only = dated[0];
  if (only?.expiry && p.batches.length === 1) return `${amount} · exp ${fullDate(only.expiry)}`;
  if (dated.length === 0) return amount;
  return `${amount} (${p.batches
    .map((b) => `${formatPacks(b.qty, p.unit, p.packSize)} ${b.expiry ? `exp ${fullDate(b.expiry)}` : "no expiry"}`)
    .join(", ")})`;
}

async function composeItem(row: OpsNotificationRow): Promise<ComposedOpsMessage | null> {
  const photoId = row.subject_id;
  if (!photoId) return null;
  const db = await getDb();
  const photo = (
    await db.execute({
      sql: `SELECT guard_name, taken_at, (bytes IS NOT NULL) AS has_bytes FROM inventory_receipt_photos WHERE photo_id = ?`,
      args: [photoId],
    })
  ).rows[0];
  if (!photo) return null;
  const receipts = (
    await db.execute({
      sql: `
        SELECT x.barcode, x.product_name, x.qty, to_char(x.expiry_date, 'YYYY-MM-DD') AS expiry,
               x.flagged, x.scanned_at, ${PRODUCT_COLS}
          FROM inventory_receipts x
          JOIN inventory_receipt_photos ph ON x.id = ANY(ph.receipt_ids)
          ${PRODUCT_JOINS}
         WHERE ph.photo_id = ?
         ORDER BY x.expiry_date NULLS LAST, x.scanned_at
      `,
      args: [photoId],
    })
  ).rows;
  if (receipts.length === 0) return null;

  // Normally one product; batches with different dates are listed on it.
  const byProduct = new Map<string, ProductLine>();
  for (const r of receipts) {
    const key = String(r.barcode);
    const entry = byProduct.get(key) ?? {
      name: String(r.product_name),
      unit: (r.unit as string | null) ?? null,
      packSize: r.pack_size == null ? null : Number(r.pack_size),
      total: 0,
      batches: [],
    };
    entry.total += Number(r.qty);
    entry.batches.push({ qty: Number(r.qty), expiry: (r.expiry as string | null) ?? null });
    byProduct.set(key, entry);
  }

  const products = Array.from(byProduct.values());
  const first = products[0];
  const head =
    products.length === 1 && first
      ? [`📦 *Received*: *${first.name}*`, describeLine(first)]
      : [`📦 *Received* (${products.length} items)`, ...products.map((p) => `• *${p.name}*: ${describeLine(p)}`)];
  const flagged = receipts.some((r) => r.flagged === true || r.flagged === "t");
  const when = toDate(photo.taken_at ?? receipts[receipts.length - 1]?.scanned_at);
  const who = (photo.guard_name as string | null) ?? null;
  const tags = ["received", ...products.map((p) => tagOf(p.name))].filter(Boolean).slice(0, 10);
  const text = [
    ...head,
    flagged ? "⚠️ Count did not match the order. Please check." : null,
    `${who ? `👤 ${who} · ` : ""}🕓 ${clock(when)}, ${dayMonth(when)}`,
    tags.map((t) => `#${t}`).join(" "),
  ]
    .filter(Boolean)
    .join("\n");
  return { text, tags, photoRef: photo.has_bytes ? `receipt:${photoId}` : null };
}

