export type CommandHandler = (message: StandardMessage, command: string, args: string[]) => Promise<void>;

/**
 * Reply sender callback. The channel provides this so the core
 * can send responses without knowing channel-specific APIs.
 */
export type ReplySender = (chatId: string, text: string, options?: { parseMode?: string }) => Promise<void>;

export interface MessageRouterConfig {
  /** Channel-specific command handler */
  onCommand?: CommandHandler;
  /** Channel-specific reply sender for query responses */
  onReply?: ReplySender;
  /** Channel-specific typing indicator */
  onTyping?: (chatId: string) => Promise<void>;
}

// ─── Channel-specific config registry ────────────────────

const channelConfigs = new Map<string, MessageRouterConfig>();

export function registerChannelConfig(
  channel: string,
  config: MessageRouterConfig,
): void {
  channelConfigs.set(channel, config);
}

// ─── Core Message Handler ─────────────────────────────────

/**
 * The main message handler. Every channel adapter calls this
 * with a StandardMessage after translating from its native format.
 */
export const handleMessage: MessageHandler = async (message: StandardMessage) => {
  const { channel, chatType, text, senderName, chatTitle } = message;

  // Enrich with staff role (if not already set by batch processor)
  if (!(message as any).senderRole) {
    const senderRole = getSenderRole(channel, message.senderId);
    const staffRecord = getStaffByChannelUid(channel, message.senderId);
    (message as any).senderRole = senderRole;
    (message as any).senderStaffName = staffRecord?.name;
  }

  // Enrich with group context (if not already set)
  if (!(message as any).groupZone) {
    const groupZone = getGroupZone(message.channelChatId);
    const groupName = getGroupName(message.channelChatId);
    const preferredDomains = getPreferredDomains(message.channelChatId);
    (message as any).groupZone = groupZone;
    (message as any).groupName = groupName;
    (message as any).preferredDomains = preferredDomains;
    (message as any).groupContextForAI = buildGroupContextForAI(message.channelChatId);
  }

  const roleTag = (message as any).senderRole !== "unknown"
    ? ` [${(message as any).senderRole}]`
    : "";
  const groupTag = (message as any).groupZone !== "general"
    ? ` {${(message as any).groupName}}`
    : "";

  logInfo(
    `[Router] ${channel}/${chatType} from ${senderName}${roleTag}${groupTag}: ${previewForLog(text, `[${message.messageType}]`)}`,
  );

  if (chatType === "group") {
    await handleGroupMessage(message);
  } else if (chatType === "private") {
    await handlePrivateMessage(message);
  }
};

// ─── Group Message Processing ─────────────────────────────

async function handleGroupMessage(message: StandardMessage): Promise<void> {
  logInfo(
    `Processing group message from ${message.senderName} in ${message.chatTitle}: ${previewForLog(message.text, `[${message.messageType}]`)}`,
  );

  const workflow = mastra.getWorkflow("ingestMessageWorkflow");
  if (!workflow) {
    logError("Ingestion workflow not found");
    return;
  }

  const run = await workflow.createRun();
  const result = await run.start({
    inputData: {
      channel: message.channel,
      messageId: Number(message.channelMessageId),
      chatId: Number(message.channelChatId),
      chatTitle: message.chatTitle || "Unknown Group",
      chatType: message.chatType as "group" | "supergroup",
      senderId: Number(message.senderId),
      senderName: message.senderName,
      senderUsername: message.senderUsername,
      text: message.text || undefined,
      messageType: message.messageType as
        | "text"
        | "photo"
        | "document"
        | "voice"
        | "video",
      mediaFileId: message.mediaFileId,
      timestamp: message.timestamp,
      senderRole: (message as any).senderRole || "unknown",
      groupZone: (message as any).groupZone || "general",
      groupName: (message as any).groupName || "General",
      preferredDomains: (message as any).preferredDomains || [],
      groupContextForAI: (message as any).groupContextForAI || "",
    },
  });

  // Log the result
  const finalStep = Object.values(result.steps).pop();
  if (finalStep?.status === "success") {
    const output = finalStep.output as Record<string, unknown>;
    if (!output.skipped) {
      logInfo(
        `Ingestion workflow completed: domain=${output.domain}, confidence=${output.confidence}`,
      );
      if (output.agentResponse) {
        logInfo(
          `Agent response preview: ${previewForLog(String(output.agentResponse), "[empty response]", 300)}`,
        );
      }
    } else {
      logWarn(`Ingestion workflow skipped: ${output.skipReason}`);
    }
  } else if (finalStep?.status === "failed") {
    logError("Ingestion workflow failed");
  }
}

// ─── Private Message Processing (Admin Queries) ───────────

async function handlePrivateMessage(message: StandardMessage): Promise<void> {
  const { text, isAdmin, channel, channelChatId, senderName } = message;

  if (!text) return;

  // Auth check
  if (!isAdmin) {
    logWarn(`Rejected unauthorized private message from ${message.senderId}`);
    const config = channelConfigs.get(channel);
    if (config?.onReply) {
      await config.onReply(channelChatId, "🔒 You are not authorized to use this bot.");
    }
    return;
  }

  logInfo(
    `Received private message from ${senderName}: ${previewForLog(text, "[empty message]")}`,
  );

  // Handle commands — delegate to channel-specific handler
  if (text.startsWith("/")) {
    const config = channelConfigs.get(channel);
    if (config?.onCommand) {
      const parts = text.trim().split(/\s+/);
      const command = parts[0] ?? "";
      const args = parts.slice(1);
      await config.onCommand(message, command, args);
    } else {
      logWarn(`No command handler registered for channel: ${channel}`);
    }
    return;
  }

  // Natural language query
  const queryAgentInstance = mastra.getAgent("queryAgent");
  if (!queryAgentInstance) {
    logError("Query agent not available");
    const config = channelConfigs.get(channel);
    if (config?.onReply) {
      await config.onReply(channelChatId, "⚠️ Query agent not available.");
    }
    return;
  }

  try {
    logInfo("Running query agent");

    // Show typing indicator if the channel supports it
    const config = channelConfigs.get(channel);
    if (config?.onTyping) {
      await config.onTyping(channelChatId);
    }

    // Start a typing loop (re-send every 4s) for channels with short indicators
    let typingInterval: ReturnType<typeof setInterval> | undefined;
    if (config?.onTyping) {
      typingInterval = setInterval(async () => {
        try {
          await config.onTyping!(channelChatId);
        } catch {}
      }, 4000);

