/**
 * Google Shared Drive storage for operational files: field-app proof photos
 * and media from WhatsApp. Files belong to the Shared Drive (the org), not
 * to a person, so they survive anyone leaving.
 *
 * Auth is the engine's existing service account (the one Sheets uses). One
 * time: create a Shared Drive, add the service account's email as a
 * "Content manager", and set OPS_SHARED_DRIVE_ID to the drive's id (the part
 * after /drive/folders/ in its URL).
 *
 *   OPS_SHARED_DRIVE_ID                Shared Drive to write into
 *   GOOGLE_SERVICE_ACCOUNT_KEY_JSON    base64 service-account key (or _PATH)
 *
 * Without them every call returns null and callers keep their bytes for
 * later, so nothing is lost while Drive is not set up.
 */

import { readFileSync } from "fs";
import { Readable } from "stream";
import { google, type drive_v3 } from "googleapis";
import { logError, logWarn } from "./logger";

const FOLDER_MIME = "application/vnd.google-apps.folder";

let client: drive_v3.Drive | null = null;
let warned = false;
/** "parentId/name" → folder id, so each folder is looked up once per process. */
const folderCache = new Map<string, string>();

function driveId(): string | null {
  return process.env.OPS_SHARED_DRIVE_ID?.trim() || null;
}

function getClient(): drive_v3.Drive | null {
  if (client) return client;
  const keyJson = process.env.GOOGLE_SERVICE_ACCOUNT_KEY_JSON;
  const keyPath = process.env.GOOGLE_SERVICE_ACCOUNT_KEY_PATH;
  if (!driveId() || (!keyJson && !keyPath)) {
    if (!warned) {
      logWarn("[Drive] OPS_SHARED_DRIVE_ID or the service account key is not set; files stay in the database until it is", {
        scope: "drive",
      });
      warned = true;
    }
    return null;
  }
  const credentials = keyJson
    ? JSON.parse(Buffer.from(keyJson, "base64").toString("utf-8"))
    : JSON.parse(readFileSync(keyPath!, "utf-8"));
  const auth = new google.auth.GoogleAuth({ credentials, scopes: ["https://www.googleapis.com/auth/drive"] });
  client = google.drive({ version: "v3", auth });
  return client;
}

export function isDriveConfigured(): boolean {
  return getClient() !== null;
}

const escapeQ = (s: string) => s.replace(/\\/g, "\\\\").replace(/'/g, "\\'");
/** Drive allows most characters, but slashes in names read like paths. */
export const cleanFileName = (s: string) => s.replace(/[\\/:*?"<>|\r\n]+/g, " ").replace(/\s+/g, " ").trim().slice(0, 150) || "file";

async function folderUnder(drive: drive_v3.Drive, parentId: string, name: string): Promise<string> {
  const key = `${parentId}/${name}`;
  const cached = folderCache.get(key);
  if (cached) return cached;
  const shared = driveId()!;
  const found = await drive.files.list({
    q: `'${escapeQ(parentId)}' in parents and name = '${escapeQ(name)}' and mimeType = '${FOLDER_MIME}' and trashed = false`,
    corpora: "drive",
    driveId: shared,
    includeItemsFromAllDrives: true,
    supportsAllDrives: true,
    fields: "files(id)",
    pageSize: 1,
  });
  let id = found.data.files?.[0]?.id ?? null;
  if (!id) {
    const created = await drive.files.create({
      requestBody: { name, mimeType: FOLDER_MIME, parents: [parentId] },
      supportsAllDrives: true,
      fields: "id",
    });
    id = created.data.id ?? null;
  }
  if (!id) throw new Error(`Drive did not return a folder id for ${name}`);
  folderCache.set(key, id);
  return id;
}

export type DriveUpload = { fileId: string; link: string };

/**
 * Upload one file into a folder path inside the Shared Drive (folders are
 * created as needed), e.g. ["Inventory", "Received", "2026-10"].
 * Returns null when Drive is not set up; throws on a real Drive error so
 * the caller can record it and retry later.
 */
export async function uploadToSharedDrive(input: {
  folders: string[];
  name: string;
  mime: string;
  bytes: Buffer | Uint8Array;
  description?: string;
  /** Exact-match search keys (Drive allows ~124 bytes per key + value). */
  properties?: Record<string, string>;
}): Promise<DriveUpload | null> {
  const drive = getClient();
  if (!drive) return null;
  let parent = driveId()!;
  for (const name of input.folders) parent = await folderUnder(drive, parent, cleanFileName(name));
  const properties: Record<string, string> = {};
  for (const [k, v] of Object.entries(input.properties ?? {})) {
    properties[k.slice(0, 40)] = Buffer.from(String(v)).subarray(0, 80).toString("utf8").replace(/�$/, "");
  }
  try {
    const res = await drive.files.create({
      requestBody: {
        name: cleanFileName(input.name),
        parents: [parent],
        description: input.description?.slice(0, 4000),
        appProperties: properties,
      },
      media: { mimeType: input.mime, body: Readable.from(Buffer.from(input.bytes)) },
      supportsAllDrives: true,
      fields: "id, webViewLink",
    });
    const fileId = res.data.id;
    if (!fileId) throw new Error("Drive did not return a file id");
    return { fileId, link: res.data.webViewLink ?? `https://drive.google.com/file/d/${fileId}/view` };
  } catch (err) {
    logError("[Drive] upload failed", err, { scope: "drive", action: input.name });
    throw err;
  }
}

/** "2026-10" in office time: Drive folders are split by month. */
export function monthFolder(d: Date): string {
  const parts = new Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Kolkata", year: "numeric", month: "2-digit" }).formatToParts(d);
  const get = (t: string) => parts.find((p) => p.type === t)?.value ?? "";
  return `${get("year")}-${get("month")}`;
}

