/**
 * The office WhatsApp number as a backend channel ('whatsapp_web').
 *
 * The WhatsApp agent on the office PC is only a courier: it forwards every
 * message the number receives (all chats) and sends what we queue. Here:
 *
 *   1. Every message is saved in wa_messages (the searchable log); media
 *      goes to the Shared Drive (lib/google-drive.ts).
 *   2. Nothing reaches the AI unless the message calls the bot: it starts
 *      with "bot" (bot, Bot:, BOT,) or tags the bot's own number.
 *   3. A called message is answered by the query agent (core message
 *      router), and the answer is queued for the agent as a reply in the
 *      same chat (ops outbox, kind whatsapp.reply).
 */

import { randomUUID } from "crypto";
import { getDb } from "../../lib/database";
import { logError, logInfo } from "../../lib/logger";
import { monthFolder, uploadToSharedDrive } from "../../lib/google-drive";
import { handleMessage, registerChannelConfig } from "../../core/message-router";
import { queueOpsNotification, registerOpsComposer, registerOpsTicker } from "../../core/ops-outbox";
import type { StandardMessage } from "../../core/types";

export const CHANNEL = "whatsapp_web" as const;

/** WhatsApp caps media at 16 MB; larger is refused before decoding. */
export const MAX_MEDIA_BYTES = 16 * 1024 * 1024;

export type InboundWhatsApp = {
  id: string;
  sessionId?: string | null;
  chatId: string;
  chatName?: string | null;
  isGroup?: boolean;
  from?: string | null;
  senderName?: string | null;
  fromMe?: boolean;
  type?: string | null;
  body?: string | null;
  quotedBody?: string | null;
  /** Seconds since epoch, as WhatsApp gives it. */
  timestamp?: number | null;
  media?: { data?: string | null; mimetype?: string | null; filename?: string | null } | null;
  /** The office number itself (digits), so a tag of it can be recognised. */
  botPhone?: string | null;
};

// ─── Calling the bot ──────────────────────────────────────────────

const BOT_PREFIX = /^\s*bot\b[\s:,.-]*/i;

/**
 * Whether a message calls the bot, and the question with the call removed.
 * "bot how many pens are left" / "@919876543210 how many pens are left".
 */
export function botCall(body: string, botPhone: string | null | undefined): { called: boolean; question: string } {
  const text = body ?? "";
  if (BOT_PREFIX.test(text)) return { called: true, question: text.replace(BOT_PREFIX, "").trim() };
  const digits = (botPhone ?? process.env.OPS_BOT_NUMBER ?? "").replace(/\D/g, "");
  if (digits.length >= 8) {
    const tag = new RegExp(`@\\+?${digits}\\b`);
    if (tag.test(text)) return { called: true, question: text.replace(tag, "").replace(/\s+/g, " ").trim() };
  }
  return { called: false, question: "" };
}

// ─── Saving ───────────────────────────────────────────────────────

const MEDIA_EXT: Record<string, string> = {
  "image/jpeg": "jpg", "image/png": "png", "image/webp": "webp", "video/mp4": "mp4", "audio/ogg": "ogg",
  "audio/mpeg": "mp3", "application/pdf": "pdf",
};

function fileNameFor(m: InboundWhatsApp, sentAt: Date): string {
  const mime = String(m.media?.mimetype ?? "").split(";")[0]!.trim();
  const original = m.media?.filename?.trim();
  const stamp = sentAt.toISOString().slice(0, 19).replace("T", " ").replace(/:/g, ".");
  const who = m.senderName || m.from || "";
  return original ? `${stamp} ${who} ${original}` : `${stamp} ${who}.${MEDIA_EXT[mime] ?? "bin"}`;
}

/** Store one forwarded message. A re-forward of the same id changes nothing. */
export async function storeInboundWhatsApp(m: InboundWhatsApp): Promise<{ stored: boolean; botCalled: boolean }> {
  const sentAt = m.timestamp ? new Date(m.timestamp * 1000) : new Date();
  const media = m.media?.data ? Buffer.from(m.media.data, "base64") : null;
  const body = m.body ?? "";
  const call = m.fromMe ? { called: false, question: "" } : botCall(body, m.botPhone);
  const db = await getDb();
  const result = await db.execute({
    sql: `
      INSERT INTO wa_messages
        (wa_id, session_id, chat_id, chat_name, is_group, sender_id, sender_name, from_me, type, body,
         quoted_body, sent_at, media_mime, media_filename, media_size, media_bytes, bot_invoked)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT (wa_id) DO NOTHING
    `,
    args: [
      m.id,
      m.sessionId ?? null,
      m.chatId,
      m.chatName ?? null,
      Boolean(m.isGroup ?? m.chatId.endsWith("@g.us")),
      m.from ?? null,
      m.senderName ?? null,
      Boolean(m.fromMe),
      m.type || (media ? "media" : "chat"),
      body,
      m.quotedBody ?? null,
      sentAt.toISOString(),
      m.media?.mimetype ?? null,
      media ? fileNameFor(m, sentAt) : null,
      media?.length ?? null,
      media,
      call.called,
    ],
  });
  const stored = (result.rowsAffected ?? 0) > 0;
  if (!stored) return { stored: false, botCalled: false };

  if (media) void uploadWhatsAppMedia(m.id).catch(() => {});
  if (call.called) void answerBotCall(m, call.question).catch((err) => logError("[WhatsApp] bot call failed", err, { scope: "whatsapp-web" }));
  return { stored: true, botCalled: call.called };
}

/** Send one message's media to the Shared Drive; on success drop the bytes. */
async function uploadWhatsAppMedia(waId: string): Promise<void> {
  const db = await getDb();
  const row = (
    await db.execute({
      sql: `SELECT wa_id, chat_id, chat_name, sender_name, sender_id, body, sent_at, media_mime, media_filename, media_bytes
              FROM wa_messages WHERE wa_id = ? AND media_bytes IS NOT NULL AND drive_file_id IS NULL`,
      args: [waId],
    })
  ).rows[0];
  if (!row) return;
  const sentAt = row.sent_at instanceof Date ? row.sent_at : new Date(String(row.sent_at));
  try {
    const up = await uploadToSharedDrive({
      folders: ["WhatsApp", String(row.chat_name || row.chat_id), monthFolder(sentAt)],
      name: String(row.media_filename || waId),
      mime: String(row.media_mime || "application/octet-stream").split(";")[0]!.trim(),
      bytes: row.media_bytes as Buffer,
      description: [
        `Chat: ${row.chat_name || row.chat_id}`,
        `From: ${row.sender_name || row.sender_id || ""}`,
        `Sent: ${sentAt.toISOString()}`,
        row.body ? `Caption: ${row.body}` : null,
      ].filter(Boolean).join("\n"),
      properties: { waId, chatId: String(row.chat_id), from: String(row.sender_id ?? "") },
    });
    if (!up) return; // Drive not set up yet: bytes stay, the ticker retries later
    await db.execute({
      sql: `UPDATE wa_messages SET drive_file_id = ?, drive_link = ?, drive_error = NULL, media_bytes = NULL WHERE wa_id = ?`,
      args: [up.fileId, up.link, waId],
    });
  } catch (err) {
    await db.execute({
      sql: `UPDATE wa_messages SET drive_error = ? WHERE wa_id = ?`,
      args: [String(err instanceof Error ? err.message : err).slice(0, 500), waId],
    });
  }
}

/** Retry media that has not reached Drive (Drive was down or not set up yet). */
async function retryPendingMedia(): Promise<void> {
  const db = await getDb();
  const pending = (
    await db.execute({
      sql: `SELECT wa_id FROM wa_messages
             WHERE media_bytes IS NOT NULL AND drive_file_id IS NULL AND created_at < now() - interval '1 minute'
             ORDER BY created_at LIMIT 5`,
      args: [],
    })
  ).rows;
  for (const p of pending) await uploadWhatsAppMedia(String(p.wa_id));
}

// ─── Answering the bot ────────────────────────────────────────────

/** Queue a reply in a chat; the agent sends it on its next check. */
export async function queueWhatsAppReply(chatId: string, text: string): Promise<void> {
  await queueOpsNotification({
    siteId: "whatsapp",
    kind: "whatsapp.reply",
    dedupeKey: `whatsapp.reply:${randomUUID()}`,
    subjectId: chatId,
    payload: { text },
  });
}

async function answerBotCall(m: InboundWhatsApp, question: string): Promise<void> {
  if (!question) {
    await queueWhatsAppReply(m.chatId, "Yes? Ask me after \"bot\", for example: bot how many blue pens are left?");
    return;
  }
  logInfo(`[WhatsApp] bot called in ${m.chatName || m.chatId} by ${m.senderName || m.from}`, { scope: "whatsapp-web" });
  const sentAt = m.timestamp ? new Date(m.timestamp * 1000) : new Date();
  const msg: StandardMessage = {
    channel: CHANNEL,
    channelMessageId: m.id,
    channelChatId: m.chatId,
    chatTitle: m.chatName ?? undefined,
    // The question path answers in the chat it came from. The group
    // ingestion workflow is Telegram-shaped (numeric ids), so a called
    // message takes the question path in groups too.
    chatType: "private",
    senderId: m.from ?? "",
    senderName: m.senderName || m.from || "Someone",
    text: question,
    messageType: "text",
    timestamp: sentAt.toISOString(),
    // Calling the bot by name is the opt-in; the number is the org's own.
    isAdmin: true,
    rawPayload: { waId: m.id },
  };
  await handleMessage(msg);
}

