function messageId(msg) {
  if (msg.id) return String(msg.id);
  const h = crypto.createHash('sha1');
  h.update([msg.chatId, msg.from, msg.timestamp, msg.type, msg.body, msg.media?.data?.length ?? ''].join('|'));
  return `gen_${h.digest('hex').slice(0, 24)}`;
}

/** WhatsApp system events (encryption notices, group changes…) that aren't user content. */
const SYSTEM_TYPES = new Set(['e2e_notification', 'notification', 'notification_template', 'gp2', 'protocol', 'call_log']);

function storeMessage(sessionId, msg) {
  if (!msg?.chatId) return false;
  if (SYSTEM_TYPES.has(msg.type)) {
    log(`ignored system message ${msg.type} from ${msg.chatId}`);
    return true;
  }
  msg = { ...msg, id: messageId(msg) };
  if (seenIds.has(`${sessionId}/${msg.id}`)) return false;

  const dir = chatDir(sessionId, msg.chatId);
  fs.mkdirSync(dir, { recursive: true });

  const rec = {
    id: msg.id,
    sessionId,
    chatId: msg.chatId,
    from: msg.from,
    to: msg.to,
    ...(msg.author ? { author: msg.author } : {}),
    fromMe: Boolean(msg.fromMe),
    isGroup: Boolean(msg.isGroup),
    type: msg.type,
    body: msg.body || '',
    timestamp: Number(msg.timestamp) || Math.floor(Date.now() / 1000),
    quotedMessage: msg.quotedMessage,
    receivedAt: new Date().toISOString(),
  };
  rec.ref = refOf(rec);
  // Tags come from #hashtags in the text, or are given (ops relay posts keep
  // their text clean and pass the tags separately).
  rec.tags = Array.isArray(msg.tags) && msg.tags.length
    ? [...new Set(msg.tags.map(normalizeTag).filter(Boolean))]
    : tagsOf(rec.body);

  if (msg.media?.data) {
    const mediaDir = path.join(dir, 'media');
    fs.mkdirSync(mediaDir, { recursive: true });
    const file = `${rec.timestamp}_${safeName(msg.id).slice(-40)}.${extFor(msg.media.mimetype, msg.media.filename)}`;
    const buf = Buffer.from(msg.media.data, 'base64');
    fs.writeFileSync(path.join(mediaDir, file), buf);
    rec.media = { file, mimetype: msg.media.mimetype, filename: msg.media.filename, size: buf.length };
    drive.enqueue(driveItem(rec, path.join(mediaDir, file)));
  } else if (msg.media) {
    rec.media = { mimetype: msg.media.mimetype, filename: msg.media.filename, missing: true };
  }

  fs.appendFileSync(path.join(dir, 'messages.jsonl'), JSON.stringify(rec) + '\n');
  indexMessage(rec);
  scheduleTranscript(sessionId, rec.chatId, monthOf(rec.timestamp));
  log(`stored ${rec.type} from ${rec.chatId}${rec.media?.file ? ` (+media ${rec.media.file})` : ''}`);
  return rec;
function sheetRow(m) {
  const sender = m.fromMe ? '' : m.author || m.from;
  return [
    csvCell(timeOf(m.timestamp)),
    csvCell(m.fromMe ? 'Me' : names.get(sender) || numberOf(sender) || 'Unknown'),
    csvCell(m.fromMe ? '' : numberOf(sender)),
    csvCell(m.type),
    csvCell(m.body),
    fileCell(m),
    csvCell(m.quotedMessage?.body || ''),
    csvCell((m.tags || []).map(t => `#${t}`).join(' ')),
    csvCell(m.ref),
  ].join(',');
}

/** Changes whenever the sheet's rows would: a new message, or a file getting its Drive link. */
async function handleWebhook(req, res) {
  const raw = await readBody(req);
  if (!validSignature(raw, req.headers['x-openwa-signature'])) {
    log(`rejected webhook: bad signature (${raw.length} bytes)`);
    return send(res, 401, { error: 'bad signature' });
  }
  const payload = JSON.parse(raw.toString('utf8'));
  if (payload.event === 'message.received') {
    const d = payload.data || {};
    if (!d.id) log(`message from ${d.chatId} has no id; data keys: ${Object.keys(d).join(',')}`);
    if (storeMessage(payload.sessionId, d)) {
      void handleAutoReply(payload.sessionId, d);
    } else {
      log(`skipped message.received (id=${d.id}, chatId=${d.chatId}, type=${d.type}) — duplicate or missing chatId`);
    }
  } else {
    log(`ignored webhook event "${payload.event}"`);
  }
  send(res, 200, { ok: true });
}
