/**
 * Forwarder: every message WhatsApp delivers goes to the Office Ops backend,
 * which saves it (searchable log, media in the Shared Drive) and decides
 * what to do with it. Nothing is kept here once the backend has it.
 *
 * Durable: a message is written to the queue folder first and the file is
 * deleted only after the backend confirms it. If the backend or the
 * internet is down, messages wait on disk and go out oldest first when it
 * is back (retrying with backoff up to 5 minutes). A message the backend
 * refuses outright (bad request) is moved to queue/refused/ so it cannot
 * block the rest; nothing is thrown away.
 */
import fs from 'node:fs';
import path from 'node:path';

const MAX_BACKOFF_MS = 5 * 60_000;

const safe = s => String(s).replace(/[^A-Za-z0-9._-]+/g, '_').slice(-80);

export function createForwarder({ queueDir, engineUrl, secret, sessionInfo, log }) {
  const base = String(engineUrl || '').replace(/\/$/, '');
  const enabled = Boolean(base && secret);
  const refusedDir = path.join(queueDir, 'refused');
  fs.mkdirSync(refusedDir, { recursive: true });

  const state = { enabled, forwarded: 0, refused: 0, lastForwardAt: null, lastError: null };
  let running = false;
  let backoffMs = 5_000;
  let retryTimer = null;

  const pending = () => fs.readdirSync(queueDir).filter(f => f.endsWith('.json')).sort();

  /** Save one message to the queue, then try to send it. */
  function enqueue(message) {
    const name = `${String(message.timestamp || Math.floor(Date.now() / 1000)).padStart(12, '0')}-${safe(message.id)}.json`;
    const file = path.join(queueDir, name);
    if (fs.existsSync(file)) return; // the same message delivered twice
    const tmp = `${file}.tmp`;
    fs.writeFileSync(tmp, JSON.stringify(message));
    fs.renameSync(tmp, file); // atomic: a crash never leaves half a message
    kick();
  }

  function kick() {
    if (!enabled || running || retryTimer) return;
    void run();
  }

  async function sendOne(file) {
    const message = JSON.parse(fs.readFileSync(path.join(queueDir, file), 'utf8'));
    const { sessionId, botPhone } = sessionInfo();
    const res = await fetch(`${base}/api/ops-relay/inbound`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-Relay-Secret': secret },
      body: JSON.stringify({ session_id: sessionId, bot_phone: botPhone, message }),
      signal: AbortSignal.timeout(120_000),
    });
    if (res.ok) return 'sent';
    const text = (await res.text()).slice(0, 200);
    // Refused for good (bad request, too large): park it, keep going.
    if (res.status >= 400 && res.status < 500 && ![401, 408, 429].includes(res.status)) {
      fs.renameSync(path.join(queueDir, file), path.join(refusedDir, file));
      state.refused++;
      log(`forwarder: backend refused ${file} (${res.status} ${text}); kept in queue/refused/`);
      return 'refused';
    }
    throw new Error(`backend ${res.status} ${text}`);
  }

  async function run() {
    running = true;
    try {
      for (const file of pending()) {
        const outcome = await sendOne(file);
        if (outcome === 'sent') {
          fs.rmSync(path.join(queueDir, file), { force: true });
          state.forwarded++;
          state.lastForwardAt = new Date().toISOString();
        }
        state.lastError = null;
        backoffMs = 5_000;
      }
    } catch (err) {
      if (state.lastError !== err.message) log(`forwarder: ${err.message}; retrying in ${Math.round(backoffMs / 1000)}s`);
      state.lastError = err.message;
      retryTimer = setTimeout(() => {
        retryTimer = null;
        kick();
      }, backoffMs);
      backoffMs = Math.min(MAX_BACKOFF_MS, backoffMs * 2);
    } finally {
      running = false;
    }
    // Anything that arrived while this pass ran.
    if (!retryTimer && pending().length) kick();
  }

  function start() {
    if (!enabled) {
      log('forwarder: off (set OPS_RELAY_URL and OPS_RELAY_SECRET); incoming messages wait in the queue folder');
      return;
    }
    log(`forwarder: sending incoming messages to ${base}`);
    kick();
  }

  return { enqueue, start, kick, status: () => ({ ...state, queued: pending().length }) };
}

