import { createOpsRelay } from './relay.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));

const PORT = Number(process.env.ARCHIVER_PORT || 4100);
const HOST = process.env.ARCHIVER_HOST || '127.0.0.1';
const ARCHIVE_DIR = path.resolve(process.env.ARCHIVE_DIR || path.join(HERE, 'archive'));
const OPENWA_URL = (process.env.OPENWA_URL || 'http://127.0.0.1:2785').replace(/\/$/, '');
const OPENWA_API_KEY = process.env.OPENWA_API_KEY || 'dev-admin-key';
// URL OpenWA uses to reach us. Must be an IP or FQDN (OpenWA rejects "localhost").
const WEBHOOK_URL = process.env.WEBHOOK_URL || `http://127.0.0.1:${PORT}/webhook`;
const SYNC_INTERVAL_MS = 10_000;
// Name of the OpenWA session the "Connect WhatsApp" button creates.
const WA_SESSION_NAME = process.env.WA_SESSION_NAME || 'archiver';
// Address people open the UI on. Google redirects back here, so it must match the
// redirect URI registered on the OAuth client: <PUBLIC_URL>/oauth/google/callback
const PUBLIC_URL = (process.env.PUBLIC_URL || `http://localhost:${PORT}`).replace(/\/$/, '');
const DRIVE_RESCAN_MS = 5 * 60_000;
const DRIVE_MESSAGES = process.env.DRIVE_MESSAGES !== '0';
// Batch a burst of messages into one sheet upload.
const TRANSCRIPT_DELAY_MS = 60_000;
// Media arrives base64 inside the JSON (4/3 of the file), and a JS string tops out near 512 MB.
const MAX_BODY_BYTES = 450 * 1024 * 1024;

fs.mkdirSync(ARCHIVE_DIR, { recursive: true });

// Shared secret for HMAC-verifying webhooks, persisted so restarts keep working.
const SECRET_FILE = path.join(ARCHIVE_DIR, '.webhook-secret');
if (!fs.existsSync(SECRET_FILE)) fs.writeFileSync(SECRET_FILE, crypto.randomBytes(24).toString('hex'));
const WEBHOOK_SECRET = fs.readFileSync(SECRET_FILE, 'utf8').trim();

const log = (...args) => console.log(new Date().toISOString(), ...args);

const drive = createDrive({
  archiveDir: ARCHIVE_DIR,
  clientId: process.env.GOOGLE_CLIENT_ID,
  clientSecret: process.env.GOOGLE_CLIENT_SECRET,
  redirectUri: `${PUBLIC_URL}/oauth/google/callback`,
  folderName: process.env.DRIVE_FOLDER_NAME || 'WhatsApp Archive',
  mediaTypes: (process.env.DRIVE_MEDIA_TYPES || '').split(',').map(s => s.trim()).filter(Boolean),
  keepLocal: process.env.KEEP_LOCAL_MEDIA === '1',
  // A file just reached Drive: its row in the sheet can link to it now.
  onUploaded: item => scheduleTranscript(item.sessionId, item.chatId, monthOf(item.timestamp)),
  chatLabel: chatId => names.get(chatId) || chatId.replace(/@.*/, '').replace(/^(\d+)$/, '+$1'),
  log,
});

// ---------------------------------------------------------------------------
// Storage
// ---------------------------------------------------------------------------

/** Make a chat/session id safe to use as a directory name. */
const safeName = s => String(s).replace(/[^a-zA-Z0-9@._-]/g, '_');

const EXT_BY_MIME = {
  'image/jpeg': 'jpg',
  'image/png': 'png',
  'image/webp': 'webp',
  'image/gif': 'gif',
  'video/mp4': 'mp4',
  'video/3gpp': '3gp',
  'audio/ogg': 'ogg',
  'audio/mpeg': 'mp3',
  'audio/mp4': 'm4a',
  'audio/aac': 'aac',
  'application/pdf': 'pdf',
};

function extFor(mimetype, filename) {
async function api(pathname, { timeoutMs = 15_000, ...init } = {}) {
  const res = await fetch(`${OPENWA_URL}/api${pathname}`, {
    ...init,
    headers: { 'Content-Type': 'application/json', 'X-API-Key': OPENWA_API_KEY, ...init.headers },
    signal: AbortSignal.timeout(timeoutMs),
  });
  if (!res.ok) throw new Error(`${init.method || 'GET'} ${pathname} -> ${res.status} ${await res.text()}`);
  return res.status === 204 ? null : res.json();
}

/** Returns false if either list failed, so it's tried again later. */
async function refreshNames(sessionId) {
  let ok = true;
  try {
    for (const c of await api(`/sessions/${sessionId}/contacts`)) {
      const n = c.name || c.pushName;
      if (n) names.set(c.id, n);
    }
  } catch (err) {
    ok = false;
    log(`names: contacts failed: ${err.message.slice(0, 120)}`);
  }
  try {
    for (const g of await api(`/sessions/${sessionId}/groups`)) if (g.name) names.set(g.id, g.name);
  } catch (err) {
    ok = false;
    log(`names: groups failed: ${err.message.slice(0, 120)}`);
  }
  return ok;
}

const namesLoadedFor = new Set();
const NAMES_RETRY_MS = 5 * 60_000;
const namesTriedAt = new Map(); // sessionId -> last failed attempt

async function syncWithOpenWA() {
  try {
    const sessions = await api('/sessions');
    openwa.reachable = true;
    openwa.sessions = sessions.map(s => ({ id: s.id, name: s.name, status: s.status, phone: s.phone }));
function send(res, status, body, type = 'application/json') {
  res.writeHead(status, { 'Content-Type': type, 'Cache-Control': 'no-store' });
  res.end(type === 'application/json' ? JSON.stringify(body) : body);
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    const parts = [];
    let size = 0;
    req.on('data', chunk => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        reject(new Error('Payload too large'));
        req.destroy();
      } else parts.push(chunk);
    });
    req.on('end', () => resolve(Buffer.concat(parts)));
    req.on('error', reject);
  });
}

function validSignature(raw, header) {
  if (!header) return false;
  const expected = 'sha256=' + crypto.createHmac('sha256', WEBHOOK_SECRET).update(raw).digest('hex');
  const a = Buffer.from(expected);
  const b = Buffer.from(String(header));
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}

async function handleWebhook(req, res) {
  const raw = await readBody(req);
  res.writeHead(200, { 'Content-Type': type, 'Cache-Control': 'private, max-age=86400', ...(remote.headers.get('content-length') ? { 'Content-Length': remote.headers.get('content-length') } : {}) });
  Readable.fromWeb(remote.body).pipe(res);
}

const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, `http://${req.headers.host}`);
    const seg = url.pathname.split('/').filter(Boolean).map(decodeURIComponent);

    if (req.method === 'POST' && url.pathname === '/webhook') return await handleWebhook(req, res);

    if (req.method === 'POST') {
      // Browsers can't send a custom header cross-site without a CORS preflight we
      // never grant, so this stops other websites from pressing our buttons.
      if (req.headers['x-archiver'] !== '1') return send(res, 403, { error: 'forbidden' });
      const actions = {
        '/api/whatsapp/connect': connectWhatsApp,
        '/api/whatsapp/restart': restartWhatsApp,
        '/api/whatsapp/disconnect': disconnectWhatsApp,
        '/api/drive/disconnect': () => drive.disconnect(),
        '/api/drive/retry': () => {
          drive.retry();
          queueDriveBacklog();
        },
      };
      const action = actions[url.pathname];
      if (!action) return send(res, 404, { error: 'not found' });
      await action();
      return send(res, 200, { ok: true });
    }
    if (req.method !== 'GET') return send(res, 405, { error: 'method not allowed' });

    if (url.pathname === '/api/whatsapp') return send(res, 200, await whatsappStatus());
    if (url.pathname === '/drive/connect') {
      try {
        return redirect(res, drive.authUrl());
      } catch (err) {
        return redirect(res, `/?drive_error=${encodeURIComponent(err.message)}`);
      }
    }
    if (url.pathname === '/oauth/google/callback') {
      try {
        await drive.handleCallback(url.searchParams);
        queueDriveBacklog();
        return redirect(res, '/?drive=connected');
      } catch (err) {
        log(`drive: connect failed: ${err.message}`);
        return redirect(res, `/?drive_error=${encodeURIComponent(err.message)}`);
      }
    }
