#!/usr/bin/env node
/**
 * WhatsApp Agent: the office number's courier to the Office Ops backend.
 *
 * - Every message WhatsApp delivers (all chats) is forwarded to the backend
 *   (forwarder.mjs), which saves it, stores its media in the Shared Drive and
 *   decides what to do with it. No AI and no storage here.
 * - Whatever the backend queues (ops cards, replies) is sent (relay.mjs).
 * - Keeps WhatsApp linked: starts the session, reconnects after restarts,
 *   and shows the QR code on a small local page (and in the terminal).
 */
import http from 'node:http';
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { startCli } from './cli.mjs';
import { createForwarder } from './forwarder.mjs';
import { createOpsRelay } from './relay.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));

const PORT = Number(process.env.ARCHIVER_PORT || 4100);
const HOST = process.env.ARCHIVER_HOST || '127.0.0.1';
// State folder: the webhook secret and the forwarding queue. (Named for the
// archive it used to hold, so existing installs keep their webhook secret.)
const STATE_DIR = path.resolve(process.env.ARCHIVE_DIR || path.join(HERE, 'archive'));
const QUEUE_DIR = path.join(STATE_DIR, 'queue');
const OPENWA_URL = (process.env.OPENWA_URL || 'http://127.0.0.1:2785').replace(/\/$/, '');
const OPENWA_API_KEY = process.env.OPENWA_API_KEY || 'dev-admin-key';
// URL OpenWA uses to reach us. Must be an IP or FQDN (OpenWA rejects "localhost").
const WEBHOOK_URL = process.env.WEBHOOK_URL || `http://127.0.0.1:${PORT}/webhook`;
const SYNC_INTERVAL_MS = 15_000;
const NAMES_REFRESH_MS = 10 * 60_000;
// Name of the OpenWA session "Connect WhatsApp" creates.
const WA_SESSION_NAME = process.env.WA_SESSION_NAME || 'archiver';
const PUBLIC_URL = (process.env.PUBLIC_URL || `http://localhost:${PORT}`).replace(/\/$/, '');
// Media arrives base64 inside the JSON; WhatsApp caps files at 2 GB for documents.
const MAX_BODY_BYTES = 450 * 1024 * 1024;
// Start the session by itself (a saved login needs no scan), a few times.
const AUTO_CONNECT_EVERY_MS = 60_000;
const AUTO_CONNECT_MAX_TRIES = 3;

fs.mkdirSync(QUEUE_DIR, { recursive: true });

// Shared secret for HMAC-verifying webhooks, persisted so restarts keep working.
const SECRET_FILE = path.join(STATE_DIR, '.webhook-secret');
if (!fs.existsSync(SECRET_FILE)) fs.writeFileSync(SECRET_FILE, crypto.randomBytes(24).toString('hex'));
const WEBHOOK_SECRET = fs.readFileSync(SECRET_FILE, 'utf8').trim();

const log = (...args) => console.log(new Date().toISOString(), ...args);

// ---------------------------------------------------------------------------
// OpenWA
// ---------------------------------------------------------------------------

const openwa = { reachable: false, sessions: [] };
const names = new Map(); // chat or contact id -> display name
let lastNamesAt = 0;

async function api(pathname, { timeoutMs = 15_000, ...init } = {}) {
  const res = await fetch(`${OPENWA_URL}/api${pathname}`, {
    ...init,
    headers: { 'Content-Type': 'application/json', 'X-API-Key': OPENWA_API_KEY, ...init.headers },
    signal: AbortSignal.timeout(timeoutMs),
  });
  if (!res.ok) throw new Error(`${init.method || 'GET'} ${pathname} -> ${res.status} ${await res.text()}`);
  return res.status === 204 ? null : res.json();
}

/** Chat and contact names, so the backend's log shows "Office-flow", not an id. */
async function refreshNames(sessionId) {
  try {
    for (const c of await api(`/sessions/${sessionId}/contacts`)) {
      const n = c.name || c.pushName;
      if (n) names.set(c.id, n);
    }
  } catch (err) {
    log(`names: contacts failed: ${err.message.slice(0, 120)}`);
  }
  try {
    for (const g of await api(`/sessions/${sessionId}/groups`)) if (g.name) names.set(g.id, g.name);
  } catch (err) {
    log(`names: groups failed: ${err.message.slice(0, 120)}`);
  }
  lastNamesAt = Date.now();
}

const readySession = () => openwa.sessions.find(s => String(s.status).toLowerCase() === 'ready') || null;

/** Keep our webhook registered on every session, and names fresh. */
async function syncWithOpenWA() {
  try {
    const sessions = await api('/sessions');
    openwa.reachable = true;
    openwa.sessions = sessions.map(s => ({ id: s.id, name: s.name, status: s.status, phone: s.phone }));
    for (const s of sessions) {
      const hooks = await api(`/sessions/${s.id}/webhooks`);
      const ours = hooks.find(h => h.url === WEBHOOK_URL);
      if (!ours) {
        await api(`/sessions/${s.id}/webhooks`, {
          method: 'POST',
          body: JSON.stringify({ url: WEBHOOK_URL, events: ['message.received'], secret: WEBHOOK_SECRET, retryCount: 3 }),
        });
        log(`registered webhook on session "${s.name}" -> ${WEBHOOK_URL}`);
      } else if (!ours.active) {
        await api(`/sessions/${s.id}/webhooks/${ours.id}`, { method: 'PUT', body: JSON.stringify({ active: true, secret: WEBHOOK_SECRET }) });
      }
    }
    const ready = readySession();
    if (ready && Date.now() - lastNamesAt > NAMES_REFRESH_MS) await refreshNames(ready.id);
  } catch (err) {
    if (openwa.reachable) log(`OpenWA sync failed: ${err.message}`);
    openwa.reachable = false;
  }
}

// ---------------------------------------------------------------------------
// Linking WhatsApp
// ---------------------------------------------------------------------------

let lastStartError = null;
let paused = false; // after "unlink": don't relink until asked
let autoTries = 0;
let lastAutoAt = 0;

/** The session the page is about: a logged-in one first, else ours, else any. */
function pickSession(sessions) {
  return sessions.find(s => s.status === 'ready') || sessions.find(s => s.name === WA_SESSION_NAME) || sessions[0] || null;
}

async function whatsappStatus() {
  let sessions;
  try {
    sessions = await api('/sessions');
  } catch {
    return { status: 'offline' };
  }
  const s = pickSession(sessions);
  if (!s) return { status: 'none', error: lastStartError };
  const out = { sessionId: s.id, status: s.status, phone: s.phone || null, pushName: s.pushName || null, error: lastStartError };
  if (s.status === 'qr_ready') {
    try {
      const q = await api(`/sessions/${s.id}/qr`);
      out.qr = q.qrCode;
      out.qrText = q.qrText || null;
    } catch {
      /* between codes, or already scanned */
    }
  }
  return out;
}

/** Start without waiting: launching WhatsApp Web can take a minute. */
function startSession(id) {
  lastStartError = null;
  api(`/sessions/${id}/start`, { method: 'POST', timeoutMs: 180_000 }).catch(err => {
    if (/already started/i.test(err.message)) return;
    lastStartError = 'WhatsApp could not start. Please try again.';
    log(`whatsapp: start failed: ${err.message}`);
  });
}

async function connectWhatsApp() {
  paused = false;
  const sessions = await api('/sessions');
  let s = pickSession(sessions);
  if (s?.status === 'ready') return;
  if (!s) {
    s = await api('/sessions', { method: 'POST', body: JSON.stringify({ name: WA_SESSION_NAME }) });
    log(`whatsapp: created session "${WA_SESSION_NAME}"`);
  }
  startSession(s.id);
  void syncWithOpenWA(); // register our webhook before the first message
}

/** A stuck or expired QR: stop the session and start it again for a fresh code. */
async function restartWhatsApp() {
  paused = false;
  const s = pickSession(await api('/sessions'));
  if (!s) return connectWhatsApp();
  try {
    await api(`/sessions/${s.id}/stop`, { method: 'POST', timeoutMs: 60_000 });
  } catch {
    /* not running */
  }
  startSession(s.id);
}

/** Unlink: log out (the phone drops this device too), then remove the session. */
async function disconnectWhatsApp() {
  paused = true;
  const s = pickSession(await api('/sessions'));
  if (!s) return;
  try {
    await api(`/sessions/${s.id}/logout`, { method: 'POST', timeoutMs: 60_000 });
  } catch (err) {
    log(`whatsapp: logout failed, removing the session anyway: ${err.message}`);
  }
  await api(`/sessions/${s.id}`, { method: 'DELETE', timeoutMs: 60_000 });
  log('whatsapp: session removed');
}

/** Keep WhatsApp linked without anyone at a terminal (the service has none). */
async function keepLinked() {
  if (paused) return;
  const w = await whatsappStatus();
  if (w.status === 'ready') {
    autoTries = 0;
    return;
  }
  if (!['none', 'created', 'disconnected', 'failed'].includes(w.status)) return;
  if (Date.now() - lastAutoAt < AUTO_CONNECT_EVERY_MS || autoTries >= AUTO_CONNECT_MAX_TRIES) return;
  autoTries++;
  lastAutoAt = Date.now();
  await connectWhatsApp().catch(err => log(`whatsapp: could not start: ${err.message}`));
}

// ---------------------------------------------------------------------------
// Incoming messages -> backend
// ---------------------------------------------------------------------------

/** WhatsApp system events (encryption notices, group changes…), not content. */
const SYSTEM_TYPES = new Set(['e2e_notification', 'notification', 'notification_template', 'gp2', 'protocol', 'call_log']);

const forwarder = createForwarder({
  queueDir: QUEUE_DIR,
  engineUrl: process.env.OPS_RELAY_URL,
  secret: process.env.OPS_RELAY_SECRET,
  sessionInfo: () => {
    const s = readySession();
    return { sessionId: s?.id || null, botPhone: s?.phone ? String(s.phone).replace(/\D/g, '') : null };
  },
  log,
});

/**
 * whatsapp-web.js sometimes delivers messages without an id (seen with @lid
 * chats), so derive a stable one from the content to keep dedupe working.
 */
function messageId(msg) {
  if (msg.id) return String(msg.id);
  const h = crypto.createHash('sha1');
  h.update([msg.chatId, msg.from, msg.timestamp, msg.type, msg.body, msg.media?.data?.length ?? ''].join('|'));
