  return a.length === b.length && crypto.timingSafeEqual(a, b);
}

async function handleWebhook(req, res) {
  const raw = await readBody(req);
  if (!validSignature(raw, req.headers['x-openwa-signature'])) {
    log(`rejected webhook: bad signature (${raw.length} bytes)`);
    return send(res, 401, { error: 'bad signature' });
  }
  const payload = JSON.parse(raw.toString('utf8'));
  if (payload.event === 'message.received') {
    const d = payload.data || {};
    if (d.chatId && !SYSTEM_TYPES.has(d.type)) {
      forwarder.enqueue(toForward(d));
      log(`queued ${d.type || 'message'} from ${names.get(d.chatId) || d.chatId}`);
    }
  }
  send(res, 200, { ok: true });
}

// ---------------------------------------------------------------------------
// Outgoing: what the backend queues
// ---------------------------------------------------------------------------

const opsRelay = createOpsRelay({
  engineUrl: process.env.OPS_RELAY_URL,
  secret: process.env.OPS_RELAY_SECRET,
  group: process.env.OPS_GROUP,
  intervalMs: Number(process.env.OPS_RELAY_INTERVAL_MS) || 15_000,
  api,
  readySessionId: async () => readySession()?.id || null,
  log,
});

// ---------------------------------------------------------------------------
// Local page (QR + status); keep it on 127.0.0.1, it has no login
// ---------------------------------------------------------------------------

const PAGE = fs.readFileSync(path.join(HERE, 'index.html'), 'utf8');

const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, `http://${req.headers.host}`);
    if (req.method === 'POST' && url.pathname === '/webhook') return await handleWebhook(req, res);

    if (req.method === 'POST') {
      // Browsers can't send a custom header cross-site without a CORS preflight we
      // never grant, so this stops other websites from pressing our buttons.
      if (req.headers['x-archiver'] !== '1') return send(res, 403, { error: 'forbidden' });
      const actions = {
        '/api/whatsapp/connect': connectWhatsApp,
        '/api/whatsapp/restart': restartWhatsApp,
        '/api/whatsapp/disconnect': disconnectWhatsApp,
        '/api/forward/retry': () => forwarder.kick(),
      };
      const action = actions[url.pathname];
      if (!action) return send(res, 404, { error: 'not found' });
      await action();
      return send(res, 200, { ok: true });
    }
    if (req.method !== 'GET') return send(res, 405, { error: 'method not allowed' });

    if (url.pathname === '/') return send(res, 200, PAGE, 'text/html; charset=utf-8');
    if (url.pathname === '/api/whatsapp') return send(res, 200, await whatsappStatus());
    if (url.pathname === '/api/status') {
      return send(res, 200, {
        openwa: { url: OPENWA_URL, ...openwa },
        webhookUrl: WEBHOOK_URL,
        forwarder: forwarder.status(),
        opsRelay: opsRelay.status(),
      });
    }
    send(res, 404, { error: 'not found' });
  } catch (err) {
    log('request error:', err.message);
    if (!res.headersSent) send(res, 500, { error: err.message });
  }
});

server.listen(PORT, HOST, () => {
  log(`Agent page:       http://${HOST}:${PORT}`);
  log(`Webhook endpoint: ${WEBHOOK_URL}`);
  log(`State folder:     ${STATE_DIR}`);
  log(`OpenWA API:       ${OPENWA_URL}`);
  forwarder.start();
  opsRelay.start();
  void syncWithOpenWA().then(keepLinked);
  setInterval(() => void syncWithOpenWA().then(keepLinked), SYNC_INTERVAL_MS);
  if (process.env.AGENT_CLI !== '0') {
    startCli({ whatsappStatus, connectWhatsApp, restartWhatsApp, disconnectWhatsApp, forwarder, opsRelay, uiUrl: PUBLIC_URL });
  }
