    const last = r.lastSentAt ? `last post ${new Date(r.lastSentAt).toLocaleTimeString()}` : 'nothing posted yet';
    return [`to "${r.group}"`, `${r.sent} posted`, last, r.waiting || (r.lastError ? `error: ${r.lastError}` : null)]
      .filter(Boolean)
      .join(' · ');
