        '  status      what is connected, files saved and waiting, ops posts',
        '  qr          show a fresh WhatsApp QR code',
        '  drive       link to connect Google Drive',
        '  drive off   disconnect Google Drive',
        '  retry       retry paused Drive uploads',
        '  unlink      unlink WhatsApp from this computer',
        'Paste the Google address here after signing in.',
      ),
