      lastQr = null;
      const w = await whatsappStatus();
      if (w.status === 'ready') return console.log('WhatsApp is already linked. Type "unlink" first to link another number.');
      console.log('Getting a fresh code…');
      await (w.status === 'none' ? connectWhatsApp() : restartWhatsApp());
