      forwarder.kick();
      console.log('Sending waiting messages to the backend.');
    },
    unlink: () => {
      confirm = {
        prompt: 'Unlink WhatsApp from this computer? Type "yes" to confirm.',
        run: async () => {
          await disconnectWhatsApp();
          console.log('WhatsApp unlinked from this computer and the phone. Type "qr" to link again.');
        },
      };
      console.log(confirm.prompt);
    },
  };
