  commands['?'] = commands.help;

  async function onLine(raw) {
    const line = raw.trim();
    if (!line) return;
    if (confirm) {
      const c = confirm;
      confirm = null;
      if (/^y(es)?$/i.test(line)) return c.run();
      return console.log('Cancelled.');
    }
    const cmd = commands[line.toLowerCase().replace(/\s+/g, ' ')];
    if (cmd) return cmd();
    console.log(`Unknown command "${line}". Type "help".`);
  }

  if (process.stdin.readable) {
    const rl = readline.createInterface({ input: process.stdin });
    rl.on('line', line => void onLine(line).catch(err => console.log(`Error: ${err.message}`)));
  }

  // OpenWA rate-limits its API: check fast only while waiting for a scan.
  const tick = async () => {
    try {
      await watchWhatsApp();
    } catch (err) {
      console.log(`Status check failed: ${err.message}`);
    }
    setTimeout(tick, lastStatus === 'ready' ? 15_000 : 3_000);
  };
  console.log(`Type "help" for commands. Page: ${uiUrl}`);
  void tick();
}

