/**
 * Terminal interface: the QR code and a few commands, for running by hand.
 * (The service has no terminal; it relinks by itself and shows the QR on
 * the local page. See server.mjs keepLinked.)
 *
 * Type `help` for commands.
 */
import readline from 'node:readline';
import QRCode from 'qrcode';

const LINE = '-'.repeat(64);
const say = (...lines) => console.log(['', LINE, ...lines, LINE, ''].join('\n'));

export function startCli({ whatsappStatus, connectWhatsApp, restartWhatsApp, disconnectWhatsApp, forwarder, opsRelay, uiUrl }) {
  let lastStatus = null;
  let lastQr = null;
  let confirm = null; // { prompt, run } waiting for "yes"

  async function printQr(text) {
    const art = await QRCode.toString(text, { type: 'terminal', small: true });
    say(
      'Link WhatsApp: scan this code with your phone',
      '  On the phone: WhatsApp > Settings > Linked devices > Link a device',
      art.replace(/\n+$/, ''),
      'The code refreshes by itself. Type "qr" if it stops working.',
    );
  }

  async function watchWhatsApp() {
    const w = await whatsappStatus();
    const status = w.status;
    if (status === 'offline') {
      if (lastStatus !== 'offline') console.log('Waiting for the WhatsApp service (OpenWA) to start…');
    } else if (status === 'ready') {
      if (lastStatus !== 'ready') {
        lastQr = null;
        say(`WhatsApp linked: ${w.pushName || 'this account'}${w.phone ? ` (+${w.phone})` : ''}`, 'Incoming messages go to the Office Ops backend.');
      }
    } else if (status === 'qr_ready' && w.qrText) {
      if (w.qrText !== lastQr) {
        lastQr = w.qrText;
        await printQr(w.qrText);
      }
    } else if (status === 'authenticating') {
      if (lastStatus !== 'authenticating') console.log('Code scanned. Linking…');
    } else if (status === 'initializing') {
      if (lastStatus !== 'initializing') console.log('Starting WhatsApp… (up to a minute)');
    } else if (lastStatus === 'ready') {
      console.log('WhatsApp disconnected. Reconnecting…');
    }
    lastStatus = status;
  }

  function forwardLine() {
    const f = forwarder.status();
    if (!f.enabled) return `off (${f.queued} waiting in the queue folder)`;
    return [`${f.forwarded} sent`, `${f.queued} waiting`, f.refused ? `${f.refused} refused` : null, f.lastError ? `error: ${f.lastError}` : null]
      .filter(Boolean)
      .join(' · ');
  }

  function relayLine() {
    const r = opsRelay.status();
    if (!r.enabled) return 'off';
    const last = r.lastSentAt ? `last ${new Date(r.lastSentAt).toLocaleTimeString()}` : 'nothing sent yet';
    return [r.group ? `cards to "${r.group}"` : 'replies only', `${r.sent} sent`, last, r.waiting || (r.lastError ? `error: ${r.lastError}` : null)]
      .filter(Boolean)
      .join(' · ');
  }

  async function printStatus() {
    const w = await whatsappStatus();
    say(
      `WhatsApp:   ${w.status === 'ready' ? `linked (${w.pushName || ''}${w.phone ? ` +${w.phone}` : ''})` : w.status}`,
      `Incoming:   ${forwardLine()}`,
      `Outgoing:   ${relayLine()}`,
      `Page:       ${uiUrl}`,
    );
  }

  const commands = {
    help: () =>
      say(
        'Commands',
        '  status   WhatsApp, messages sent to the backend, messages sent out',
        '  qr       show a fresh WhatsApp QR code',
        '  retry    send waiting messages to the backend now',
        '  unlink   unlink WhatsApp from this computer',
      ),
    status: printStatus,
    qr: async () => {
      lastQr = null;
      const w = await whatsappStatus();
      if (w.status === 'ready') return console.log('WhatsApp is already linked. Type "unlink" first to link another number.');
      console.log('Getting a fresh code…');
      await (w.status === 'none' ? connectWhatsApp() : restartWhatsApp());
    },
    retry: () => {
      forwarder.kick();
      console.log('Sending waiting messages to the backend.');
    },
    unlink: () => {
      confirm = {
        prompt: 'Unlink WhatsApp from this computer? Type "yes" to confirm.',
        run: async () => {
          await disconnectWhatsApp();
          console.log('WhatsApp unlinked from this computer and the phone. Type "qr" to link again.');
        },
      };
      console.log(confirm.prompt);
    },
  };
  commands.connect = commands.qr;
  commands['?'] = commands.help;

  async function onLine(raw) {
    const line = raw.trim();
    if (!line) return;
    if (confirm) {
      const c = confirm;
      confirm = null;
      if (/^y(es)?$/i.test(line)) return c.run();
      return console.log('Cancelled.');
    }
    const cmd = commands[line.toLowerCase().replace(/\s+/g, ' ')];
    if (cmd) return cmd();
    console.log(`Unknown command "${line}". Type "help".`);
  }

  if (process.stdin.readable) {
    const rl = readline.createInterface({ input: process.stdin });
    rl.on('line', line => void onLine(line).catch(err => console.log(`Error: ${err.message}`)));
  }

  // OpenWA rate-limits its API: check fast only while waiting for a scan.
  const tick = async () => {
    try {
      await watchWhatsApp();
    } catch (err) {
      console.log(`Status check failed: ${err.message}`);
    }
    setTimeout(tick, lastStatus === 'ready' ? 15_000 : 3_000);
  };
  console.log(`Type "help" for commands. Page: ${uiUrl}`);
  void tick();
}

toolUseResult.originalFile:
/**
 * Terminal interface: everything the web page does, from the terminal.
 *
 * - Links WhatsApp on its own: starts the session (a saved login reconnects
 *   without a scan) and prints the QR code right in the terminal.
 * - Prints the Google sign-in link. Open it on any computer or phone; the
 *   browser then lands on a localhost address that won't load there, so paste
 *   that address back here. On this computer it connects by itself.
 * - Type `help` for commands.
 */
import readline from 'node:readline';
import QRCode from 'qrcode';

const LINE = '-'.repeat(64);
const say = (...lines) => console.log(['', LINE, ...lines, LINE, ''].join('\n'));

const AUTO_CONNECT_EVERY_MS = 60_000;
const AUTO_CONNECT_MAX_TRIES = 3;

export function startCli({ whatsappStatus, connectWhatsApp, restartWhatsApp, disconnectWhatsApp, drive, onDriveConnected, uiUrl, opsRelay }) {
  let lastStatus = null;
  let lastQr = null;
  let paused = false; // after "unlink": don't relink until asked
  let autoTries = 0;
  let lastAutoAt = 0;
  let driveWasConnected = drive.status().connected;
  let driveNagged = false;
  let confirm = null; // { prompt, run } waiting for "yes"

  // -------------------------------------------------------------------------
  // WhatsApp
  // -------------------------------------------------------------------------

  async function printQr(text) {
    const art = await QRCode.toString(text, { type: 'terminal', small: true });
    say(
      'Link WhatsApp: scan this code with your phone',
      '  On the phone: WhatsApp > Settings > Linked devices > Link a device',
      art.replace(/\n+$/, ''),
      'The code refreshes by itself. Type "qr" if it stops working.',
    );
  }

  async function watchWhatsApp() {
    const w = await whatsappStatus();
    const status = w.status;

    if (status === 'offline') {
      if (lastStatus !== 'offline') console.log('Waiting for the WhatsApp service (OpenWA) to start…');
    } else if (status === 'ready') {
      if (lastStatus !== 'ready') {
        autoTries = 0;
        lastQr = null;
        say(`WhatsApp linked: ${w.pushName || 'this account'}${w.phone ? ` (+${w.phone})` : ''}`, 'Incoming photos, videos and files will be saved.');
        promptDrive();
      }
    } else if (status === 'qr_ready' && w.qrText) {
      if (w.qrText !== lastQr) {
        lastQr = w.qrText;
        await printQr(w.qrText);
      }
    } else if (status === 'authenticating') {
      if (lastStatus !== 'authenticating') console.log('Code scanned. Linking…');
    } else if (status === 'initializing') {
      if (lastStatus !== 'initializing') console.log('Starting WhatsApp… (up to a minute)');
    } else if (['none', 'created', 'disconnected', 'failed'].includes(status)) {
      if (lastStatus === 'ready') console.log('WhatsApp disconnected. Reconnecting…');
      // Start (or restart) the session by itself; a saved login needs no scan.
      const due = Date.now() - lastAutoAt > AUTO_CONNECT_EVERY_MS;
      if (!paused && due && autoTries < AUTO_CONNECT_MAX_TRIES) {
        autoTries++;
        lastAutoAt = Date.now();
        await connectWhatsApp().catch(err => console.log(`Could not start WhatsApp: ${err.message}`));
      } else if (!paused && autoTries >= AUTO_CONNECT_MAX_TRIES && lastStatus !== status) {
        console.log('WhatsApp could not start. Type "connect" to try again.');
      }
    }
    lastStatus = status;
  }

  // -------------------------------------------------------------------------
  // Google Drive
  // -------------------------------------------------------------------------

  function printDriveLink() {
    const d = drive.status();
    if (!d.configured) {
      say('Google Drive is not set up.', 'Add GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET to apps/whatsapp-agent/.env and restart.');
      return;
    }
    say(
      'Connect Google Drive (where photos, videos and files are saved)',
      '',
      '1. Open this link on any computer or phone and sign in:',
      '',
      drive.authUrl(),
      '',
      '2. Allow access. Keep the Google Drive box ticked.',
      '3. The browser then shows a page that does not load. That is expected.',
      '   Copy the whole address from the address bar, paste it here and press Enter.',
      '   (If you signed in on this computer, it connects by itself.)',
      '',
      'The link works for 10 minutes. Type "drive" for a new one.',
    );
  }

  function promptDrive() {
    const d = drive.status();
    if (d.connected && !d.needsReconnect) return;
    if (driveNagged) return;
    driveNagged = true;
    printDriveLink();
  }

  function watchDrive() {
    const d = drive.status();
    if (d.connected && !driveWasConnected) {
      say(`Google Drive connected: ${d.email}`, 'Files go to the "WhatsApp Archive" folder in that Drive.');
    }
    if (d.needsReconnect && !driveNagged) {
      console.log('Google Drive access stopped working. New files wait on this computer until it is connected again.');
      promptDrive();
    }
    driveWasConnected = d.connected;
  }

  async function pasteCallback(line) {
    const query = line.includes('?') ? line.slice(line.indexOf('?') + 1) : line;
    try {
      await drive.handleCallback(new URLSearchParams(query.trim()));
      onDriveConnected();
      watchDrive();
    } catch (err) {
      console.log(`${err.message} Type "drive" for a new link.`);
    }
  }

  // -------------------------------------------------------------------------
  // Commands
  // -------------------------------------------------------------------------

  async function printStatus() {
    const w = await whatsappStatus();
    const d = drive.status();
    say(
      `WhatsApp:     ${w.status === 'ready' ? `linked (${w.pushName || ''}${w.phone ? ` +${w.phone}` : ''})` : w.status}`,
      `Google Drive: ${!d.configured ? 'not set up' : d.connected ? `${d.email} · ${d.uploaded} saved · ${d.pending} waiting${d.lastError ? ` · paused: ${d.lastError}` : ''}` : 'not connected'}`,
      `Ops relay:    ${opsRelayLine()}`,
      `Archive page: ${uiUrl}`,
    );
  }

  function opsRelayLine() {
    const r = opsRelay?.status();
    if (!r?.enabled) return 'off';
    const last = r.lastSentAt ? `last post ${new Date(r.lastSentAt).toLocaleTimeString()}` : 'nothing posted yet';
    return [`to "${r.group}"`, `${r.sent} posted`, last, r.waiting || (r.lastError ? `error: ${r.lastError}` : null)]
      .filter(Boolean)
      .join(' · ');
  }

  const commands = {
    help: () =>
      say(
        'Commands',
        '  status      what is connected, files saved and waiting, ops posts',
        '  qr          show a fresh WhatsApp QR code',
        '  drive       link to connect Google Drive',
        '  drive off   disconnect Google Drive',
        '  retry       retry paused Drive uploads',
        '  unlink      unlink WhatsApp from this computer',
        'Paste the Google address here after signing in.',
      ),
    status: printStatus,
    qr: async () => {
      paused = false;
      autoTries = 0;
      lastQr = null;
      const w = await whatsappStatus();
      if (w.status === 'ready') return console.log('WhatsApp is already linked. Type "unlink" first to link another number.');
      console.log('Getting a fresh code…');
      await (w.status === 'none' ? connectWhatsApp() : restartWhatsApp());
    },
    drive: () => {
      const d = drive.status();
      if (d.connected && !d.needsReconnect) return console.log(`Google Drive is connected (${d.email}). Type "drive off" to disconnect it.`);
      driveNagged = true;
      printDriveLink();
    },
    'drive off': () => {
      if (!drive.status().connected) return console.log('Google Drive is not connected.');
      confirm = {
        prompt: 'Disconnect Google Drive? Files already there stay. New files will wait on this computer. Type "yes" to confirm.',
        run: async () => {
          await drive.disconnect();
          driveWasConnected = false;
          driveNagged = false;
          console.log('Google Drive disconnected. Type "drive" to connect one again.');
        },
      };
      console.log(confirm.prompt);
    },
    retry: () => {
      drive.retry();
      onDriveConnected();
      console.log('Retrying Drive uploads.');
    },
    unlink: () => {
      confirm = {
        prompt: 'Unlink WhatsApp from this computer? Saved files stay. Type "yes" to confirm.',
        run: async () => {
          paused = true;
          await disconnectWhatsApp();
          console.log('WhatsApp unlinked from this computer and the phone. Type "qr" to link again.');
        },
      };
      console.log(confirm.prompt);
    },
  };
  commands.connect = commands.qr;
  commands['?'] = commands.help;

  async function onLine(raw) {
    const line = raw.trim();
    if (!line) return;
    if (confirm) {
      const c = confirm;
      confirm = null;
      if (/^y(es)?$/i.test(line)) return c.run();
      return console.log('Cancelled.');
    }
    if (/[?&]code=/.test(line) || /^code=/.test(line)) return pasteCallback(line);
    const cmd = commands[line.toLowerCase().replace(/\s+/g, ' ')];
    if (cmd) return cmd();
    console.log(`Unknown command "${line}". Type "help".`);
  }

  // -------------------------------------------------------------------------

  if (process.stdin.readable) {
    const rl = readline.createInterface({ input: process.stdin });
    rl.on('line', line => void onLine(line).catch(err => console.log(`Error: ${err.message}`)));
  }

  // Every check costs OpenWA calls, which it rate-limits: poll fast only while
  // something is changing (starting up, waiting for a scan), slowly once linked.
  const tick = async () => {
    try {
      await watchWhatsApp();
      watchDrive();
    } catch (err) {
      console.log(`Status check failed: ${err.message}`);
    }
    setTimeout(tick, lastStatus === 'ready' ? 15_000 : 3_000);
  };
  console.log(`Type "help" for commands. Archive page: ${uiUrl}`);
  void tick();
}

