import { readFileSync } from "fs";
import { google } from "googleapis";
const line = readFileSync("env.updated", "utf8").split("\n").find((l) => l.startsWith("GOOGLE_SERVICE_ACCOUNT_KEY_JSON="))!;
const raw = line.split("=").slice(1).join("=").trim().replace(/^["']|["']$/g, "");
const credentials = JSON.parse(Buffer.from(raw, "base64").toString("utf8"));
const auth = new google.auth.GoogleAuth({ credentials, scopes: ["https://www.googleapis.com/auth/drive"] });
const drive = google.drive({ version: "v3", auth });
const id = "0AIq0fmpn24cAUk9PVA";
try {
  const d = await drive.drives.get({ driveId: id, fields: "id,name,capabilities(canAddChildren,canEdit)" });
  console.log("shared drive:", d.data.name, "| can add files:", d.data.capabilities?.canAddChildren);
  const f = await drive.files.list({ corpora: "drive", driveId: id, includeItemsFromAllDrives: true, supportsAllDrives: true, pageSize: 10, fields: "files(name,mimeType)" });
  console.log("top-level items:", (f.data.files ?? []).map((x) => x.name));
} catch (e: any) {
  console.log("drive error:", e?.code, e?.errors?.[0]?.message ?? e?.message);
}
EOF
cp /tmp/rbacpg/drive-probe.ts ./.drive-probe.ts && bun ./.drive-probe.ts; rm -f ./.drive-probe.ts

