import { AsyncLocalStorage } from "node:async_hooks";
import { inspect } from "node:util";
import { randomUUID } from "node:crypto";
import { telegram as telegramConfig } from "./config";

type LogLevel = "INFO" | "WARN" | "ERROR" | "HTTP";

export interface LogContext {
  scope?: string;
  eventId?: string;
  chatId?: number | string;
  userId?: number | string;
  messageId?: number | string;
  job?: string;
  action?: string;
  reqId?: string;
}

const MAX_TELEGRAM_MESSAGE_LENGTH = 3600;
const SCOPE_WIDTH = 22;
const contextStore = new AsyncLocalStorage<LogContext>();

const originalConsole = {
  log: console.log.bind(console),
  warn: console.warn.bind(console),
  error: console.error.bind(console),
};

let consoleBridgeInstalled = false;
let transportQueue = Promise.resolve();
let lastTransportFailureAt = 0;

// ─── Telegram batch state ────────────────────────────────
const BATCH_WINDOW_MS = 2000;
const MIN_SEND_GAP_MS = 1100;

let _batchBuffer: string[] = [];
let _batchTimer: ReturnType<typeof setTimeout> | null = null;
let _lastSentAt = 0;

// ─── Color support (terminal only) ───────────────────────
const SUPPORTS_COLOR =
  Boolean((process.stdout as { isTTY?: boolean }).isTTY) &&
  process.env.NO_COLOR !== "1" &&
  process.env.TERM !== "dumb";

function ansi(code: string, text: string): string {
  return SUPPORTS_COLOR ? `\x1b[${code}m${text}\x1b[0m` : text;
}

const color = {
  dim: (s: string) => ansi("2", s),
  bold: (s: string) => ansi("1", s),
  red: (s: string) => ansi("31", s),
  green: (s: string) => ansi("32", s),
  yellow: (s: string) => ansi("33", s),
  blue: (s: string) => ansi("34", s),
  magenta: (s: string) => ansi("35", s),
  cyan: (s: string) => ansi("36", s),
  gray: (s: string) => ansi("90", s),

export function installConsoleBridge(): void {
  if (consoleBridgeInstalled) return;
  consoleBridgeInstalled = true;

  console.log = (...args: unknown[]) => {
    originalConsole.log(...args);
    queueTelegramLog("INFO", serializeArgs(args), contextStore.getStore());
  };

  console.warn = (...args: unknown[]) => {
    originalConsole.warn(...args);
    queueTelegramLog("WARN", serializeArgs(args), contextStore.getStore());
  };

  console.error = (...args: unknown[]) => {
    originalConsole.error(...args);
    queueTelegramLog("ERROR", serializeArgs(args), contextStore.getStore());
  };
}


export function newRequestId(): string {
  // 6 chars, plenty for correlating req/res in a single terminal session
  return randomUUID().replace(/-/g, "").slice(0, 6);
}

// ─── URL redaction ───────────────────────────────────────
//
// Request lines are mirrored to a Telegram log channel, so anything we print
// leaves the box. A few URLs unavoidably carry live credentials: EventSource
// cannot set headers, so the reception desk stream authenticates with `?key=`
// and a visitor's pass stream carries its token in the path. Those stay in the
// URL, so we scrub them here instead — the log keeps its shape for debugging
// and the secret never reaches the channel.

/** Query params whose values are credentials, not diagnostics. */
const SENSITIVE_QUERY_KEYS = new Set([
  "key",
  "token",
  "secret",
  "code",
  "state",
  "access_token",
  "refresh_token",
  "id_token",
  "t",
]);

/** Path prefixes whose next segment is a bearer-equivalent token. */
const TOKENISED_PATH_PREFIXES = [
  "/api/visitor/status-stream/",
  "/api/visitor/status/",
  "/api/visitor/self-checkin/",
  "/api/visitor/checkin/",
  "/api/visitor/checkout/",
  "/api/visitor/verify/",
  "/visitor/checkin/",
];

export function redactQuery(query?: string): string | undefined {
  if (!query) return query;
  return query
    .split("&")
    .map((pair) => {
      const eq = pair.indexOf("=");
      if (eq === -1) return pair;
      const name = pair.slice(0, eq);
      return SENSITIVE_QUERY_KEYS.has(name.toLowerCase())
        ? `${name}=[redacted]`
        : pair;
    })
    .join("&");
}

export function redactPath(path: string): string {
  for (const prefix of TOKENISED_PATH_PREFIXES) {
    if (!path.startsWith(prefix)) continue;
    const rest = path.slice(prefix.length);
    if (!rest) return path;
    const slash = rest.indexOf("/");
    const tail = slash === -1 ? "" : rest.slice(slash);
    return `${prefix}[redacted]${tail}`;
  }
  return path;
}

export function logHttpRequest(entry: HttpRequestLog): void {
  const safe: HttpRequestLog = {
    ...entry,
    path: redactPath(entry.path),
    query: redactQuery(entry.query),
  };
  const line = formatHttpRequestLine(safe);
  originalConsole.log(line);
  queueTelegramLog(
    "HTTP",
    `-> ${safe.method} ${safe.path}${safe.query ? "?" + safe.query : ""}${safe.ip ? " ip=" + safe.ip : ""}`,
    { scope: "http", reqId: safe.reqId },
  );
}

export function logHttpResponse(entry: HttpResponseLog): void {
  const line = formatHttpResponseLine({ ...entry, path: redactPath(entry.path) });
  if (entry.status >= 500) {
    originalConsole.error(line);
  } else if (entry.status >= 400) {
    originalConsole.warn(line);
  } else {
    originalConsole.log(line);
  }

  // Only push non-2xx responses to Telegram to keep noise down
  if (entry.status >= 400) {
    queueTelegramLog(
      entry.status >= 500 ? "ERROR" : "WARN",
      `<- ${entry.status} ${entry.method} ${redactPath(entry.path)} (${entry.durationMs}ms)`,
      { scope: "http", reqId: entry.reqId },
    );
  }
}

// ─── Core formatting ─────────────────────────────────────

function emitLog(level: LogLevel, message: string, context?: LogContext): void {
  const mergedContext = compactContext({
    ...(contextStore.getStore() ?? {}),
    ...(context ?? {}),
  });
  const formatted = formatTerminalLine(level, message, mergedContext);

  if (level === "ERROR") {
    originalConsole.error(formatted);
  } else if (level === "WARN") {
    originalConsole.warn(formatted);
  } else {
    originalConsole.log(formatted);
  }

  queueTelegramLog(level, message, mergedContext);
}

// ─── Visual design ───────────────────────────────────────
//
// Each line is a single row of three lanes:
//
//   <time>  <level tag>  <scope> | <message>  <kv pairs>
    return base;
  }

  return serializeValue(error);
}

function truncate(text: string, maxLength: number): string {
  if (text.length <= maxLength) return text;
  return `${text.slice(0, maxLength - 14)}\n[truncated]`;
}

// ─── Telegram transport ──────────────────────────────────
// Rendered with Telegram's HTML parse mode so logs are easy to scan in the
// chat: a per-line timestamp, a level badge, the scope in bold, the message in
// plain text, and the key/value context in muted monospace. No ANSI here —
// that is terminal-only.

const TELEGRAM_LEVEL_BADGE: Record<LogLevel, string> = {
  INFO: "🟦",
  WARN: "🟧",
  ERROR: "🟥",
  HTTP: "⬜",
};

// Per-message cap so a single noisy log can't eat the whole batch budget.
const MAX_TELEGRAM_LINE_MESSAGE = 700;

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function shortTime(): string {
  const d = new Date();
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
}

function formatTelegramLine(
  level: LogLevel,
  message: string,
  context?: LogContext,
): string {
  const time = `<code>${shortTime()}</code>`;
  const badge = TELEGRAM_LEVEL_BADGE[level];
  const scope = context?.scope
    ? ` <b>${escapeHtml(context.scope)}</b>`
    : "";
  const kvs = formatContextKVs(context);
  const tail = kvs ? `  <i>${escapeHtml(kvs)}</i>` : "";

  const normalized = truncate(
    normalizeMessage(message),
    MAX_TELEGRAM_LINE_MESSAGE,
  );
  // Multi-line messages (stack traces, JSON dumps) render best in a code block.
  const body = normalized
    ? normalized.includes("\n")
      ? `\n<pre>${escapeHtml(normalized)}</pre>`
      : ` ${escapeHtml(normalized)}`
    : "";

  return `${time} ${badge}${scope}${body}${tail}`;
}

// Join pre-rendered HTML lines without ever cutting a line (and therefore a
// tag) in half. If the batch overflows, drop whole trailing lines and note it.
function joinTelegramLines(lines: string[], max: number): string {
  const kept: string[] = [];
  let length = 0;
  for (const line of lines) {
    const next = length + line.length + 1;
    if (next > max - 60 && kept.length > 0) break;
    kept.push(line);
    length = next;
  }
  const dropped = lines.length - kept.length;
  let text = kept.join("\n");
  if (dropped > 0) {
    text += `\n<i>... ${dropped} more line${dropped === 1 ? "" : "s"} omitted</i>`;
  }
  return text;
}

function queueTelegramLog(
  level: LogLevel,
  message: string,
  context?: LogContext,
): void {
  if (!telegramConfig.logEnabled()) return;
  const channelId = telegramConfig.logChannelId();
  if (!channelId) return;

  _batchBuffer.push(formatTelegramLine(level, message, context));

  if (_batchTimer) clearTimeout(_batchTimer);
  _batchTimer = setTimeout(() => {
    _batchTimer = null;
    const lines = _batchBuffer.splice(0);
    if (lines.length === 0) return;

    const text = joinTelegramLines(lines, MAX_TELEGRAM_MESSAGE_LENGTH);

    transportQueue = transportQueue
      .then(async () => {
        const gap = Date.now() - _lastSentAt;
        if (gap < MIN_SEND_GAP_MS) {
          await new Promise((r) => setTimeout(r, MIN_SEND_GAP_MS - gap));
        }
        await sendTelegramLog(channelId, text);
        _lastSentAt = Date.now();
      })
      .catch((error) => {
        const now = Date.now();
        if (now - lastTransportFailureAt > 60_000) {
          lastTransportFailureAt = now;
          originalConsole.error(
            `[ ERR! ] logger.transport | Failed to send log to Telegram channel\n${serializeError(error)}`,
          );
        }
      });
  }, BATCH_WINDOW_MS);
}

async function sendTelegramLog(channelId: string, text: string): Promise<void> {
  const response = await fetch(
    `https://api.telegram.org/bot${telegramConfig.botToken()}/sendMessage`,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        chat_id: channelId,
        text,
        parse_mode: "HTML",
        disable_notification: true,
        disable_web_page_preview: true,
      }),
    },
  );

  if (!response.ok) {
    throw new Error(`Telegram log send failed with HTTP ${response.status}`);
  }

  const data = (await response.json()) as {
    ok?: boolean;
    description?: string;
  };
  if (!data.ok) {
    throw new Error(data.description || "Telegram log send failed");
  }
}

