  _batchBuffer.push(formatTelegramLine(level, message, context));

  if (_batchTimer) clearTimeout(_batchTimer);
  _batchTimer = setTimeout(() => {
    _batchTimer = null;
    const lines = _batchBuffer.splice(0);
    if (lines.length === 0) return;

    const text = joinTelegramLines(lines, MAX_TELEGRAM_MESSAGE_LENGTH);

    transportQueue = transportQueue
      .then(async () => {
        const gap = Date.now() - _lastSentAt;
        if (gap < MIN_SEND_GAP_MS) {
          await new Promise((r) => setTimeout(r, MIN_SEND_GAP_MS - gap));
        }
        await sendTelegramLog(channelId, text);
        _lastSentAt = Date.now();
      })
      .catch((error) => {
        const now = Date.now();
        if (now - lastTransportFailureAt > 60_000) {
          lastTransportFailureAt = now;
          originalConsole.error(
            `[ ERR! ] logger.transport | Failed to send log to Telegram channel\n${serializeError(error)}`,
          );
        }
      });
  }, BATCH_WINDOW_MS);
}

async function sendTelegramLog(channelId: string, text: string): Promise<void> {
  const response = await fetch(
    `https://api.telegram.org/bot${telegramConfig.botToken()}/sendMessage`,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        chat_id: channelId,
        text,
        parse_mode: "HTML",
        disable_notification: true,
        disable_web_page_preview: true,
      }),
    },
  );

  if (!response.ok) {
    throw new Error(`Telegram log send failed with HTTP ${response.status}`);
  }

  const data = (await response.json()) as {
    ok?: boolean;
    description?: string;
  };
  if (!data.ok) {
    throw new Error(data.description || "Telegram log send failed");
  }
}

