// Paths excluded from per-request terminal logging. Health/readiness probes
// from orchestrators hit constantly and would drown out actual API traffic.
const HTTP_LOG_SKIP_PATHS = new Set(["/health", "/ready", "/favicon.ico"]);

function shouldLogHttp(method: string | undefined, path: string): boolean {
  if (HTTP_LOG_SKIP_PATHS.has(path)) return false;
  if (method === "OPTIONS") return false; // CORS preflight noise
  return true;
}

function jsonResponse(
  res: ServerResponse,
  status: number,
  body: Record<string, unknown>,
): void {
  res.writeHead(status, {
    ...VISITOR_HTTP_CORS_HEADERS,
    "Content-Type": "application/json",
  });
  res.end(JSON.stringify(body));
}

async function handleHealthRequest(
  req: IncomingMessage,
  res: ServerResponse,
): Promise<boolean> {
  if (req.method !== "GET" && req.method !== "HEAD") return false;

  const pathname = getRequestPathname(req);
  if (pathname === "/health") {
    jsonResponse(res, 200, {
      ok: true,
      service: "appointy-ops-backend",
      timestamp: new Date().toISOString(),
    });
    return true;
  }

  if (pathname === "/ready") {
    try {
      await getPostgresPool().query("select 1");
      jsonResponse(res, 200, {
        ok: true,
        database: "reachable",
        timestamp: new Date().toISOString(),
      });
    } catch (error) {
      jsonResponse(res, 503, {
        ok: false,
        database: "unreachable",
        error: error instanceof Error ? error.message : String(error),
        timestamp: new Date().toISOString(),
      });
    }
    return true;
  }

  return false;
}

function buildMessageLogContext(
  scope: string,
  msg: TelegramBot.Message,
): LogContext {
  return {
    scope,
    eventId: `${msg.chat.id}:${msg.message_id}`,
    chatId: msg.chat.id,
    userId: msg.from?.id,
    messageId: msg.message_id,
  };
}

function isVisitorManagementGroup(chatId: number): boolean {
  return tgConfig.visitorGroupIds().includes(chatId);
}

// ─── Telegram Channel Adapter ─────────────────────────────
// Implements ChannelAdapter interface for the registry.

const telegramAdapter: ChannelAdapter = {
  name: "telegram",

  async initialize(): Promise<void> {
    // Bot initialization is handled in startTelegramChannel()
  },

  async shutdown(): Promise<void> {
    const bot = getBot();
    try {
      await bot.stopPolling();
      logInfo("Telegram polling stopped", { scope: "telegram" });
    } catch {
      // ignore
    }
  },

  async sendMessage(chatId: string, text: string, options?: SendMessageOptions): Promise<void> {
    const parseMode = options?.parseMode === "markdown" ? "Markdown" as const
      : options?.parseMode === "html" ? "HTML" as const
      : undefined;
    await sendMessage(Number(chatId), text, {
      parseMode,
      replyToMessageId: options?.replyToMessageId ? Number(options.replyToMessageId) : undefined,
    });
  },

  async notifyAdmins(text: string, options?: SendMessageOptions): Promise<void> {
    const adminIds = tgConfig.adminIds();
    const parseMode = options?.parseMode === "markdown" ? "Markdown" as const
      : options?.parseMode === "html" ? "HTML" as const
      : undefined;

    for (const adminId of adminIds) {
      try {
        await sendMessage(adminId, text, { parseMode });
      } catch (error) {
        logWarn(`Failed to notify Telegram admin ${adminId}: ${error instanceof Error ? error.message : String(error)}`);
      }
    }
  },
};

// ─── Start Telegram Channel ──────────────────────────────

async function startTelegramChannel(): Promise<void> {
  const bot = getBot();

  // ─── Graceful Shutdown ───────────────────────────────────
  let shuttingDown = false;
  const shutdown = async () => {
    if (shuttingDown) return;
    shuttingDown = true;
    logInfo("Shutting down bot", { scope: "server" });
    await telegramAdapter.shutdown();
    setTimeout(() => process.exit(0), 3000).unref();
    process.exit(0);
  };
  process.on("SIGINT", shutdown);
  process.on("SIGTERM", shutdown);
  process.on("SIGHUP", shutdown);
  process.on("beforeExit", shutdown);

  // ─── Polling Error Handler ──────────────────────────────
  bot.on("polling_error", (error: any) => {
    logError("Telegram polling error", error?.message || error, {
      scope: "telegram.polling",
    });
    if (error?.message?.includes("409")) {
      logError(
        "Another bot instance is running. Stop the duplicate process and restart.",
        undefined,
        { scope: "telegram.polling" },
      );
    }
  });

  // ─── Raw Update Diagnostics ─────────────────────────────
  (bot as any).on("update", (update: any) => {
    const type =
      Object.keys(update)
        .filter((k) => k !== "update_id")
        .join(", ") || "unknown";
    const id = update.update_id;
    if (update.callback_query) {
      const cb = update.callback_query;
      logInfo(
        `Telegram update received: callback_query data="${cb.data}" from=${cb.from?.first_name} (${cb.from?.id}) msg_id=${cb.message?.message_id}`,
        {
          scope: "telegram.update",
          eventId: String(id),
          chatId: cb.message?.chat?.id,
          userId: cb.from?.id,
          messageId: cb.message?.message_id,
          action: cb.data,
        },
      );
    } else {
      logInfo(`Telegram update received: ${type}`, {
        scope: "telegram.update",
        eventId: String(id),
      });
    }
  });

  await registerBotCommands();

  // ─── Message Handler ────────────────────────────────────
  // Translates Telegram messages to StandardMessage and routes to core.
  bot.on("message", async (msg: TelegramBot.Message) => {
    try {
      const scope = isPrivateMessage(msg)
        ? "telegram.dm"
        : isGroupMessage(msg)
          ? "telegram.group"
          : "telegram.message";
      await withLogContext(buildMessageLogContext(scope, msg), async () => {
        // Skip bot's own messages
        if (msg.from?.is_bot) return;

        if (isWhereAmICommand(getMessageText(msg))) {
          await replyWithChatDetails(msg);
          return;
        }

        if (isGroupMessage(msg)) {
          if (isVisitorManagementGroup(msg.chat.id)) {
