function getClientIp(req: IncomingMessage): string | undefined {
  const fwd = req.headers["x-forwarded-for"];
  if (typeof fwd === "string" && fwd.length > 0) return fwd.split(",")[0]?.trim();
  if (Array.isArray(fwd) && fwd.length > 0) return fwd[0];
  return req.socket?.remoteAddress ?? undefined;
}

// Paths excluded from per-request terminal logging. Health/readiness probes
// from orchestrators hit constantly and would drown out actual API traffic.
const HTTP_LOG_SKIP_PATHS = new Set(["/health", "/ready", "/favicon.ico"]);

function shouldLogHttp(method: string | undefined, path: string): boolean {
  if (HTTP_LOG_SKIP_PATHS.has(path)) return false;
  if (method === "OPTIONS") return false; // CORS preflight noise
  return true;
}

function jsonResponse(
  res: ServerResponse,
  status: number,
  body: Record<string, unknown>,
): void {
  res.writeHead(status, {
    ...VISITOR_HTTP_CORS_HEADERS,
    "Content-Type": "application/json",
  });
  res.end(JSON.stringify(body));
}

async function handleHealthRequest(
  req: IncomingMessage,
  res: ServerResponse,
): Promise<boolean> {
  if (req.method !== "GET" && req.method !== "HEAD") return false;

  const pathname = getRequestPathname(req);
  if (pathname === "/health") {
    jsonResponse(res, 200, {
      ok: true,
      service: "appointy-ops-backend",
      timestamp: new Date().toISOString(),
    });
    return true;
  }

  if (pathname === "/ready") {
    try {
      await getPostgresPool().query("select 1");
      jsonResponse(res, 200, {
        ok: true,
        database: "reachable",
        timestamp: new Date().toISOString(),
      });
    } catch (error) {
      jsonResponse(res, 503, {
        ok: false,
        database: "unreachable",
        error: error instanceof Error ? error.message : String(error),
        timestamp: new Date().toISOString(),
      });
    }
    return true;
  }

  return false;
}

function buildMessageLogContext(
  scope: string,
  msg: TelegramBot.Message,
): LogContext {
  return {
    scope,
    eventId: `${msg.chat.id}:${msg.message_id}`,
    chatId: msg.chat.id,
    userId: msg.from?.id,
    messageId: msg.message_id,
  };
}

