input.content:
/**
 * What the office WhatsApp number may listen to and where it posts, set by
 * an admin in the dashboard (WhatsApp page).
 *
 * - A chat is saved only when an admin has turned "listen" on for it; new
 *   groups start off. Private (1:1) chats share one switch.
 * - Each ops card type goes to the groups an admin ticked for it.
 *
 * The agent fetches this (relayConfig) so it only forwards what is allowed;
 * the backend checks again on every message (it is the source of truth).
 */

import { getDb } from "../../lib/database";

/** Ops card types an admin can route to groups. */
export const CARD_TYPES = [
  { key: "stock_received", label: "Stock received (with photo)" },
  { key: "count_corrected", label: "Stock count corrected" },
  { key: "stock_alerts", label: "Low and out of stock" },
  { key: "daily_summary", label: "Daily take out summary" },
] as const;
export type CardType = (typeof CARD_TYPES)[number]["key"];

/** Which card type each queued message kind is. */
export const CARD_OF_KIND: Record<string, CardType> = {
  "inventory.item_received": "stock_received",
  "inventory.count_corrected": "count_corrected",
  "inventory.low_stock": "stock_alerts",
  "inventory.out_of_stock": "stock_alerts",
  "inventory.daily_takeouts": "daily_summary",
};

export type WaChat = {
  chat_id: string;
  name: string | null;
  is_group: boolean;
  listen: boolean;
  cards: CardType[];
  last_seen_at: string | null;
};

const iso = (v: unknown) => (v == null ? null : v instanceof Date ? v.toISOString() : String(v));

function toChat(r: Record<string, unknown>): WaChat {
  const cards = Array.isArray(r.cards) ? r.cards : typeof r.cards === "string" ? String(r.cards).replace(/[{}]/g, "").split(",").filter(Boolean) : [];
  return {
    chat_id: String(r.chat_id),
    name: (r.name as string | null) ?? null,
    is_group: Boolean(r.is_group),
    listen: Boolean(r.listen),
    cards: cards as CardType[],
    last_seen_at: iso(r.last_seen_at),
  };
}

/** Record that the number is in a chat (from the agent or a message). Never changes the admin's switches. */
export async function seeChat(chatId: string, name: string | null, isGroup: boolean): Promise<void> {
  const db = await getDb();
  await db.execute({
    sql: `
      INSERT INTO wa_chats (chat_id, name, is_group, last_seen_at)
      VALUES (?, ?, ?, now())
      ON CONFLICT (chat_id) DO UPDATE SET
        name = COALESCE(EXCLUDED.name, wa_chats.name),
        is_group = EXCLUDED.is_group OR wa_chats.is_group,
        last_seen_at = now()
    `,
    args: [chatId, name, isGroup],
  });
}

export async function listChats(): Promise<WaChat[]> {
  const db = await getDb();
  const rows = (
    await db.execute({
      sql: `SELECT chat_id, name, is_group, listen, cards, last_seen_at FROM wa_chats
             ORDER BY is_group DESC, listen DESC, lower(coalesce(name, chat_id))`,
      args: [],
    })
  ).rows;
  return rows.map(toChat);
}

export async function updateChat(chatId: string, input: { listen?: boolean; cards?: string[] }, actor: string | null): Promise<WaChat | null> {
  const valid = new Set<string>(CARD_TYPES.map((c) => c.key));
  const cards = input.cards?.filter((c) => valid.has(c));
  const db = await getDb();
  const rows = (
    await db.execute({
      sql: `
        UPDATE wa_chats SET
          listen = COALESCE(?, listen),
          cards = COALESCE(string_to_array(?, ','), cards),
          updated_by = ?, updated_at = now()
        WHERE chat_id = ?
        RETURNING chat_id, name, is_group, listen, cards, last_seen_at
      `,
      args: [
        typeof input.listen === "boolean" ? input.listen : null,
        cards ? cards.join(",") : null,
        actor,
        chatId,
      ],
    })
  ).rows;
  return rows[0] ? toChat(rows[0]) : null;
}

export async function getPrivateChatsAllowed(): Promise<boolean> {
  const db = await getDb();
  const row = (await db.execute({ sql: `SELECT value FROM wa_settings WHERE key = 'private_chats'`, args: [] })).rows[0];
  const v = typeof row?.value === "string" ? JSON.parse(row.value) : row?.value;
  return v === true;
}

export async function setPrivateChatsAllowed(allowed: boolean, actor: string | null): Promise<void> {
  const db = await getDb();
  await db.execute({
    sql: `INSERT INTO wa_settings (key, value, updated_by, updated_at) VALUES ('private_chats', ?::jsonb, ?, now())
          ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_by = EXCLUDED.updated_by, updated_at = now()`,
    args: [JSON.stringify(allowed), actor],
  });
}

/** May a message from this chat be saved? Unknown chats are recorded (off) so they show in the dashboard. */
export async function mayListen(chatId: string, chatName: string | null, isGroup: boolean): Promise<boolean> {
  await seeChat(chatId, chatName, isGroup);
  if (!isGroup) return getPrivateChatsAllowed();
  const db = await getDb();
  const row = (await db.execute({ sql: `SELECT listen FROM wa_chats WHERE chat_id = ?`, args: [chatId] })).rows[0];
  return Boolean(row?.listen);
}

/** Groups a card type goes to. Empty: the agent falls back to its OPS_GROUP. */
export async function chatsForCard(card: CardType): Promise<string[]> {
  const db = await getDb();
  const rows = (
    await db.execute({ sql: `SELECT chat_id FROM wa_chats WHERE ? = ANY(cards) ORDER BY chat_id`, args: [card] })
  ).rows;
  return rows.map((r) => String(r.chat_id));
}

/** What the agent needs to filter before forwarding. */
export async function relayConfig(): Promise<{ listen: string[]; private_chats: boolean }> {
  const db = await getDb();
  const rows = (await db.execute({ sql: `SELECT chat_id FROM wa_chats WHERE listen AND is_group`, args: [] })).rows;
  return { listen: rows.map((r) => String(r.chat_id)), private_chats: await getPrivateChatsAllowed() };
}

