import { getDb } from "../../lib/database";

/** Ops card types an admin can route to groups. */
export const CARD_TYPES = [
  { key: "stock_received", label: "Stock received (with photo)" },
  { key: "count_corrected", label: "Stock count corrected" },
  { key: "stock_alerts", label: "Low and out of stock" },
  { key: "daily_summary", label: "Daily take out summary" },
] as const;
export type CardType = (typeof CARD_TYPES)[number]["key"];

/** Which card type each queued message kind is. */
export const CARD_OF_KIND: Record<string, CardType> = {
  "inventory.item_received": "stock_received",
  "inventory.count_corrected": "count_corrected",
  "inventory.low_stock": "stock_alerts",
  "inventory.out_of_stock": "stock_alerts",
  "inventory.daily_takeouts": "daily_summary",
};

export type WaChat = {
  chat_id: string;
  name: string | null;
  is_group: boolean;
  listen: boolean;
  cards: CardType[];
  last_seen_at: string | null;
};

const iso = (v: unknown) => (v == null ? null : v instanceof Date ? v.toISOString() : String(v));

function toChat(r: Record<string, unknown>): WaChat {
  const cards = Array.isArray(r.cards) ? r.cards : typeof r.cards === "string" ? String(r.cards).replace(/[{}]/g, "").split(",").filter(Boolean) : [];
  return {
    chat_id: String(r.chat_id),
    name: (r.name as string | null) ?? null,
    is_group: Boolean(r.is_group),
    listen: Boolean(r.listen),
    cards: cards as CardType[],
    last_seen_at: iso(r.last_seen_at),
  };
}

/** Record that the number is in a chat (from the agent or a message). Never changes the admin's switches. */
export async function seeChat(chatId: string, name: string | null, isGroup: boolean): Promise<void> {
  const db = await getDb();
  await db.execute({
    sql: `
      INSERT INTO wa_chats (chat_id, name, is_group, last_seen_at)
      VALUES (?, ?, ?, now())
      ON CONFLICT (chat_id) DO UPDATE SET
        name = COALESCE(EXCLUDED.name, wa_chats.name),
        is_group = EXCLUDED.is_group OR wa_chats.is_group,
        last_seen_at = now()
    `,
    args: [chatId, name, isGroup],
  });
}

export async function listChats(): Promise<WaChat[]> {
  const db = await getDb();
  const rows = (
    await db.execute({
      sql: `SELECT chat_id, name, is_group, listen, cards, last_seen_at FROM wa_chats
             ORDER BY is_group DESC, listen DESC, lower(coalesce(name, chat_id))`,
      args: [],
    })
  ).rows;
  return rows.map(toChat);
}

export async function updateChat(chatId: string, input: { listen?: boolean; cards?: string[] }, actor: string | null): Promise<WaChat | null> {
  const valid = new Set<string>(CARD_TYPES.map((c) => c.key));
  const cards = input.cards?.filter((c) => valid.has(c));
  const db = await getDb();
  const rows = (
    await db.execute({
      sql: `
