      args: [
        typeof input.listen === "boolean" ? input.listen : null,
        cards ? cards.join(",") : null,
        actor,
        chatId,
      ],
    })
  ).rows;
  return rows[0] ? toChat(rows[0]) : null;
}

export async function getPrivateChatsAllowed(): Promise<boolean> {
  const db = await getDb();
  const row = (await db.execute({ sql: `SELECT value FROM wa_settings WHERE key = 'private_chats'`, args: [] })).rows[0];
