// ─── Notify host ──────────────────────────────────────────────

async function notifySingleHost(
  staffMember: StaffRecord,
  invitation: VisitorInvitation,
  sessionId: string,
  now: string,
  locationName?: string,
  delayedSync?: boolean,
): Promise<boolean> {
  let notified = false;

  const telegramChannel = staffMember.channels?.find((c) => c.channel === 'telegram');
  const text = [
    `👋 Your visitor has arrived\\!`,
    ``,
    `👤 *${invitation.visitor_name}*`,
    invitation.purpose ? `📋 ${invitation.purpose}` : '',
    locationName ? `📍 ${locationName}` : '',
    `⏰ Arrived at ${now}`,
    delayedSync ? `_Delayed alert: synced after offline guard capture_` : '',
  ].filter(Boolean).join('\n');

  // Arrival is a plain notification — no response buttons. The host's only
  // interaction is approving/rejecting walk-ins (a separate message); this
  // arrival DM just tells them their (already-expected) visitor is here.
  try {
    const hostChatId = Number(telegramChannel?.channelUid);
    if (Number.isFinite(hostChatId) && hostChatId !== 0) {
      const { getBot } = await import('../../channels/telegram/bot');
      await getBot().sendMessage(hostChatId, text, { parse_mode: 'Markdown' });
      notified = true;
    }
  } catch (error) {
    console.error(`[HostNotifier] Failed to DM Telegram host ${staffMember.name}:`, error);
  }

  const slackChannel = staffMember.channels?.find((c) => c.channel === 'slack');
  if (slackChannel?.channelUid) {
    try {
      const slackBlocks = buildSlackHostResponseBlocks(
        invitation,
        sessionId,
        now,
        locationName,
        delayedSync,
        slackChannel.channelUid,
        invitation.id,
      );
      const slackRef = await sendSlackDm({
        userId: slackChannel.channelUid,
        text: `Visitor arrived: ${invitation.visitor_name}`,
        blocks: slackBlocks,
      });
      notified = notified || !!slackRef?.ts;
    } catch (error) {
      console.error(`[HostNotifier] Failed to DM Slack host ${staffMember.name}:`, error);
    }
  }

  return notified;
}

