  // Master switch for all Telegram I/O (channel + log transport).
  // Explicit TELEGRAM_ENABLED wins; otherwise defaults on when a token is present.
  enabled: () => {
    const explicit = envFlag(process.env.TELEGRAM_ENABLED);
    if (explicit !== undefined) return explicit;
    return Boolean(process.env.TELEGRAM_BOT_TOKEN);
  },
  botToken: () => env('TELEGRAM_BOT_TOKEN'),
